window.ABBOTT={"short":1,"L":{"ἀγαθός":"G18","ἀγάπη":"G26","ἀγαπητός":"G27","ἅγιος":"G40","ἀδελφή":"G79","ἀδελφός":"G80","ἀδικέω":"G91","αἰώνιος":"G166","ἀκούω":"G191","ἀλλά":"G235","ἅμα":"G260","ἀνάγκη":"G318","ἀναπαύω":"G373","ἀναπέμπω":"G375","ἀνήκω":"G433","ἀπέχω":"G568","ἀποτίνω":"G661","Ἀπφία":"G682","Ἀρίσταρχος":"G708","Ἄρχιππος":"G751","ἀσπάζομαι":"G782","αὐτός":"G846","ἄχρηστος":"G890","βούλομαι":"G1014","γεννάω":"G1080","γίνομαι":"G1096","γνώμη":"G1106","γράφω":"G1125","δέσμιος":"G1198","δεσμός":"G1199","Δημᾶς":"G1214","διά":"G1223","διακονέω":"G1247","διό":"G1352","δοῦλος":"G1401","ἐγώ":"G1473","εἰρήνη":"G1515","εἰς":"G1519","ἐκκλησία":"G1577","ἐκούσιος":"G1595","ἐλλογάω":"G1677","ἐλπίζω":"G1679","ἐμαυτοῦ":"G1683","ἐμός":"G1699","ἐνεργής":"G1756","Ἐπαφρᾶς":"G1889","ἐπίγνωσις":"G1922","ἐπιτάσσω":"G2004","ἑτοιμάζω":"G2090","εὐαγγέλιον":"G2098","εὐχαριστέω":"G2168","εὔχρηστος":"G2173","ἔχω":"G2192","θέλω":"G2309","θεός":"G2316","Ἰησοῦς":"G2424","καί":"G2532","κατέχω":"G2722","κοινωνία":"G2842","κοινωνός":"G2844","κύριος":"G2962","Λουκᾶς":"G3065","μάλα":"G3123","μάλιστα":"G3122","Μάρκος":"G3138","μή":"G3361","μνεία":"G3417","ναί":"G3483","νυνί":"G3570","ξενία":"G3578","οἶδα":"G1492","οἶκος":"G3624","Ὀνήσιμος":"G3682","ὀνίνημι":"G3685","ὅς":"G3739","οὐδείς":"G3762","οὐκέτι":"G3765","ὀφείλω":"G3784","πάντοτε":"G3842","παρακαλέω":"G3870","παράκλησις":"G3874","παρρησία":"G3954","πᾶς":"G3956","πατήρ":"G3962","Παῦλος":"G3972","πείθω":"G3982","πίστις":"G4102","πνεῦμα":"G4151","ποιέω":"G4160","πολύς":"G4183","πόσος":"G4214","ποτέ":"G4218","πρεσβύτης":"G4246","πρός":"G4314","προσευχή":"G4335","προσλαμβάνω":"G4355","προσοφείλω":"G4359","σάρξ":"G4561","σεαυτοῦ":"G4572","σπλάγχνον":"G4698","συναιχμάλωτος":"G4869","συνεργός":"G4904","συνστρατιώτης":"G4961","τάχα":"G5029","τέκνον":"G5043","Τιμόθεος":"G5095","τις":"G5100","τοιοῦτος":"G5108","ὑπακοή":"G5218","ὑπέρ":"G5228","φιλήμων":"G5371","χαρά":"G5479","χαρίζομαι":"G5483","χάρις":"G5485","χείρ":"G5495","Χριστός":"G5547","χωρίζω":"G5563","χωρίς":"G5565","ὥρα":"G5610","ὡς":"G5613"},"D":{"G1014":{"l":"βούλομαι","o":37,"en":"<f><o>βούλομαι</o>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2654\">חפץ</h>, <h n=\"H14\">אבה</h>, <h n=\"H3289\">יעץ</h>, etc. ;]</e> </et> <s><b>to will, wish, desire, purpose, be minded</b>, implying more strongly than <g>θέλω</g> (q.v.), the deliberate exercise of volition (v. Hort on <r v=\"Jas.1.18\"></r>): c. inf. (M, <i>Pr.</i>, 205; Bl., §69, 4), <r v=\"Mark.15.15\"></r>, <r v=\"Acts.5.28\"></r>, <r v=\"Acts.5.33\"></r> <r v=\"Acts.12.4\"></r> <r v=\"Acts.15.37\"></r> <r v=\"Acts.17.20\"></r> <r v=\"Acts.18.15\"></r>, <r v=\"Acts.15.27\"></r> <r v=\"Acts.19.30\"></r> <r v=\"Acts.22.30\"></r> <r v=\"Acts.23.28\"></r> <r v=\"Acts.27.43\"></r> <r v=\"Acts.28.18\"></r>, <r v=\"2Cor.1.15\"></r>, <r v=\"1Tim.6.9\"></r>, <r v=\"Heb.6.17\"></r>, <r v=\"2John.1.12\"></r>, <r v=\"3John.1.10\"></r>, <r v=\"Jude.1.5\"></r>; c. acc., <r v=\"2Cor.1.17\"></r>; c. acc. et inf., <r v=\"Phil.1.12\"></r>, <r v=\"1Tim.2.8\"></r> <r v=\"1Tim.5.14\"></r>, <r v=\"Titus.3.8\"></r>, <r v=\"2Pet.3.9\"></r>; of the will making choice between alternatives, <r v=\"Matt.1.19\"></r> <r v=\"Matt.11.27\"></r>, <r v=\"Luke.10.22\"></r>, <r v=\"Acts.25.20\"></r>, <r v=\"1Cor.12.11\"></r>, <r v=\"Jas.3.4\"></r> <r v=\"Jas.4.4\"></r>; <g>εἰ βούλει</g> (cl., a courteous phrase = <g>θέλεις</g>, colloq.; Bl., §21, 8; LS, s.v.), <r v=\"Luke.22.4\"></r>; c. subjc., adding force to a question of deliberation (Bl., §64, 6), <r v=\"John.18.39\"></r>; <g>βουληθείς</g>, <i>of set purpose</i> (v. Hort, in l.), <r v=\"Jas.1.18\"></r>; impf., <g>ἐβουλόμην</g> (= cl. <g>βουλοίμην ἄν</g>; Bl., §63, 5; Lft., <i>Phm.</i> 13), <r v=\"Acts.25.22\"></r>, <r v=\"Phlm.1.13\"></r> (v. also Cremer, 143).†</s>","ar":"<f><o>βούλομαι</o>، </f> <s><b>أراد، رغب، اشتهى، قصد، عزم</b>، ويدل أقوى من <g>θέλω</g> (انظره) على ممارسة الإرادة عن تروٍّ (انظر التعليق على <r v=\"Jas.1.18\"></r>): مع المصدر: <r v=\"Mark.15.15\"></r>، <r v=\"Acts.5.28\"></r>، <r v=\"Acts.5.33\"></r>، <r v=\"Acts.12.4\"></r>، <r v=\"Acts.15.37\"></r>، <r v=\"Acts.17.20\"></r>، <r v=\"Acts.18.15\"></r>، <r v=\"Acts.15.27\"></r>، <r v=\"Acts.19.30\"></r>، <r v=\"Acts.22.30\"></r>، <r v=\"Acts.23.28\"></r>، <r v=\"Acts.27.43\"></r>، <r v=\"Acts.28.18\"></r>، <r v=\"2Cor.1.15\"></r>، <r v=\"1Tim.6.9\"></r>، <r v=\"Heb.6.17\"></r>، <r v=\"2John.1.12\"></r>، <r v=\"3John.1.10\"></r>، <r v=\"Jude.1.5\"></r>؛ مع المنصوب: <r v=\"2Cor.1.17\"></r>؛ مع المنصوب والمصدر: <r v=\"Phil.1.12\"></r>، <r v=\"1Tim.2.8\"></r>، <r v=\"1Tim.5.14\"></r>، <r v=\"Titus.3.8\"></r>، <r v=\"2Pet.3.9\"></r>؛ عن الإرادة حين تختار بين أمرين: <r v=\"Matt.1.19\"></r>، <r v=\"Matt.11.27\"></r>، <r v=\"Luke.10.22\"></r>، <r v=\"Acts.25.20\"></r>، <r v=\"1Cor.12.11\"></r>، <r v=\"Jas.3.4\"></r>، <r v=\"Jas.4.4\"></r>؛ <g>εἰ βούλει</g> (عبارة مهذبة = <g>θέλεις</g> في اللغة الدارجة): <r v=\"Luke.22.4\"></r>؛ مع صيغة الاحتمال، تقويةً لسؤال التروّي: <r v=\"John.18.39\"></r>؛ <g>βουληθείς</g>: <i>عن قصد، بمشيئته</i>: <r v=\"Jas.1.18\"></r>؛ الماضي الناقص <g>ἐβουλόμην</g> (= <g>βουλοίμην ἄν</g>): <r v=\"Acts.25.22\"></r>، <r v=\"Phlm.1.13\"></r>.†</s>"},"G1080":{"l":"γεννάω","o":97,"en":"<f><o>γεννάω</o>, <g>-ῶ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γέννα</g>, poët. for <g>γένος</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3205\">ילד</h> ;]</e> </et> <s> <s n=\"1.\">of the father, <b>to beget</b>: c. acc., <r v=\"Matt.1.1-Matt.1.16\"></r>, <r v=\"Acts.7.8\"></r>, <r v=\"Acts.7.29\"></r>; seq. <g>ἐκ</g>, <r v=\"Matt.1.3\"></r>, <r v=\"Matt.1.5\"></r>, <r v=\"Matt.1.6\"></r>. </s> <s n=\"2.\">Of the mother, <b>to bring forth, bear</b>: <r v=\"Luke.1.13\"></r>, <r v=\"Luke.1.57\"></r> <r v=\"Luke.23.29\"></r>, <r v=\"John.16.21\"></r>; <g>εἰς δουλείαν</g>, <r v=\"Gal.4.24\"></r>. Pass. <s n=\"(1)\"><b>to be begotten</b>: <r v=\"Matt.1.20\"></r>; </s> <s n=\"(2)\"><b>to be born</b>: <r v=\"Matt.2.1\"></r>, <r v=\"Matt.2.4\"></r> <r v=\"Matt.19.12\"></r> <r v=\"Matt.26.24\"></r>, <r v=\"Mark.14.21\"></r>, <r v=\"Luke.1.35\"></r>, <r v=\"John.3.4\"></r>, <r v=\"Acts.7.20\"></r>, <r v=\"Rom.9.11\"></r>, <r v=\"Heb.11.23\"></r>; seq. <g>εἰς</g>, <r v=\"John.16.21\"></r> <r v=\"John.18.37\"></r>, <r v=\"2Pet.2.12\"></r>; <g>ἐν</g>, <r v=\"Acts.2.8\"></r> <r v=\"Acts.22.3\"></r>, (<g>ἁμαρτίαις</g>), <r v=\"John.9.34\"></r>; <g>ἀπό</g>, <r v=\"Heb.11.12\"></r> (WH, mg., <g>ἐγεν-</g>); <g>ἐκ</g>, <r v=\"John.1.13\"></r> <r v=\"John.3.6\"></r> <r v=\"John.8.41\"></r>; c. adj., <g>τυφλὸς γ.</g>, <r v=\"John.9.2\"></r>; [<g>Ῥωμαῖος</g> ], <r v=\"Acts.22.28\"></r>; <g>κατὰ σάρκα: κ. πνεῦμα</g>: <r v=\"Gal.4.29\"></r>. Metaph.; <g>μάχας</g>, <r v=\"2Tim.2.23\"></r>; <g>ὑμᾶς ἐγέννησα</g>, <r v=\"1Cor.4.15\"></r>, (<g>ὅν</g>), Phm 10; in quotation, <r v=\"Ps.2.7\"></r> (LXX), <r v=\"Acts.13.33\"></r>, <r v=\"Heb.1.5\"></r> <r v=\"Heb.5.5\"></r>; of Christians as begotten of God, born again: <r v=\"John.1.13\"></r> <r v=\"John.3.3\"></r>, <r v=\"John.3.5-John.3.8\"></r>, <r v=\"1John.2.29\"></r> <r v=\"1John.3.9\"></r> <r v=\"1John.4.7\"></r> <r v=\"1John.5.1\"></r>, <r v=\"1John.5.4\"></r>, <r v=\"1John.5.18\"></r> (cf. <g>ἀνα-γεννάω</g>); (Cremer, 146).</s> </s> </s>","ar":"<f><o>γεννάω</o>، <g>-ῶ</g> </f> <s> <s n=\"1.\">عن الأب، <b>يَلِد</b> (يُنجب): مع المنصوب، <r v=\"Matt.1.1-Matt.1.16\"></r>، <r v=\"Acts.7.8\"></r>، <r v=\"Acts.7.29\"></r>؛ يليه <g>ἐκ</g>، <r v=\"Matt.1.3\"></r>، <r v=\"Matt.1.5\"></r>، <r v=\"Matt.1.6\"></r>. </s> <s n=\"2.\">عن الأم، <b>تَلِد، تضع</b>: <r v=\"Luke.1.13\"></r>، <r v=\"Luke.1.57\"></r> <r v=\"Luke.23.29\"></r>، <r v=\"John.16.21\"></r>؛ <g>εἰς δουλείαν</g>، <r v=\"Gal.4.24\"></r>. المبني للمجهول <s n=\"(1)\"><b>يُحبَل به</b>، <b>يُولَد (من أب)</b>: <r v=\"Matt.1.20\"></r>؛ </s> <s n=\"(2)\"><b>يُولَد</b>: <r v=\"Matt.2.1\"></r>، <r v=\"Matt.2.4\"></r> <r v=\"Matt.19.12\"></r> <r v=\"Matt.26.24\"></r>، <r v=\"Mark.14.21\"></r>، <r v=\"Luke.1.35\"></r>، <r v=\"John.3.4\"></r>، <r v=\"Acts.7.20\"></r>، <r v=\"Rom.9.11\"></r>، <r v=\"Heb.11.23\"></r>؛ يليه <g>εἰς</g>، <r v=\"John.16.21\"></r> <r v=\"John.18.37\"></r>، <r v=\"2Pet.2.12\"></r>؛ <g>ἐν</g>، <r v=\"Acts.2.8\"></r> <r v=\"Acts.22.3\"></r>، (<g>ἁμαρτίαις</g>)، <r v=\"John.9.34\"></r>؛ <g>ἀπό</g>، <r v=\"Heb.11.12\"></r>؛ <g>ἐκ</g>، <r v=\"John.1.13\"></r> <r v=\"John.3.6\"></r> <r v=\"John.8.41\"></r>؛ مع صفة، <g>τυφλὸς γ.</g>، <r v=\"John.9.2\"></r>؛ <g>Ῥωμαῖος</g>، <r v=\"Acts.22.28\"></r>؛ <g>κατὰ σάρκα: κ. πνεῦμα</g>: <r v=\"Gal.4.29\"></r>. مجازيًا؛ <g>μάχας</g>، <r v=\"2Tim.2.23\"></r>؛ <g>ὑμᾶς ἐγέννησα</g>، <r v=\"1Cor.4.15\"></r>، (<g>ὅν</g>)، فليمون 10؛ في الاقتباس، <r v=\"Ps.2.7\"></r> (السبعينية)، <r v=\"Acts.13.33\"></r>، <r v=\"Heb.1.5\"></r> <r v=\"Heb.5.5\"></r>؛ عن المسيحيين بوصفهم مولودين من الله، مولودين ثانيةً: <r v=\"John.1.13\"></r> <r v=\"John.3.3\"></r>، <r v=\"John.3.5-John.3.8\"></r>، <r v=\"1John.2.29\"></r> <r v=\"1John.3.9\"></r> <r v=\"1John.4.7\"></r> <r v=\"1John.5.1\"></r>، <r v=\"1John.5.4\"></r>، <r v=\"1John.5.18\"></r> (قارن <g>ἀνα-γεννάω</g>).</s> </s> </s>"},"G1096":{"l":"γίνομαι","o":667,"en":"<f><o>γίνομαι</o>, Ion. and <g>κοινή</g> for Att. <g>γίγν-</g> (M. <i>Pr.</i>, 47; Bl., §6, 8 Mayser, 166 f.), </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1961\">היה</h> ;]</e> </et> <s> <s n=\"1.\">of persons, things occurrences, <b>to come into being, be born, arise, come on</b>: <r v=\"John.1.15\"></r> <r v=\"John.8.58\"></r>, <r v=\"1Cor.15.37\"></r>; a first appearance in public, <r v=\"Mark.1.4\"></r>, <r v=\"John.1.6\"></r>, al.; seq. <g>ἐκ</g> (of birth), <r v=\"Rom.1.3\"></r>, <r v=\"Gal.4.4\"></r>; <g>διά</g>, <r v=\"John.1.3\"></r>; <g>βροντή</g>, <r v=\"John.12.29\"></r>; <g>σεισμός</g>, <r v=\"Rev.6.12\"></r>; <g>γογγυσμός</g>, <r v=\"Acts.6.1\"></r>; <g>χαρά</g>, <r v=\"Acts.8.8\"></r>, many other similar exx.; <g>ἡμέρα</g>, <r v=\"Luke.22.66\"></r>, al.; <g>ὀψέ</g>, <r v=\"Mark.11.19\"></r>; <g>πρωΐα</g>, <r v=\"Matt.27.1\"></r>; <g>νύξ</g>, <r v=\"Acts.27.27\"></r>. </s> <s n=\"2.\">Of events, <b>to come to pass, take place, happen</b>: <r v=\"Matt.5.18\"></r>, <r v=\"Mark.5.14\"></r>, <r v=\"Luke.1.20\"></r> <r v=\"Luke.2.15\"></r>, <r v=\"Acts.4.21\"></r>, <r v=\"2Tim.2.18\"></r>, al.; <g>μὴ γένοιτο</g> [LXX for <h n=\"H2486\">חָלִילָה</h>, <r v=\"Josh.22.29\"></r>, al.], <b> far be it, God forbid</b>: <r v=\"Rom.3.4\"></r> (<i>ICC</i>, in l.), <r v=\"1Cor.6.15\"></r> and freq. in Pl.; <g>καὶ ἐγένετο, ἐγένετο δέ</g> ([in LXX for <h n=\"H1961\">וַיְהִי</h> ;] v. Burton, 142 f.; M, <i>Pr.</i>, 16f.; Dalman, <i>Words</i>, 32 f.; Robertson, <i>Gr.</i>, 1042 f.), c. indic, <r v=\"Matt.7.28\"></r>, <r v=\"Luke.1.8\"></r>, al.; seq. <g>καί</g> et indic., <r v=\"Luke.8.1\"></r>, <r v=\"Acts.5.7\"></r>, al.; c. acc. et inf., <r v=\"Mark.2.23\"></r>, <r v=\"Luke.3.21\"></r>, al.; <g>ὡς δὲ ἐγένετο</g>, seq. <g>τοῦ</g> c. inf., <r v=\"Acts.10.25\"></r>; c. dat. pers., <i>to befall one</i>: c. inf., <r v=\"Acts.20.16\"></r>; c. acc. et inf., <r v=\"Acts.22.6\"></r>; c. adv., <g>εὖ</g>, <r v=\"Eph.6.3\"></r>; <g>τί ἐγένετο αὐτῷ</g> (Field, <i>Notes</i>, 115), <r v=\"Acts.7.40\"></r> <i>(LXX)</i>; seq. <g>εἰς</g>, <r v=\"Acts.28.6\"></r>. </s> <s n=\"3.\"><b>to be made, done, performed, observed, enacted, ordained</b>, etc.: <r v=\"Matt.6.10\"></r> <r v=\"Matt.19.8\"></r>, <r v=\"Mark.2.27\"></r> <r v=\"Mark.11.23\"></r>, <r v=\"Acts.19.26\"></r>, al.; seq. <g>διά</g> c. gen., <r v=\"Mark.6.2\"></r>, <r v=\"Acts.2.43\"></r>; <g>ὑπό</g>, <r v=\"Luke.13.17\"></r>; <g>ἐκ</g>, <r v=\"Luke.4.23\"></r>; <g>ἐν</g>, <r v=\"1Cor.9.15\"></r>; <g>ἀπογραφή</g>, <r v=\"Luke.2.2\"></r>; <g>ἀνάκρισις</g> Ac 25:26; <g>ἄφεσις</g>, <r v=\"Heb.9.22\"></r>; <g>ὁ νόμος</g>, <r v=\"Gal.3.17\"></r>; <g>τὸ πάσχα</g>, <r v=\"Matt.26.2\"></r>. </s> <s n=\"4.\"><b>to become, be made, come to be</b>: c. pred., <r v=\"Matt.4.3\"></r>, <r v=\"Luke.4.3\"></r>, <r v=\"John.2.9\"></r>, <r v=\"1Cor.13.11\"></r>, al.; seq. <g>ὡς, ὡσεί</g>, <r v=\"Matt.10.25\"></r>, <r v=\"Mark.9.26\"></r>; <g>εἰς</g> (M, <i>Pr.</i>, 71f.), <r v=\"Mark.12.1\"></r>o, al.; c. gen. <r v=\"Rev.11.15\"></r>; id., of age, <r v=\"Luke.2.42\"></r>; c. dat., <g>γ. ἀνδρί</g> ([LXX for <h n=\"H1961,H376\">הָיָה לְאִישׁ</h>, <r v=\"Ruth.1.12\"></r>, al. ;] v. Field, <i>Notes</i>, 156), <r v=\"Rom.7.3\"></r>, 4; seq. <g>ἐν</g>, <r v=\"Acts.22.17\"></r>, <r v=\"Rev.1.10\"></r>, al.; <g>ἐπάνω</g>, <r v=\"Luke.19.19\"></r>; <g>μετά</g>, c. gen., <r v=\"Mark.16.10\"></r>, <r v=\"Acts.9.19\"></r>; seq. <g>εἰς, ἐπί</g> (Field, <i>Notes</i>, 135), <g>κατά</g> (ib., 62), c. acc. of place, <r v=\"Acts.20.16\"></r> <r v=\"Acts.21.35\"></r> <r v=\"Acts.27.7\"></r>, al.; seq. <g>ἐκ</g>, <r v=\"Mark.9.7\"></r>, <r v=\"Luke.3.22\"></r>, <r v=\"2Thess.2.7\"></r>, al. Aoristic pf. <g>γέγονα</g> (M, <i>Pr.</i>, 52, 145f.; Field, <i>Notes</i>, 1f.), <r v=\"Matt.25.6\"></r>, <r v=\"Luke.10.36\"></r>, al. Aor. <g>ἐγενήθη</g> (for <g>ἐγένετο</g>, M, <i>Pr.</i>, 139f.; Mayser, 379), <r v=\"Matt.11.23\"></r>, al. (Cf. <g>απο-, δια-, επι-, παρα-, συμ-, παρα-, προ-</g>.)</s> </s>","ar":"<f><o>γίνομαι</o>، صيغة أيونية وعامية (<g>κοινή</g>) بدل الأتيكية <g>γίγν-</g>، </f> <s> <s n=\"1.\">عن الأشخاص والأشياء والحوادث: <b>يأتي إلى الوجود، يُولَد، ينشأ، يحلّ</b>: <r v=\"John.1.15\"></r> <r v=\"John.8.58\"></r>، <r v=\"1Cor.15.37\"></r>؛ عن الظهور الأول على الملأ، <r v=\"Mark.1.4\"></r>، <r v=\"John.1.6\"></r>، وفي مواضع أخرى؛ يليه <g>ἐκ</g> (عن الولادة)، <r v=\"Rom.1.3\"></r>، <r v=\"Gal.4.4\"></r>؛ <g>διά</g>، <r v=\"John.1.3\"></r>؛ <g>βροντή</g> (رعد)، <r v=\"John.12.29\"></r>؛ <g>σεισμός</g> (زلزلة)، <r v=\"Rev.6.12\"></r>؛ <g>γογγυσμός</g> (تذمُّر)، <r v=\"Acts.6.1\"></r>؛ <g>χαρά</g> (فرح)، <r v=\"Acts.8.8\"></r>، وأمثلة أخرى كثيرة مشابهة؛ <g>ἡμέρα</g> (نهار)، <r v=\"Luke.22.66\"></r>، وفي مواضع أخرى؛ <g>ὀψέ</g> (مساء)، <r v=\"Mark.11.19\"></r>؛ <g>πρωΐα</g> (صباح)، <r v=\"Matt.27.1\"></r>؛ <g>νύξ</g> (ليل)، <r v=\"Acts.27.27\"></r>. </s> <s n=\"2.\">عن الأحداث: <b>يحدث، يقع، يجري، يصير</b>: <r v=\"Matt.5.18\"></r>، <r v=\"Mark.5.14\"></r>، <r v=\"Luke.1.20\"></r> <r v=\"Luke.2.15\"></r>، <r v=\"Acts.4.21\"></r>، <r v=\"2Tim.2.18\"></r>، وفي مواضع أخرى؛ <g>μὴ γένοιτο</g> [في السبعينية ترجمةً لـ <h n=\"H2486\">חָלִילָה</h>، <r v=\"Josh.22.29\"></r>، وفي مواضع أخرى]: <b>حاشا، لا سمح الله</b>: <r v=\"Rom.3.4\"></r>، <r v=\"1Cor.6.15\"></r>، وكثيرًا عند بولس؛ <g>καὶ ἐγένετο, ἐγένετο δέ</g> (وحدث، وكان)، مع الإخباري، <r v=\"Matt.7.28\"></r>، <r v=\"Luke.1.8\"></r>، وفي مواضع أخرى؛ يليه <g>καί</g> والإخباري، <r v=\"Luke.8.1\"></r>، <r v=\"Acts.5.7\"></r>، وفي مواضع أخرى؛ مع المنصوب والمصدر، <r v=\"Mark.2.23\"></r>، <r v=\"Luke.3.21\"></r>، وفي مواضع أخرى؛ <g>ὡς δὲ ἐγένετο</g> يليه <g>τοῦ</g> مع المصدر، <r v=\"Acts.10.25\"></r>؛ مع القابل للأشخاص: <i>يصيب أحدًا، يحدث له</i>: مع المصدر، <r v=\"Acts.20.16\"></r>؛ مع المنصوب والمصدر، <r v=\"Acts.22.6\"></r>؛ مع ظرف، <g>εὖ</g>، <r v=\"Eph.6.3\"></r>؛ <g>τί ἐγένετο αὐτῷ</g> (ماذا أصابه)، <r v=\"Acts.7.40\"></r> <i>(السبعينية)</i>؛ يليه <g>εἰς</g>، <r v=\"Acts.28.6\"></r>. </s> <s n=\"3.\"><b>يُصنَع، يُعمَل، يُنجَز، يُحفَظ، يُسَنّ، يُرسَم</b>، إلخ: <r v=\"Matt.6.10\"></r> <r v=\"Matt.19.8\"></r>، <r v=\"Mark.2.27\"></r> <r v=\"Mark.11.23\"></r>، <r v=\"Acts.19.26\"></r>، وفي مواضع أخرى؛ يليه <g>διά</g> مع المضاف إليه، <r v=\"Mark.6.2\"></r>، <r v=\"Acts.2.43\"></r>؛ <g>ὑπό</g>، <r v=\"Luke.13.17\"></r>؛ <g>ἐκ</g>، <r v=\"Luke.4.23\"></r>؛ <g>ἐν</g>، <r v=\"1Cor.9.15\"></r>؛ <g>ἀπογραφή</g> (اكتتاب)، <r v=\"Luke.2.2\"></r>؛ <g>ἀνάκρισις</g> (فحص)، أعمال 25: 26؛ <g>ἄφεσις</g> (مغفرة)، <r v=\"Heb.9.22\"></r>؛ <g>ὁ νόμος</g> (الناموس)، <r v=\"Gal.3.17\"></r>؛ <g>τὸ πάσχα</g> (الفصح)، <r v=\"Matt.26.2\"></r>. </s> <s n=\"4.\"><b>يصير، يُجعَل، يغدو</b>: مع الخبر، <r v=\"Matt.4.3\"></r>، <r v=\"Luke.4.3\"></r>، <r v=\"John.2.9\"></r>، <r v=\"1Cor.13.11\"></r>، وفي مواضع أخرى؛ يليه <g>ὡς, ὡσεί</g>، <r v=\"Matt.10.25\"></r>، <r v=\"Mark.9.26\"></r>؛ <g>εἰς</g>، <r v=\"Mark.12.1\"></r>، وفي مواضع أخرى؛ مع المضاف إليه، <r v=\"Rev.11.15\"></r>؛ وكذلك عن العُمر، <r v=\"Luke.2.42\"></r>؛ مع القابل، <g>γ. ἀνδρί</g> (تصير لرجل) [في السبعينية ترجمةً لـ <h n=\"H1961,H376\">הָיָה לְאִישׁ</h>، <r v=\"Ruth.1.12\"></r>، وفي مواضع أخرى]، <r v=\"Rom.7.3\"></r>، 4؛ يليه <g>ἐν</g>، <r v=\"Acts.22.17\"></r>، <r v=\"Rev.1.10\"></r>، وفي مواضع أخرى؛ <g>ἐπάνω</g>، <r v=\"Luke.19.19\"></r>؛ <g>μετά</g> مع المضاف إليه، <r v=\"Mark.16.10\"></r>، <r v=\"Acts.9.19\"></r>؛ يليه <g>εἰς, ἐπί</g>، <g>κατά</g>، مع المنصوب للمكان، <r v=\"Acts.20.16\"></r> <r v=\"Acts.21.35\"></r> <r v=\"Acts.27.7\"></r>، وفي مواضع أخرى؛ يليه <g>ἐκ</g>، <r v=\"Mark.9.7\"></r>، <r v=\"Luke.3.22\"></r>، <r v=\"2Thess.2.7\"></r>، وفي مواضع أخرى. التام بمعنى الماضي البسيط <g>γέγονα</g>، <r v=\"Matt.25.6\"></r>، <r v=\"Luke.10.36\"></r>، وفي مواضع أخرى. الماضي البسيط <g>ἐγενήθη</g> (بدل <g>ἐγένετο</g>)، <r v=\"Matt.11.23\"></r>، وفي مواضع أخرى. (قارن <g>απο-, δια-, επι-, παρα-, συμ-, παρα-, προ-</g>.)</s> </s>"},"G1106":{"l":"γνώμη","o":9,"en":"<f><o>γνώμη</o>, <g>-ης, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>γιγνώσκω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Bel.2.15\"></r> (<h n=\"H1881\">דָּת</h>), <r v=\"LXX:Ps.82.3\"></r> (<h n=\"H5475\">סוֹד</h>), elsewhere, chiefly II Es, for <h n=\"H2942\">טְעֵם</h> ;]</e> </et> <s> <s n=\"1.\"><b>a means of knowing, a token</b> (Theogn.). </s> <s n=\"2.\">In Attic writers, <b>the mind</b>, its operations and results (v. Edwards, <i>Lex.</i>, <i>App.</i>, A); <s n=\"(a)\"><b>mind, understanding</b>; </s> <s n=\"(b)\"><b>purpose, intention</b>: <r v=\"Acts.20.3\"></r>; </s> <s n=\"(c)\"><b>judgment, opinion</b>: <r v=\"1Cor.1.10\"></r>, <r v=\"Rev.17.13\"></r>; </s> <s n=\"(d)\"><b>counsel, advice</b>: <r v=\"1Cor.7.25\"></r>, <r v=\"1Cor.7.40\"></r> <r v=\"2Cor.8.10\"></r>, <r v=\"Phlm.1.14\"></r>; </s> <s n=\"(e)\"><b>royal purpose, decree</b> (as in Da, I and II Es): <r v=\"Rev.17.17\"></r> (Cremer, 671).</s> †</s> </s>","ar":"<f><o>γνώμη</o>، <g>-ης, ἡ</g> </f> <s> <s n=\"1.\"><b>وسيلة للمعرفة، علامة</b>. </s> <s n=\"2.\"><b>الذهن</b>، وعملياته ونتائجها؛ <s n=\"(a)\"><b>ذهن، فهم</b>؛ </s> <s n=\"(b)\"><b>قصد، نيّة</b>: <r v=\"Acts.20.3\"></r>؛ </s> <s n=\"(c)\"><b>حُكم، رأي</b>: <r v=\"1Cor.1.10\"></r>، <r v=\"Rev.17.13\"></r>؛ </s> <s n=\"(d)\"><b>مشورة، نصيحة</b>: <r v=\"1Cor.7.25\"></r>، <r v=\"1Cor.7.40\"></r> <r v=\"2Cor.8.10\"></r>، <r v=\"Phlm.1.14\"></r>؛ </s> <s n=\"(e)\"><b>قصد ملكي، أمر</b> (كما في دانيال وعزرا الأول والثاني): <r v=\"Rev.17.17\"></r>.</s> †</s> </s>"},"G1125":{"l":"γράφω","o":191,"en":"<f><o>γράφω</o>, [in LXX chiefly for <h n=\"H3789\">כּתב</h> ]; </f> <s> <s n=\"1.\"><b>to scrape, graze</b> (Hom.), and later (Hdt.) <b>to sketch, draw</b>. </s> <s n=\"2.\"><b>to write</b>; <s n=\"(a)\">of forming or tracing letters on writing material: <r v=\"John.8.6\"></r>, <r v=\"Gal.6.11\"></r>, <r v=\"2Thess.3.17\"></r>; </s> <s n=\"(b)\">to express in writing, commit to writing, record: <r v=\"Luke.1.63\"></r>, <r v=\"John.19.21\"></r>, <r v=\"John.19.22\"></r> <r v=\"Rev.1.11\"></r>, <r v=\"Rev.1.19\"></r> al.; of scripture as a standing authority (Deiss., <i>BS</i>, 112ff.), <g>γέγραπται</g>, <i>it stands written</i> (Luther), <r v=\"Matt.4.4\"></r>, <r v=\"Mark.7.6\"></r>, <r v=\"Luke.4.8\"></r>, <r v=\"Rom.1.17\"></r>, <r v=\"1Cor.1.31\"></r>, al.; id. seq. <g>ἐν</g>, <r v=\"Mark.1.2\"></r>, <r v=\"Acts.1.20\"></r>, al.; c. acc., <b>to write of</b>: <r v=\"John.1.46\"></r>, <r v=\"Rom.10.5\"></r>; seq. <g>περί</g>, <r v=\"Matt.26.24\"></r>, <r v=\"Mark.14.21\"></r>, <r v=\"John.5.46\"></r>; al.; c. dat. (WM, §31, 4), <r v=\"Luke.18.31\"></r>; id. seq. <g>ἵνα</g> (M, <i>Pr.</i>, 207f.), <r v=\"Mark.12.19\"></r>, <r v=\"Luke.20.28\"></r>; <g>κατὰ τ. γεγραμμένον</g>, <r v=\"2Cor.4.13\"></r>; <g>γεγραμμένον ἐστί</g>, <r v=\"John.2.17\"></r>; <g>ἐγράφη</g>, <r v=\"Rom.4.24\"></r>; <g>ἐπ’ αὐτῷ γεγραμμένα</g>, <r v=\"John.12.16\"></r>; </s> <s n=\"(c)\">of writing directions or information, c. dat. pers.: <r v=\"Rom.15.15\"></r>, <r v=\"2Cor.7.12\"></r>, al.; </s> <s n=\"(d)\">of that which contains the record or message: <g>βιβλίον</g>, <r v=\"Mark.10.4\"></r>, <r v=\"John.21.25\"></r>, <r v=\"Rev.5.1\"></r>; <g>τίτλον</g>, <r v=\"John.19.19\"></r>; <g>ἐπιστολήν</g>, <r v=\"Acts.23.25\"></r>; <g>ἐντολήν</g>, <r v=\"Mark.10.5\"></r> (cf. <g>ἀπο-, ἐγ-, ἐπι-, κατα-, προ-</g>).</s> </s> </s>","ar":"<f><o>γράφω</o>، </f> <s> <s n=\"1.\"><b>كشط، خدش</b>، ثم لاحقًا <b>رسم، خطّ</b>. </s> <s n=\"2.\"><b>كتب</b>؛ <s n=\"(a)\">عن تشكيل الحروف أو رسمها على مادة الكتابة: <r v=\"John.8.6\"></r>، <r v=\"Gal.6.11\"></r>، <r v=\"2Thess.3.17\"></r>؛ </s> <s n=\"(b)\">التعبير كتابةً، التدوين، التسجيل: <r v=\"Luke.1.63\"></r>، <r v=\"John.19.21\"></r>، <r v=\"John.19.22\"></r>، <r v=\"Rev.1.11\"></r>، <r v=\"Rev.1.19\"></r>، وفي مواضع أخرى؛ عن الكتاب المقدس بوصفه سلطة قائمة: <g>γέγραπται</g>: <i>مكتوب</i>: <r v=\"Matt.4.4\"></r>، <r v=\"Mark.7.6\"></r>، <r v=\"Luke.4.8\"></r>، <r v=\"Rom.1.17\"></r>، <r v=\"1Cor.1.31\"></r>، وفي مواضع أخرى؛ ونفسه يليه <g>ἐν</g>: <r v=\"Mark.1.2\"></r>، <r v=\"Acts.1.20\"></r>، وفي مواضع أخرى؛ مع المنصوب: <b>كتب عن</b>: <r v=\"John.1.46\"></r>، <r v=\"Rom.10.5\"></r>؛ يليه <g>περί</g>: <r v=\"Matt.26.24\"></r>، <r v=\"Mark.14.21\"></r>، <r v=\"John.5.46\"></r>، وفي مواضع أخرى؛ مع القابل: <r v=\"Luke.18.31\"></r>؛ ونفسه يليه <g>ἵνα</g>: <r v=\"Mark.12.19\"></r>، <r v=\"Luke.20.28\"></r>؛ <g>κατὰ τ. γεγραμμένον</g>: <r v=\"2Cor.4.13\"></r>؛ <g>γεγραμμένον ἐστί</g>: <r v=\"John.2.17\"></r>؛ <g>ἐγράφη</g>: <r v=\"Rom.4.24\"></r>؛ <g>ἐπ’ αὐτῷ γεγραμμένα</g>: <r v=\"John.12.16\"></r>؛ </s> <s n=\"(c)\">عن كتابة التوجيهات أو الأخبار، مع القابل للشخص: <r v=\"Rom.15.15\"></r>، <r v=\"2Cor.7.12\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(d)\">عمّا يحوي السجل أو الرسالة: <g>βιβλίον</g>: <r v=\"Mark.10.4\"></r>، <r v=\"John.21.25\"></r>، <r v=\"Rev.5.1\"></r>؛ <g>τίτλον</g>: <r v=\"John.19.19\"></r>؛ <g>ἐπιστολήν</g>: <r v=\"Acts.23.25\"></r>؛ <g>ἐντολήν</g>: <r v=\"Mark.10.5\"></r> (قارن <g>ἀπο-, ἐγ-, ἐπι-, κατα-, προ-</g>).</s> </s> </s>"},"G1198":{"l":"δέσμιος","o":16,"en":"<f><o>δέσμιος</o>, <g>-ον</g> (also <g>-α, -ον</g>; </f> <et> <e t=\"derivation\">&lt; <g>δεσμός</g>), [in LXX for <h n=\"H631\">אסר</h>;]</e> </et> <s n=\"1.\"><b>binding</b>. </s> <s n=\"2.\"><b>bound, captive</b>; <g>ὁ δ.</g>, as subst., <b>a prisoner</b>: <r v=\"Matt.27.15\"></r>, <r v=\"Matt.27.16\"></r>, <r v=\"Mark.15.6\"></r>, <r v=\"Acts.16.25\"></r>, <r v=\"Acts.16.27\"></r> <r v=\"Acts.23.18\"></r> <r v=\"Acts.25.14\"></r>, <r v=\"Acts.25.27\"></r> <r v=\"Acts.28.16\"></r> (Rec.) <r v=\"Acts.28.17\"></r>, <r v=\"Heb.10.34\"></r> <r v=\"Heb.13.3\"></r>; <g>ὁ δ. τοῦ Χριστοῦ</g>, <r v=\"Eph.3.1\"></r>, <r v=\"2Tim.1.8\"></r>, <r v=\"Phlm.1.1\"></r>, <r v=\"Phlm.1.9\"></r>; <g>ὁ δ. ἐν κυρίῳ</g>, <r v=\"Eph.4.1\"></r>.†</s>","ar":"<f><o>δέσμιος</o>، <g>-ον</g> (وأيضًا <g>-α, -ον</g>)؛ </f> <s n=\"1.\"><b>رابط</b>. </s> <s n=\"2.\"><b>مقيَّد، أسير</b>؛ <g>ὁ δ.</g> اسمًا: <b>سجين، أسير</b>: <r v=\"Matt.27.15\"></r>، <r v=\"Matt.27.16\"></r>، <r v=\"Mark.15.6\"></r>، <r v=\"Acts.16.25\"></r>، <r v=\"Acts.16.27\"></r>، <r v=\"Acts.23.18\"></r>، <r v=\"Acts.25.14\"></r>، <r v=\"Acts.25.27\"></r>، <r v=\"Acts.28.16\"></r>، <r v=\"Acts.28.17\"></r>، <r v=\"Heb.10.34\"></r>، <r v=\"Heb.13.3\"></r>؛ <g>ὁ δ. τοῦ Χριστοῦ</g>: <r v=\"Eph.3.1\"></r>، <r v=\"2Tim.1.8\"></r>، <r v=\"Phlm.1.1\"></r>، <r v=\"Phlm.1.9\"></r>؛ <g>ὁ δ. ἐν κυρίῳ</g>: <r v=\"Eph.4.1\"></r>.†</s>"},"G1199":{"l":"δεσμός","o":3,"en":"<f><o>δεσμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>δέω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H631\">אסר</h> ;] </e> </et> <s><b>a band, bond</b>: metaph., <r v=\"Luke.13.16\"></r>; <g>ὁ δεσμὸς τ. γλώσσης</g>, <r v=\"Mark.7.35\"></r> (for this expression in <g>π.</g>, v. Deiss., <i>LAE</i>, 306 ff.; of actual bonds, v. Ruth., <i>Gr.</i>, 9). Pl., <g>δεσμοί</g>, <r v=\"Phil.1.13\"></r>; <g>δεσμά</g> (as also in cl.), <r v=\"Luke.8.29\"></r>, <r v=\"Acts.16.26\"></r> <r v=\"Acts.20.23\"></r>; gen., dat., <r v=\"Acts.23.29\"></r> <r v=\"Acts.26.29\"></r>, <r v=\"Acts.26.31\"></r>, <r v=\"Phil.1.7\"></r>, <r v=\"Phil.1.14\"></r>, <r v=\"Phil.1.17\"></r>, <r v=\"Col.4.18\"></r>, <r v=\"2Tim.2.9\"></r>, <r v=\"Phlm.1.10\"></r>, <r v=\"Heb.11.36\"></r>, <r v=\"Jude.1.6\"></r>; <g>ἐν τοῖς δ. τοῦ εὐαγγελίου</g> <r v=\"Phlm.1.13\"></r>.†</s>","ar":"<f><o>δεσμός</o>، <g>-οῦ, ὁ</g></f> <s><b>رباط، قيد</b>: مجازيًا: <r v=\"Luke.13.16\"></r>؛ <g>ὁ δεσμὸς τ. γλώσσης</g>: <r v=\"Mark.7.35\"></r>. الجمع <g>δεσμοί</g>: <r v=\"Phil.1.13\"></r>؛ <g>δεσμά</g>: <r v=\"Luke.8.29\"></r>، <r v=\"Acts.16.26\"></r>، <r v=\"Acts.20.23\"></r>؛ المضاف إليه والقابل: <r v=\"Acts.23.29\"></r>، <r v=\"Acts.26.29\"></r>، <r v=\"Acts.26.31\"></r>، <r v=\"Phil.1.7\"></r>، <r v=\"Phil.1.14\"></r>، <r v=\"Phil.1.17\"></r>، <r v=\"Col.4.18\"></r>، <r v=\"2Tim.2.9\"></r>، <r v=\"Phlm.1.10\"></r>، <r v=\"Heb.11.36\"></r>، <r v=\"Jude.1.6\"></r>؛ <g>ἐν τοῖς δ. τοῦ εὐαγγελίου</g> <r v=\"Phlm.1.13\"></r>.†</s>"},"G1214":{"l":"Δημᾶς","o":3,"en":"<f><o>Δημᾶς</o>, <g>ὁ</g></f> <et> <e t=\"derivation\">(perh. contracted from <g>Δημήτριος</g>), </e> </et> <s><b>Demas</b>, a companion of St. Paul: <r v=\"Col.4.14\"></r>, <r v=\"Phlm.1.24\"></r>, <r v=\"2Tim.4.10\"></r>.†</s>","ar":"<f><o>Δημᾶς</o>، <g>ὁ</g></f> <s><b>ديماس</b>، رفيق القديس بولس: <r v=\"Col.4.14\"></r>، <r v=\"Phlm.1.24\"></r>، <r v=\"2Tim.4.10\"></r>.†</s>"},"G1223":{"l":"διά","o":720,"en":"<f><o>διά</o> (before a vowel <g>δ’</g>, exc. <r v=\"Rom.8.10\"></r>, <r v=\"2Cor.5.7\"></r>, and in pr. names; Tdf., <i>Pr.</i>, 94), </f> prep. c. gen., acc, as in cl.; <s> <s n=\"1.\">c. gen., <b>through</b>; <s n=\"(i)\">of Place, after verbs of motion or action: <r v=\"Matt.2.12\"></r> <r v=\"Matt.12.43\"></r>, <r v=\"Mark.2.23\"></r>, <r v=\"Luke.4.30\"></r>, <r v=\"John.4.4\"></r>, <r v=\"2Cor.11.33\"></r>, al.; <g>σώζεσθαι (διας-) δ. πυρός, ὕδατος</g>, <r v=\"1Cor.3.15\"></r>, <r v=\"1Pet.3.20\"></r>; <g>βλέπειν δ. ἐσόπτρου</g>, <r v=\"1Cor.13.12\"></r>; metaph., of a state or condition: <r v=\"Rom.14.20\"></r>, <r v=\"2Cor.2.4\"></r> <r v=\"2Cor.5.7\"></r>, 10; <g>δ. γράμματος, ἀκροβυστίας</g> (Lft., <i>Notes</i>, 263, 279), <r v=\"Rom.2.27\"></r> <r v=\"Rom.4.11\"></r>; <g>δι’ ὑπομενῆς</g>, <r v=\"Rom.8.25\"></r>. </s> <s n=\"(ii)\">Of Time; <s n=\"(a)\">during which: <r v=\"Matt.26.61\"></r>, <r v=\"Mark.14.58\"></r>, <r v=\"Luke.5.5\"></r>; <g>δ. παντὸς τοῦ ζῆν</g>, <r v=\"Heb.2.15\"></r>; <g>δ. παντός</g> (<g>διαπαντός</g> in <r v=\"Mark.5.5\"></r>, <r v=\"Luke.24.53\"></r>), <b>always, continually</b>, <r v=\"Matt.18.10\"></r>, <r v=\"Acts.2.25\"></r> <i>(LXX)</i> <r v=\"Acts.10.1\"></r> <r v=\"Acts.24.16\"></r>, <r v=\"Rom.11.10\"></r> <i>(LXX)</i>, <r v=\"2Thess.3.16\"></r>, <r v=\"Heb.9.6\"></r> <r v=\"Heb.13.15\"></r>. </s> <s n=\"(b)\">within which: <r v=\"Acts.1.3\"></r>; <g>δ. νυκτός</g>, <r v=\"Acts.5.19\"></r> <r v=\"Acts.16.9\"></r> <r v=\"Acts.17.10\"></r> <r v=\"Acts.23.31\"></r>; </s> <s n=\"(c)\">after which (Field, <i>Notes</i>, 20; Abbott, <i>JG</i>, 255 f.): <r v=\"Mark.2.1\"></r>, <r v=\"Acts.24.17\"></r>, <r v=\"Gal.2.1\"></r>. </s> </s> <s n=\"(iii)\">Of the Means or Instrument; <s n=\"(1)\">of the efficient cause (regarded also as the instrument): of God, <r v=\"Rom.11.36\"></r>, <r v=\"1Cor.1.9\"></r>, <r v=\"Gal.4.7\"></r>, <r v=\"Heb.2.10\"></r> <r v=\"Heb.7.21\"></r>; of Christ, <r v=\"Rom.1.8\"></r> <r v=\"Rom.5.1\"></r>, <r v=\"Rom.5.17\"></r>, <r v=\"1Cor.15.21\"></r>, <r v=\"1Pet.4.11\"></r>, al.; <g>δ. τ. ὑμῶν δεήσεως</g>, <r v=\"Rom.1.12\"></r>, <r v=\"2Cor.1.4\"></r>, <r v=\"Gal.4.23\"></r>, al.; </s> <s n=\"(2)\">of the agent, instrument or means; <s n=\"(a)\">c. gen. pers., <r v=\"Matt.11.2\"></r>, <r v=\"Luke.1.70\"></r>, <r v=\"John.1.17\"></r>, <r v=\"Acts.1.16\"></r>, <r v=\"Rom.2.16\"></r>, <r v=\"1Cor.1.21\"></r>, <r v=\"Eph.1.5\"></r>, <r v=\"Heb.2.14\"></r>, <r v=\"Rev.1.1\"></r>, al.; <g>ὑπὸ τ. κυρίου δ. τ. προφήτου</g> (<g>δ. τ. κυρίου</g>, <r v=\"1Thess.4.2\"></r> (M, <i>Th.</i>, in l.); Lft., <i>Rev.</i>, 121 f.), <r v=\"Matt.1.22\"></r> <r v=\"Matt.2.15\"></r>, <r v=\"Rom.1.2\"></r>; <g>δ. ἐπιστολῆς ὡς δ. ἡμῶν</g> (Field, <i>Notes</i>, 202), <r v=\"2Thess.2.2\"></r>; <g>δ. Σ.</g> (<i>NTD</i>, 22), <r v=\"1Pet.5.12\"></r>; </s> <s n=\"(b)\"> c. gen. rei (where often the simple dat. is used in cl.; Jannaris, <i>Gr.</i>, 375), <r v=\"John.11.4\"></r>, <r v=\"Acts.5.12\"></r>; <g>δ. τ. πίστεως</g>, <r v=\"Rom.3.30\"></r>; <g>δ. λόγου θεοῦ</g>, <r v=\"1Pet.1.23\"></r>; <g>δ. παραβολῆς</g>, <r v=\"Luke.8.4\"></r>; <g>δουλεύειν δ. τ. ἀγάπης</g>, <r v=\"Gal.5.13\"></r>; <g>δ. ἐπαγγελίας</g>, <r v=\"Gal.3.18\"></r>.</s> </s> </s> </s> <s n=\"2.\">C. acc.; <s n=\"(i)\">rarely, as c. gen., <b>through</b> (Hom), <g>δ. μέσον Σαμαρίας</g> (<i>ICC</i>, in l.; Bl., §42, 1; Robertson, <i>Gr.</i>, 581), <r v=\"Luke.17.11\"></r>. </s> <s n=\"(ii)\"><b>by reason of, because of, for the sake of</b>; <s n=\"(a)\">c. acc pers. (M, <i>Pr.</i>, 105), <r v=\"Mark.2.27\"></r>, <r v=\"John.6.57\"></r> <r v=\"John.11.42\"></r>, <r v=\"Rom.8.20\"></r>; </s> <s n=\"(b)\">c. acc. rei, <g>δ. φθόνον</g>, <r v=\"Matt.27.18\"></r>, <r v=\"Mark.15.10\"></r>; <g>δ. φόβον</g>, <r v=\"John.7.13\"></r> <r v=\"John.20.19\"></r>; <g>δ. ἀγάπην</g>, <r v=\"Eph.2.4\"></r>; <g>δ. τοῦτο</g>, freq., <b>for this cause, therefore</b>, <r v=\"Matt.6.25\"></r>, <r v=\"Mark.6.14\"></r>, <r v=\"Luke.11.49\"></r>, <r v=\"John.6.65\"></r>, al.; id. seq. <g>ὅτι</g>, <r v=\"John.5.16\"></r> <r v=\"John.10.17\"></r>, al.; <g>δ. τί</g>, <b>why</b>, <r v=\"Matt.9.11\"></r>, <r v=\"Matt.9.14\"></r>, <r v=\"Mark.2.18\"></r>, <r v=\"John.7.45\"></r>, al.; <g>δ. τό</g>, c. inf., <r v=\"Mark.5.4\"></r>, <r v=\"Luke.9.7\"></r>, <r v=\"Jas.4.2\"></r>. </s> </s> </s> <s n=\"3.\">In composition, <s n=\"(1)\"><b>through</b>, as in <g>διαβαίνω</g>; </s> <s n=\"(2)\">of separation, <b>asunder</b>, as in <g>διασπάω</g>; </s> <s n=\"(3)\">of distribution, <b>abroad</b>, as in <g>διαγγέλλω</g>; </s> <s n=\"(4)\">of transition, as <g>διαλλάσσω</g>; </s> <s n=\"(5)\">of \"perfective\" action (M, <i>Pr.</i>, 112 f., 115 f.), as <g>διαφύγω, διακαθαρίζω</g>. </s> </s> </s>","ar":"<f><o>διά</o> (قبل الحرف الصائت <g>δ’</g>، إلا في <r v=\"Rom.8.10\"></r>، <r v=\"2Cor.5.7\"></r>، وفي أسماء العَلَم)، </f> حرف جر مع المضاف إليه ومع المنصوب؛ <s> <s n=\"1.\">مع المضاف إليه: <b>عبر، خلال، بـ</b>؛ <s n=\"(i)\">للمكان، بعد أفعال الحركة أو الفعل: <r v=\"Matt.2.12\"></r> <r v=\"Matt.12.43\"></r>، <r v=\"Mark.2.23\"></r>، <r v=\"Luke.4.30\"></r>، <r v=\"John.4.4\"></r>، <r v=\"2Cor.11.33\"></r>، وفي مواضع أخرى؛ <g>σώζεσθαι (διας-) δ. πυρός, ὕδατος</g> (الخلاص عبر النار، عبر الماء)، <r v=\"1Cor.3.15\"></r>، <r v=\"1Pet.3.20\"></r>؛ <g>βλέπειν δ. ἐσόπτρου</g> (النظر في مرآة)، <r v=\"1Cor.13.12\"></r>؛ مجازيًا، عن حال أو وضع: <r v=\"Rom.14.20\"></r>، <r v=\"2Cor.2.4\"></r> <r v=\"2Cor.5.7\"></r>، 10؛ <g>δ. γράμματος, ἀκροβυστίας</g>، <r v=\"Rom.2.27\"></r> <r v=\"Rom.4.11\"></r>؛ <g>δι’ ὑπομενῆς</g>، <r v=\"Rom.8.25\"></r>. </s> <s n=\"(ii)\">للزمان؛ <s n=\"(a)\">الزمن الذي يقع الفعل في أثنائه: <r v=\"Matt.26.61\"></r>، <r v=\"Mark.14.58\"></r>، <r v=\"Luke.5.5\"></r>؛ <g>δ. παντὸς τοῦ ζῆν</g>، <r v=\"Heb.2.15\"></r>؛ <g>δ. παντός</g> (<g>διαπαντός</g> في <r v=\"Mark.5.5\"></r>، <r v=\"Luke.24.53\"></r>): <b>كل حين، دائمًا</b>، <r v=\"Matt.18.10\"></r>، <r v=\"Acts.2.25\"></r> <i>(السبعينية)</i> <r v=\"Acts.10.1\"></r> <r v=\"Acts.24.16\"></r>، <r v=\"Rom.11.10\"></r> <i>(السبعينية)</i>، <r v=\"2Thess.3.16\"></r>، <r v=\"Heb.9.6\"></r> <r v=\"Heb.13.15\"></r>. </s> <s n=\"(b)\">الزمن الذي يقع الفعل في غضونه: <r v=\"Acts.1.3\"></r>؛ <g>δ. νυκτός</g> (ليلاً)، <r v=\"Acts.5.19\"></r> <r v=\"Acts.16.9\"></r> <r v=\"Acts.17.10\"></r> <r v=\"Acts.23.31\"></r>؛ </s> <s n=\"(c)\">الزمن الذي يقع الفعل بعده: <r v=\"Mark.2.1\"></r>، <r v=\"Acts.24.17\"></r>، <r v=\"Gal.2.1\"></r>. </s> </s> <s n=\"(iii)\">للوسيلة أو الأداة؛ <s n=\"(1)\">للعلة الفاعلة (منظورًا إليها أيضًا كأداة): عن الله، <r v=\"Rom.11.36\"></r>، <r v=\"1Cor.1.9\"></r>، <r v=\"Gal.4.7\"></r>، <r v=\"Heb.2.10\"></r> <r v=\"Heb.7.21\"></r>؛ عن المسيح، <r v=\"Rom.1.8\"></r> <r v=\"Rom.5.1\"></r>، <r v=\"Rom.5.17\"></r>، <r v=\"1Cor.15.21\"></r>، <r v=\"1Pet.4.11\"></r>، وفي مواضع أخرى؛ <g>δ. τ. ὑμῶν δεήσεως</g>، <r v=\"Rom.1.12\"></r>، <r v=\"2Cor.1.4\"></r>، <r v=\"Gal.4.23\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(2)\">للفاعل الوسيط أو الأداة أو الوسيلة؛ <s n=\"(a)\">مع المضاف إليه للأشخاص، <r v=\"Matt.11.2\"></r>، <r v=\"Luke.1.70\"></r>، <r v=\"John.1.17\"></r>، <r v=\"Acts.1.16\"></r>، <r v=\"Rom.2.16\"></r>، <r v=\"1Cor.1.21\"></r>، <r v=\"Eph.1.5\"></r>، <r v=\"Heb.2.14\"></r>، <r v=\"Rev.1.1\"></r>، وفي مواضع أخرى؛ <g>ὑπὸ τ. κυρίου δ. τ. προφήτου</g> (من الرب بالنبي) (<g>δ. τ. κυρίου</g>، <r v=\"1Thess.4.2\"></r>)، <r v=\"Matt.1.22\"></r> <r v=\"Matt.2.15\"></r>، <r v=\"Rom.1.2\"></r>؛ <g>δ. ἐπιστολῆς ὡς δ. ἡμῶν</g>، <r v=\"2Thess.2.2\"></r>؛ <g>δ. Σ.</g>، <r v=\"1Pet.5.12\"></r>؛ </s> <s n=\"(b)\"> مع المضاف إليه للأشياء، <r v=\"John.11.4\"></r>، <r v=\"Acts.5.12\"></r>؛ <g>δ. τ. πίστεως</g> (بالإيمان)، <r v=\"Rom.3.30\"></r>؛ <g>δ. λόγου θεοῦ</g>، <r v=\"1Pet.1.23\"></r>؛ <g>δ. παραβολῆς</g>، <r v=\"Luke.8.4\"></r>؛ <g>δουλεύειν δ. τ. ἀγάπης</g>، <r v=\"Gal.5.13\"></r>؛ <g>δ. ἐπαγγελίας</g>، <r v=\"Gal.3.18\"></r>.</s> </s> </s> </s> <s n=\"2.\">مع المنصوب؛ <s n=\"(i)\">نادرًا، كما مع المضاف إليه: <b>عبر، في وسط</b>، <g>δ. μέσον Σαμαρίας</g>، <r v=\"Luke.17.11\"></r>. </s> <s n=\"(ii)\"><b>بسبب، من أجل، لأجل</b>؛ <s n=\"(a)\">مع المنصوب للأشخاص، <r v=\"Mark.2.27\"></r>، <r v=\"John.6.57\"></r> <r v=\"John.11.42\"></r>، <r v=\"Rom.8.20\"></r>؛ </s> <s n=\"(b)\">مع المنصوب للأشياء، <g>δ. φθόνον</g> (حسدًا)، <r v=\"Matt.27.18\"></r>، <r v=\"Mark.15.10\"></r>؛ <g>δ. φόβον</g>، <r v=\"John.7.13\"></r> <r v=\"John.20.19\"></r>؛ <g>δ. ἀγάπην</g>، <r v=\"Eph.2.4\"></r>؛ <g>δ. τοῦτο</g>، كثيرًا: <b>لهذا السبب، لذلك</b>، <r v=\"Matt.6.25\"></r>، <r v=\"Mark.6.14\"></r>، <r v=\"Luke.11.49\"></r>، <r v=\"John.6.65\"></r>، وفي مواضع أخرى؛ والتعبير نفسه يليه <g>ὅτι</g>، <r v=\"John.5.16\"></r> <r v=\"John.10.17\"></r>، وفي مواضع أخرى؛ <g>δ. τί</g>: <b>لماذا</b>، <r v=\"Matt.9.11\"></r>، <r v=\"Matt.9.14\"></r>، <r v=\"Mark.2.18\"></r>، <r v=\"John.7.45\"></r>، وفي مواضع أخرى؛ <g>δ. τό</g> مع المصدر، <r v=\"Mark.5.4\"></r>، <r v=\"Luke.9.7\"></r>، <r v=\"Jas.4.2\"></r>. </s> </s> </s> <s n=\"3.\">في التركيب، <s n=\"(1)\"><b>عبر، خلال</b>، كما في <g>διαβαίνω</g>؛ </s> <s n=\"(2)\">للانفصال: <b>إلى قطع، تفريقًا</b>، كما في <g>διασπάω</g>؛ </s> <s n=\"(3)\">للتوزيع: <b>في كل مكان، هنا وهناك</b>، كما في <g>διαγγέλλω</g>؛ </s> <s n=\"(4)\">للانتقال (التحوُّل)، كما في <g>διαλλάσσω</g>؛ </s> <s n=\"(5)\">للفعل «التام» (الإتمام والاستيفاء)، كما في <g>διαφύγω, διακαθαρίζω</g>. </s> </s> </s>"},"G1247":{"l":"διακονέω","o":37,"en":"<f>* <o>διακονέω</o>, <g>ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>δίακονος</g>); </e> </et> <s n=\"1.\">generally, <b>to minister, serve, wait upon</b>, especially at table, <b>to do one a service, care for one's needs</b>: absol., <r v=\"Matt.20.28\"></r>, <r v=\"Mark.10.45\"></r>, <r v=\"Luke.10.40\"></r> <r v=\"Luke.22.26\"></r>, <r v=\"Luke.22.27\"></r>, <r v=\"John.12.2\"></r>, <r v=\"1Pet.4.11\"></r>; <g>ὅσα διηκόνησεν</g>, <r v=\"2Tim.1.18\"></r>; c. dat. pers., <r v=\"Matt.4.11\"></r> <r v=\"Matt.8.15\"></r> <r v=\"Matt.25.44\"></r> <r v=\"Matt.27.55\"></r>, <r v=\"Mark.1.13\"></r>, <r v=\"Mark.1.31\"></r> <r v=\"Mark.15.41\"></r>, <r v=\"Luke.4.39\"></r> <r v=\"Luke.8.3\"></r> <r v=\"Luke.12.37\"></r> <r v=\"Luke.17.8\"></r>, <r v=\"John.12.26\"></r>, <r v=\"Acts.6.2\"></r> <r v=\"Acts.19.22\"></r>, <r v=\"Rom.15.25\"></r>, <r v=\"Phlm.1.13\"></r>, <r v=\"Heb.6.10\"></r>. </s> <s n=\"2.\"><b>to serve as deacon</b>: <r v=\"1Tim.3.10\"></r>, <r v=\"1Tim.3.13\"></r>. </s> <s n=\"3.\">C. acc. rei, <b>to minister, supply, supply by ministration</b>: <r v=\"1Pet.1.12\"></r> <r v=\"1Pet.4.10\"></r>; pass., <r v=\"2Cor.3.3\"></r> <r v=\"2Cor.8.19\"></r>, <r v=\"2Cor.8.20\"></r>.†</s> <sy><i>SYN.</i>: <g>λειτουργέω</g>, q.v. (Cremer, 179).</sy>","ar":"<f>* <o>διακονέω</o>، <g>ῶ</g></f> <s n=\"1.\">بوجه عام، <b>يخدم، يقوم بخدمة، يقوم على خدمة</b>، خاصةً على المائدة، <b>يؤدي لأحدٍ خدمة، يسدّ حاجاته</b>: مطلقًا، <r v=\"Matt.20.28\"></r>، <r v=\"Mark.10.45\"></r>، <r v=\"Luke.10.40\"></r> <r v=\"Luke.22.26\"></r>، <r v=\"Luke.22.27\"></r>، <r v=\"John.12.2\"></r>، <r v=\"1Pet.4.11\"></r>؛ <g>ὅσα διηκόνησεν</g>، <r v=\"2Tim.1.18\"></r>؛ مع قابل الشخص، <r v=\"Matt.4.11\"></r> <r v=\"Matt.8.15\"></r> <r v=\"Matt.25.44\"></r> <r v=\"Matt.27.55\"></r>، <r v=\"Mark.1.13\"></r>، <r v=\"Mark.1.31\"></r> <r v=\"Mark.15.41\"></r>، <r v=\"Luke.4.39\"></r> <r v=\"Luke.8.3\"></r> <r v=\"Luke.12.37\"></r> <r v=\"Luke.17.8\"></r>، <r v=\"John.12.26\"></r>، <r v=\"Acts.6.2\"></r> <r v=\"Acts.19.22\"></r>، <r v=\"Rom.15.25\"></r>، <r v=\"Phlm.1.13\"></r>، <r v=\"Heb.6.10\"></r>. </s> <s n=\"2.\"><b>يخدم شمّاسًا</b>: <r v=\"1Tim.3.10\"></r>، <r v=\"1Tim.3.13\"></r>. </s> <s n=\"3.\">مع منصوب الشيء، <b>يخدم بـ، يقدّم، يقدّم بالخدمة</b>: <r v=\"1Pet.1.12\"></r> <r v=\"1Pet.4.10\"></r>؛ المبني للمجهول، <r v=\"2Cor.3.3\"></r> <r v=\"2Cor.8.19\"></r>، <r v=\"2Cor.8.20\"></r>.†</s>"},"G1352":{"l":"διό","o":52,"en":"<f><o>διό </o></f> <s>conjunct. for <g>δι᾽ ὅ</g>, </s> <s><b>wherefore, on which account</b>: <r v=\"Matt.27.8\"></r>, <r v=\"Luke.7.7\"></r>, <r v=\"Acts.15.19\"></r>, <r v=\"Rom.1.24\"></r>, al.; <g>δ. καί</g>, <r v=\"Luke.1.35\"></r>, <r v=\"Acts.10.29\"></r> <r v=\"Acts.24.26\"></r>, <r v=\"Rom.4.22\"></r> <r v=\"Rom.15.22\"></r>, <r v=\"2Cor.1.20\"></r> <r v=\"2Cor.4.13\"></r> <r v=\"2Cor.5.9\"></r>, <r v=\"Phil.2.9\"></r>, <r v=\"Heb.11.12\"></r> <r v=\"Heb.13.12\"></r> (v. Ellic. on <r v=\"Gal.4.31\"></r>).</s>","ar":"<f><o>διό </o></f> <s>أداة ربط بمعنى <g>δι᾽ ὅ</g>، </s> <s><b>لذلك، لهذا السبب</b>: <r v=\"Matt.27.8\"></r>، <r v=\"Luke.7.7\"></r>، <r v=\"Acts.15.19\"></r>، <r v=\"Rom.1.24\"></r>، وفي مواضع أخرى؛ <g>δ. καί</g>: <r v=\"Luke.1.35\"></r>، <r v=\"Acts.10.29\"></r>، <r v=\"Acts.24.26\"></r>، <r v=\"Rom.4.22\"></r>، <r v=\"Rom.15.22\"></r>، <r v=\"2Cor.1.20\"></r>، <r v=\"2Cor.4.13\"></r>، <r v=\"2Cor.5.9\"></r>، <r v=\"Phil.2.9\"></r>، <r v=\"Heb.11.12\"></r>، <r v=\"Heb.13.12\"></r> (قارن <r v=\"Gal.4.31\"></r>).</s>"},"G1401":{"l":"δοῦλος","o":124,"en":"<f><o>δοῦλος</o>, <g>-η, -ον</g>, </f> <et> <e t=\"septuagint\">[in LXX, <g>ὁ δ.</g> nearly always for <h n=\"H5650\">עֶבֶד</h>; <g>ἡ δ.</g> chiefly for <h n=\"H8198,H519\">שִׁפְחָה ,אָמָה</h> ;]</e> </et> <s> <s n=\"1.\"><b>in bondage to, subject to</b>: <r v=\"Rom.6.19\"></r>. </s> <s n=\"2.\">As subst., <g>ὁ, ἡ δ.</g>, <b>a slave</b>; <s n=\"(a)\">fem., <g>ἡ δ.</g>, <b>a female slave, bondmaid</b> (Cremer, 702; <i>DB</i>, iii, 215): <r v=\"Luke.1.38\"></r>, <r v=\"Luke.1.48\"></r>, <r v=\"Acts.2.18\"></r> <i>(LXX)</i>; </s> <s n=\"(b)\">masc., <g>ὁ δ.</g>, <b>a slave, bondman</b>: <r v=\"Matt.8.9\"></r> <r v=\"Matt.18.23\"></r>, al.; opp. to <g>ἐλεύθερος</g>, <r v=\"1Cor.7.22\"></r> <r v=\"1Cor.12.13\"></r>, <r v=\"Gal.3.28\"></r>, <r v=\"Eph.6.8\"></r>, <r v=\"Col.3.11\"></r>, <r v=\"Rev.6.15\"></r> <r v=\"Rev.13.16\"></r> <r v=\"Rev.19.18\"></r>; opp. to <g>κύριος, δεσπότης, οἰκοδεσπότης</g>, <r v=\"Matt.10.24\"></r> <r v=\"Matt.13.27\"></r>, <r v=\"Matt.13.28\"></r>, <r v=\"Luke.12.46\"></r>, <r v=\"John.15.15\"></r>, <r v=\"Eph.6.5\"></r>, <r v=\"Col.3.22\"></r> <r v=\"Col.4.1\"></r>, al.; metaph., <g>δ. Χριστοῦ, τοῦ Χρ., Ἰησοῦ Χρ.</g>, <r v=\"Rom.1.1\"></r>, <r v=\"1Cor.7.22\"></r>, <r v=\"Gal.1.10\"></r>, <r v=\"Eph.6.6\"></r>, <r v=\"Phil.1.1\"></r>, <r v=\"Col.4.12\"></r>, <r v=\"Jas.1.1\"></r>, <r v=\"2Pet.1.1\"></r>, <r v=\"Jude.1.1\"></r>; <g>δ. τ. θεοῦ, τ. κυρίου</g>, <r v=\"Acts.16.17\"></r>, <r v=\"2Tim.2.24\"></r>, <r v=\"Titus.1.1\"></r>, <r v=\"1Pet.2.16\"></r>, <r v=\"Rev.7.3\"></r> <r v=\"Rev.15.3\"></r>; <g>δ. πονηρός, ἀχρεῖος, κακός</g>, <r v=\"Matt.18.32\"></r> <r v=\"Matt.24.48\"></r> <r v=\"Matt.25.26\"></r>, <r v=\"Matt.25.30\"></r>, <r v=\"Luke.17.10\"></r> <r v=\"Luke.19.22\"></r>; <g>δ. ἁμαρτίας</g>, <r v=\"John.8.34\"></r>, <r v=\"Rom.6.17\"></r>, <r v=\"Rom.6.20\"></r>; <g>τ. φθορᾶς</g>, <r v=\"2Pet.2.19\"></r>. </s> </s> </s> <sy><i>SYN.</i>: <g>διάκονος</g> (q.v.), <g>θεράπων, ὐπηρέτης</g> (v. <i>DB</i>, iii, 377; iv, 461, 469; <i>DCG</i>, i, 221; ii, 613; Cremer, 215, 702).</sy>","ar":"<f><o>δοῦλος</o>، <g>-η, -ον</g>، </f> <s> <s n=\"1.\"><b>مُستعبَد لـ، خاضع لـ</b>: <r v=\"Rom.6.19\"></r>. </s> <s n=\"2.\">اسمًا، <g>ὁ, ἡ δ.</g>: <b>عبد</b>؛ <s n=\"(a)\">مؤنث، <g>ἡ δ.</g>: <b>أَمَة، جارية</b>: <r v=\"Luke.1.38\"></r>، <r v=\"Luke.1.48\"></r>، <r v=\"Acts.2.18\"></r> <i>(السبعينية)</i>؛ </s> <s n=\"(b)\">مذكر، <g>ὁ δ.</g>: <b>عبد، مملوك</b>: <r v=\"Matt.8.9\"></r> <r v=\"Matt.18.23\"></r>، وفي مواضع أخرى؛ عكس <g>ἐλεύθερος</g> (حُرّ)، <r v=\"1Cor.7.22\"></r> <r v=\"1Cor.12.13\"></r>، <r v=\"Gal.3.28\"></r>، <r v=\"Eph.6.8\"></r>، <r v=\"Col.3.11\"></r>، <r v=\"Rev.6.15\"></r> <r v=\"Rev.13.16\"></r> <r v=\"Rev.19.18\"></r>؛ عكس <g>κύριος, δεσπότης, οἰκοδεσπότης</g> (سيد، رب البيت)، <r v=\"Matt.10.24\"></r> <r v=\"Matt.13.27\"></r>، <r v=\"Matt.13.28\"></r>، <r v=\"Luke.12.46\"></r>، <r v=\"John.15.15\"></r>، <r v=\"Eph.6.5\"></r>، <r v=\"Col.3.22\"></r> <r v=\"Col.4.1\"></r>، وفي مواضع أخرى؛ مجازيًا، <g>δ. Χριστοῦ, τοῦ Χρ., Ἰησοῦ Χρ.</g> (عبد المسيح، عبد يسوع المسيح)، <r v=\"Rom.1.1\"></r>، <r v=\"1Cor.7.22\"></r>، <r v=\"Gal.1.10\"></r>، <r v=\"Eph.6.6\"></r>، <r v=\"Phil.1.1\"></r>، <r v=\"Col.4.12\"></r>، <r v=\"Jas.1.1\"></r>، <r v=\"2Pet.1.1\"></r>، <r v=\"Jude.1.1\"></r>؛ <g>δ. τ. θεοῦ, τ. κυρίου</g> (عبد الله، عبد الرب)، <r v=\"Acts.16.17\"></r>، <r v=\"2Tim.2.24\"></r>، <r v=\"Titus.1.1\"></r>، <r v=\"1Pet.2.16\"></r>، <r v=\"Rev.7.3\"></r> <r v=\"Rev.15.3\"></r>؛ <g>δ. πονηρός, ἀχρεῖος, κακός</g> (العبد الشرير، البطّال، الرديء)، <r v=\"Matt.18.32\"></r> <r v=\"Matt.24.48\"></r> <r v=\"Matt.25.26\"></r>، <r v=\"Matt.25.30\"></r>، <r v=\"Luke.17.10\"></r> <r v=\"Luke.19.22\"></r>؛ <g>δ. ἁμαρτίας</g> (عبد الخطية)، <r v=\"John.8.34\"></r>، <r v=\"Rom.6.17\"></r>، <r v=\"Rom.6.20\"></r>؛ <g>τ. φθορᾶς</g> (عبيد الفساد)، <r v=\"2Pet.2.19\"></r>. </s> </s> </s>"},"G1473":{"l":"ἐγώ","o":2572,"en":"<f><o>ἐγώ</o>, gen, etc., <g>ἐμοῦ, ἐμοί, ἐμέ</g> (enclitic <g>μου, μοι, με</g>), pl. <g>ἡμεῖς, -ῶν, -ῖν, -ᾶς</g>, </f> pers. pron. <s><b>I</b>. <s n=\"(a)\">The nom. is usually emphatic, when expressed as subjc, as in <r v=\"Matt.3.11\"></r>, <r v=\"Mark.1.8\"></r>, <r v=\"Luke.3.16\"></r>, al. But often there is no apparent emphasis, as <r v=\"Matt.10.16\"></r>, <r v=\"John.10.17\"></r>; <g>ἰδοὺ ἐ.</g> (= Heb. <h n=\"H2005\">הִנֵּנִי</h>, cf. <r v=\"1Kgs.3.8\"></r>), <r v=\"Acts.9.10\"></r>; <g>ἐ.</g> (like Heb. <h n=\"H589\">אֲנִי</h>), <b>I am</b>, <r v=\"John.1.23\"></r>, <r v=\"Acts.7.32\"></r>. </s> <s n=\"(b)\">The enclitic forms (v. supr.) are used with nouns, adjectives, verbs, adverbs, where there is no emphasis: <g>ἐν τ. πατρί μου</g>, <r v=\"John.14.20\"></r>; <g>μου τ. λόγους</g>, <r v=\"Matt.7.24\"></r>; <g>ὀπίσω μου</g>, <r v=\"Matt.3.11\"></r>; <g>ἰσχυρότερός μου</g>, <r v=\"Matt.3.11\"></r>; <g>λέγει μοι</g>, <r v=\"Rev.5.5\"></r>; also with the prep. <g>πρός</g>, as <r v=\"Mark.9.19\"></r>, al. The full forms (<g>ἐμοῦ</g>, etc.) are used with the other prepositions, as <g>δι' ἐμοῦ, ἐν ἐμοί, εἰς ἐμέ</g>, etc., also for emphasis, as <r v=\"Luke.10.16\"></r>, <r v=\"John.7.23\"></r>, <r v=\"Mark.14.7\"></r>, al. </s> <s n=\"(c)\">The gen. <g>μου</g> and <g>ἡμῶν</g> are often used for the poss. pronouns <g>ἐμός, ἡμέτερος: τ. λαόν μου</g>, <r v=\"Matt.2.6\"></r>; <g>μου τῂ ἀπιστιᾳ</g>, <r v=\"Mark.9.24\"></r>. </s> <s n=\"(d)\"><g>τί ἐμοὶ καὶ σοί</g> ( = Heb. <h n=\"H4100\">וָלָךְ מַה־לִי</h>, <r v=\"Judg.11.12\"></r>, al.), i.e. <b>what have we in common</b>: <r v=\"Matt.8.29\"></r>, <r v=\"Mark.1.24\"></r> <r v=\"Mark.5.7\"></r>, <r v=\"Luke.8.28\"></r>, <r v=\"John.2.4\"></r>; <g>τί γάρ μοι</g>, <r v=\"1Cor.5.2\"></r>. </s> <s n=\"(e)\">The interchange of <g>ἐγώ</g> and <g>ἡμεῖς</g>, common in <g>π.</g>, appears in Pauline Epp. (v. M, <i>Pr.</i>, 86f., M, <i>Th.</i>, 131f.).</s> <s n=\"(f)\"><g>κἀγώ</g> (= <g>καὶ ἐγώ</g>, <b>and I, even I, I also</b>: <r v=\"Matt.2.8\"></r>, <r v=\"Luke.2.48\"></r>, <r v=\"John.6.56\"></r>, <r v=\"Rom.3.7\"></r>, <r v=\"1Cor.7.40\"></r>, al.; <g>κἀγώ . . . καί</g>, <b>both . . . and</b>, <r v=\"John.7.28\"></r>.</s> </s>","ar":"<f><o>ἐγώ</o>، حالة الجر إلخ: <g>ἐμοῦ, ἐμοί, ἐμέ</g> (الملحقة: <g>μου, μοι, με</g>)، الجمع: <g>ἡμεῖς, -ῶν, -ῖν, -ᾶς</g>، </f> ضمير شخصي. <s><b>أنا</b>. <s n=\"(a)\">حالة الرفع تفيد التوكيد عادةً حين تُذكر فاعلاً، كما في <r v=\"Matt.3.11\"></r>، <r v=\"Mark.1.8\"></r>، <r v=\"Luke.3.16\"></r>، وفي مواضع أخرى. لكن كثيرًا ما لا يظهر توكيد، كما في <r v=\"Matt.10.16\"></r>، <r v=\"John.10.17\"></r>؛ <g>ἰδοὺ ἐ.</g> (هأنذا) (= بالعبرية <h n=\"H2005\">הִנֵּנִי</h>، قارن <r v=\"1Kgs.3.8\"></r>)، <r v=\"Acts.9.10\"></r>؛ <g>ἐ.</g> (مثل العبرية <h n=\"H589\">אֲנִי</h>): <b>أنا هو</b>، <r v=\"John.1.23\"></r>، <r v=\"Acts.7.32\"></r>. </s> <s n=\"(b)\">تُستعمل الصيغ الملحقة (انظر أعلاه) مع الأسماء والصفات والأفعال والظروف حيث لا توكيد: <g>ἐν τ. πατρί μου</g> (في أبي)، <r v=\"John.14.20\"></r>؛ <g>μου τ. λόγους</g> (أقوالي)، <r v=\"Matt.7.24\"></r>؛ <g>ὀπίσω μου</g> (بعدي)، <r v=\"Matt.3.11\"></r>؛ <g>ἰσχυρότερός μου</g> (أقوى مني)، <r v=\"Matt.3.11\"></r>؛ <g>λέγει μοι</g> (قال لي)، <r v=\"Rev.5.5\"></r>؛ وكذلك مع حرف الجر <g>πρός</g>، كما في <r v=\"Mark.9.19\"></r>، وفي مواضع أخرى. وتُستعمل الصيغ الكاملة (<g>ἐμοῦ</g> إلخ) مع سائر حروف الجر، مثل <g>δι' ἐμοῦ, ἐν ἐμοί, εἰς ἐμέ</g> إلخ، وكذلك للتوكيد، كما في <r v=\"Luke.10.16\"></r>، <r v=\"John.7.23\"></r>، <r v=\"Mark.14.7\"></r>، وفي مواضع أخرى. </s> <s n=\"(c)\">كثيرًا ما تُستعمل حالة الجر <g>μου</g> و<g>ἡμῶν</g> بدل ضميري الملكية <g>ἐμός, ἡμέτερος: τ. λαόν μου</g> (شعبي)، <r v=\"Matt.2.6\"></r>؛ <g>μου τῂ ἀπιστιᾳ</g> (عدم إيماني)، <r v=\"Mark.9.24\"></r>. </s> <s n=\"(d)\"><g>τί ἐμοὶ καὶ σοί</g> ( = بالعبرية <h n=\"H4100\">וָלָךְ מַה־לִי</h>، <r v=\"Judg.11.12\"></r>، وفي مواضع أخرى)، أي <b>ما لي ولك، ما الذي يجمعنا</b>: <r v=\"Matt.8.29\"></r>، <r v=\"Mark.1.24\"></r> <r v=\"Mark.5.7\"></r>، <r v=\"Luke.8.28\"></r>، <r v=\"John.2.4\"></r>؛ <g>τί γάρ μοι</g> (ماذا لي)، <r v=\"1Cor.5.2\"></r>. </s> <s n=\"(e)\">التبادل بين <g>ἐγώ</g> و<g>ἡμεῖς</g> يظهر في رسائل بولس.</s> <s n=\"(f)\"><g>κἀγώ</g> (= <g>καὶ ἐγώ</g>): <b>وأنا، حتى أنا، أنا أيضًا</b>: <r v=\"Matt.2.8\"></r>، <r v=\"Luke.2.48\"></r>، <r v=\"John.6.56\"></r>، <r v=\"Rom.3.7\"></r>، <r v=\"1Cor.7.40\"></r>، وفي مواضع أخرى؛ <g>κἀγώ . . . καί</g>: <b>كلٌّ من . . . و</b>، <r v=\"John.7.28\"></r>.</s> </s>"},"G1492":{"l":"οἶδα","o":300,"en":"<f><o>οἶδα</o>, (from same root as <g>εἶδον</g>, q.v.),</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3045\">ידע</h>;]</e> <e t=\"derivation\">pf. with pres. meaning (plpf. as impf.; on irregular tense-forms, v. App.),</e> </et> <s><b>to have seen</b> or <b>perceived</b>, hence, <b>to know</b>, <b>have knowledge of</b>: c. acc. rei, <r v=\"Matt.25.13\"></r>, <r v=\"Mark.10.19\"></r>, <r v=\"John.10.4\"></r>, <r v=\"Rom.7.7\"></r>, al.; c. acc. pers., <r v=\"Matt.26.72\"></r>, <r v=\"John.1.31\"></r>, <r v=\"Acts.3.16\"></r>, al.; <g>τ. θεόν</g>, <r v=\"1Thess.4.5\"></r>, <r v=\"Titus.1.16\"></r>, al.; c. acc. et inf., <r v=\"Luke.4.41\"></r>, al.; seq. <g>ὅτι</g>, <r v=\"Matt.9.6\"></r>, <r v=\"Luke.20.21\"></r>, <r v=\"John.3.2\"></r>, <r v=\"Rom.2.2\"></r> <r v=\"Rom.11.2\"></r>, al.; seq. quaest. indir., <r v=\"Matt.26.70\"></r>, <r v=\"John.9.21\"></r>, <r v=\"Eph.1.18\"></r>, al.; c. inf., <b>to know how</b> (cl.), <r v=\"Matt.7.11\"></r>, <r v=\"Luke.11.13\"></r>, <r v=\"Phil.4.12\"></r>, <r v=\"1Thess.4.4\"></r>, al.; in unique sense of <b>respect</b>, <b>appreciate</b>: <r v=\"1Thess.5.12\"></r> (but v. also <i>ICC</i> on <r v=\"1Thess.4.4\"></r>).</s> <sy><i>SYN.</i>: v.s. <g>γινώσκω</g>.</sy>","ar":"<f><o>οἶδα</o>، (من الجذر نفسه الذي منه <g>εἶδον</g>، انظره)،</f> <s><b>يكون قد رأى</b> أو <b>أدرك</b>، ومن ثَمَّ: <b>يعرف</b>، <b>يعلم</b>: مع المنصوب للأشياء، <r v=\"Matt.25.13\"></r>، <r v=\"Mark.10.19\"></r>، <r v=\"John.10.4\"></r>، <r v=\"Rom.7.7\"></r>، وفي مواضع أخرى؛ مع المنصوب للأشخاص، <r v=\"Matt.26.72\"></r>، <r v=\"John.1.31\"></r>، <r v=\"Acts.3.16\"></r>، وفي مواضع أخرى؛ <g>τ. θεόν</g> (يعرف الله)، <r v=\"1Thess.4.5\"></r>، <r v=\"Titus.1.16\"></r>، وفي مواضع أخرى؛ مع المنصوب والمصدر، <r v=\"Luke.4.41\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g>، <r v=\"Matt.9.6\"></r>، <r v=\"Luke.20.21\"></r>، <r v=\"John.3.2\"></r>، <r v=\"Rom.2.2\"></r> <r v=\"Rom.11.2\"></r>، وفي مواضع أخرى؛ يليه سؤال غير مباشر، <r v=\"Matt.26.70\"></r>، <r v=\"John.9.21\"></r>، <r v=\"Eph.1.18\"></r>، وفي مواضع أخرى؛ مع المصدر: <b>يعرف كيف</b>، <r v=\"Matt.7.11\"></r>، <r v=\"Luke.11.13\"></r>، <r v=\"Phil.4.12\"></r>، <r v=\"1Thess.4.4\"></r>، وفي مواضع أخرى؛ وبمعنى فريد: <b>يحترم</b>، <b>يقدِّر</b>: <r v=\"1Thess.5.12\"></r> (وانظر أيضًا <r v=\"1Thess.4.4\"></r>).</s>"},"G1510":{"l":"εἰμί","o":2456,"en":"<f><o>εἰμί</o>, </f> <s>with various uses and significations, like the English verb <b>to be</b>. <s n=\"I.\">As substantive verb. <s n=\"1.\">Of persons and things, <b>to be, exist</b>: <r v=\"Acts.17.28\"></r>, <r v=\"John.1.1\"></r> <r v=\"John.8.58\"></r> <r v=\"John.17.5\"></r>, al; <g>ὁ ὢν καὶ ὁ ἦν</g> (for past ptcp.), <r v=\"Rev.1.4\"></r>, <r v=\"Rev.1.8\"></r> <r v=\"Rev.4.8\"></r> <r v=\"Rev.11.17\"></r> <r v=\"Rev.16.5\"></r> (v. Swete, <i>Ap.</i>, 5; M, <i>Pr.</i>, 228); <g>τὰ (μὴ) ὄντα</g>, <r v=\"Rom.4.17\"></r>, <r v=\"1Cor.1.28\"></r>. </s> <s n=\"2.\">Of times, events, etc., <b>to be, happen, take place</b>: <r v=\"Matt.24.3\"></r>, <r v=\"Mark.14.2\"></r> <r v=\"Mark.15.42\"></r>, <r v=\"Luke.21.23\"></r>, <r v=\"John.4.6\"></r>, <r v=\"John.4.23\"></r> <r v=\"John.5.10\"></r>, al. </s> <s n=\"3.\"><b>to be present, be</b> in a place, <b>have come</b>: <r v=\"Matt.2.13\"></r>, <r v=\"Matt.2.15\"></r>, <r v=\"Mark.1.45\"></r> <r v=\"Mark.5.21\"></r> <r v=\"Mark.15.40\"></r>, <r v=\"Luke.1.80\"></r> <r v=\"Luke.5.29\"></r>, <r v=\"John.7.30\"></r>, al.; seq. <g>εἰς</g>, <r v=\"Mark.2.1\"></r>; seq. <g>ἐκ, (ἐξ)</g>, <r v=\"Matt.1.20\"></r> <r v=\"Matt.21.25\"></r>, <r v=\"Mark.11.30\"></r>, <r v=\"John.3.31\"></r>, al. </s> <s n=\"4.\">Impers., <g>ἔστι, ἦν</g>, etc.; <s n=\"(a)\"><b>there is</b> (Fr. <i>il y a</i>), <b>was</b>, etc.: <r v=\"Matt.16.28\"></r>, <r v=\"Luke.16.19\"></r>, <r v=\"John.3.1\"></r> <r v=\"John.5.2\"></r>, <r v=\"Rom.3.10\"></r>, al.; c. dat. (of the possessor; Bl., §37, 3), <r v=\"Matt.16.22\"></r>, <r v=\"Luke.1.7\"></r>, <r v=\"John.18.10\"></r>, <r v=\"Rom.9.2\"></r>, al.; <g>ἔστιν ὅς, ὅστις</g> (chiefly in pl), <r v=\"Matt.16.28\"></r> <r v=\"Matt.19.2\"></r>, <r v=\"Mark.9.1\"></r>, al.; </s> <s n=\"(b)\">c. inf., = <g>ἔξεστιν</g> (q.v.), <b>it is possible</b>: <r v=\"Heb.9.5\"></r>, <r v=\"1Cor.11.20\"></r>, RV (but v. <i>ICC</i>, in l.).</s> </s> </s> <s n=\"II.\">As copula uniting subject and predicate. <s n=\"1.\">Expressing simply identity or equivalence: <r v=\"Matt.5.13\"></r> <r v=\"Matt.14.15\"></r>, <r v=\"Luke.1.18\"></r>, <r v=\"Luke.1.19\"></r>, <r v=\"John.1.1\"></r> <r v=\"John.4.19\"></r>, <r v=\"Rev.3.9\"></r>, al. mult.</s> <s n=\"2.\">Explicative, as in parable, figure, type, etc.: <r v=\"Matt.13.19\"></r>, <r v=\"1Cor.9.2\"></r>, <r v=\"1Cor.10.4\"></r>, <r v=\"1Cor.11.25\"></r>, <r v=\"Gal.4.24\"></r>, <r v=\"Rev.17.15\"></r>, al.; <g>τοῦτ’ ἔστιν</g>, <r v=\"Matt.27.46\"></r>, <r v=\"Mark.7.2\"></r>, <r v=\"Rom.7.18\"></r> al.; <g>ὅ ἐστιν</g>, <r v=\"Mark.3.17\"></r>, <r v=\"Col.1.24\"></r>, <r v=\"Heb.7.2\"></r>, al.; akin to this is the sacramental usage: <r v=\"Matt.26.26-Matt.26.28\"></r>, <r v=\"Mark.14.22\"></r>, <r v=\"Mark.14.24\"></r>, <r v=\"Luke.22.19\"></r>, <r v=\"1Cor.11.24\"></r> (v. <i>ICC</i> on Mk, I Co, ll. c.; <i>DB</i>, iii, 148 f.). </s> <s n=\"3.\">C. gen.: qual., etc., <r v=\"Mark.5.42\"></r>, <r v=\"Luke.3.23\"></r>, <r v=\"1Cor.14.33\"></r>, <r v=\"Heb.12.11\"></r>, al.; part., <r v=\"1Tim.1.20\"></r>, <r v=\"2Tim.1.15\"></r>; poss., <r v=\"Matt.5.3\"></r>, <r v=\"Matt.5.10\"></r>, <r v=\"Mark.12.7\"></r>, <r v=\"Luke.4.7\"></r>; of service or partisanship, <r v=\"Rom.8.9\"></r>, <r v=\"1Cor.1.12\"></r>, <r v=\"2Cor.10.7\"></r>, <r v=\"2Tim.2.19\"></r>. </s> <s n=\"4.\">C. dat. (BL, §37, 3): <r v=\"Acts.1.8\"></r> <r v=\"Acts.9.15\"></r>, <r v=\"Rom.4.12\"></r>, <r v=\"1Cor.1.18\"></r> <r v=\"1Cor.2.14\"></r>, <r v=\"Rev.21.7\"></r>, al. </s> <s n=\"5.\">C. ptcp., as a periphrasis for the simple verb (Bl., §62, 1, 2; M, <i>Pr.</i>, 225 ff.); <s n=\"(a)\">c. ptcp. pf. (cl.): <r v=\"Matt.10.30\"></r>, <r v=\"Luke.9.32\"></r>, <r v=\"John.3.24\"></r>, <r v=\"Acts.21.35\"></r>, <r v=\"1Cor.15.19\"></r>, al; </s> <s n=\"(b)\">c. ptcp. pr. (esp. in impf., as in Heb. and Aram.; Dalman, <i>Words</i>, 35 f.), <r v=\"Matt.7.29\"></r>, <r v=\"Mark.1.22\"></r>, <r v=\"Luke.4.31\"></r> <r v=\"Luke.14.1\"></r>, <r v=\"Acts.1.10\"></r>, al. mult., id. for imper. (M, <i>Pr.</i>, 180f., 182f.), with ellipsis of <g>εἰμί</g>, <r v=\"Rom.12.9\"></r>, <r v=\"Rom.12.10\"></r>, <r v=\"Heb.13.5\"></r>, al.;</s> <s n=\"(c)\">c. ptcp. aor. (cl), <r v=\"Luke.23.9\"></r>.</s> </s> <s n=\"6.\">Seq. <g>εἰς</g> (cf. Heb. <h n=\"H1961\">הָיָה לְ</h>), a vernac. usage (M, <i>Pr.</i>, 71): <r v=\"Matt.19.5\"></r>, <r v=\"Mark.10.8\"></r>, <r v=\"Heb.8.10\"></r>, al. </s> <s n=\"7.\">C. adv.: <r v=\"Matt.19.20\"></r>, <r v=\"Mark.4.26\"></r>, <r v=\"Luke.18.11\"></r>, al. </s> <s n=\"8.\">Ellipses; <s n=\"(a)\">of the copula (Bl., §30, 3): <r v=\"Matt.8.29\"></r> <r v=\"Matt.24.32\"></r>, <r v=\"John.21.22\"></r>, <r v=\"John.21.23\"></r>, <r v=\"Heb.6.4\"></r>, al.;</s> <s n=\"(b)\">of the predicate: <g>ἐγώ εἰμί</g>, <r v=\"Matt.14.27\"></r>, <r v=\"Mark.6.50\"></r>, al.; absol. (cf. <r v=\"Deut.32.39\"></r>; <h n=\"H589,H1931\">אֲנִי הוּא</h>), <r v=\"Mark.13.6\"></r>, <r v=\"John.4.26\"></r>, al. (cf. <g>ἄπ-, ἔν-, πάρ-, συμ-πάρ-, σύν-ειμι</g>).</s> </s> </s> </s>","ar":"<f><o>εἰμί</o>، </f> <s>له استعمالات ومعانٍ متنوعة، مثل الفعل «<b>كان، يكون</b>». <s n=\"I.\">بوصفه فعل وجود. <s n=\"1.\">عن الأشخاص والأشياء: <b>كان، وُجد</b>: <r v=\"Acts.17.28\"></r>، <r v=\"John.1.1\"></r>، <r v=\"John.8.58\"></r>، <r v=\"John.17.5\"></r>، وفي مواضع أخرى؛ <g>ὁ ὢν καὶ ὁ ἦν</g> (بدلاً من اسم فاعل ماضٍ): <r v=\"Rev.1.4\"></r>، <r v=\"Rev.1.8\"></r>، <r v=\"Rev.4.8\"></r>، <r v=\"Rev.11.17\"></r>، <r v=\"Rev.16.5\"></r>؛ <g>τὰ (μὴ) ὄντα</g>: <r v=\"Rom.4.17\"></r>، <r v=\"1Cor.1.28\"></r>. </s> <s n=\"2.\">عن الأزمنة والأحداث ونحوها: <b>كان، حدث، وقع</b>: <r v=\"Matt.24.3\"></r>، <r v=\"Mark.14.2\"></r>، <r v=\"Mark.15.42\"></r>، <r v=\"Luke.21.23\"></r>، <r v=\"John.4.6\"></r>، <r v=\"John.4.23\"></r>، <r v=\"John.5.10\"></r>، وفي مواضع أخرى. </s> <s n=\"3.\"><b>حضر، كان</b> في مكان، <b>أتى</b>: <r v=\"Matt.2.13\"></r>، <r v=\"Matt.2.15\"></r>، <r v=\"Mark.1.45\"></r>، <r v=\"Mark.5.21\"></r>، <r v=\"Mark.15.40\"></r>، <r v=\"Luke.1.80\"></r>، <r v=\"Luke.5.29\"></r>، <r v=\"John.7.30\"></r>، وفي مواضع أخرى؛ يليه <g>εἰς</g>: <r v=\"Mark.2.1\"></r>؛ يليه <g>ἐκ, (ἐξ)</g>: <r v=\"Matt.1.20\"></r>، <r v=\"Matt.21.25\"></r>، <r v=\"Mark.11.30\"></r>، <r v=\"John.3.31\"></r>، وفي مواضع أخرى. </s> <s n=\"4.\">غير شخصي، <g>ἔστι, ἦν</g> إلخ؛ <s n=\"(a)\"><b>يوجد</b>، <b>كان يوجد</b> إلخ: <r v=\"Matt.16.28\"></r>، <r v=\"Luke.16.19\"></r>، <r v=\"John.3.1\"></r>، <r v=\"John.5.2\"></r>، <r v=\"Rom.3.10\"></r>، وفي مواضع أخرى؛ مع القابل (للدلالة على المالك): <r v=\"Matt.16.22\"></r>، <r v=\"Luke.1.7\"></r>، <r v=\"John.18.10\"></r>، <r v=\"Rom.9.2\"></r>، وفي مواضع أخرى؛ <g>ἔστιν ὅς, ὅστις</g> (غالبًا في الجمع): <r v=\"Matt.16.28\"></r>، <r v=\"Matt.19.2\"></r>، <r v=\"Mark.9.1\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(b)\">مع المصدر، بمعنى <g>ἔξεστιν</g> (انظره): <b>يمكن، يجوز</b>: <r v=\"Heb.9.5\"></r>، <r v=\"1Cor.11.20\"></r>.</s> </s> </s> <s n=\"II.\">بوصفه رابطًا بين المبتدأ والخبر. <s n=\"1.\">للتعبير عن مجرد الهوية أو المساواة: <r v=\"Matt.5.13\"></r>، <r v=\"Matt.14.15\"></r>، <r v=\"Luke.1.18\"></r>، <r v=\"Luke.1.19\"></r>، <r v=\"John.1.1\"></r>، <r v=\"John.4.19\"></r>، <r v=\"Rev.3.9\"></r>، ومواضع أخرى كثيرة.</s> <s n=\"2.\">تفسيري، كما في المثل والتشبيه والرمز ونحوها: <r v=\"Matt.13.19\"></r>، <r v=\"1Cor.9.2\"></r>، <r v=\"1Cor.10.4\"></r>، <r v=\"1Cor.11.25\"></r>، <r v=\"Gal.4.24\"></r>، <r v=\"Rev.17.15\"></r>، وفي مواضع أخرى؛ <g>τοῦτ’ ἔστιν</g>: <r v=\"Matt.27.46\"></r>، <r v=\"Mark.7.2\"></r>، <r v=\"Rom.7.18\"></r>، وفي مواضع أخرى؛ <g>ὅ ἐστιν</g>: <r v=\"Mark.3.17\"></r>، <r v=\"Col.1.24\"></r>، <r v=\"Heb.7.2\"></r>، وفي مواضع أخرى؛ ويقرب من هذا الاستعمال الأسراري: <r v=\"Matt.26.26-Matt.26.28\"></r>، <r v=\"Mark.14.22\"></r>، <r v=\"Mark.14.24\"></r>، <r v=\"Luke.22.19\"></r>، <r v=\"1Cor.11.24\"></r>. </s> <s n=\"3.\">مع المضاف إليه: للنوع ونحوه: <r v=\"Mark.5.42\"></r>، <r v=\"Luke.3.23\"></r>، <r v=\"1Cor.14.33\"></r>، <r v=\"Heb.12.11\"></r>، وفي مواضع أخرى؛ للتبعيض: <r v=\"1Tim.1.20\"></r>، <r v=\"2Tim.1.15\"></r>؛ للملكية: <r v=\"Matt.5.3\"></r>، <r v=\"Matt.5.10\"></r>، <r v=\"Mark.12.7\"></r>، <r v=\"Luke.4.7\"></r>؛ للخدمة أو الانتماء إلى فريق: <r v=\"Rom.8.9\"></r>، <r v=\"1Cor.1.12\"></r>، <r v=\"2Cor.10.7\"></r>، <r v=\"2Tim.2.19\"></r>. </s> <s n=\"4.\">مع القابل: <r v=\"Acts.1.8\"></r>، <r v=\"Acts.9.15\"></r>، <r v=\"Rom.4.12\"></r>، <r v=\"1Cor.1.18\"></r>، <r v=\"1Cor.2.14\"></r>، <r v=\"Rev.21.7\"></r>، وفي مواضع أخرى. </s> <s n=\"5.\">مع اسم الفاعل، صيغةً مركّبة بدل الفعل البسيط؛ <s n=\"(a)\">مع اسم فاعل التام: <r v=\"Matt.10.30\"></r>، <r v=\"Luke.9.32\"></r>، <r v=\"John.3.24\"></r>، <r v=\"Acts.21.35\"></r>، <r v=\"1Cor.15.19\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(b)\">مع اسم فاعل المضارع (خاصةً في الماضي الناقص، كما في العبرية والآرامية): <r v=\"Matt.7.29\"></r>، <r v=\"Mark.1.22\"></r>، <r v=\"Luke.4.31\"></r>، <r v=\"Luke.14.1\"></r>، <r v=\"Acts.1.10\"></r>، ومواضع أخرى كثيرة؛ ونفسه بمعنى الأمر، مع حذف <g>εἰμί</g>: <r v=\"Rom.12.9\"></r>، <r v=\"Rom.12.10\"></r>، <r v=\"Heb.13.5\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">مع اسم فاعل الماضي البسيط: <r v=\"Luke.23.9\"></r>.</s> </s> <s n=\"6.\">يليه <g>εἰς</g> (قارن العبرية <h n=\"H1961\">הָיָה לְ</h>)، وهو استعمال دارج: <r v=\"Matt.19.5\"></r>، <r v=\"Mark.10.8\"></r>، <r v=\"Heb.8.10\"></r>، وفي مواضع أخرى. </s> <s n=\"7.\">مع الظرف: <r v=\"Matt.19.20\"></r>، <r v=\"Mark.4.26\"></r>، <r v=\"Luke.18.11\"></r>، وفي مواضع أخرى. </s> <s n=\"8.\">الحذف؛ <s n=\"(a)\">حذف الرابط: <r v=\"Matt.8.29\"></r>، <r v=\"Matt.24.32\"></r>، <r v=\"John.21.22\"></r>، <r v=\"John.21.23\"></r>، <r v=\"Heb.6.4\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">حذف الخبر: <g>ἐγώ εἰμί</g>: <r v=\"Matt.14.27\"></r>، <r v=\"Mark.6.50\"></r>، وفي مواضع أخرى؛ مطلقًا (قارن <r v=\"Deut.32.39\"></r>؛ <h n=\"H589,H1931\">אֲנִי הוּא</h>): <r v=\"Mark.13.6\"></r>، <r v=\"John.4.26\"></r>، وفي مواضع أخرى (قارن <g>ἄπ-, ἔν-, πάρ-, συμ-πάρ-, σύν-ειμι</g>).</s> </s> </s> </s>"},"G1515":{"l":"εἰρήνη","o":92,"en":"<f><o>εἰρήνη</o>, <g>-ης, ἡ</g>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7965\">שָׁלוֹם</h> ;]</e> </et> <s><b>peace</b>; <s n=\"1.\">of public peace, freedom from war: <r v=\"Luke.14.32\"></r>, <r v=\"Acts.12.20\"></r> <r v=\"Acts.24.2\"></r>; of the church, <r v=\"Acts.9:31\"></r>. </s> <s n=\"2.\">Of peace between persons, concord, agreement : <r v=\"Matt.10.34\"></r>, <r v=\"Luke.12.51\"></r>, <r v=\"Rom.14.17\"></r>, <r v=\"1Cor.7.15\"></r>, <r v=\"Gal.5.22\"></r>, <r v=\"Jas.3.18\"></r>; <g>ζητεῖν εἰ.</g>, <r v=\"1Pet.3.11\"></r>; <g>διώκειν</g>, <r v=\"2Tim.2.22\"></r>; ib. seq. <g>μετὰ πάντων</g>, <r v=\"Heb.12.14\"></r>; by meton., of him who brings peace, <r v=\"Eph.2.14\"></r>. </s> <s n=\"3.\">As in LXX (= Heb. <h n=\"H7965\">שָׁלוֹם</h> , Aram. <h n=\"H8001\">שְׁלָם</h>), of a state of security and safety: <r v=\"John.16.33\"></r>, <r v=\"Rom.2.10\"></r>, <r v=\"1Thess.5.3\"></r>,́ whence the formulae, <g>ὕπαγε (πορεύου) εἰς εἰ</g>, <r v=\"Mark.5.34\"></r>, <r v=\"Luke.7.50\"></r> (cf. <r v=\"1Kgs.1.17\"></r>, al.; <h n=\"H1980,H7965\">לְכִי לְשָׁלוֹם</h>); <g>εἰ. ὑμῖν</g> (<h n=\"H7965\">שָׁלוֹם לָכֶם</h>), <r v=\"John.20.19\"></r>, <r v=\"John.20.21\"></r>, <r v=\"John.20.26\"></r>; <g>ἀπολύειν ἐν εἰ.</g>, <r v=\"Luke.2.29\"></r>, cf. <r v=\"1Cor.16.11\"></r>; <g>ἡ εἰ. ὑμῶν</g>, <r v=\"Matt.10.13\"></r>, <r v=\"Luke.10.6\"></r>; <g>υἱὸς εἰρήνης</g>, ib. </s> <s n=\"4.\">Of spiritual peace, the peace of Christ's kingdom (<i>DCG</i>, ii, 330f.): <r v=\"Luke.1.79\"></r> <r v=\"Luke.2.14\"></r>, <r v=\"John.16.33\"></r>, <r v=\"Rom.2.10\"></r> <r v=\"Rom.5.1\"></r> <r v=\"Rom.8.6\"></r>, al.; <g>ὁ κύριος τῆς εἰ.</g>, <r v=\"2Thess.3.16\"></r>; <g>ὁ θεὸς τῆς εἰ.</g>, <r v=\"Rom.15.33\"></r> <r v=\"Rom.16.20\"></r>, <r v=\"2Cor.13.11\"></r>, al.; in epistolary salutations, <r v=\"Rom.1.7\"></r>, <r v=\"1Cor.1.3\"></r>, <r v=\"Gal.1.3\"></r>, <r v=\"1Thess.1.1\"></r>, <r v=\"1Pet.1.2\"></r>, <r v=\"2John.1.3\"></r>, <r v=\"Rev.1.4\"></r>, al. (v. Cremer, 244).</s> </s>","ar":"<f><o>εἰρήνη</o>، <g>-ης, ἡ</g>، </f> <s><b>سلام</b>؛ <s n=\"1.\">عن السلام العام، أي الخلو من الحرب: <r v=\"Luke.14.32\"></r>، <r v=\"Acts.12.20\"></r>، <r v=\"Acts.24.2\"></r>؛ عن سلام الكنيسة: <r v=\"Acts.9:31\"></r>. </s> <s n=\"2.\">عن السلام بين الأشخاص، أي الوفاق والاتفاق: <r v=\"Matt.10.34\"></r>، <r v=\"Luke.12.51\"></r>، <r v=\"Rom.14.17\"></r>، <r v=\"1Cor.7.15\"></r>، <r v=\"Gal.5.22\"></r>، <r v=\"Jas.3.18\"></r>؛ <g>ζητεῖν εἰ.</g>: <r v=\"1Pet.3.11\"></r>؛ <g>διώκειν</g>: <r v=\"2Tim.2.22\"></r>؛ وفي الموضع نفسه يليه <g>μετὰ πάντων</g>: <r v=\"Heb.12.14\"></r>؛ وكنايةً عمّن يأتي بالسلام: <r v=\"Eph.2.14\"></r>. </s> <s n=\"3.\">كما في السبعينية (= العبرية <h n=\"H7965\">שָׁלוֹם</h>، والآرامية <h n=\"H8001\">שְׁלָם</h>)، عن حالة الأمن والسلامة: <r v=\"John.16.33\"></r>، <r v=\"Rom.2.10\"></r>، <r v=\"1Thess.5.3\"></r>، ومن هنا الصيغ: <g>ὕπαγε (πορεύου) εἰς εἰ</g>: <r v=\"Mark.5.34\"></r>، <r v=\"Luke.7.50\"></r> (قارن <r v=\"1Kgs.1.17\"></r>، وفي مواضع أخرى؛ <h n=\"H1980,H7965\">לְכִי לְשָׁלוֹם</h>)؛ <g>εἰ. ὑμῖν</g> (<h n=\"H7965\">שָׁלוֹם לָכֶם</h>): <r v=\"John.20.19\"></r>، <r v=\"John.20.21\"></r>، <r v=\"John.20.26\"></r>؛ <g>ἀπολύειν ἐν εἰ.</g>: <r v=\"Luke.2.29\"></r>، قارن <r v=\"1Cor.16.11\"></r>؛ <g>ἡ εἰ. ὑμῶν</g>: <r v=\"Matt.10.13\"></r>، <r v=\"Luke.10.6\"></r>؛ <g>υἱὸς εἰρήνης</g>: في الموضع نفسه. </s> <s n=\"4.\">عن السلام الروحي، سلام ملكوت المسيح: <r v=\"Luke.1.79\"></r>، <r v=\"Luke.2.14\"></r>، <r v=\"John.16.33\"></r>، <r v=\"Rom.2.10\"></r>، <r v=\"Rom.5.1\"></r>، <r v=\"Rom.8.6\"></r>، وفي مواضع أخرى؛ <g>ὁ κύριος τῆς εἰ.</g>: <r v=\"2Thess.3.16\"></r>؛ <g>ὁ θεὸς τῆς εἰ.</g>: <r v=\"Rom.15.33\"></r>، <r v=\"Rom.16.20\"></r>، <r v=\"2Cor.13.11\"></r>، وفي مواضع أخرى؛ في تحيات الرسائل: <r v=\"Rom.1.7\"></r>، <r v=\"1Cor.1.3\"></r>، <r v=\"Gal.1.3\"></r>، <r v=\"1Thess.1.1\"></r>، <r v=\"1Pet.1.2\"></r>، <r v=\"2John.1.3\"></r>، <r v=\"Rev.1.4\"></r>، وفي مواضع أخرى.</s> </s>"},"G1519":{"l":"εἰς","o":2112,"en":"<f><o>εἰς</o>, </f> prep. c. acc., <s>expressing entrance, direction, limit, <b>into, unto, to, upon, towards, for, among</b> (Lat. <l>in</l>, c. acc.). <s n=\"I.\">Of place. <s n=\"1.\">After verbs of motion; <s n=\"(a)\">of entrance into: <r v=\"Matt.8.23\"></r> <r v=\"Matt.9.7\"></r>, <r v=\"Mark.1.45\"></r>, <r v=\"Luke.2.15\"></r> <r v=\"Luke.8.31\"></r>, al.; </s> <s n=\"(b)\">of approach, <b>to</b> or <b>towards</b>: <r v=\"Mark.11.1\"></r>, <r v=\"Luke.6.8\"></r> <r v=\"Luke.19.28\"></r>, <r v=\"John.11.31\"></r> <r v=\"John.21.6\"></r>, al.; </s> <s n=\"(c)\">before pl. and collective nouns, <b>among</b>: <r v=\"Mark.4.7\"></r> <r v=\"Mark.8.19\"></r>, <r v=\"Mark.8.20\"></r>, <r v=\"Luke.11.49\"></r>, <r v=\"John.21.23\"></r>, al.; </s> <s n=\"(d)\">Of a limit reached, <b>unto, on, upon</b>: <r v=\"Matt.8.18\"></r>, <r v=\"Matt.21.1\"></r>, <r v=\"Mark.11.1\"></r> <r v=\"Mark.13.16\"></r>, <r v=\"Luke.14.10\"></r>, <r v=\"John.6.3\"></r> <r v=\"John.11.32\"></r>, al.; c. acc. pers. (as in Ep. and Ion.), <r v=\"Acts.23.15\"></r>, <r v=\"Rom.5.12\"></r> <r v=\"Rom.16.19\"></r>, <r v=\"2Cor.10.14\"></r>; </s> <s n=\"(e)\">elliptical: <g>ἐπιστολαὶ εἰς Δαμασκόν</g>, <r v=\"Acts.9.2\"></r>; <g>ἡ διακονία μου ἡ εἰς Ἱ.</g>, <r v=\"Rom.15.31\"></r>; metaph., of entrance into a certain state or condition, or of approach or direction towards some end (Thayer, B, i, 1; ii, 1), <g>εἰς τ. ὄνομα</g>, M, <i>Pr.</i>, 200. </s> </s> <s n=\"2.\">Of direction; <s n=\"(a)\">after verbs of seeing: <r v=\"Matt.6.26\"></r>, <r v=\"Mark.6.41\"></r>, <r v=\"Luke.9.16\"></r>, <r v=\"Luke.9.62\"></r>, <r v=\"John.13.22\"></r>, al.; metaph., of the mind, <r v=\"Heb.11.26\"></r> <r v=\"Heb.12.2\"></r>, al.; </s> <s n=\"(b)\">after verbs of speaking: <r v=\"Matt.13.10\"></r> <r v=\"Matt.14.9\"></r>, <r v=\"1Thess.2.9\"></r>, al.</s> </s> <s n=\"3.\">After verbs of rest; <s n=\"(a)\">in \"pregnant\" construction, implying previous motion (cl.; v. WM, 516; Bl., §39, 3; M, <i>Pr.</i>, 234f.): <r v=\"Matt.2.23\"></r> <r v=\"Matt.4.13\"></r>, <r v=\"2Thess.2.4\"></r>, <r v=\"2Tim.1.11\"></r>, <r v=\"Heb.11.9\"></r>, al.; </s> <s n=\"(b)\">by an assimilation general in late Gk (v. Bl., M, <i>Pr.</i>, ll. c.) = <g>ἐν</g>: <r v=\"Luke.1.44\"></r> <r v=\"Luke.4.23\"></r>, <r v=\"Acts.20.16\"></r> <r v=\"Acts.21.17\"></r>, <r v=\"John.1.18\"></r> (but v. Westc, in l.), al. </s> </s> </s> <s n=\"II.\">Of time, <b>for, unto</b>; <s n=\"1.\">accentuating the duration expressed by the acc.: <g>εἰς τ. αἰῶνα</g>, <r v=\"Matt.21.19\"></r>; <g>εἰς γενεὰς καὶ γ.</g>, <r v=\"Luke.1.50\"></r>; <g>εἰς τ. διηνεκές</g>, <r v=\"Heb.7.3\"></r>, al. </s> <s n=\"2.\">Of a point or limit of time, <b>unto, up to, until</b>: <r v=\"Matt.6.34\"></r>, <r v=\"Acts.4.3\"></r> <r v=\"Acts.25.21\"></r>, <r v=\"Phil.1.10\"></r> <r v=\"Phil.2.16\"></r>, <r v=\"1Thess.4.15\"></r>, <r v=\"2Tim.1.12\"></r>; of entrance into a future period, <g>εις τὸ μέλλον</g> (v.s. <g>μέλλω</g>), <b>next (year)</b>, <r v=\"Luke.13.9\"></r> (but c. <i>ICC</i>, in l.); <g>εἰς τ. μεταξὺ σάββατον</g>, <b>on the next Sabbath</b>, <r v=\"Acts.13.42\"></r>; <g>εἰς τὸ πάλιν</g> (v.s. <g>πάλιν</g>, <r v=\"2Cor.13.2\"></r>. </s> </s> <s n=\"III.\">Of result, after verbs of changing, joining, dividing, etc.: <g>στρέφειν εἰς</g>, <r v=\"Rev.11.6\"></r>; <g>μετας-</g>, <r v=\"Acts.2.20\"></r>, <r v=\"Jas.4.9\"></r>; <g>μεταλλάσσειν</g>, <r v=\"Rom.1.26\"></r>; <g>σχίζειν εἰς δύο</g>, <r v=\"Matt.27.51\"></r>, al.; predicatively with <g>εἴναι</g>, <r v=\"Acts.8.23\"></r>. </s> <s n=\"IV.\">Of relation, <b>to, towards, for, in regard to</b> (so in cl., but more freq. in late Gk., <g>εἰς</g> encroaching on the simple dat., which it has wholly displaced in MGr.; Jannaris, <i>Gr.</i>, §1541; Robertson, <i>Gr.</i>, 594; Deiss., <i>BS</i>, 117f.): <r v=\"Luke.7.30\"></r>, <r v=\"Rom.4.20\"></r> <r v=\"Rom.15.2\"></r>, <r v=\"Rom.15.26\"></r>, <r v=\"1Cor.16.1\"></r>, <r v=\"Eph.3.16\"></r>, al.; <g>ἀγάπη εἰς</g>, <r v=\"Rom.5.8\"></r>, al.; <g>χρηστός</g>, <r v=\"Eph.4.32\"></r>; <g>φρονεῖν εἰς</g>, <r v=\"Rom.12.16\"></r>; <g>θαρρεῖν</g>, <r v=\"2Cor.10.1\"></r>. </s> <s n=\"V.\">Of the end or object: <g>εὔθετος εἰς</g>, <r v=\"Luke.14.34\"></r>; <g>σόφος</g>, <r v=\"Rom.16.19\"></r>; <g>ἰσχύειν</g>, <r v=\"Matt.5.13\"></r>; <g>εἰς τοῦτο</g>, <r v=\"Mark.1.38\"></r>, al.; <g>ἀφορίζειν εἰς</g>, <r v=\"Rom.1.1\"></r>; indicating purpose, <g>εἰς φόβον</g>, <r v=\"Rom.8.15\"></r>; <g>εἰς ἔνδειξιν</g>, <r v=\"Rom.3.25\"></r>; <g>εἰς τό</g>, c. inf. (= <g>ἵνα</g> or <g>ὥστε</g>; Bl., §71, 5; M, <i>Pr.</i>, 218ff.): <r v=\"Matt.20.19\"></r>, <r v=\"Rom.1.11\"></r>, <r v=\"1Cor.9.18\"></r>, al. </s> <s n=\"VI.\">Adverbial phrases: <g>εἰς τέλος, εἰς τὸ πάλιν</g>, etc (v.s. <g>τέλος, πάλιν</g>, etc.).</s> </s>","ar":"<f><o>εἰς</o>، </f> حرف جر مع المنصوب، <s>يدل على الدخول والاتجاه والحد، <b>إلى، حتى، على، نحو، لأجل، بين</b> (اللاتينية <l>in</l> مع المنصوب). <s n=\"I.\">عن المكان. <s n=\"1.\">بعد أفعال الحركة؛ <s n=\"(a)\">عن الدخول إلى: <r v=\"Matt.8.23\"></r> <r v=\"Matt.9.7\"></r>، <r v=\"Mark.1.45\"></r>، <r v=\"Luke.2.15\"></r> <r v=\"Luke.8.31\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(b)\">عن الاقتراب، <b>إلى</b> أو <b>نحو</b>: <r v=\"Mark.11.1\"></r>، <r v=\"Luke.6.8\"></r> <r v=\"Luke.19.28\"></r>، <r v=\"John.11.31\"></r> <r v=\"John.21.6\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(c)\">قبل الجمع وأسماء الجمع، <b>بين</b>: <r v=\"Mark.4.7\"></r> <r v=\"Mark.8.19\"></r>، <r v=\"Mark.8.20\"></r>، <r v=\"Luke.11.49\"></r>، <r v=\"John.21.23\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(d)\">عن بلوغ حدٍّ ما، <b>إلى، على</b>: <r v=\"Matt.8.18\"></r>، <r v=\"Matt.21.1\"></r>، <r v=\"Mark.11.1\"></r> <r v=\"Mark.13.16\"></r>، <r v=\"Luke.14.10\"></r>، <r v=\"John.6.3\"></r> <r v=\"John.11.32\"></r>، وفي مواضع أخرى؛ مع منصوب الشخص، <r v=\"Acts.23.15\"></r>، <r v=\"Rom.5.12\"></r> <r v=\"Rom.16.19\"></r>، <r v=\"2Cor.10.14\"></r>؛ </s> <s n=\"(e)\">بالحذف: <g>ἐπιστολαὶ εἰς Δαμασκόν</g>، <r v=\"Acts.9.2\"></r>؛ <g>ἡ διακονία μου ἡ εἰς Ἱ.</g>، <r v=\"Rom.15.31\"></r>؛ مجازيًا، عن الدخول في حالة أو وضع معين، أو عن الاقتراب أو الاتجاه نحو غاية ما، <g>εἰς τ. ὄνομα</g>. </s> </s> <s n=\"2.\">عن الاتجاه؛ <s n=\"(a)\">بعد أفعال النظر: <r v=\"Matt.6.26\"></r>، <r v=\"Mark.6.41\"></r>، <r v=\"Luke.9.16\"></r>، <r v=\"Luke.9.62\"></r>، <r v=\"John.13.22\"></r>، وفي مواضع أخرى؛ مجازيًا، عن الذهن، <r v=\"Heb.11.26\"></r> <r v=\"Heb.12.2\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(b)\">بعد أفعال الكلام: <r v=\"Matt.13.10\"></r> <r v=\"Matt.14.9\"></r>، <r v=\"1Thess.2.9\"></r>، وفي مواضع أخرى.</s> </s> <s n=\"3.\">بعد أفعال السكون؛ <s n=\"(a)\">في تركيب «مُضمَّن» يفيد حركةً سابقة: <r v=\"Matt.2.23\"></r> <r v=\"Matt.4.13\"></r>، <r v=\"2Thess.2.4\"></r>، <r v=\"2Tim.1.11\"></r>، <r v=\"Heb.11.9\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(b)\">بتماثلٍ شائع في اليونانية المتأخرة = <g>ἐν</g>: <r v=\"Luke.1.44\"></r> <r v=\"Luke.4.23\"></r>، <r v=\"Acts.20.16\"></r> <r v=\"Acts.21.17\"></r>، <r v=\"John.1.18\"></r>، وفي مواضع أخرى. </s> </s> </s> <s n=\"II.\">عن الزمان، <b>إلى، لمدة</b>؛ <s n=\"1.\">تأكيدًا للمدة التي يعبّر عنها المنصوب: <g>εἰς τ. αἰῶνα</g>، <r v=\"Matt.21.19\"></r>؛ <g>εἰς γενεὰς καὶ γ.</g>، <r v=\"Luke.1.50\"></r>؛ <g>εἰς τ. διηνεκές</g>، <r v=\"Heb.7.3\"></r>، وفي مواضع أخرى. </s> <s n=\"2.\">عن نقطة أو حدٍّ زمني، <b>إلى، حتى</b>: <r v=\"Matt.6.34\"></r>، <r v=\"Acts.4.3\"></r> <r v=\"Acts.25.21\"></r>، <r v=\"Phil.1.10\"></r> <r v=\"Phil.2.16\"></r>، <r v=\"1Thess.4.15\"></r>، <r v=\"2Tim.1.12\"></r>؛ عن الدخول في زمن مقبل، <g>εις τὸ μέλλον</g> (انظر تحت مدخل <g>μέλλω</g>)، <b>(السنة) المقبلة</b>، <r v=\"Luke.13.9\"></r>؛ <g>εἰς τ. μεταξὺ σάββατον</g>، <b>في السبت التالي</b>، <r v=\"Acts.13.42\"></r>؛ <g>εἰς τὸ πάλιν</g> (انظر تحت مدخل <g>πάλιν</g>)، <r v=\"2Cor.13.2\"></r>. </s> </s> <s n=\"III.\">عن النتيجة، بعد أفعال التحويل والضم والتقسيم ونحوها: <g>στρέφειν εἰς</g>، <r v=\"Rev.11.6\"></r>؛ <g>μετας-</g>، <r v=\"Acts.2.20\"></r>، <r v=\"Jas.4.9\"></r>؛ <g>μεταλλάσσειν</g>، <r v=\"Rom.1.26\"></r>؛ <g>σχίζειν εἰς δύο</g>، <r v=\"Matt.27.51\"></r>، وفي مواضع أخرى؛ خبريًا مع <g>εἴναι</g>، <r v=\"Acts.8.23\"></r>. </s> <s n=\"IV.\">عن العلاقة، <b>إلى، نحو، لأجل، من جهة</b> (وهو أكثر في اليونانية المتأخرة، إذ أخذ <g>εἰς</g> يحل محل حالة القابل المجردة): <r v=\"Luke.7.30\"></r>، <r v=\"Rom.4.20\"></r> <r v=\"Rom.15.2\"></r>، <r v=\"Rom.15.26\"></r>، <r v=\"1Cor.16.1\"></r>، <r v=\"Eph.3.16\"></r>، وفي مواضع أخرى؛ <g>ἀγάπη εἰς</g>، <r v=\"Rom.5.8\"></r>، وفي مواضع أخرى؛ <g>χρηστός</g>، <r v=\"Eph.4.32\"></r>؛ <g>φρονεῖν εἰς</g>، <r v=\"Rom.12.16\"></r>؛ <g>θαρρεῖν</g>، <r v=\"2Cor.10.1\"></r>. </s> <s n=\"V.\">عن الغاية أو الهدف: <g>εὔθετος εἰς</g>، <r v=\"Luke.14.34\"></r>؛ <g>σόφος</g>، <r v=\"Rom.16.19\"></r>؛ <g>ἰσχύειν</g>، <r v=\"Matt.5.13\"></r>؛ <g>εἰς τοῦτο</g>، <r v=\"Mark.1.38\"></r>، وفي مواضع أخرى؛ <g>ἀφορίζειν εἰς</g>، <r v=\"Rom.1.1\"></r>؛ للدلالة على القصد، <g>εἰς φόβον</g>، <r v=\"Rom.8.15\"></r>؛ <g>εἰς ἔνδειξιν</g>، <r v=\"Rom.3.25\"></r>؛ <g>εἰς τό</g>، مع المصدر (= <g>ἵνα</g> أو <g>ὥστε</g>): <r v=\"Matt.20.19\"></r>، <r v=\"Rom.1.11\"></r>، <r v=\"1Cor.9.18\"></r>، وفي مواضع أخرى. </s> <s n=\"VI.\">عبارات ظرفية: <g>εἰς τέλος, εἰς τὸ πάλιν</g>، إلخ (انظر تحت مدخل <g>τέλος, πάλιν</g>، إلخ).</s> </s>"},"G1577":{"l":"ἐκκλησία","o":114,"en":"<f><o>ἐκκλησία</o>, <g>-ας, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>ἐκ-καλέω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6951\">קָהָל</h>, otherwise for one of its cogn. forms ;]</e> </et> <s> <s n=\"1.\">prop., <b>an assembly</b> of citizens regularly convened (in Thuc., ii, 22, opp. to <g>σύλλογος</g>, <i>a concourse</i>): <r v=\"Acts.19.32\"></r>, <r v=\"Acts.19.39\"></r>, <r v=\"Acts.19.41\"></r>. </s> <s n=\"2.\">In LXX of <b>the assembly, congregation, community</b> of Israel (De 4:10 23:2, al.): <r v=\"Acts.7.38\"></r>, <r v=\"Heb.2.12\"></r> <i>(LXX)</i>. </s> <s n=\"3.\">NT, esp. of an assembly or company of Christians, a <b>(the) church</b>; <s n=\"(a)\">of gatherings for worship: <r v=\"1Cor.11.18\"></r> <r v=\"1Cor.14.19\"></r>, <r v=\"1Cor.14.34\"></r>, <r v=\"1Cor.14.35\"></r>; </s> <s n=\"(b)\">of local communities: <r v=\"Acts.8.3\"></r>, <r v=\"1Cor.4.17\"></r>; with name added, <r v=\"Acts.8.1\"></r>, <r v=\"Rom.16.1\"></r>, <r v=\"1Thess.1.1\"></r>, al.; pl., <r v=\"Acts.15.41\"></r>, <r v=\"1Cor.7.17\"></r>; <g>τ. Χριστοῦ</g>, <r v=\"Rom.16.16\"></r>; <g>τ. Ἀσίας</g>, <r v=\"1Cor.16.19\"></r>; <g>τ. ἁγίων</g>, <r v=\"1Cor.14.33\"></r>; <g>εἰπὸν τ. ἐκκλησίᾳ</g>, <r v=\"Matt.18.17\"></r> (but v. Hort, <i>Ecclesia</i>, 10); of a house-congregation (<i>DB</i>, i, 431a), <r v=\"Rom.16.5\"></r>, <r v=\"1Cor.16.19\"></r>, <r v=\"Col.4.15\"></r>, <r v=\"Phlm.1.2\"></r>; </s> <s n=\"(c)\">of the whole body of Christians: <r v=\"Matt.16.18\"></r>, <r v=\"1Cor.12.28\"></r>, <r v=\"Eph.1.22\"></r>, <r v=\"Phil.3.6\"></r>, al.; <g>τ. θεοῦ</g>, <r v=\"Acts.20.28\"></r> (<g>Κυρίου</g>, T, R, mg.), <r v=\"1Cor.15.9\"></r>, <r v=\"Gal.1.13\"></r>, <r v=\"1Tim.3.15\"></r>; <g>ἐ. προτοτόκων ἀπογεγραμμένων ἐν οὐρανοῖς</g>, <r v=\"Heb.12.23\"></r>. </s> </s> </s> <sy><i>SYN.</i>: <g>συναγωγή</g>, q.v. (v. Tr., <i>Syn.</i>, §i; <i>DB</i>, i, 426; Hort, <i>Ecclesia</i>, esp. 4ff., 107ff.; Hamilton, <i>People of God</i>, ii, 37ff.; reff. s.vv. \"Church,\" \"Congregation,\" in <i>DB</i> and <i>DCG</i>; Cremer, 332).</sy>","ar":"<f><o>ἐκκλησία</o>، <g>-ας, ἡ</g> </f> <s> <s n=\"1.\">بالمعنى الحرفي، <b>جماعة</b> (مجمع) من المواطنين تنعقد بانتظام: <r v=\"Acts.19.32\"></r>، <r v=\"Acts.19.39\"></r>، <r v=\"Acts.19.41\"></r>. </s> <s n=\"2.\">في السبعينية عن <b>جماعة، جمهور، شعب</b> إسرائيل (التثنية 4:10، 23:2، وفي مواضع أخرى): <r v=\"Acts.7.38\"></r>، <r v=\"Heb.2.12\"></r> <i>(السبعينية)</i>. </s> <s n=\"3.\">في العهد الجديد، خاصةً عن جماعة أو جمع من المسيحيين، <b>كنيسة (الكنيسة)</b>؛ <s n=\"(a)\">عن الاجتماعات للعبادة: <r v=\"1Cor.11.18\"></r> <r v=\"1Cor.14.19\"></r>، <r v=\"1Cor.14.34\"></r>، <r v=\"1Cor.14.35\"></r>؛ </s> <s n=\"(b)\">عن الجماعات المحلية: <r v=\"Acts.8.3\"></r>، <r v=\"1Cor.4.17\"></r>؛ مع إضافة الاسم، <r v=\"Acts.8.1\"></r>، <r v=\"Rom.16.1\"></r>، <r v=\"1Thess.1.1\"></r>، وفي مواضع أخرى؛ جمعًا، <r v=\"Acts.15.41\"></r>، <r v=\"1Cor.7.17\"></r>؛ <g>τ. Χριστοῦ</g>، <r v=\"Rom.16.16\"></r>؛ <g>τ. Ἀσίας</g>، <r v=\"1Cor.16.19\"></r>؛ <g>τ. ἁγίων</g>، <r v=\"1Cor.14.33\"></r>؛ <g>εἰπὸν τ. ἐκκλησίᾳ</g>، <r v=\"Matt.18.17\"></r>؛ عن الكنيسة التي في بيت، <r v=\"Rom.16.5\"></r>، <r v=\"1Cor.16.19\"></r>، <r v=\"Col.4.15\"></r>، <r v=\"Phlm.1.2\"></r>؛ </s> <s n=\"(c)\">عن جماعة المسيحيين كلها: <r v=\"Matt.16.18\"></r>، <r v=\"1Cor.12.28\"></r>، <r v=\"Eph.1.22\"></r>، <r v=\"Phil.3.6\"></r>، وفي مواضع أخرى؛ <g>τ. θεοῦ</g>، <r v=\"Acts.20.28\"></r>، <r v=\"1Cor.15.9\"></r>، <r v=\"Gal.1.13\"></r>، <r v=\"1Tim.3.15\"></r>؛ <g>ἐ. προτοτόκων ἀπογεγραμμένων ἐν οὐρανοῖς</g>، <r v=\"Heb.12.23\"></r>. </s> </s> </s>"},"G1595":{"l":"ἐκούσιος","o":1,"en":"<f><o>ἐκούσιος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>έκών</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5071\">נְדָבָה</h>, as <r v=\"Num.15.3\"></r> (<g>κατ’ ἑ.</g>);]</e> </et> <s>usually of actions, <b>voluntary</b>: <g>κατὰ ἑ.</g>, of free will (Lft., in l), <r v=\"Phlm.1.14\"></r>.†</s>","ar":"<f><o>ἐκούσιος</o>، <g>-ον</g></f> <s>عادةً عن الأفعال: <b>طوعي، اختياري</b>: <g>κατὰ ἑ.</g>: بإرادة حرّة، طوعًا: <r v=\"Phlm.1.14\"></r>.†</s>"},"G166":{"l":"αἰώνιος","o":71,"en":"<f><o>αἰώνιος</o>, <g>-ον</g> (as usual in Attic), also <g>-α, -ον</g>. <r v=\"2Thess.2.16\"></r>, <r v=\"Heb.9.12\"></r>;</f> <et> <e t=\"derivation\">(&lt; <x><g>αἰών</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5769\">עוֹלָם</h>;]</e> </et> <s><b>age-long</b>, <b>eternal</b>, <s n=\"(a)\">of that which is without either beginning or end: <r v=\"Rom.16.26\"></r>, <r v=\"Heb.9.14\"></r>; </s> <s n=\"(b)\">of that which is without beginning: <r v=\"Rom.16.25\"></r>, <r v=\"2Tim.1.9\"></r>, <r v=\"Titus.1.2\"></r>; </s> <s n=\"(c)\">of that which is without end (MM, <i>VGT</i>, s.v.): <g>σκηναί</g>, <r v=\"Luke.16.9\"></r> <g>οἰκία</g>, <r v=\"2Cor.5.1\"></r>; <g>διαθήκη</g>, <r v=\"Heb.13.20\"></r>; <g>εὐαγγέλιον</g>, <r v=\"Rev.14.6\"></r>; <g>παράκλησις</g>, <r v=\"2Thess.2.16\"></r>; <g>λύτρωσις</g>, <r v=\"Heb.9.12\"></r>; <g>κληρονομία</g>, <r v=\"Heb.9.15\"></r>; <g>κόλασις</g>, <r v=\"Matt.25.46\"></r>; <g>κρίμα</g>, <r v=\"Heb.6.2\"></r>; <g>κρίσις</g>, <r v=\"Mark.3.29\"></r>; <g>ὄλεθρον</g>, <r v=\"2Thess.1.9\"></r>; <g>πῦρ</g>, <r v=\"Matt.18.8\"></r>; freq. c. <g>ζωή</g>, q.v. </s> </s> <sy><i>SYN.</i>: <x><g>ἀΐδιος</g></x>, q.v.</sy>","ar":"<f><o>αἰώνιος</o>، <g>-ον</g>، وأيضًا <g>-α, -ον</g>. <r v=\"2Thess.2.16\"></r>، <r v=\"Heb.9.12\"></r>؛</f> <s><b>دهري، ممتد عبر الدهور</b>، <b>أبدي</b>، <s n=\"(a)\">عما ليس له بداية ولا نهاية: <r v=\"Rom.16.26\"></r>، <r v=\"Heb.9.14\"></r>؛ </s> <s n=\"(b)\">عما ليس له بداية (أزلي): <r v=\"Rom.16.25\"></r>، <r v=\"2Tim.1.9\"></r>، <r v=\"Titus.1.2\"></r>؛ </s> <s n=\"(c)\">عما ليس له نهاية: <g>σκηναί</g> (مظال)، <r v=\"Luke.16.9\"></r> <g>οἰκία</g> (بيت)، <r v=\"2Cor.5.1\"></r>؛ <g>διαθήκη</g> (عهد)، <r v=\"Heb.13.20\"></r>؛ <g>εὐαγγέλιον</g> (بشارة)، <r v=\"Rev.14.6\"></r>؛ <g>παράκλησις</g> (عزاء)، <r v=\"2Thess.2.16\"></r>؛ <g>λύτρωσις</g> (فداء)، <r v=\"Heb.9.12\"></r>؛ <g>κληρονομία</g> (ميراث)، <r v=\"Heb.9.15\"></r>؛ <g>κόλασις</g> (عذاب)، <r v=\"Matt.25.46\"></r>؛ <g>κρίμα</g> (دينونة)، <r v=\"Heb.6.2\"></r>؛ <g>κρίσις</g> (دينونة)، <r v=\"Mark.3.29\"></r>؛ <g>ὄλεθρον</g> (هلاك)، <r v=\"2Thess.1.9\"></r>؛ <g>πῦρ</g> (نار)، <r v=\"Matt.18.8\"></r>؛ وكثيرًا مع <g>ζωή</g> (حياة)، انظره. </s> </s>"},"G1677":{"l":"ἐλλογάω","o":2,"en":"<f>*† <o>ἐλλογάω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(a <g>κοινή</g> word, elsewhere usually <g>-έω</g>; cf. Bl., § 22, 2), </e> </et> <s><b>to charge to one's account, impute</b>: <r v=\"Phlm.1.18\"></r> (on parallels, cf. Deiss., <i>LAE</i>, 79 f., 335 f.; Milligan, <i>NTD</i>, 73; MM, <i>Exp.</i>, xii); of sin, <r v=\"Rom.5.13\"></r> (Cremer, 400).†</s>","ar":"<f>*† <o>ἐλλογάω</o>، <g>-ῶ</g></f> <s><b>حسب على حساب أحد، نسب إليه</b>: <r v=\"Phlm.1.18\"></r>؛ عن الخطية: <r v=\"Rom.5.13\"></r>.†</s>"},"G1679":{"l":"ἐλπίζω","o":31,"en":"<f><o>ἐλπίζω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H982\">בָּטַח</h>, also for <h n=\"H2620\">חָסָה</h>, <h n=\"H3176\">יָחַל</h> pi., hi., etc. ;] </e> </et> <s><b>to look for, expect, hope</b> (<b>for</b>): c. acc rei, <r v=\"Rom.8.24\"></r>, <r v=\"Rom.8.25\"></r>, <r v=\"1Cor.13.7\"></r>, <r v=\"Heb.11.1\"></r>; c. dat. rei (<g>τ. τύχῃ</g>, Thuc., iii, 97, 2), <r v=\"Matt.12.21\"></r>; seq. <g>καθώς</g>, <r v=\"2Cor.8.5\"></r>; c. inf., <r v=\"Luke.6.34\"></r> <r v=\"Luke.23.8\"></r>, <r v=\"Acts.26.7\"></r>, <r v=\"Rom.15.24\"></r>, <r v=\"1Cor.16.7\"></r>, <r v=\"2Cor.5.11\"></r>, <r v=\"Phil.2.19\"></r>, <r v=\"Phil.2.23\"></r>, <r v=\"1Tim.3.14\"></r>, <r v=\"2John.1.12\"></r>, <r v=\"3John.1.14\"></r>; seq. <g>ὅτι</g>, c. pres., <r v=\"Luke.24.21\"></r>; c. fut., <r v=\"Acts.24.26\"></r>, <r v=\"2Cor.1.13\"></r> <r v=\"2Cor.13.6\"></r>, <r v=\"Phlm.1.22\"></r>. As in LXX (WM, § xxxiii, d; and esp. in the pf., Ellic. on <r v=\"1Tim.4.10\"></r>; Bl., § 59, 2), c. prep.; <g>εἰς</g>, <r v=\"John.5.45\"></r> (v. Ellis., l.c.), <r v=\"1Pet.3.5\"></r>; seq. <g>ὅτι</g>, <r v=\"2Cor.1.10\"></r>; <g>ἐπί</g>, c. dat., <r v=\"Rom.15.12\"></r> <i>(LXX)</i>, <r v=\"1Tim.4.10\"></r> <r v=\"1Tim.6.17\"></r>; <g>ἐν</g>, <r v=\"1Cor.15.19\"></r>; c. acc, <r v=\"1Pet.1.13\"></r> (aor. imper. v. Bl., § 58, 2); <g>τ. θεόν</g>, <r v=\"1Tim.5.5\"></r> (of. <g>ἀπ-, προ-ελπίζω</g>, v. Cremer, 255).†</s>","ar":"<f><o>ἐλπίζω </o></f> <s><b>يترقّب، ينتظر، يرجو</b>: مع منصوب الشيء، <r v=\"Rom.8.24\"></r>، <r v=\"Rom.8.25\"></r>، <r v=\"1Cor.13.7\"></r>، <r v=\"Heb.11.1\"></r>؛ مع قابل الشيء، <r v=\"Matt.12.21\"></r>؛ يليه <g>καθώς</g>، <r v=\"2Cor.8.5\"></r>؛ مع المصدر، <r v=\"Luke.6.34\"></r> <r v=\"Luke.23.8\"></r>، <r v=\"Acts.26.7\"></r>، <r v=\"Rom.15.24\"></r>، <r v=\"1Cor.16.7\"></r>، <r v=\"2Cor.5.11\"></r>، <r v=\"Phil.2.19\"></r>، <r v=\"Phil.2.23\"></r>، <r v=\"1Tim.3.14\"></r>، <r v=\"2John.1.12\"></r>، <r v=\"3John.1.14\"></r>؛ يليه <g>ὅτι</g>، مع المضارع، <r v=\"Luke.24.21\"></r>؛ مع المستقبل، <r v=\"Acts.24.26\"></r>، <r v=\"2Cor.1.13\"></r> <r v=\"2Cor.13.6\"></r>، <r v=\"Phlm.1.22\"></r>. وكما في السبعينية (وخاصةً في التام، قارن <r v=\"1Tim.4.10\"></r>)، مع حرف جر؛ <g>εἰς</g>، <r v=\"John.5.45\"></r>، <r v=\"1Pet.3.5\"></r>؛ يليه <g>ὅτι</g>، <r v=\"2Cor.1.10\"></r>؛ <g>ἐπί</g>، مع القابل، <r v=\"Rom.15.12\"></r> <i>(السبعينية)</i>، <r v=\"1Tim.4.10\"></r> <r v=\"1Tim.6.17\"></r>؛ <g>ἐν</g>، <r v=\"1Cor.15.19\"></r>؛ مع المنصوب، <r v=\"1Pet.1.13\"></r> (الأمر الماضي البسيط)؛ <g>τ. θεόν</g>، <r v=\"1Tim.5.5\"></r> (قارن <g>ἀπ-, προ-ελπίζω</g>).†</s>"},"G1683":{"l":"ἐμαυτοῦ","o":37,"en":"<f><o>ἐμαυτοῦ</o>, <g>-ῆς, -οῦ</g>, </f> <s>reflex pron. of first pers., used only in gen., dat. and acc sing., </s> <s><b>of myself</b>: <r v=\"Luke.7.7\"></r>, al.; <g>ἀπ’ ἐ.</g>, <r v=\"John.5.30\"></r> <r v=\"John.7.17\"></r>, <r v=\"John.7.28\"></r> <r v=\"John.8.28\"></r>, <r v=\"John.8.42\"></r> <r v=\"John.10.18\"></r> <r v=\"John.14.10\"></r>; <g>ὑπ’ ἐμαυτόν</g>, <r v=\"Matt.8.9\"></r>, <r v=\"Luke.7.8\"></r> </s>","ar":"<f><o>ἐμαυτοῦ</o>، <g>-ῆς, -οῦ</g>، </f> <s>ضمير انعكاسي للمتكلم، لا يُستعمل إلا في المضاف إليه والقابل والمنصوب المفرد، </s> <s><b>نفسي</b>، <b>ذاتي</b>: <r v=\"Luke.7.7\"></r>، وفي مواضع أخرى؛ <g>ἀπ’ ἐ.</g>، <r v=\"John.5.30\"></r> <r v=\"John.7.17\"></r>، <r v=\"John.7.28\"></r> <r v=\"John.8.28\"></r>، <r v=\"John.8.42\"></r> <r v=\"John.10.18\"></r> <r v=\"John.14.10\"></r>؛ <g>ὑπ’ ἐμαυτόν</g>، <r v=\"Matt.8.9\"></r>، <r v=\"Luke.7.8\"></r> </s>"},"G1699":{"l":"ἐμός","o":63,"en":"<f><o>ἐμός</o>, <g>-ή, -όν </g></f> <s>poss. prop. of first pers., representing the em­phasized gen. <g>ἐμοῦ</g>, </s> <s><b>mine</b>, subjectively and objectively, i.e. belonging to, proceeding from or related to me: <r v=\"Matt.18.20\"></r>, <r v=\"Mark.8.38\"></r>, <r v=\"John.3.29\"></r> (most freq. in this gospel), al.; absol., <g>τὸ ἐμόν, τὰ ἐμά</g>, <r v=\"Matt.20.15\"></r> <r v=\"Matt.25.27\"></r>, <r v=\"Luke.15.31\"></r>, <r v=\"John.10.14\"></r> <r v=\"John.16.14\"></r>, <r v=\"John.16.15\"></r> <r v=\"John.17.10\"></r>; = gen. obj. (cl.), <g>εἰς τ. ἐμὴν ἀνάμνησιν</g>, <r v=\"Luke.22.19\"></r>, <r v=\"1Cor.11.24\"></r>, <r v=\"1Cor.11.25\"></r>; c. gen. expl., <g>τ. ἐμῇ χειρὶ Παύλου</g>, <r v=\"1Cor.16.21\"></r>, <r v=\"Col.4.18\"></r>, <r v=\"2Thess.3.17\"></r> </s>","ar":"<f><o>ἐμός</o>، <g>-ή, -όν </g></f> <s>ضمير ملكية للمتكلم، يقوم مقام المضاف إليه المؤكَّد <g>ἐμοῦ</g>، </s> <s><b>لي</b>، <b>خاصتي</b>، بالمعنيين الفاعلي والمفعولي، أي ما يخصني أو يصدر عني أو يتعلق بي: <r v=\"Matt.18.20\"></r>، <r v=\"Mark.8.38\"></r>، <r v=\"John.3.29\"></r> (وهي أكثر ورودًا في هذا الإنجيل)، وفي مواضع أخرى؛ مطلقًا، <g>τὸ ἐμόν, τὰ ἐμά</g>، <r v=\"Matt.20.15\"></r> <r v=\"Matt.25.27\"></r>، <r v=\"Luke.15.31\"></r>، <r v=\"John.10.14\"></r> <r v=\"John.16.14\"></r>، <r v=\"John.16.15\"></r> <r v=\"John.17.10\"></r>؛ = المضاف إليه المفعولي، <g>εἰς τ. ἐμὴν ἀνάμνησιν</g>، <r v=\"Luke.22.19\"></r>، <r v=\"1Cor.11.24\"></r>، <r v=\"1Cor.11.25\"></r>؛ مع مضاف إليه تفسيري، <g>τ. ἐμῇ χειρὶ Παύλου</g>، <r v=\"1Cor.16.21\"></r>، <r v=\"Col.4.18\"></r>، <r v=\"2Thess.3.17\"></r> </s>"},"G1756":{"l":"ἐνεργής","o":3,"en":"<f>* <o>ἐνεργής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(late form of <g>ἐνεργός</g>, on wh. cf. AR, <i>Eph.</i>, 241), </e> </et> <s><b>at work, active, effective</b>: <r v=\"1Cor.16.9\"></r>, <r v=\"Phlm.1.6\"></r>, <r v=\"Heb.4.12\"></r> (Cremer, 261).†</s>","ar":"<f>* <o>ἐνεργής</o>، <g>-ές</g></f> <s><b>عامل، فعّال، مؤثِّر</b>: <r v=\"1Cor.16.9\"></r>، <r v=\"Phlm.1.6\"></r>، <r v=\"Heb.4.12\"></r>.†</s>"},"G18":{"l":"ἀγαθός","o":102,"en":"<f><o>ἀγαθός</o>, <g>-ή, -όν</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2896\">טוֹב</h>;]</e> </et> <s>in general, <b>good</b>, in physical and in moral sense, used of persons, things, acts, conditions, etc., applied to that which is regarded as \"perfect in its kind, so as to produce pleasure and satisfaction, . . . that which, in itself good, is also at once for the good and the advantage of him who comes in contact with it\" (Cremer, 3): <g>γῆ</g>, <r v=\"Luke.8.8\"></r>; <g>δένδρον</g>, <r v=\"Matt.7.18\"></r>; <g>καρδία</g>, <r v=\"Luke.8.15\"></r>; <g>δόσις</g>, <r v=\"Jas.1.17\"></r>; <g>μέρις</g>, <r v=\"Luke.10.42\"></r>; <g>ἔργον</g> (freq. in Pl.), <r v=\"Phil.1.6\"></r>; <g>ἐλπίς</g>, <r v=\"2Thess.2.16\"></r>; <g>θησαυρός</g>, <r v=\"Matt.12.35\"></r>; <g>μνεία</g>, <r v=\"1Thess.3.6\"></r> (cf. <r v=\"2Macc.7.20\"></r>); as subst., <g>τὸ ἀ.</g>, that which is morally good, beneficial, acceptable to God, <r v=\"Rom.12.2\"></r>; <g>ἐργάζεσθαι τὸ ἀ</g>, <r v=\"Rom.2.10\"></r>, <r v=\"Eph.4.28\"></r>; <g>πράσσειν</g>, <r v=\"Rom.9.11\"></r>, <r v=\"2Cor.5.10\"></r>; <g>διώκειν</g>, <r v=\"1Thess.5.15\"></r>; <g>μιμεῖσθαι</g>, <r v=\"3John.1.11\"></r>; <g>κολλᾶσθαι τῷ ἀ.</g>, <r v=\"Rom.12.9\"></r>; <g>ερωτᾶν περὶ τοῦ ἀ.</g>, <r v=\"Matt.19.17\"></r>; <g>διάκονος εἰς τὸ ἀ.</g>, <r v=\"Rom.13.4\"></r>; <g>τὸ ἀ. σου</g>, <b>thy favour, benefit</b>, <r v=\"Phlm.1.14\"></r>; pl., <g>τὰ ἀ.</g>, of goods, possessions, <r v=\"Luke.12.18\"></r>; of spiritual benefits, <r v=\"Rom.10.15\"></r>, <r v=\"Heb.9.11\"></r>, <r v=\"Heb.10.1\"></r>. <g>ἀ.</g> is opp. to <g>πονηρός</g>, <r v=\"Matt.5.45\"></r>, <r v=\"Matt.20.15\"></r>; <g>κακός</g>, <r v=\"Rom.7.19\"></r>; <g>φαῦλος</g>, <r v=\"Rom.9.11\"></r>, <r v=\"2Cor.5.10\"></r> (cf. MM, <i>VGT</i>, s.v.).</s> <sy><i>SYN.</i>: <x><g>καλός</g></x>, <x><g>δίκαιος</g></x>. <g>κ.</g> properly refers to <b>goodliness</b> as manifested in form: <g>ἀ.</g> to inner excellence (cf. the cl. <g>καλὸς κἀγαθός</g> and <g>ἐν καρδίᾳ κ. καὶ ἀ.</g>, <r v=\"Luke.8.15\"></r>). In <r v=\"Rom.5.7\"></r>, where it is contrasted with <g>δ.</g>, <g>ἀ.</g> implies a kindliness and attractiveness not necessarily possessed by the <x><g>δίκαιος</g></x>, who merely measures up to a high standard of rectitude (cf. <x><g>ἀγαθωσύνη</g></x>).</sy>","ar":"<f><o>ἀγαθός</o>، <g>-ή, -όν</g>،</f> <s>بوجه عام: <b>صالح، جيد</b>، بالمعنى المادي والأخلاقي، يُقال عن الأشخاص والأشياء والأعمال والأحوال إلخ، ويُطلق على ما يُعَدّ «كاملاً في نوعه بحيث يبعث السرور والرضا، . . . ما هو صالح في ذاته، وهو في الوقت نفسه لخير ونفع من يتصل به»: <g>γῆ</g> (أرض)، <r v=\"Luke.8.8\"></r>؛ <g>δένδρον</g> (شجرة)، <r v=\"Matt.7.18\"></r>؛ <g>καρδία</g> (قلب)، <r v=\"Luke.8.15\"></r>؛ <g>δόσις</g> (عطية)، <r v=\"Jas.1.17\"></r>؛ <g>μέρις</g> (نصيب)، <r v=\"Luke.10.42\"></r>؛ <g>ἔργον</g> (عمل) (كثيرًا عند بولس)، <r v=\"Phil.1.6\"></r>؛ <g>ἐλπίς</g> (رجاء)، <r v=\"2Thess.2.16\"></r>؛ <g>θησαυρός</g> (كنز)، <r v=\"Matt.12.35\"></r>؛ <g>μνεία</g> (ذِكر)، <r v=\"1Thess.3.6\"></r> (قارن <r v=\"2Macc.7.20\"></r>)؛ اسمًا، <g>τὸ ἀ.</g>: ما هو صالح أخلاقيًا، نافع، مرضيّ عند الله، <r v=\"Rom.12.2\"></r>؛ <g>ἐργάζεσθαι τὸ ἀ</g> (يفعل الصلاح)، <r v=\"Rom.2.10\"></r>، <r v=\"Eph.4.28\"></r>؛ <g>πράσσειν</g>، <r v=\"Rom.9.11\"></r>، <r v=\"2Cor.5.10\"></r>؛ <g>διώκειν</g> (يتبع)، <r v=\"1Thess.5.15\"></r>؛ <g>μιμεῖσθαι</g> (يتمثّل بـ)، <r v=\"3John.1.11\"></r>؛ <g>κολλᾶσθαι τῷ ἀ.</g> (يلتصق بالخير)، <r v=\"Rom.12.9\"></r>؛ <g>ερωτᾶν περὶ τοῦ ἀ.</g> (يسأل عن الصالح)، <r v=\"Matt.19.17\"></r>؛ <g>διάκονος εἰς τὸ ἀ.</g> (خادم للصلاح)، <r v=\"Rom.13.4\"></r>؛ <g>τὸ ἀ. σου</g>: <b>إحسانك، خيرك</b>، <r v=\"Phlm.1.14\"></r>؛ جمع، <g>τὰ ἀ.</g>، عن الخيرات والممتلكات، <r v=\"Luke.12.18\"></r>؛ وعن البركات الروحية، <r v=\"Rom.10.15\"></r>، <r v=\"Heb.9.11\"></r>، <r v=\"Heb.10.1\"></r>. و<g>ἀ.</g> عكس <g>πονηρός</g> (شرير)، <r v=\"Matt.5.45\"></r>، <r v=\"Matt.20.15\"></r>؛ و<g>κακός</g> (رديء، شر)، <r v=\"Rom.7.19\"></r>؛ و<g>φαῦλος</g> (سيئ)، <r v=\"Rom.9.11\"></r>، <r v=\"2Cor.5.10\"></r>.</s>"},"G1889":{"l":"Ἐπαφρᾶς","o":3,"en":"<f><o>Ἐπαφρᾶς</o>, <g>-ᾶ</g> (B1., § 7, 4), <g>ὁ</g>, </f> <s><b>Epaphras</b>: <r v=\"Col.1.7\"></r> <r v=\"Col.4.12\"></r>, <r v=\"Phlm.1.23\"></r>.*† </s>","ar":"<f><o>Ἐπαφρᾶς</o>، <g>-ᾶ</g>، <g>ὁ</g>، </f> <s><b>أبفراس</b>: <r v=\"Col.1.7\"></r> <r v=\"Col.4.12\"></r>، <r v=\"Phlm.1.23\"></r>.*† </s>"},"G191":{"l":"ἀκούω","o":428,"en":"<f><o>ἀκούω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8085\">שׁמע</h>;]</e> </et> <s><b>to hear</b>, <b>listen</b>, <b>attend</b>, <b>perceive by hearing</b>, <b>comprehend by hearing</b>. <s n=\"1.\">Intrans.: <r v=\"Mark.4.3\"></r> <r v=\"Mark.7.37\"></r>, <r v=\"Jas.2.5\"></r>, <r v=\"Rev.2.7\"></r>, al.; <g>τ. ὠσίν</g>, <r v=\"Matt.13.15\"></r><i>(LXX)</i>; c. cogn. dat., <g>ακοῇ ἀ.</g> (v.s. <g>ἀκοή</g>), <r v=\"Matt.13.14\"></r>, <r v=\"Acts.28.26\"></r><i>(LXX)</i>; <g>ὁ ἔχων ὦτα</g> (<g>οὖς</g>) <g>ἀκούειν, ἀκουσάτω</g>, <r v=\"Matt.11.15\"></r>, <r v=\"Mark.4.23\"></r>, <r v=\"Rev.2.7\"></r>, al.</s> <s n=\"2.\">Trans., prop. c. acc. rei, of thing heard, gen. pers., from whom heard (LS, s.v.): <r v=\"Acts.1.4\"></r>; c. acc. rei, <r v=\"Matt.12.19\"></r>, <r v=\"John.3.8\"></r> (Abbott, <i>JG</i>, 76), <r v=\"Acts.22.9\"></r>, al.; c. dupl. acc., <r v=\"John.12.18\"></r>, <r v=\"1Cor.11.18\"></r>; c. gen. rei, <r v=\"John.7.40\"></r> (Abbott, <i>JV</i>, 116); <g>τ. φωνῆς</g> (cf. Heb. <h n=\"H8085,H6963\">שָׁמַע בְּקֹול</h>, <r v=\"Exod.18.19\"></r>), <r v=\"John.5.25\"></r>, <r v=\"John.5.28\"></r> <r v=\"Acts.9.7\"></r> (on the distinction bet. this and <g>ἀ. φωνήν</g>, <r v=\"Acts.9.4\"></r>, v. M, <i>Pr.</i>, 66; Field, <i>Notes</i>, 117; Abbott, <i>Essays</i>, 93f.); of God answering prayer, <r v=\"John.9.31\"></r>, <r v=\"1John.5.14\"></r>, 15; c. acc. rei, seq. <g>παρά</g>, <r v=\"John.8.26\"></r>, <r v=\"John.8.40\"></r> <r v=\"Acts.10.22\"></r>, <r v=\"2Tim.2.2\"></r>; id. seq. <g>ἀπό</g>, <r v=\"1John.1.5\"></r>; c. gen. pars. seq. ptcp., <r v=\"Mark.14.58\"></r>, <r v=\"Luke.18.36\"></r>, al. (On NT usage generally, v. Bl., §36, 5; Cremer, 82.) </s> </s>","ar":"<f><o>ἀκούω</o>،</f> <s><b>سمع</b>، <b>أصغى</b>، <b>انتبه</b>، <b>أدرك بالسمع</b>، <b>فهم بالسمع</b>. <s n=\"1.\">لازم: <r v=\"Mark.4.3\"></r>، <r v=\"Mark.7.37\"></r>، <r v=\"Jas.2.5\"></r>، <r v=\"Rev.2.7\"></r>، وفي مواضع أخرى؛ <g>τ. ὠσίν</g>: <r v=\"Matt.13.15\"></r><i>(السبعينية)</i>؛ مع القابل من لفظ الفعل: <g>ακοῇ ἀ.</g> (انظر تحت مدخل <g>ἀκοή</g>): <r v=\"Matt.13.14\"></r>، <r v=\"Acts.28.26\"></r><i>(السبعينية)</i>؛ <g>ὁ ἔχων ὦτα</g> (<g>οὖς</g>) <g>ἀκούειν, ἀκουσάτω</g>: <r v=\"Matt.11.15\"></r>، <r v=\"Mark.4.23\"></r>، <r v=\"Rev.2.7\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\">متعدٍّ، أصلاً مع المنصوب للشيء المسموع، والمضاف إليه للشخص المسموع منه: <r v=\"Acts.1.4\"></r>؛ مع المنصوب للشيء: <r v=\"Matt.12.19\"></r>، <r v=\"John.3.8\"></r>، <r v=\"Acts.22.9\"></r>، وفي مواضع أخرى؛ مع مفعولين منصوبين: <r v=\"John.12.18\"></r>، <r v=\"1Cor.11.18\"></r>؛ مع المضاف إليه للشيء: <r v=\"John.7.40\"></r>؛ <g>τ. φωνῆς</g> (قارن العبرية <h n=\"H8085,H6963\">שָׁמַע בְּקֹול</h>، <r v=\"Exod.18.19\"></r>): <r v=\"John.5.25\"></r>، <r v=\"John.5.28\"></r>، <r v=\"Acts.9.7\"></r> (وعن الفرق بين هذا و<g>ἀ. φωνήν</g>، <r v=\"Acts.9.4\"></r>)؛ عن استجابة الله للصلاة: <r v=\"John.9.31\"></r>، <r v=\"1John.5.14\"></r>، 15؛ مع المنصوب للشيء يليه <g>παρά</g>: <r v=\"John.8.26\"></r>، <r v=\"John.8.40\"></r>، <r v=\"Acts.10.22\"></r>، <r v=\"2Tim.2.2\"></r>؛ ونفسه يليه <g>ἀπό</g>: <r v=\"1John.1.5\"></r>؛ مع المضاف إليه للشخص يليه اسم الفاعل: <r v=\"Mark.14.58\"></r>، <r v=\"Luke.18.36\"></r>، وفي مواضع أخرى. </s> </s>"},"G1922":{"l":"ἐπίγνωσις","o":20,"en":"<f>† <o>ἐπί-γνωσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπιγινώσκω</g>, q.v.), </e> <e t=\"septuagint\">[in LXX: <r v=\"1Kgs.7.14\"></r> (B. <g>γν-</g>), <r v=\"Prov.2.5\"></r>, <r v=\"Hos.4.1\"></r>, <r v=\"Hos.4.6\"></r> <r v=\"Hos.6.6\"></r> (<h n=\"H1847\">דַּעַת</h>), <r v=\"Jdt.9.14\"></r>, <r v=\"2Macc.9.11\"></r> * ;]</e> </et> <s><b>acquaintance, discernment, recognition</b> (Plut., al.): <r v=\"Phil.1.9\"></r>, <r v=\"Col.3.10\"></r>; c. gen. rei, <r v=\"Col.1.9\"></r> <r v=\"Col.2.2\"></r>, <r v=\"Phlm.1.6\"></r>; <g>τ. ἀληθείας</g>, <r v=\"1Tim.2.4\"></r>, <r v=\"2Tim.2.25\"></r> <r v=\"2Tim.3.7\"></r>, <r v=\"Titus.1.1\"></r>, <r v=\"Heb.10.26\"></r>; <g>τ. ἁμαρτίας</g>, <r v=\"Rom.3.20\"></r>; c. gen. pers., of God: <r v=\"Eph.1.17\"></r>, <r v=\"Col.1.10\"></r>, <r v=\"2Pet.1.2\"></r>, <r v=\"2Pet.1.3\"></r>; of Christ: <r v=\"Eph.4.13\"></r>, <r v=\"2Pet.1.8\"></r> <r v=\"2Pet.2.20\"></r>; of God and Christ: <r v=\"2Pet.1.2\"></r>; <g>κατ</g> ̓ <g>ἐ.</g>, <r v=\"Rom.10.2\"></r>; <g>ἔχειν ἐν ἐ.</g>, <r v=\"Rom.1.28\"></r> (v. AR, <i>Eph.</i>, 248 ff.; and for a somewhat different view, Thayer, s.v.; Lft. on <r v=\"Col.1.9\"></r>; Tr., <i>Syn.</i>, lxxv; Cremer, 159 f.; cf. <g>αἴσθησις</g>).†</s>","ar":"<f>† <o>ἐπί-γνωσις</o>، <g>-εως, ἡ</g></f> <s><b>معرفة، تمييز، إدراك</b>: <r v=\"Phil.1.9\"></r>، <r v=\"Col.3.10\"></r>؛ مع المضاف إليه للشيء، <r v=\"Col.1.9\"></r> <r v=\"Col.2.2\"></r>، <r v=\"Phlm.1.6\"></r>؛ <g>τ. ἀληθείας</g>، <r v=\"1Tim.2.4\"></r>، <r v=\"2Tim.2.25\"></r> <r v=\"2Tim.3.7\"></r>، <r v=\"Titus.1.1\"></r>، <r v=\"Heb.10.26\"></r>؛ <g>τ. ἁμαρτίας</g>، <r v=\"Rom.3.20\"></r>؛ مع المضاف إليه للشخص، عن الله: <r v=\"Eph.1.17\"></r>، <r v=\"Col.1.10\"></r>، <r v=\"2Pet.1.2\"></r>، <r v=\"2Pet.1.3\"></r>؛ عن المسيح: <r v=\"Eph.4.13\"></r>، <r v=\"2Pet.1.8\"></r> <r v=\"2Pet.2.20\"></r>؛ عن الله والمسيح: <r v=\"2Pet.1.2\"></r>؛ <g>κατ</g> ̓ <g>ἐ.</g>، <r v=\"Rom.10.2\"></r>؛ <g>ἔχειν ἐν ἐ.</g>، <r v=\"Rom.1.28\"></r> (قارن <r v=\"Col.1.9\"></r>؛ <g>αἴσθησις</g>).†</s>"},"G2004":{"l":"ἐπιτάσσω","o":10,"en":"<f><o>ἐπι-τάσσω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H559\">אָמַר</h>, <h n=\"H6680\">צָוָה</h>, etc. ;]</e> </et> <s><b>to command, charge</b>: c. acc rei, <r v=\"Luke.14.22\"></r>; c. dat. pers., <r v=\"Mark.1.27\"></r> <r v=\"Mark.9.25\"></r>, <r v=\"Luke.4.36\"></r> <r v=\"Luke.8.25\"></r>; id. c. acc rei, <r v=\"Phlm.1.8\"></r>; id. c. inf., <r v=\"Mark.6.39\"></r>, <r v=\"Luke.8.31\"></r>, <r v=\"Acts.23.2\"></r>; id. c. imperat., <r v=\"Mark.9.25\"></r>; c. acc et inf., <r v=\"Mark.6.27\"></r>.†</s> <sy><i>SYN.</i>: <g>κελεύω</g> </sy>","ar":"<f><o>ἐπι-τάσσω </o></f> <s><b>يأمر، يوصي</b>: مع المنصوب للأشياء، <r v=\"Luke.14.22\"></r>؛ مع القابل للأشخاص، <r v=\"Mark.1.27\"></r> <r v=\"Mark.9.25\"></r>، <r v=\"Luke.4.36\"></r> <r v=\"Luke.8.25\"></r>؛ والتعبير نفسه مع المنصوب للأشياء، <r v=\"Phlm.1.8\"></r>؛ ومع المصدر، <r v=\"Mark.6.39\"></r>، <r v=\"Luke.8.31\"></r>، <r v=\"Acts.23.2\"></r>؛ ومع الأمر، <r v=\"Mark.9.25\"></r>؛ مع المنصوب والمصدر، <r v=\"Mark.6.27\"></r>.†</s>"},"G2090":{"l":"ἑτοιμάζω","o":40,"en":"<f><o>ἑτοιμάζω</o></f> <et> <e t=\"derivation\">(&lt; <g>ἕτοιμος</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3559\">כּוּן</h> hi. (Hatch, <i>Essays</i>, 51 ff.) ;] </e> </et> <s>to prepare, make ready; </s> <s n=\"(a)\">absol., of hospitable preparation: <r v=\"Mark.14.15\"></r>, <r v=\"Luke.9.52\"></r> <r v=\"Luke.12.47\"></r> <r v=\"Luke.22.9\"></r>, <r v=\"Luke.22.12\"></r>; c. inf., <r v=\"Matt.26.17\"></r>; <g>ἵνα</g>, <r v=\"Mark.14.12\"></r>; </s> <s n=\"(b)\">c. acc rei: <r v=\"Matt.22.4\"></r> <r v=\"Matt.26.19\"></r>, <r v=\"Mark.14.16\"></r>, <r v=\"Luke.12.20\"></r> <r v=\"Luke.17.8\"></r> <r v=\"Luke.22.8\"></r>, <r v=\"Luke.22.13\"></r> <r v=\"Luke.23.56\"></r> <r v=\"Luke.24.1\"></r>, <r v=\"John.14.2-John.14.3\"></r>, <r v=\"Phlm.1.22\"></r>, <r v=\"Rev.9.7\"></r> <r v=\"Rev.16.12\"></r>; seq. <g>εἰς</g>, <r v=\"2Tim.2.21\"></r>; of God's ordaining coming events (Dalman, <i>Words</i>, 128); of blessing, <r v=\"Matt.20.23\"></r> <r v=\"Matt.25.34\"></r>, <r v=\"Mark.10.40\"></r>, <r v=\"Luke.2.31\"></r>, <r v=\"1Cor.2.9\"></r>, <r v=\"Heb.11.16\"></r>, <r v=\"Rev.12.6\"></r>; of judgment, <r v=\"Matt.25.41\"></r>; of preparation for the Messiah, <g>τ. ὁδὸν κυρίου</g>, <r v=\"Matt.3.3\"></r>, <r v=\"Mark.1.3\"></r>, <r v=\"Luke.1.76\"></r> <r v=\"Luke.3.4\"></r> <i>(LXX)</i>; </s> <s n=\"(c)\">c. acc pers.: <r v=\"Luke.1.17\"></r>, <r v=\"Acts.23.23\"></r>, <r v=\"Rev.19.7\"></r>, seq. <g>ἵνα</g>, <r v=\"Rev.8.6\"></r>; <g>εἰς</g>, <r v=\"2Tim.2.21\"></r>, <r v=\"Rev.9.7\"></r>, <r v=\"Rev.9.15\"></r> <r v=\"Rev.21.2\"></r>.†</s>","ar":"<f><o>ἑτοιμάζω</o></f> <s><b>يُعِدّ، يُهيِّئ</b>؛ </s> <s n=\"(a)\">مطلقًا، عن الإعداد لضيافة: <r v=\"Mark.14.15\"></r>، <r v=\"Luke.9.52\"></r> <r v=\"Luke.12.47\"></r> <r v=\"Luke.22.9\"></r>، <r v=\"Luke.22.12\"></r>؛ مع المصدر، <r v=\"Matt.26.17\"></r>؛ <g>ἵνα</g>، <r v=\"Mark.14.12\"></r>؛ </s> <s n=\"(b)\">مع المنصوب للأشياء: <r v=\"Matt.22.4\"></r> <r v=\"Matt.26.19\"></r>، <r v=\"Mark.14.16\"></r>، <r v=\"Luke.12.20\"></r> <r v=\"Luke.17.8\"></r> <r v=\"Luke.22.8\"></r>، <r v=\"Luke.22.13\"></r> <r v=\"Luke.23.56\"></r> <r v=\"Luke.24.1\"></r>، <r v=\"John.14.2-John.14.3\"></r>، <r v=\"Phlm.1.22\"></r>، <r v=\"Rev.9.7\"></r> <r v=\"Rev.16.12\"></r>؛ يليه <g>εἰς</g>، <r v=\"2Tim.2.21\"></r>؛ وعن تدبير الله المسبق لأحداث آتية: للبركة، <r v=\"Matt.20.23\"></r> <r v=\"Matt.25.34\"></r>، <r v=\"Mark.10.40\"></r>، <r v=\"Luke.2.31\"></r>، <r v=\"1Cor.2.9\"></r>، <r v=\"Heb.11.16\"></r>، <r v=\"Rev.12.6\"></r>؛ وللدينونة، <r v=\"Matt.25.41\"></r>؛ وعن الإعداد لمجيء المسيا، <g>τ. ὁδὸν κυρίου</g> (طريق الرب)، <r v=\"Matt.3.3\"></r>، <r v=\"Mark.1.3\"></r>، <r v=\"Luke.1.76\"></r> <r v=\"Luke.3.4\"></r> <i>(السبعينية)</i>؛ </s> <s n=\"(c)\">مع المنصوب للأشخاص: <r v=\"Luke.1.17\"></r>، <r v=\"Acts.23.23\"></r>، <r v=\"Rev.19.7\"></r>، يليه <g>ἵνα</g>، <r v=\"Rev.8.6\"></r>؛ <g>εἰς</g>، <r v=\"2Tim.2.21\"></r>، <r v=\"Rev.9.7\"></r>، <r v=\"Rev.9.15\"></r> <r v=\"Rev.21.2\"></r>.†</s>"},"G2098":{"l":"εὐαγγέλιον","o":76,"en":"<f><o>εὐαγγέλιον</o>, <g>-ου, τό </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1309\">בְּשׂוֹרָה</h>, <h n=\"H1309\">בְּשׂרָה</h>, <r v=\"2Sam.4.10\"></r> <r v=\"2Sam.18.22\"></r> <r v=\"2Sam.18.25\"></r> * ;] </e> </et> <s n=\"1.\">in cl., </s> <s n=\"(a)\"><h n=\"H1309\">בְּשׂוֹרָה</h>, <b>a reward for good tidings</b> (Hom.; pl., LXX, <r v=\"2Sam.4.10\"></r>); </s> <s n=\"(b)\">in pl., <g>εὐ. θύειν</g>, <b>to make a thank-offering for good tidings</b> (Xen., al.). </s> <s n=\"2.\">Later (Luc., Plut., al.), <b>good tidings, good news</b>; in NT of the good tidings of the kingdom of God and of salvation through Christ, <b>the gospel</b>: <r v=\"Mark.1.15\"></r>, <r v=\"Acts.15.7\"></r>, <r v=\"Rom.1.16\"></r>, <r v=\"Gal.2.2\"></r>, <r v=\"1Thess.2.4\"></r>, al.; c. gen. obj., <g>τ. βασιλείας</g>, <r v=\"Matt.4.23\"></r>; <g>τ. Χριστοῦ</g>, <r v=\"Rom.15.19\"></r>, al.; <g>τ. κυρίου ἡμῶν Ἰησοῦ</g>, <r v=\"2Thess.1.8\"></r>; <g>τ. υἱοῦ τ. θεοῦ</g>, <r v=\"Rom.1.9\"></r>; <g>τ. δόξης τ. μακαρίου θεοῦ</g>, <r v=\"1Tim.1.11\"></r>; <g>τ. δόξης τ. Χριστοῦ</g>, <r v=\"2Cor.4.4\"></r>; of the author, <g>τ. θεοῦ</g>, <r v=\"Rom.15.16\"></r>, al.; of the teacher, <g>ἡμῶν</g>, <r v=\"Rom.2.16\"></r>, <r v=\"2Cor.4.3\"></r>, <r v=\"1Thess.1.5\"></r>, <r v=\"2Tim.2.8\"></r>; of the taught, <g>τ. περιτομῆς, τ. ἀκροβυστίας</g>, <r v=\"Gal.2.7\"></r>; <g>ἡ ἀλήθεια τοῦ εὐ.</g>, <r v=\"Gal.2.5\"></r>, <r v=\"Gal.2.14\"></r> <r v=\"Col.1.5\"></r>; <g>ἡ ἐλπὶς</g> (<g>πίστις</g>) <g>τοῦ εὐ.</g>, <r v=\"Col.1.23\"></r>, <r v=\"Phil.1.27\"></r> (v. Cremer, 31 ff.; and on the later eccl. use of the word„ M, <i>Th.</i>, 143 f.) </s>","ar":"<f><o>εὐαγγέλιον</o>، <g>-ου, τό </g></f> <s n=\"1.\">في اليونانية الكلاسيكية، </s> <s n=\"(a)\"><h n=\"H1309\">בְּשׂוֹרָה</h>: <b>مكافأة على البشارة</b> (جمع، السبعينية، <r v=\"2Sam.4.10\"></r>)؛ </s> <s n=\"(b)\">في الجمع، <g>εὐ. θύειν</g>: <b>تقديم ذبيحة شكر على خبر سارّ</b>. </s> <s n=\"2.\">وفيما بعد: <b>بشارة، خبر سارّ</b>؛ وفي العهد الجديد عن بشارة ملكوت الله والخلاص بالمسيح: <b>الإنجيل</b>: <r v=\"Mark.1.15\"></r>، <r v=\"Acts.15.7\"></r>، <r v=\"Rom.1.16\"></r>، <r v=\"Gal.2.2\"></r>، <r v=\"1Thess.2.4\"></r>، وفي مواضع أخرى؛ مع المضاف إليه الدال على الموضوع، <g>τ. βασιλείας</g> (بشارة الملكوت)، <r v=\"Matt.4.23\"></r>؛ <g>τ. Χριστοῦ</g> (إنجيل المسيح)، <r v=\"Rom.15.19\"></r>، وفي مواضع أخرى؛ <g>τ. κυρίου ἡμῶν Ἰησοῦ</g>، <r v=\"2Thess.1.8\"></r>؛ <g>τ. υἱοῦ τ. θεοῦ</g>، <r v=\"Rom.1.9\"></r>؛ <g>τ. δόξης τ. μακαρίου θεοῦ</g> (إنجيل مجد الله المبارك)، <r v=\"1Tim.1.11\"></r>؛ <g>τ. δόξης τ. Χριστοῦ</g>، <r v=\"2Cor.4.4\"></r>؛ وعن مصدره، <g>τ. θεοῦ</g> (إنجيل الله)، <r v=\"Rom.15.16\"></r>، وفي مواضع أخرى؛ وعن المعلِّم، <g>ἡμῶν</g> (إنجيلنا)، <r v=\"Rom.2.16\"></r>، <r v=\"2Cor.4.3\"></r>، <r v=\"1Thess.1.5\"></r>، <r v=\"2Tim.2.8\"></r>؛ وعن المتلقّين، <g>τ. περιτομῆς, τ. ἀκροβυστίας</g> (إنجيل الختان، إنجيل الغرلة)، <r v=\"Gal.2.7\"></r>؛ <g>ἡ ἀλήθεια τοῦ εὐ.</g> (حق الإنجيل)، <r v=\"Gal.2.5\"></r>، <r v=\"Gal.2.14\"></r> <r v=\"Col.1.5\"></r>؛ <g>ἡ ἐλπὶς</g> (<g>πίστις</g>) <g>τοῦ εὐ.</g> (رجاء الإنجيل، إيمان الإنجيل)، <r v=\"Col.1.23\"></r>، <r v=\"Phil.1.27\"></r>. </s>"},"G2168":{"l":"εὐχαριστέω","o":38,"en":"<f>** <o>εὐχαριστέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jdt.8.25\"></r> <r v=\"Wis.18.2\"></r>, <r v=\"2Macc.1.11\"></r> <r v=\"2Macc.10.7\"></r> A <r v=\"2Macc.12.31\"></r> R, <r v=\"3Macc.7.16\"></r> * ;]</e> </et> <s><b>to be thankful, give thanks</b> (chiefly in late writers and Inscr.; cf. Milligan, <i>Th.</i>, 5; Ellic. on <r v=\"Col.1.12\"></r>; Lft., <i>Notes</i>, 9): <r v=\"Rom.1.21\"></r>, <r v=\"1Cor.14.17\"></r>, <r v=\"1Thess.5.18\"></r>; of giving thanks before meat, <r v=\"Matt.15.36\"></r> <r v=\"Matt.26.27\"></r>, <r v=\"Mark.8.6\"></r> <r v=\"Mark.14.23\"></r>, <r v=\"Luke.22.17\"></r>, <r v=\"Luke.22.19\"></r>, <r v=\"John.6.11\"></r>, <r v=\"John.6.23\"></r>, <r v=\"1Cor.11.24\"></r>; c. dat. pens., <g>τ. θεῷ</g>, <r v=\"Luke.17.16\"></r>, <r v=\"Acts.27.35\"></r> <r v=\"Acts.28.15\"></r>, <r v=\"Rom.14.6\"></r> <r v=\"Rom.16.4\"></r>, <r v=\"1Cor.14.18\"></r>, <r v=\"Phil.1.3\"></r>, <r v=\"Col.1.3\"></r>, <r v=\"Col.1.12\"></r>, <r v=\"Phlm.1.4\"></r>; seq. <g>διὰ Ἰ. Χριστοῦ</g>, <r v=\"Rom.1.8\"></r> <r v=\"Rom.7.25\"></r>, R, WH, mg., <r v=\"Col.3.17\"></r>; <g>ἐν ὀνόματι Χρ.</g>, <r v=\"Eph.5.20\"></r>; seq. <g>περί</g>, <r v=\"1Thess.1.2\"></r>, <r v=\"2Thess.1.3\"></r>; <g>ὅτι</g>, <r v=\"Rom.1.8\"></r>, <r v=\"2Thess.2.13\"></r>; <g>ἐπι</g>, c. dat. rei, <r v=\"1Cor.1.4\"></r>; <g>ὐπέρ</g>, <r v=\"1Cor.10.30\"></r>, <r v=\"Eph.1.16\"></r> <r v=\"Eph.5.20\"></r>; <g>ὅτι</g>, <r v=\"Luke.18.11\"></r>, <r v=\"John.11.41\"></r>, <r v=\"1Cor.1.14\"></r>, <r v=\"1Thess.2.13\"></r>, <r v=\"Rev.11.17\"></r>; pass. (Deiss., <i>BS</i>, 122 f.), <r v=\"2Cor.1.11\"></r>.†</s> <sy><i>SYN.</i>: v.s. <x><g>αἰνέω</g></x>; and cf. Cremer, 903 f </sy>","ar":"<f>** <o>εὐχαριστέω</o>، <g>-ῶ </g></f> <s><b>يشكر، يقدّم الشكر</b> (قارن <r v=\"Col.1.12\"></r>): <r v=\"Rom.1.21\"></r>، <r v=\"1Cor.14.17\"></r>، <r v=\"1Thess.5.18\"></r>؛ عن الشكر قبل الطعام، <r v=\"Matt.15.36\"></r> <r v=\"Matt.26.27\"></r>، <r v=\"Mark.8.6\"></r> <r v=\"Mark.14.23\"></r>، <r v=\"Luke.22.17\"></r>، <r v=\"Luke.22.19\"></r>، <r v=\"John.6.11\"></r>، <r v=\"John.6.23\"></r>، <r v=\"1Cor.11.24\"></r>؛ مع قابل الشخص، <g>τ. θεῷ</g>، <r v=\"Luke.17.16\"></r>، <r v=\"Acts.27.35\"></r> <r v=\"Acts.28.15\"></r>، <r v=\"Rom.14.6\"></r> <r v=\"Rom.16.4\"></r>، <r v=\"1Cor.14.18\"></r>، <r v=\"Phil.1.3\"></r>، <r v=\"Col.1.3\"></r>، <r v=\"Col.1.12\"></r>، <r v=\"Phlm.1.4\"></r>؛ يليه <g>διὰ Ἰ. Χριστοῦ</g>، <r v=\"Rom.1.8\"></r> <r v=\"Rom.7.25\"></r>، <r v=\"Col.3.17\"></r>؛ <g>ἐν ὀνόματι Χρ.</g>، <r v=\"Eph.5.20\"></r>؛ يليه <g>περί</g>، <r v=\"1Thess.1.2\"></r>، <r v=\"2Thess.1.3\"></r>؛ <g>ὅτι</g>، <r v=\"Rom.1.8\"></r>، <r v=\"2Thess.2.13\"></r>؛ <g>ἐπι</g>، مع قابل الشيء، <r v=\"1Cor.1.4\"></r>؛ <g>ὐπέρ</g>، <r v=\"1Cor.10.30\"></r>، <r v=\"Eph.1.16\"></r> <r v=\"Eph.5.20\"></r>؛ <g>ὅτι</g>، <r v=\"Luke.18.11\"></r>، <r v=\"John.11.41\"></r>، <r v=\"1Cor.1.14\"></r>، <r v=\"1Thess.2.13\"></r>، <r v=\"Rev.11.17\"></r>؛ المبني للمجهول، <r v=\"2Cor.1.11\"></r>.†</s>"},"G2173":{"l":"εὔχρηστος","o":3,"en":"<f><o>εὔ-χρηστος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(<g>εὖ, χράομαι</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.31.13\"></r> (<h n=\"H2656\">חֵפֶץ</h>), <r v=\"Wis.13.13\"></r> * ;] </e> </et> <s><b>useful, serviceable</b>: c. dat. pers., <r v=\"2Tim.2.21\"></r>; id. seq. <g>εἰς</g>, c. dat. rei, <r v=\"2Tim.4.11\"></r>; opp. to <g>ἄχρηστος</g>, <r v=\"Phlm.1.11\"></r>.†</s>","ar":"<f><o>εὔ-χρηστος</o>، <g>-ον</g></f> <s><b>نافع، صالح للخدمة</b>: مع القابل للشخص: <r v=\"2Tim.2.21\"></r>؛ ونفسه يليه <g>εἰς</g> مع القابل للشيء: <r v=\"2Tim.4.11\"></r>؛ عكس <g>ἄχρηστος</g>: <r v=\"Phlm.1.11\"></r>.†</s>"},"G2192":{"l":"ἔχω","o":708,"en":"<f><o>ἔχω</o>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H680\">אָצֵל</h> (<x><g>ἐχόμενος</g></x>), <h n=\"H1167\">בַּעַל</h>, <h n=\"H3426\">יֵשׁ</h>, etc., 59 words in all;]</e> <e t=\"derivation\">(on the <i>Aktionsart</i> of the various tenses, v. M, <i>Pr.</i>, 110, 145, 150, 183),</e> </et> <s><b>to have</b>, as in cl., in various senses and constructions. <s n=\"I.\">Trans.; <s n=\"1.\"><b>to have</b>, <b>hold</b>, <b>hold fast</b>, etc.; <s n=\"(a)\"><b>to hold</b>, as, in the hand: <r v=\"Rev.5.8\"></r> <r v=\"Rev.14.6\"></r>, al.; <g>ἐν τ. χειρί</g>, <r v=\"Rev.1.16\"></r> <r v=\"Rev.10.2\"></r>, al.;</s> <s n=\"(b)\">of arms and clothing, = <x><g>φέρω</g></x>, <x><g>φορέω</g></x>, <b>to bear</b>, <b>wear</b>: <r v=\"Matt.3.4\"></r> <r v=\"Matt.22.12\"></r>, al.; so freq. pres. ptcp. (LS, s.v., A, I, 6; Bl., § 74, 2), <r v=\"Mark.11.13\"></r>, <r v=\"John.18.10\"></r>, <r v=\"Rev.9.17\"></r>, al.;</s> <s n=\"(c)\">of a woman, <g>ἐν γαστρὶ ἔ</g> (<g>κοίτην ἔ.</g>), <b>to be with child</b>: <r v=\"Mark.13.17\"></r>, <r v=\"Rom.9.10\"></r>;</s> <s n=\"(d)\"><b>to hold fast</b>, <b>keep</b>: <r v=\"Luke.19.20\"></r>; metaph., of the mind and conduct, <r v=\"Mark.16.8\"></r> (cf. <r v=\"Job.21.6\"></r>, <r v=\"Isa.13.8\"></r>; Deiss., <i>BS</i>, 293; Field, <i>Notes</i>, 44 f.), <r v=\"John.14.21\"></r>, <r v=\"Rom.1.28\"></r>, <r v=\"1Tim.3.9\"></r>, <r v=\"2Tim.1.13\"></r>, <r v=\"Rev.6.9\"></r>, al.;</s> <s n=\"(e)\"><b>to involve</b>: <r v=\"Heb.10.35\"></r><i>(LXX)</i>, <r v=\"Jas.1.4\"></r>, <r v=\"John.4.18\"></r>;</s> <s n=\"(f)\">= Lat. <l>habere</l> (Bl., § 34, 5; 73, 5), <b>to hold</b>, <b>consider</b>: c. acc. et predic. ptcp., <r v=\"Luke.14.18\"></r>; c. acc., seq. <g>ὡς</g>, <r v=\"Matt.14.5\"></r>; <g>εἰς</g> (Hebraism), <r v=\"Matt.21.46\"></r>; on (Bl., § 70, 2), <r v=\"Mark.11.32\"></r>.</s> </s> <s n=\"2.\"><b>to have</b>, <b>possess</b>; <s n=\"(a)\">in general, c. acc. rei: <r v=\"Matt.19.22\"></r>, <r v=\"Mark.10.22\"></r>, <r v=\"Luke.12.19\"></r>, <r v=\"John.10.16\"></r>, <r v=\"1Cor.11.22\"></r>, al.; of wealth or poverty, absol., <g>ἔχειν</g> (neg. <g>οὐκ</g>, <g>μή</g>), <r v=\"Matt.13.12\"></r> <r v=\"Matt.25.29\"></r>, <r v=\"2Cor.8.12\"></r>; <g>ἐκ τ. ἔχειν</g>, <b>according to your means</b>, <r v=\"2Cor.8.11\"></r>;</s> <s n=\"(b)\">of relationship, association, etc.: <g>πατέρα</g>, <r v=\"John.8.41\"></r>; <g>γυναῖκα</g> (MM, xiv), <r v=\"1Cor.7.2\"></r>; <g>φίλον</g>, <r v=\"Luke.11.5\"></r>; <g>βασιλέα</g>, <r v=\"John.19.15\"></r>; <g>ποιμένα</g>, <r v=\"Matt.9.36\"></r>; c. dupl. acc., <r v=\"Matt.3.9\"></r>, al.;</s> <s n=\"(c)\">of parts or members: <g>ὦτα</g>, <r v=\"Matt.19.15\"></r>; <g>μέλη</g>, <r v=\"Rom.12.4\"></r>; <g>θεμελίους</g>, </s> <s n=\"(d)\">c. acc., as periphrasis of verb: <g>μνεῖαν ἔ.</g> (= <x><g>μεμνῆσθαι</g></x>), <r v=\"1Thess.3.6\"></r>; <g>ἀγάπην</g>, <r v=\"John.13.35\"></r>; <g>γνῶσιν</g>, <r v=\"1Cor.8.1\"></r>; <g>πεποίθησιν</g>, <r v=\"2Cor.3.4\"></r>; <g>θλίψιν</g>, <r v=\"John.16.33\"></r>, etc. (Thayer, s.v., I, 2, f., g.);</s> <s n=\"(e)\">of duty, necessity, etc.: <g>ἀνάγκην</g>, <r v=\"1Cor.7.37\"></r>; <g>νόμον</g>, <r v=\"John.19.7\"></r>; <g>ἐπιταγήν</g>, <r v=\"1Cor.7.25\"></r>; <g>ἀγῶνα</g>, <r v=\"Phil.1.30\"></r>; <g>κρίμα</g>, <r v=\"1Tim.5.12\"></r>;</s> <s n=\"(f)\">of complaints and disputes; <g>κατά</g>, c. gen. pers., <r v=\"Matt.5.23\"></r>, <r v=\"Mark.11.25\"></r>; id. seq. <g>ὅτι</g>, <r v=\"Rev.2.4\"></r>, <r v=\"Rev.2.20\"></r>; c. acc. seq. <g>πρός</g>, <r v=\"Acts.24.19\"></r>, al.;</s> <s n=\"(g)\">c. inf., <s n=\"(α)\">(cl.) <b>to be able</b> (Field, <i>Notes</i>, 14): <r v=\"Matt.18.25\"></r>, <r v=\"Mark.14.8\"></r> (sc. <x><g>ποιῆσαι</g></x>), <r v=\"Luke.12.4\"></r>, <r v=\"Acts.4.14\"></r>, al;</s> <s n=\"(β)\">of necessity (Bl., § 69, 4): <r v=\"Luke.12.50\"></r>, <r v=\"Acts.23.17-Acts.23.19\"></r> <r v=\"Acts.28.19\"></r>.</s> </s> </s> </s> <s n=\"II.\">Intrans. (Bl., § 53, 1), <b>to be</b> in a certain condition: <g>ἑτοίμως ἔ.</g>, c. inf., <r v=\"Acts.21.13\"></r>, <r v=\"2Cor.12.14\"></r>; <g>ἐσχάτως</g> (q.v.), <r v=\"Mark.5.23\"></r>; <g>κακῶς</g>, <b>to be ill</b>, <r v=\"Matt.4.24\"></r>, al.; <g>καλῶς</g>, <r v=\"Mark.16.18\"></r>; <g>κομψότερον</g>, <r v=\"John.4.52\"></r>; <g>πῶς</g>, <r v=\"Acts.15.36\"></r>; impers., <g>ἄλλως ἔχει</g>, <b>it is otherwise</b>, <r v=\"1Tim.5.25\"></r>; <g>οὕτως</g>, <r v=\"Acts.7.1\"></r>, al.; <g>τὸ νῦν ἔχον</g>, <b>as things now are</b> (<r v=\"Tob.7.11\"></r>), <r v=\"Acts.24.25\"></r>.</s> <s n=\"III.\">Mid., <g>-ομαι</g>, <b>to hold oneself fast</b>, <b>hold on</b> or <b>cling to</b>, <b>be next to</b>: c. gen., <g>τ. ἐχόμενα σωτηρίας</g>, <r v=\"Heb.6.9\"></r> (Rendall, in l.); ptcp., <g>ὁ ἐχόμενος</g>, <b>near</b>, <b>next</b>: of place, <r v=\"Mark.1.38\"></r>; of time, <g>τ. ἐχομένῃ</g> (<g>ἡμέρα</g>, expressed or understood), <r v=\"Luke.13.33\"></r>, <r v=\"Acts.20.15\"></r> <r v=\"Acts.21.26\"></r>; (<g>σαββάτῳ</g>), <r v=\"Acts.13.44\"></r>. (Cf. <g>ἀν-</g>, <g>προσ-αν-</g>, <g>ἀντ-</g>, <g>ἀπ-</g>, <g>ἐν-</g>, <g>ἐπ-</g>, <g>κατ-</g>, <g>μετ-</g>, <g>παρ-</g>, <g>περι-</g>, <g>προ-</g>, <g>προσ-</g>, <g>συν-</g>, <g>ὑπερ-</g>, <g>ὑπ-έχω</g>.) </s> </s>","ar":"<f><o>ἔχω</o>، </f> <s><b>يملك</b>، <b>له</b>، بمعانٍ وتراكيب متنوعة. <s n=\"I.\">متعدٍّ؛ <s n=\"1.\"><b>يملك</b>، <b>يمسك</b>، <b>يتمسك بـ</b>، إلخ؛ <s n=\"(a)\"><b>يمسك</b>، كما في اليد: <r v=\"Rev.5.8\"></r> <r v=\"Rev.14.6\"></r>، وفي مواضع أخرى؛ <g>ἐν τ. χειρί</g>، <r v=\"Rev.1.16\"></r> <r v=\"Rev.10.2\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">عن السلاح والثياب، = <x><g>φέρω</g></x>، <x><g>φορέω</g></x>، <b>يحمل</b>، <b>يلبس</b>: <r v=\"Matt.3.4\"></r> <r v=\"Matt.22.12\"></r>، وفي مواضع أخرى؛ وهكذا كثيرًا في اسم الفاعل المضارع، <r v=\"Mark.11.13\"></r>، <r v=\"John.18.10\"></r>، <r v=\"Rev.9.17\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">عن المرأة، <g>ἐν γαστρὶ ἔ</g> (<g>κοίτην ἔ.</g>)، <b>تكون حبلى</b>: <r v=\"Mark.13.17\"></r>، <r v=\"Rom.9.10\"></r>؛</s> <s n=\"(d)\"><b>يتمسك بـ</b>، <b>يحفظ</b>: <r v=\"Luke.19.20\"></r>؛ مجازيًا، عن الذهن والسلوك، <r v=\"Mark.16.8\"></r> (قارن <r v=\"Job.21.6\"></r>، <r v=\"Isa.13.8\"></r>)، <r v=\"John.14.21\"></r>، <r v=\"Rom.1.28\"></r>، <r v=\"1Tim.3.9\"></r>، <r v=\"2Tim.1.13\"></r>، <r v=\"Rev.6.9\"></r>، وفي مواضع أخرى؛</s> <s n=\"(e)\"><b>ينطوي على</b>: <r v=\"Heb.10.35\"></r><i>(السبعينية)</i>، <r v=\"Jas.1.4\"></r>، <r v=\"John.4.18\"></r>؛</s> <s n=\"(f)\">= اللاتينية <l>habere</l>، <b>يحسب</b>، <b>يعتبر</b>: مع المنصوب واسم فاعل خبري، <r v=\"Luke.14.18\"></r>؛ مع المنصوب، يليه <g>ὡς</g>، <r v=\"Matt.14.5\"></r>؛ <g>εἰς</g> (تعبير عبري)، <r v=\"Matt.21.46\"></r>؛ <r v=\"Mark.11.32\"></r>.</s> </s> <s n=\"2.\"><b>يملك</b>، <b>يقتني</b>؛ <s n=\"(a)\">بوجه عام، مع منصوب الشيء: <r v=\"Matt.19.22\"></r>، <r v=\"Mark.10.22\"></r>، <r v=\"Luke.12.19\"></r>، <r v=\"John.10.16\"></r>، <r v=\"1Cor.11.22\"></r>، وفي مواضع أخرى؛ عن الغنى أو الفقر، مطلقًا (بلا مفعول)، <g>ἔχειν</g> (والنفي <g>οὐκ</g>، <g>μή</g>)، <r v=\"Matt.13.12\"></r> <r v=\"Matt.25.29\"></r>، <r v=\"2Cor.8.12\"></r>؛ <g>ἐκ τ. ἔχειν</g>، <b>بحسب ما لكم</b>، <r v=\"2Cor.8.11\"></r>؛</s> <s n=\"(b)\">عن القرابة والصحبة ونحوهما: <g>πατέρα</g>، <r v=\"John.8.41\"></r>؛ <g>γυναῖκα</g>، <r v=\"1Cor.7.2\"></r>؛ <g>φίλον</g>، <r v=\"Luke.11.5\"></r>؛ <g>βασιλέα</g>، <r v=\"John.19.15\"></r>؛ <g>ποιμένα</g>، <r v=\"Matt.9.36\"></r>؛ مع منصوبين، <r v=\"Matt.3.9\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">عن الأجزاء والأعضاء: <g>ὦτα</g>، <r v=\"Matt.19.15\"></r>؛ <g>μέλη</g>، <r v=\"Rom.12.4\"></r>؛ <g>θεμελίους</g>، </s> <s n=\"(d)\">مع المنصوب، تعبيرًا بديلاً عن الفعل: <g>μνεῖαν ἔ.</g> (= <x><g>μεμνῆσθαι</g></x>)، <r v=\"1Thess.3.6\"></r>؛ <g>ἀγάπην</g>، <r v=\"John.13.35\"></r>؛ <g>γνῶσιν</g>، <r v=\"1Cor.8.1\"></r>؛ <g>πεποίθησιν</g>، <r v=\"2Cor.3.4\"></r>؛ <g>θλίψιν</g>، <r v=\"John.16.33\"></r>، إلخ؛</s> <s n=\"(e)\">عن الواجب والضرورة ونحوهما: <g>ἀνάγκην</g>، <r v=\"1Cor.7.37\"></r>؛ <g>νόμον</g>، <r v=\"John.19.7\"></r>؛ <g>ἐπιταγήν</g>، <r v=\"1Cor.7.25\"></r>؛ <g>ἀγῶνα</g>، <r v=\"Phil.1.30\"></r>؛ <g>κρίμα</g>، <r v=\"1Tim.5.12\"></r>؛</s> <s n=\"(f)\">عن الشكاوى والخصومات: <g>κατά</g>، مع المضاف إليه للشخص، <r v=\"Matt.5.23\"></r>، <r v=\"Mark.11.25\"></r>؛ والتعبير نفسه يليه <g>ὅτι</g>، <r v=\"Rev.2.4\"></r>، <r v=\"Rev.2.20\"></r>؛ مع المنصوب يليه <g>πρός</g>، <r v=\"Acts.24.19\"></r>، وفي مواضع أخرى؛</s> <s n=\"(g)\">مع المصدر، <s n=\"(α)\"><b>يستطيع</b>: <r v=\"Matt.18.25\"></r>، <r v=\"Mark.14.8\"></r> (والمقدَّر <x><g>ποιῆσαι</g></x>)، <r v=\"Luke.12.4\"></r>، <r v=\"Acts.4.14\"></r>، وفي مواضع أخرى؛</s> <s n=\"(β)\">عن الضرورة: <r v=\"Luke.12.50\"></r>، <r v=\"Acts.23.17-Acts.23.19\"></r> <r v=\"Acts.28.19\"></r>.</s> </s> </s> </s> <s n=\"II.\">لازم، <b>يكون</b> في حالة معينة: <g>ἑτοίμως ἔ.</g>، مع المصدر، <r v=\"Acts.21.13\"></r>، <r v=\"2Cor.12.14\"></r>؛ <g>ἐσχάτως</g> (انظره)، <r v=\"Mark.5.23\"></r>؛ <g>κακῶς</g>، <b>يكون مريضًا</b>، <r v=\"Matt.4.24\"></r>، وفي مواضع أخرى؛ <g>καλῶς</g>، <r v=\"Mark.16.18\"></r>؛ <g>κομψότερον</g>، <r v=\"John.4.52\"></r>؛ <g>πῶς</g>، <r v=\"Acts.15.36\"></r>؛ غير شخصي، <g>ἄλλως ἔχει</g>، <b>الأمر على خلاف ذلك</b>، <r v=\"1Tim.5.25\"></r>؛ <g>οὕτως</g>، <r v=\"Acts.7.1\"></r>، وفي مواضع أخرى؛ <g>τὸ νῦν ἔχον</g>، <b>على ما الأمور عليه الآن</b> (<r v=\"Tob.7.11\"></r>)، <r v=\"Acts.24.25\"></r>.</s> <s n=\"III.\">الصيغة الوسطى، <g>-ομαι</g>، <b>يتمسك</b>، <b>يتعلق بـ</b> أو <b>يلتصق بـ</b>، <b>يكون ملاصقًا لـ</b>: مع المضاف إليه، <g>τ. ἐχόμενα σωτηρίας</g>، <r v=\"Heb.6.9\"></r>؛ اسم الفاعل، <g>ὁ ἐχόμενος</g>، <b>القريب</b>، <b>التالي</b>: عن المكان، <r v=\"Mark.1.38\"></r>؛ عن الزمان، <g>τ. ἐχομένῃ</g> (<g>ἡμέρα</g>، مذكورة أو مقدَّرة)، <r v=\"Luke.13.33\"></r>، <r v=\"Acts.20.15\"></r> <r v=\"Acts.21.26\"></r>؛ (<g>σαββάτῳ</g>)، <r v=\"Acts.13.44\"></r>. (قارن <g>ἀν-</g>، <g>προσ-αν-</g>، <g>ἀντ-</g>، <g>ἀπ-</g>، <g>ἐν-</g>، <g>ἐπ-</g>، <g>κατ-</g>، <g>μετ-</g>، <g>παρ-</g>، <g>περι-</g>، <g>προ-</g>، <g>προσ-</g>، <g>συν-</g>، <g>ὑπερ-</g>، <g>ὑπ-έχω</g>.) </s> </s>"},"G2257":{"l":"ἐγώ","o":2572,"en":"<f><o>ἐγώ</o>, gen, etc., <g>ἐμοῦ, ἐμοί, ἐμέ</g> (enclitic <g>μου, μοι, με</g>), pl. <g>ἡμεῖς, -ῶν, -ῖν, -ᾶς</g>, </f> pers. pron. <s><b>I</b>. <s n=\"(a)\">The nom. is usually emphatic, when expressed as subjc, as in <r v=\"Matt.3.11\"></r>, <r v=\"Mark.1.8\"></r>, <r v=\"Luke.3.16\"></r>, al. But often there is no apparent emphasis, as <r v=\"Matt.10.16\"></r>, <r v=\"John.10.17\"></r>; <g>ἰδοὺ ἐ.</g> (= Heb. <h n=\"H2005\">הִנֵּנִי</h>, cf. <r v=\"1Kgs.3.8\"></r>), <r v=\"Acts.9.10\"></r>; <g>ἐ.</g> (like Heb. <h n=\"H589\">אֲנִי</h>), <b>I am</b>, <r v=\"John.1.23\"></r>, <r v=\"Acts.7.32\"></r>. </s> <s n=\"(b)\">The enclitic forms (v. supr.) are used with nouns, adjectives, verbs, adverbs, where there is no emphasis: <g>ἐν τ. πατρί μου</g>, <r v=\"John.14.20\"></r>; <g>μου τ. λόγους</g>, <r v=\"Matt.7.24\"></r>; <g>ὀπίσω μου</g>, <r v=\"Matt.3.11\"></r>; <g>ἰσχυρότερός μου</g>, <r v=\"Matt.3.11\"></r>; <g>λέγει μοι</g>, <r v=\"Rev.5.5\"></r>; also with the prep. <g>πρός</g>, as <r v=\"Mark.9.19\"></r>, al. The full forms (<g>ἐμοῦ</g>, etc.) are used with the other prepositions, as <g>δι' ἐμοῦ, ἐν ἐμοί, εἰς ἐμέ</g>, etc., also for emphasis, as <r v=\"Luke.10.16\"></r>, <r v=\"John.7.23\"></r>, <r v=\"Mark.14.7\"></r>, al. </s> <s n=\"(c)\">The gen. <g>μου</g> and <g>ἡμῶν</g> are often used for the poss. pronouns <g>ἐμός, ἡμέτερος: τ. λαόν μου</g>, <r v=\"Matt.2.6\"></r>; <g>μου τῂ ἀπιστιᾳ</g>, <r v=\"Mark.9.24\"></r>. </s> <s n=\"(d)\"><g>τί ἐμοὶ καὶ σοί</g> ( = Heb. <h n=\"H4100\">וָלָךְ מַה־לִי</h>, <r v=\"Judg.11.12\"></r>, al.), i.e. <b>what have we in common</b>: <r v=\"Matt.8.29\"></r>, <r v=\"Mark.1.24\"></r> <r v=\"Mark.5.7\"></r>, <r v=\"Luke.8.28\"></r>, <r v=\"John.2.4\"></r>; <g>τί γάρ μοι</g>, <r v=\"1Cor.5.2\"></r>. </s> <s n=\"(e)\">The interchange of <g>ἐγώ</g> and <g>ἡμεῖς</g>, common in <g>π.</g>, appears in Pauline Epp. (v. M, <i>Pr.</i>, 86f., M, <i>Th.</i>, 131f.).</s> <s n=\"(f)\"><g>κἀγώ</g> (= <g>καὶ ἐγώ</g>, <b>and I, even I, I also</b>: <r v=\"Matt.2.8\"></r>, <r v=\"Luke.2.48\"></r>, <r v=\"John.6.56\"></r>, <r v=\"Rom.3.7\"></r>, <r v=\"1Cor.7.40\"></r>, al.; <g>κἀγώ . . . καί</g>, <b>both . . . and</b>, <r v=\"John.7.28\"></r>.</s> </s>","ar":"<f><o>ἐγώ</o>، المضاف إليه إلخ: <g>ἐμοῦ, ἐμοί, ἐμέ</g> (الصيغ الملحقة: <g>μου, μοι, με</g>)، الجمع: <g>ἡμεῖς, -ῶν, -ῖν, -ᾶς</g>، </f> ضمير شخصي، <s><b>أنا</b>. <s n=\"(a)\">حالة الرفع تفيد التوكيد عادةً حين يُصرَّح بها فاعلاً، كما في <r v=\"Matt.3.11\"></r>، <r v=\"Mark.1.8\"></r>، <r v=\"Luke.3.16\"></r>، وفي مواضع أخرى. لكن كثيرًا ما لا يظهر فيها توكيد، كما في <r v=\"Matt.10.16\"></r>، <r v=\"John.10.17\"></r>؛ <g>ἰδοὺ ἐ.</g> (= العبرية <h n=\"H2005\">הִנֵּנִי</h>، قارن <r v=\"1Kgs.3.8\"></r>): <r v=\"Acts.9.10\"></r>؛ <g>ἐ.</g> (مثل العبرية <h n=\"H589\">אֲנִי</h>): <b>أنا هو</b>: <r v=\"John.1.23\"></r>، <r v=\"Acts.7.32\"></r>. </s> <s n=\"(b)\">الصيغ الملحقة (انظر أعلاه) تُستعمل مع الأسماء والصفات والأفعال والظروف حيث لا توكيد: <g>ἐν τ. πατρί μου</g>: <r v=\"John.14.20\"></r>؛ <g>μου τ. λόγους</g>: <r v=\"Matt.7.24\"></r>؛ <g>ὀπίσω μου</g>: <r v=\"Matt.3.11\"></r>؛ <g>ἰσχυρότερός μου</g>: <r v=\"Matt.3.11\"></r>؛ <g>λέγει μοι</g>: <r v=\"Rev.5.5\"></r>؛ وأيضًا مع حرف الجر <g>πρός</g>، كما في <r v=\"Mark.9.19\"></r>، وفي مواضع أخرى. أما الصيغ الكاملة (<g>ἐμοῦ</g> إلخ) فتُستعمل مع حروف الجر الأخرى، مثل <g>δι' ἐμοῦ, ἐν ἐμοί, εἰς ἐμέ</g> إلخ، وكذلك للتوكيد، كما في <r v=\"Luke.10.16\"></r>، <r v=\"John.7.23\"></r>، <r v=\"Mark.14.7\"></r>، وفي مواضع أخرى. </s> <s n=\"(c)\">كثيرًا ما يُستعمل المضاف إليه <g>μου</g> و<g>ἡμῶν</g> بدلاً من ضميري الملكية <g>ἐμός, ἡμέτερος: τ. λαόν μου</g>: <r v=\"Matt.2.6\"></r>؛ <g>μου τῂ ἀπιστιᾳ</g>: <r v=\"Mark.9.24\"></r>. </s> <s n=\"(d)\"><g>τί ἐμοὶ καὶ σοί</g> (= العبرية <h n=\"H4100\">וָלָךְ מַה־לִי</h>، <r v=\"Judg.11.12\"></r>، وفي مواضع أخرى)، أي <b>ما لنا وما لك؟، أيّ شأن مشترك بيننا؟</b>: <r v=\"Matt.8.29\"></r>، <r v=\"Mark.1.24\"></r>، <r v=\"Mark.5.7\"></r>، <r v=\"Luke.8.28\"></r>، <r v=\"John.2.4\"></r>؛ <g>τί γάρ μοι</g>: <r v=\"1Cor.5.2\"></r>. </s> <s n=\"(e)\">التبادل بين <g>ἐγώ</g> و<g>ἡμεῖς</g>، الشائع في <g>π.</g>، يظهر في رسائل بولس.</s> <s n=\"(f)\"><g>κἀγώ</g> (= <g>καὶ ἐγώ</g>): <b>وأنا، حتى أنا، أنا أيضًا</b>: <r v=\"Matt.2.8\"></r>، <r v=\"Luke.2.48\"></r>، <r v=\"John.6.56\"></r>، <r v=\"Rom.3.7\"></r>، <r v=\"1Cor.7.40\"></r>، وفي مواضع أخرى؛ <g>κἀγώ . . . καί</g>: <b>كلٌّ من ... و</b>: <r v=\"John.7.28\"></r>.</s> </s>"},"G2309":{"l":"θέλω","o":208,"en":"<f><o>θέλω</o> (the strengthened form <g>ἐθέλω</g> is found in Hom., and is the more freq. in Attic; v. Rutherford, <i>NPhr.</i>, 415 f.),</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2654,H14\">חפץ ,אבה</h>; c. neg., <h n=\"H3985\">מאן</h> pi., etc.;]</e> </et> <s><b>to will</b>, <b>be willing</b>, <b>wish</b>, <b>desire</b> (more freq. than <g>βούλομαι</g>, q.v., in vernac. and late Gk., also in MGr.; for various views as to its relation to <g>β.</g>, v. Thayer, 286; but v. also Bl., §24, s.v.): absol., <r v=\"Rom.9.16\"></r>, <r v=\"1Cor.4.19\"></r> <r v=\"1Cor.12.18\"></r>, <r v=\"Jas.4.15\"></r>; <g>τ. θεοῦ θέλοντος</g>, <r v=\"Acts.18.21\"></r>; c. acc. rei, <r v=\"Matt.20.21\"></r>, <r v=\"Mark.14.36\"></r>, <r v=\"John.15.7\"></r>, <r v=\"Rom.7.15\"></r>, <r v=\"Rom.7.16\"></r>, <r v=\"1Cor.4.21\"></r> <r v=\"1Cor.7.36\"></r>, <r v=\"Gal.5.17\"></r>; c. inf., <r v=\"Matt.5.40\"></r>, <r v=\"Mark.10.43\"></r>, <r v=\"John.6.21\"></r>, <r v=\"John.6.67\"></r>, <r v=\"Rom.7.21\"></r>, <r v=\"Gal.4.9\"></r>; c. acc. et inf., <r v=\"Mark.7.24\"></r>, <r v=\"Luke.1.62\"></r>, <r v=\"John.21.22\"></r>, <r v=\"John.21.23\"></r>, <r v=\"Rom.16.19\"></r>, <r v=\"1Cor.14.5\"></r>, <r v=\"Gal.6.13\"></r>; <g>οὐ θέλω</g>, <r v=\"Matt.18.30\"></r>, al.; id. c. inf., <r v=\"Matt.2.18\"></r>, <r v=\"Mark.6.26\"></r>, <r v=\"John.5.40\"></r>, <r v=\"1Cor.16.7\"></r>; seq. <g>ἵνα</g>, <r v=\"Matt.7.12\"></r>, <r v=\"Mark.6.25\"></r>, <r v=\"John.17.24\"></r>; opp. to <g>ποιέω, πράσσω, ἐνεργέω</g>, <r v=\"Rom.7.15\"></r>, <r v=\"Rom.7.19\"></r>, <r v=\"2Cor.8.10\"></r>, <r v=\"2Cor.8.11\"></r>, <r v=\"Phil.2.13\"></r>; seq. <g>ἤ</g> (<i>ICG</i>, in l.; Deiss., <i>LAE</i>, 179<i>24</i>), <r v=\"1Cor.14.19\"></r>; <g>θέλων ἐν ταπεινοφροσυνῄ</g> (<i>of his own mere will, by humility</i>, R, mg), <r v=\"Col.2.18\"></r>; in OT quotations, for Heb. <h n=\"H2654\">חפץ</h>, c. acc. pers., <r v=\"Matt.27.43\"></r>; c. acc. rei, <r v=\"Matt.9.13\"></r> <r v=\"Matt.12.7\"></r>, <r v=\"Heb.10.5\"></r>, <r v=\"Heb.10.8\"></r>; c. inf., <r v=\"1Pet.3.10\"></r>; for <h n=\"H559\">אמר</h>, c. inf., <r v=\"Acts.7.28\"></r> (v. Cremer, 726 ff.).</s>","ar":"<f><o>θέλω</o> (الصيغة المقوّاة <g>ἐθέλω</g>)،</f> <s><b>يريد</b>، <b>يرضى، يشاء</b>، <b>يرغب</b>، <b>يشتهي</b> (أكثر استعمالاً من <g>βούλομαι</g>، انظره، في اللغة الدارجة واليونانية المتأخرة): مطلقًا، <r v=\"Rom.9.16\"></r>، <r v=\"1Cor.4.19\"></r> <r v=\"1Cor.12.18\"></r>، <r v=\"Jas.4.15\"></r>؛ <g>τ. θεοῦ θέλοντος</g> (إن شاء الله)، <r v=\"Acts.18.21\"></r>؛ مع المنصوب للأشياء، <r v=\"Matt.20.21\"></r>، <r v=\"Mark.14.36\"></r>، <r v=\"John.15.7\"></r>، <r v=\"Rom.7.15\"></r>، <r v=\"Rom.7.16\"></r>، <r v=\"1Cor.4.21\"></r> <r v=\"1Cor.7.36\"></r>، <r v=\"Gal.5.17\"></r>؛ مع المصدر، <r v=\"Matt.5.40\"></r>، <r v=\"Mark.10.43\"></r>، <r v=\"John.6.21\"></r>، <r v=\"John.6.67\"></r>، <r v=\"Rom.7.21\"></r>، <r v=\"Gal.4.9\"></r>؛ مع المنصوب والمصدر، <r v=\"Mark.7.24\"></r>، <r v=\"Luke.1.62\"></r>، <r v=\"John.21.22\"></r>، <r v=\"John.21.23\"></r>، <r v=\"Rom.16.19\"></r>، <r v=\"1Cor.14.5\"></r>، <r v=\"Gal.6.13\"></r>؛ <g>οὐ θέλω</g> (لست أريد)، <r v=\"Matt.18.30\"></r>، وفي مواضع أخرى؛ والتعبير نفسه مع المصدر، <r v=\"Matt.2.18\"></r>، <r v=\"Mark.6.26\"></r>، <r v=\"John.5.40\"></r>، <r v=\"1Cor.16.7\"></r>؛ يليه <g>ἵνα</g>، <r v=\"Matt.7.12\"></r>، <r v=\"Mark.6.25\"></r>، <r v=\"John.17.24\"></r>؛ عكس <g>ποιέω, πράσσω, ἐνεργέω</g> (يفعل، يعمل)، <r v=\"Rom.7.15\"></r>، <r v=\"Rom.7.19\"></r>، <r v=\"2Cor.8.10\"></r>، <r v=\"2Cor.8.11\"></r>، <r v=\"Phil.2.13\"></r>؛ يليه <g>ἤ</g> (أريد ... أكثر من)، <r v=\"1Cor.14.19\"></r>؛ <g>θέλων ἐν ταπεινοφροσυνῄ</g> (<i>بمحض إرادته، بالتواضع</i>)، <r v=\"Col.2.18\"></r>؛ في اقتباسات العهد القديم، ترجمةً للعبرية <h n=\"H2654\">חפץ</h> (يُسَرّ بـ): مع المنصوب للأشخاص، <r v=\"Matt.27.43\"></r>؛ مع المنصوب للأشياء، <r v=\"Matt.9.13\"></r> <r v=\"Matt.12.7\"></r>، <r v=\"Heb.10.5\"></r>، <r v=\"Heb.10.8\"></r>؛ مع المصدر، <r v=\"1Pet.3.10\"></r>؛ وترجمةً لـ <h n=\"H559\">אמר</h>، مع المصدر، <r v=\"Acts.7.28\"></r>.</s>"},"G2316":{"l":"θεός","o":1307,"en":"<f><o>θεός</o>, <g>-οῦ, ὁ, ἡ</g> (<r v=\"Acts.19.37\"></r> only; v. M, <i>Pr.</i>, 60, 244), late voc., <g>θεέ</g> (<r v=\"Matt.27.46\"></r>; cf. <r v=\"Deut.3.24\"></r>, al.),</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H430\">אֱלֹהִים</h>, also for <h n=\"H410\">אֵל</h> and other cognate forms, <h n=\"H3069\">יהוה</h>, etc.;]</e> </et> <s><b>a god or deity</b>, <b>God</b>. <s n=\"1.\">In polytheistic sense, <b>a god</b> or <b>deity</b>: <r v=\"Acts.28.6\"></r>, <r v=\"1Cor.8.4\"></r>, <r v=\"2Thess.2.4\"></r>, al.; pl., <r v=\"Acts.14.11\"></r> <r v=\"Acts.19.26\"></r>, <r v=\"Gal.4.8\"></r>, al.</s> <s n=\"2.\">Of the one true <b>God</b>; <s n=\"(a)\">anarthrous: Mt 6:24, Lk 20:38, al.; esp. c. prep. (Kühner<i>3</i>, iii, 605), <g>ἀπὸ θ.</g>, <r v=\"John.3.2\"></r>; <g>ἐκ</g>, <r v=\"Acts.5.39\"></r>, <r v=\"2Cor.5.1\"></r>, <r v=\"Phil.3.9\"></r>; <g>ὑπό</g>, <r v=\"Rom.13.1\"></r>; <g>παρὰ θεοῦ</g>, <r v=\"John.1.6\"></r>; <g>παρὰ θεῷ</g>, <r v=\"2Thess.1.6\"></r>, <r v=\"1Pet.2.4\"></r>; <g>κατὰ θεόν</g>, <r v=\"Rom.8.27\"></r>, <r v=\"2Cor.7.9\"></r>, <r v=\"2Cor.7.10\"></r>; also when in gen. dependent on an anarth. noun (Bl., §46, 6), <r v=\"Matt.27.43\"></r>, <r v=\"Luke.3.2\"></r>, <r v=\"Rom.1.17\"></r>, <r v=\"1Thess.2.13\"></r>; as pred., <r v=\"Luke.20.38\"></r>, <r v=\"John.1.1\"></r>, and when the nature and character rather than the person of God is meant, <r v=\"Acts.5.29\"></r>, <r v=\"Gal.2.6\"></r>, al. (M, <i>Th.</i>, 14);</s> <s n=\"(b)\">more freq., c. art.: <r v=\"Matt.1.23\"></r>, <r v=\"Mark.2.7\"></r>, al. mult.; c. prep., <g>ἀπὸ τ. θ.</g>, <r v=\"Luke.1.26\"></r>; <g>ἐκ</g>, <r v=\"John.8.42\"></r>, al.; <g>παρὰ τοῦ θ.</g>, <r v=\"John.8.40\"></r>; <g>π. τῷ θ.</g>, <r v=\"Rom.9.14\"></r>; <g>ἐν</g>, <r v=\"Col.3.3\"></r>; <g>ἐπὶ τῷ θ.</g>, <r v=\"Luke.1.47\"></r>; <g>ἐπὶ τὸν θ.</g>, <r v=\"Acts.15.19\"></r>; <g>εἰς τ. θ.</g>, <r v=\"Acts.24.15\"></r>; <g>πρὸς τ. θ.</g>, <r v=\"John.1.2\"></r>; c. gen. pers., <r v=\"Matt.22.32\"></r>, <r v=\"Mark.12.26\"></r>, <r v=\"Mark.12.26\"></r>, <r v=\"Luke.20.37\"></r>, <r v=\"John.20.17\"></r>, al.; <g>ὁ θ. μου</g>, <r v=\"Rom.1.8\"></r>, <r v=\"Phil.1.3\"></r>, al.; <g>ὁ θ. καὶ πατήρ κ. τ. λ.</g>, <r v=\"Rom.15.6\"></r>, <r v=\"Eph.1.3\"></r>, <r v=\"Phil.4.20\"></r>, al.; c. gen. rei, <r v=\"Rom.15.5\"></r>, <r v=\"Rom.15.13\"></r>, <r v=\"Rom.15.33\"></r>, <r v=\"2Cor.1.3\"></r>, <r v=\"1Thess.5.23\"></r>; <g>τὰ τ. θεοῦ</g>, <r v=\"Matt.16.23\"></r>, <r v=\"Mark.12.17\"></r>, <r v=\"1Cor.2.11\"></r>; <g>τὰ πρὸς τὸν θ.</g>, <r v=\"Rom.15.17\"></r>, <r v=\"Heb.2.17\"></r> <r v=\"Heb.5.1\"></r>; <g>τ. θεῷ</g>, as a superl. (LXX, <r v=\"Josh.3.3\"></r>), <r v=\"Acts.7.20\"></r>, <r v=\"2Cor.10.4\"></r>; Hebraistically, of judges (<r v=\"LXX:Ps.82.6\"></r>), <r v=\"John.10.34\"></r><i>(LXX)</i>, <r v=\"John.10.35\"></r>.</s> </s> </s>","ar":"<f><o>θεός</o>، <g>-οῦ, ὁ, ἡ</g> (<r v=\"Acts.19.37\"></r> فقط)، النداء في اليونانية المتأخرة <g>θεέ</g> (<r v=\"Matt.27.46\"></r>؛ قارن <r v=\"Deut.3.24\"></r>، وفي مواضع أخرى)،</f> <s><b>إله أو معبود</b>، <b>الله</b>. <s n=\"1.\">بالمعنى الوثني (تعدد الآلهة): <b>إله</b> أو <b>معبود</b>: <r v=\"Acts.28.6\"></r>، <r v=\"1Cor.8.4\"></r>، <r v=\"2Thess.2.4\"></r>، وفي مواضع أخرى؛ جمع (آلهة)، <r v=\"Acts.14.11\"></r> <r v=\"Acts.19.26\"></r>، <r v=\"Gal.4.8\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\">عن الإله الحقيقي الواحد، <b>الله</b>؛ <s n=\"(a)\">بدون أداة التعريف: متى 6: 24، لوقا 20: 38، وفي مواضع أخرى؛ خاصةً مع حرف جر، <g>ἀπὸ θ.</g>، <r v=\"John.3.2\"></r>؛ <g>ἐκ</g>، <r v=\"Acts.5.39\"></r>، <r v=\"2Cor.5.1\"></r>، <r v=\"Phil.3.9\"></r>؛ <g>ὑπό</g>، <r v=\"Rom.13.1\"></r>؛ <g>παρὰ θεοῦ</g>، <r v=\"John.1.6\"></r>؛ <g>παρὰ θεῷ</g>، <r v=\"2Thess.1.6\"></r>، <r v=\"1Pet.2.4\"></r>؛ <g>κατὰ θεόν</g> (بحسب مشيئة الله)، <r v=\"Rom.8.27\"></r>، <r v=\"2Cor.7.9\"></r>، <r v=\"2Cor.7.10\"></r>؛ وكذلك حين يكون في حالة الجر تابعًا لاسم بدون أداة التعريف، <r v=\"Matt.27.43\"></r>، <r v=\"Luke.3.2\"></r>، <r v=\"Rom.1.17\"></r>، <r v=\"1Thess.2.13\"></r>؛ خبرًا، <r v=\"Luke.20.38\"></r>، <r v=\"John.1.1\"></r>، وحين يُقصد طبيعة الله وصفته لا شخصه، <r v=\"Acts.5.29\"></r>، <r v=\"Gal.2.6\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">وأكثر من ذلك مع أداة التعريف: <r v=\"Matt.1.23\"></r>، <r v=\"Mark.2.7\"></r>، وفي مواضع أخرى كثيرة؛ مع حرف جر، <g>ἀπὸ τ. θ.</g>، <r v=\"Luke.1.26\"></r>؛ <g>ἐκ</g>، <r v=\"John.8.42\"></r>، وفي مواضع أخرى؛ <g>παρὰ τοῦ θ.</g>، <r v=\"John.8.40\"></r>؛ <g>π. τῷ θ.</g>، <r v=\"Rom.9.14\"></r>؛ <g>ἐν</g>، <r v=\"Col.3.3\"></r>؛ <g>ἐπὶ τῷ θ.</g>، <r v=\"Luke.1.47\"></r>؛ <g>ἐπὶ τὸν θ.</g>، <r v=\"Acts.15.19\"></r>؛ <g>εἰς τ. θ.</g>، <r v=\"Acts.24.15\"></r>؛ <g>πρὸς τ. θ.</g>، <r v=\"John.1.2\"></r>؛ مع المضاف إليه للأشخاص (إله فلان)، <r v=\"Matt.22.32\"></r>، <r v=\"Mark.12.26\"></r>، <r v=\"Mark.12.26\"></r>، <r v=\"Luke.20.37\"></r>، <r v=\"John.20.17\"></r>، وفي مواضع أخرى؛ <g>ὁ θ. μου</g> (إلهي)، <r v=\"Rom.1.8\"></r>، <r v=\"Phil.1.3\"></r>، وفي مواضع أخرى؛ <g>ὁ θ. καὶ πατήρ κ. τ. λ.</g> (الله والآب...)، <r v=\"Rom.15.6\"></r>، <r v=\"Eph.1.3\"></r>، <r v=\"Phil.4.20\"></r>، وفي مواضع أخرى؛ مع المضاف إليه للأشياء (إله الصبر، إله الرجاء...)، <r v=\"Rom.15.5\"></r>، <r v=\"Rom.15.13\"></r>، <r v=\"Rom.15.33\"></r>، <r v=\"2Cor.1.3\"></r>، <r v=\"1Thess.5.23\"></r>؛ <g>τὰ τ. θεοῦ</g> (ما لله)، <r v=\"Matt.16.23\"></r>، <r v=\"Mark.12.17\"></r>، <r v=\"1Cor.2.11\"></r>؛ <g>τὰ πρὸς τὸν θ.</g> (ما لله، ما يخص الله)، <r v=\"Rom.15.17\"></r>، <r v=\"Heb.2.17\"></r> <r v=\"Heb.5.1\"></r>؛ <g>τ. θεῷ</g> بمعنى صيغة التفضيل العليا (جدًّا) (السبعينية، <r v=\"Josh.3.3\"></r>)، <r v=\"Acts.7.20\"></r>، <r v=\"2Cor.10.4\"></r>؛ وعلى الطريقة العبرية عن القضاة (<r v=\"LXX:Ps.82.6\"></r>)، <r v=\"John.10.34\"></r><i>(السبعينية)</i>، <r v=\"John.10.35\"></r>.</s> </s> </s>"},"G235":{"l":"ἀλλά","o":638,"en":"<f><o>ἀλλά</o> (<g>ἀλλ’</g> usually bef. <g>α</g> and <g>υ</g>, often bef. <g>ε</g> and <g>η</g>, rarely bef. <g>ο</g> and <g>ω</g>, never bef. <g>ι</g>; Tdf., <i>Pr.</i>, 93 f.; WH, <i>App.</i>, 146), </f> adversative particle, <s>stronger than <g>δέ</g>; prop. neuter pl. of <g>ἄλλος</g>, used adverbially, with changed accent; hence prop. <b>otherwise</b>, <b>on the other hand</b> (cf. <r v=\"Rom.3.31\"></r>); <s n=\"1.\">opposing a previous negation, <b>but</b>: <g>οὐ (μὴ) . . . ἀ.</g>, <r v=\"Matt.5.15\"></r>, <r v=\"Matt.5.17\"></r> <r v=\"Mark.5.39\"></r>, <r v=\"John.7.16\"></r>, al.; rhetorically subordinating but not entirely negativing what precedes, <g>οὐ . . . ἀ.</g>, <b>not so much . . . as</b>, <r v=\"Mark.9.37\"></r>, <r v=\"Matt.10.20\"></r>, <r v=\"John.12.44\"></r>, al.; with ellipse of the negation, <r v=\"Matt.11.7-Matt.11.9\"></r>, <r v=\"Acts.19.2\"></r>, <r v=\"1Cor.3.6\"></r> <r v=\"1Cor.6.11\"></r> 7:7, <r v=\"2Cor.7.1\"></r>, <r v=\"Gal.2.3\"></r>, al.; in opposition to a foregoing pos. sentence, <g>ἀ. οὐ</g>, <r v=\"Matt.24.6\"></r>, <r v=\"1Cor.10.23\"></r>; <g>οὐ μόνον . . . ἀ. καί</g>, <r v=\"John.5.18\"></r>, <r v=\"Rom.1.32\"></r>, al.; elliptically, after a negation, <g>ἀ. ἵνα</g>, <r v=\"Mark.14.49\"></r>, <r v=\"John.1.8\"></r> <r v=\"John.9.3\"></r>, al.; = <g>εἰ μή</g> (Bl., §77, 13; M, <i>Pr.</i>, 241; but cf. WM, §iii, 10), <r v=\"Matt.20.23\"></r>, <r v=\"Mark.4.22\"></r>. </s> <s n=\"2.\">Without previous negation, to express opposition, interruption, transition, etc., <b>but</b>: <r v=\"John.16.20\"></r> <r v=\"John.12.27\"></r>, <r v=\"Gal.2.14\"></r>; before commands or requests, <r v=\"Acts.10.20\"></r> <r v=\"Acts.26.16\"></r>, <r v=\"Matt.9.18\"></r>, <r v=\"Mark.9.22\"></r>, al.; to introduce an accessory idea, <r v=\"2Cor.7.11\"></r>; in the apodosis after a condition or concession with <g>εἰ, ἐάν, εἴπερ</g>, <b>yet</b>, <b>still</b>, <b>at least</b>, <r v=\"Mark.14.29\"></r>, <r v=\"1Cor.9.2\"></r>, <r v=\"2Cor.4.16\"></r>, <r v=\"Col.2.5\"></r>, al.; after <g>μέν</g>, <r v=\"Acts.4.17\"></r>, <r v=\"Rom.14.20\"></r>, <r v=\"1Cor.14.17\"></r>; giving emphasis to the following clause, <g>ἀλλ’ ἔρχεται ὥρα</g>, <b>yea</b>, etc., <r v=\"John.16.2\"></r>; so with neg., <g>ἀλλ’ οὐδέ</g>, <b>nay</b>, <b>nor yet</b>, <r v=\"Luke.23.15\"></r>. </s> <s n=\"3.\">Joined with other particles (a practice which increases in late writers; Simcox, <i>LNT</i>, 166), <g>ἀ. γε</g>, <b>yet at least</b>, <r v=\"Luke.24.21\"></r>, <r v=\"1Cor.9.2\"></r>; <g>ἄ ἤ.</g>, <b>save only</b>, <b>except</b>, <r v=\"Luke.12.51\"></r>, <r v=\"2Cor.1.13\"></r>; <g>ἀ. μὲν οὖν</g>, <r v=\"Phil.3.8\"></r> (on this usage, v. MM, <i>VGT</i>, s.v.). </s> </s>","ar":"<f><o>ἀλλά</o> (<g>ἀλλ’</g> عادةً قبل <g>α</g> و<g>υ</g>، وكثيرًا قبل <g>ε</g> و<g>η</g>، ونادرًا قبل <g>ο</g> و<g>ω</g>، ولا تأتي قبل <g>ι</g>)، </f> أداة استدراك، <s>أقوى من <g>δέ</g>؛ وهي أصلاً جمع محايد لـ <g>ἄλλος</g>، مستعمل ظرفًا مع تغيير النبرة؛ ومن ثم معناها الأصلي <b>بخلاف ذلك</b>، <b>من جهة أخرى</b> (قارن <r v=\"Rom.3.31\"></r>)؛ <s n=\"1.\">في مقابلة نفيٍ سابق، <b>بل</b>، <b>لكن</b>: <g>οὐ (μὴ) . . . ἀ.</g>، <r v=\"Matt.5.15\"></r>، <r v=\"Matt.5.17\"></r> <r v=\"Mark.5.39\"></r>، <r v=\"John.7.16\"></r>، وفي مواضع أخرى؛ بلاغيًا، لتقليل ما سبق دون نفيه كليًّا، <g>οὐ . . . ἀ.</g>، <b>لا ... بقدر ما</b>، <r v=\"Mark.9.37\"></r>، <r v=\"Matt.10.20\"></r>، <r v=\"John.12.44\"></r>، وفي مواضع أخرى؛ مع حذف النفي، <r v=\"Matt.11.7-Matt.11.9\"></r>، <r v=\"Acts.19.2\"></r>، <r v=\"1Cor.3.6\"></r> <r v=\"1Cor.6.11\"></r> 7:7، <r v=\"2Cor.7.1\"></r>، <r v=\"Gal.2.3\"></r>، وفي مواضع أخرى؛ في مقابلة جملة مثبتة سابقة، <g>ἀ. οὐ</g>، <r v=\"Matt.24.6\"></r>، <r v=\"1Cor.10.23\"></r>؛ <g>οὐ μόνον . . . ἀ. καί</g>، <r v=\"John.5.18\"></r>، <r v=\"Rom.1.32\"></r>، وفي مواضع أخرى؛ بالحذف، بعد نفي، <g>ἀ. ἵνα</g>، <r v=\"Mark.14.49\"></r>، <r v=\"John.1.8\"></r> <r v=\"John.9.3\"></r>، وفي مواضع أخرى؛ = <g>εἰ μή</g>، <r v=\"Matt.20.23\"></r>، <r v=\"Mark.4.22\"></r>. </s> <s n=\"2.\">دون نفيٍ سابق، للتعبير عن المقابلة أو القطع أو الانتقال ونحوها، <b>لكن</b>: <r v=\"John.16.20\"></r> <r v=\"John.12.27\"></r>، <r v=\"Gal.2.14\"></r>؛ قبل الأوامر أو الطلبات، <r v=\"Acts.10.20\"></r> <r v=\"Acts.26.16\"></r>، <r v=\"Matt.9.18\"></r>، <r v=\"Mark.9.22\"></r>، وفي مواضع أخرى؛ لإدخال فكرة إضافية، <r v=\"2Cor.7.11\"></r>؛ في جواب الشرط أو التسليم مع <g>εἰ, ἐάν, εἴπερ</g>، <b>فمع ذلك</b>، <b>بعدُ</b>، <b>على الأقل</b>، <r v=\"Mark.14.29\"></r>، <r v=\"1Cor.9.2\"></r>، <r v=\"2Cor.4.16\"></r>، <r v=\"Col.2.5\"></r>، وفي مواضع أخرى؛ بعد <g>μέν</g>، <r v=\"Acts.4.17\"></r>، <r v=\"Rom.14.20\"></r>، <r v=\"1Cor.14.17\"></r>؛ لتوكيد الجملة التالية، <g>ἀλλ’ ἔρχεται ὥρα</g>، <b>نعم</b>، إلخ، <r v=\"John.16.2\"></r>؛ وكذلك مع النفي، <g>ἀλλ’ οὐδέ</g>، <b>بل</b>، <b>ولا</b>، <r v=\"Luke.23.15\"></r>. </s> <s n=\"3.\">مقترنةً بأدوات أخرى، <g>ἀ. γε</g>، <b>فعلى الأقل</b>، <r v=\"Luke.24.21\"></r>، <r v=\"1Cor.9.2\"></r>؛ <g>ἄ ἤ.</g>، <b>إلا</b>، <b>سوى</b>، <r v=\"Luke.12.51\"></r>، <r v=\"2Cor.1.13\"></r>؛ <g>ἀ. μὲν οὖν</g>، <r v=\"Phil.3.8\"></r>. </s> </s>"},"G2424":{"l":"Ἰησοῦς","o":917,"en":"<f><o>Ἰησοῦς</o>, <g>-οῦ</g>, dat., voc. <g>-οῦ</g>, acc., <g>-οῦν</g> (Heb. <h n=\"H3091\">יְהוֹשׁוּעַ</h>, <h n=\"H3091\">יְהֹשֻׁעַ</h>, <h n=\"H3091\">יֵשׁוּעַ</h>),</f> <s> <s n=\"1.\"><b>JESUS</b>: <r v=\"Matt.1.21\"></r>, al.; <g>ὁ Ἰ</g>, <r v=\"Matt.3.13\"></r>, al.; <g>Ἰ. Χριστός</g>, <r v=\"Matt.1.1\"></r>, <r v=\"Mark.1.1\"></r>, al.; <g>Χρ. Ἰ.</g>, <r v=\"Rom.2.26\"></r>, al.; <g>κύριος Ἰ.</g>, <r v=\"Acts.28.31\"></r>, al.; <g>Ἰησοῦ</g>, voc., <r v=\"Mark.1.24\"></r>, al.</s> <s n=\"2.\"><b>Joshua</b>: <r v=\"Acts.7.45\"></r>, <r v=\"Heb.4.8\"></r>.</s> <s n=\"3.\"><b>Jesus</b>, son of Eliezer: <r v=\"Luke.3.29\"></r>.</s> <s n=\"4.\"><b>Jesus</b>, surnamed Justus: <r v=\"Col.4.11\"></r>.</s> <s n=\"5.\">v.s. <g>βαραββᾶς</g>.</s> </s>","ar":"<f><o>Ἰησοῦς</o>، <g>-οῦ</g>، القابل والنداء <g>-οῦ</g>، النصب <g>-οῦν</g> (بالعبرية <h n=\"H3091\">יְהוֹשׁוּעַ</h>، <h n=\"H3091\">יְהֹשֻׁעַ</h>، <h n=\"H3091\">יֵשׁוּעַ</h>)،</f> <s> <s n=\"1.\"><b>يسوع</b>: <r v=\"Matt.1.21\"></r>، وفي مواضع أخرى؛ <g>ὁ Ἰ</g>، <r v=\"Matt.3.13\"></r>، وفي مواضع أخرى؛ <g>Ἰ. Χριστός</g> (يسوع المسيح)، <r v=\"Matt.1.1\"></r>، <r v=\"Mark.1.1\"></r>، وفي مواضع أخرى؛ <g>Χρ. Ἰ.</g> (المسيح يسوع)، <r v=\"Rom.2.26\"></r>، وفي مواضع أخرى؛ <g>κύριος Ἰ.</g> (الرب يسوع)، <r v=\"Acts.28.31\"></r>، وفي مواضع أخرى؛ <g>Ἰησοῦ</g>، النداء، <r v=\"Mark.1.24\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\"><b>يشوع</b>: <r v=\"Acts.7.45\"></r>، <r v=\"Heb.4.8\"></r>.</s> <s n=\"3.\"><b>يسوع</b> (يوسي) بن أليعازر: <r v=\"Luke.3.29\"></r>.</s> <s n=\"4.\"><b>يسوع</b> المدعو يُسطُس: <r v=\"Col.4.11\"></r>.</s> <s n=\"5.\">انظر تحت مدخل <g>βαραββᾶς</g>.</s> </s>"},"G2532":{"l":"καί","o":9018,"en":"<f><o>καί</o>,</f> conj., <s><b>and</b>. <s n=\"I.\">Copulative. <s n=\"1.\">Connecting single words; <s n=\"(a)\">in general: <r v=\"Matt.2.18\"></r> <r v=\"Matt.16.1\"></r>, <r v=\"Mark.2.15\"></r>, <r v=\"Luke.8.15\"></r>, <r v=\"Heb.1.1\"></r>, al. mult.; repeated before each of the terms in a series, <r v=\"Matt.23.23\"></r>, <r v=\"Luke.14.21\"></r>, <r v=\"Rom.7.12\"></r> <r v=\"Rom.9.4\"></r>, al.;</s> <s n=\"(b)\">connecting numerals (WM, § 37, 4): <r v=\"John.2.20\"></r>, <r v=\"Acts.13.20\"></r>;</s> <s n=\"(c)\">joining terms which are not mutually exclusive, as the part with the whole: <r v=\"Matt.8.33\"></r> <r v=\"Matt.26.59\"></r>, <r v=\"Mark.16.17\"></r>, <r v=\"Acts.5.29\"></r>, al.</s> </s> <s n=\"2.\">Connecting clauses and sentences: <r v=\"Matt.3.12\"></r>, <r v=\"Acts.5.21\"></r>, al. mult.; esp. <s n=\"(a)\">where, after the simplicity of the popular language, sentences are paratactically joined (WM, § 60, 3; M, <i>Pr.</i>, 12; Deiss., <i>LAE</i>, 128 ff.): <r v=\"Matt.1.21\"></r> <r v=\"Matt.7.25\"></r>, <r v=\"Mark.9.5\"></r>, <r v=\"John.10.3\"></r>, al.;</s> <s n=\"(b)\">joining affirmative to negative sentences: <r v=\"Luke.3.14\"></r>, <r v=\"John.4.11\"></r>, <r v=\"3John.1.10\"></r>;</s> <s n=\"(c)\">consecutive, <b>and so</b>: <r v=\"Matt.5.15\"></r> <r v=\"Matt.23.32\"></r>, <r v=\"Heb.3.19\"></r>, al.; after imperatives, <r v=\"Matt.4.19\"></r>, <r v=\"Luke.7.7\"></r>, al.;</s> <s n=\"(d)\">= <g>καίτοι</g>, <b>and yet</b>: <r v=\"Matt.3.14\"></r> <r v=\"Matt.6.26\"></r>, <r v=\"Mark.12.12\"></r>, <r v=\"Luke.18.7\"></r> (Field, <i>Notes</i>, 72), <r v=\"1Cor.5.2\"></r>, al.;</s> <s n=\"(e)\">beginning an apodosis (= Heb. <h>וְ</h>; so sometimes <g>δέ</g> in cl.), <b>then</b>: <r v=\"Luke.2.21\"></r> <r v=\"Luke.7.12\"></r>, <r v=\"Acts.1.10\"></r>; beginning a question (WM, § 53, 3a): <r v=\"Mark.10.26\"></r>, <r v=\"Luke.10.29\"></r>, <r v=\"John.9.36\"></r>.</s> </s> <s n=\"3.\">Epexegetic, <b>and</b>, <b>and indeed</b>, <b>namely</b> (WM, § 53, 3c): <r v=\"Luke.3.18\"></r>, <r v=\"John.1.16\"></r>, <r v=\"Acts.23.6\"></r>, <r v=\"Rom.1.5\"></r>, <r v=\"1Cor.3.5\"></r>, al.</s> <s n=\"4.\">In transition: <r v=\"Matt.4.23\"></r>, <r v=\"Mark.5.1\"></r>, <r v=\"Mark.5.21\"></r>, <r v=\"John.1.19\"></r>, al.; so, Hebraistically, <g>καὶ ἐγένετο</g> (<h n=\"H1961\">וַיְהִי</h>; also <g>ἐγένετο δέ</g>), <r v=\"Mark.1.9\"></r> (cf. <r v=\"Luke.5.1\"></r>; V. Burton, §§ 357-60; M, <i>Pr.</i>, 14, 16).</s> <s n=\"5.\"><g>καὶ . . . καί</g>, <b>both . . . and</b> (for <g>τε . . . καί</g>, v.s. <g>τε</g>); <s n=\"(a)\">connecting single words: <r v=\"Matt.10.28\"></r>, <r v=\"Mark.4.41\"></r>, <r v=\"Rom.11.33\"></r>, al.;</s> <s n=\"(b)\">clauses and sentences: <r v=\"Mark.9.13\"></r>, <r v=\"John.7.28\"></r>, <r v=\"1Cor.1.22\"></r>, al.</s> </s> </s> <s n=\"II.\">Adjunctive, <b>also</b>, <b>even</b>, <b>still</b>: <r v=\"Matt.5.39\"></r>, <r v=\"Matt.5.40\"></r>, <r v=\"Mark.2.28\"></r>, al. mult.; esp. c. pron., adv., etc., <r v=\"Matt.20.4\"></r>, <r v=\"John.7.47\"></r>, al; <g>ὡς κ.</g>, <r v=\"Acts.11.17\"></r>; <g>καθὼς κ.</g>, <r v=\"Rom.15.7\"></r>; <g>οὕτω κ.</g>, <r v=\"Rom.6.11\"></r>; <g>διὸ κ.</g>, <r v=\"Luke.1.35\"></r>; <g>ὁ κ.</g> (Deiss., <i>BS</i>, 313ff.), <r v=\"Acts.13.9\"></r>; pleonastically, <g>μετὰ κ.</g>. (Bl., §77, 7; Deiss., <i>BS</i>, 265 f,), <r v=\"Phil.4.3\"></r>; <g>τί κ.</g>, <r v=\"1Cor.15.29\"></r>; <g>ἀλλὰ κ.</g>, <r v=\"Luke.14.22\"></r>, <r v=\"John.5.18\"></r>, al.; <g>καίγε</g> (M, <i>Pr.</i>, 230; Burton, § 437), <r v=\"Acts.17.27\"></r>; <g>καίπερ</g>, <r v=\"Heb.5.8\"></r>; <g>κ. ἐάν</g>, v.s. <g>ἐάν</g>.</s> </s>","ar":"<f><o>καί</o>،</f> أداة ربط، <s><b>و</b>. <s n=\"I.\">للعطف. <s n=\"1.\">تربط كلمات مفردة؛ <s n=\"(a)\">عمومًا: <r v=\"Matt.2.18\"></r>، <r v=\"Matt.16.1\"></r>، <r v=\"Mark.2.15\"></r>، <r v=\"Luke.8.15\"></r>، <r v=\"Heb.1.1\"></r>، ومواضع أخرى كثيرة؛ مكررة قبل كل لفظ في سلسلة: <r v=\"Matt.23.23\"></r>، <r v=\"Luke.14.21\"></r>، <r v=\"Rom.7.12\"></r>، <r v=\"Rom.9.4\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">تربط الأعداد: <r v=\"John.2.20\"></r>، <r v=\"Acts.13.20\"></r>؛</s> <s n=\"(c)\">تربط ألفاظًا لا يُقصي بعضها بعضًا، كالجزء مع الكل: <r v=\"Matt.8.33\"></r>، <r v=\"Matt.26.59\"></r>، <r v=\"Mark.16.17\"></r>، <r v=\"Acts.5.29\"></r>، وفي مواضع أخرى.</s> </s> <s n=\"2.\">تربط العبارات والجمل: <r v=\"Matt.3.12\"></r>، <r v=\"Acts.5.21\"></r>، ومواضع أخرى كثيرة؛ خاصةً <s n=\"(a)\">حيث تُعطف الجمل بعضها على بعض عطفًا متتابعًا على بساطة اللغة الشعبية: <r v=\"Matt.1.21\"></r>، <r v=\"Matt.7.25\"></r>، <r v=\"Mark.9.5\"></r>، <r v=\"John.10.3\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">تربط الجمل المثبتة بالمنفية: <r v=\"Luke.3.14\"></r>، <r v=\"John.4.11\"></r>، <r v=\"3John.1.10\"></r>؛</s> <s n=\"(c)\">للنتيجة: <b>وهكذا، ولذلك</b>: <r v=\"Matt.5.15\"></r>، <r v=\"Matt.23.32\"></r>، <r v=\"Heb.3.19\"></r>، وفي مواضع أخرى؛ بعد صيغ الأمر: <r v=\"Matt.4.19\"></r>، <r v=\"Luke.7.7\"></r>، وفي مواضع أخرى؛</s> <s n=\"(d)\">بمعنى <g>καίτοι</g>: <b>ومع ذلك</b>: <r v=\"Matt.3.14\"></r>، <r v=\"Matt.6.26\"></r>، <r v=\"Mark.12.12\"></r>، <r v=\"Luke.18.7\"></r>، <r v=\"1Cor.5.2\"></r>، وفي مواضع أخرى؛</s> <s n=\"(e)\">في بداية جواب الشرط (= العبرية <h>וְ</h>؛ وكذلك أحيانًا <g>δέ</g>): <b>حينئذٍ</b>: <r v=\"Luke.2.21\"></r>، <r v=\"Luke.7.12\"></r>، <r v=\"Acts.1.10\"></r>؛ في بداية سؤال: <r v=\"Mark.10.26\"></r>، <r v=\"Luke.10.29\"></r>، <r v=\"John.9.36\"></r>.</s> </s> <s n=\"3.\">تفسيرية: <b>و</b>، <b>بل</b>، <b>أي</b>: <r v=\"Luke.3.18\"></r>، <r v=\"John.1.16\"></r>، <r v=\"Acts.23.6\"></r>، <r v=\"Rom.1.5\"></r>، <r v=\"1Cor.3.5\"></r>، وفي مواضع أخرى.</s> <s n=\"4.\">للانتقال: <r v=\"Matt.4.23\"></r>، <r v=\"Mark.5.1\"></r>، <r v=\"Mark.5.21\"></r>، <r v=\"John.1.19\"></r>، وفي مواضع أخرى؛ وكذلك على الطريقة العبرية، <g>καὶ ἐγένετο</g> (<h n=\"H1961\">וַיְהִי</h>؛ وأيضًا <g>ἐγένετο δέ</g>): <r v=\"Mark.1.9\"></r> (قارن <r v=\"Luke.5.1\"></r>).</s> <s n=\"5.\"><g>καὶ . . . καί</g>: <b>كلٌّ من ... و</b> (وعن <g>τε . . . καί</g> انظر تحت مدخل <g>τε</g>)؛ <s n=\"(a)\">تربط كلمات مفردة: <r v=\"Matt.10.28\"></r>، <r v=\"Mark.4.41\"></r>، <r v=\"Rom.11.33\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">تربط العبارات والجمل: <r v=\"Mark.9.13\"></r>، <r v=\"John.7.28\"></r>، <r v=\"1Cor.1.22\"></r>، وفي مواضع أخرى.</s> </s> </s> <s n=\"II.\">للإضافة: <b>أيضًا</b>، <b>حتى</b>، <b>بعدُ</b>: <r v=\"Matt.5.39\"></r>، <r v=\"Matt.5.40\"></r>، <r v=\"Mark.2.28\"></r>، ومواضع أخرى كثيرة؛ خاصةً مع الضمائر والظروف ونحوها: <r v=\"Matt.20.4\"></r>، <r v=\"John.7.47\"></r>، وفي مواضع أخرى؛ <g>ὡς κ.</g>: <r v=\"Acts.11.17\"></r>؛ <g>καθὼς κ.</g>: <r v=\"Rom.15.7\"></r>؛ <g>οὕτω κ.</g>: <r v=\"Rom.6.11\"></r>؛ <g>διὸ κ.</g>: <r v=\"Luke.1.35\"></r>؛ <g>ὁ κ.</g>: <r v=\"Acts.13.9\"></r>؛ للحشو: <g>μετὰ κ.</g>: <r v=\"Phil.4.3\"></r>؛ <g>τί κ.</g>: <r v=\"1Cor.15.29\"></r>؛ <g>ἀλλὰ κ.</g>: <r v=\"Luke.14.22\"></r>، <r v=\"John.5.18\"></r>، وفي مواضع أخرى؛ <g>καίγε</g>: <r v=\"Acts.17.27\"></r>؛ <g>καίπερ</g>: <r v=\"Heb.5.8\"></r>؛ <g>κ. ἐάν</g>: انظر تحت مدخل <g>ἐάν</g>.</s> </s>"},"G26":{"l":"ἀγάπη","o":116,"en":"<f>† <o>ἀγάπη</o>, <g>-ης, ἡ</g> </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H160\">אַהֲבָה</h>, which is also rendered by <x><g>ἀγάπησις</g></x> and <x><g>φιλία</g></x>;]</e> </et> <s><b>love</b>, <b>goodwill</b>, <b>esteem</b>. Outside of bibl. and eccl. books, there is no clear instance (with Deiss., <i>LAE</i>, 18:4, 70:2, cf. the same writer in <i>Constr. Quar.</i>, ii, 4; and with MM, <i>VGT</i>, s.v., cf. Dr. Moulton in <i>Exp. Times</i>, xxvi, 3, 139). In NT, like <x><g>ἀγαπάω</g></x>, <g>-ῶ</g>, <s n=\"1.\">Of men's love: <s n=\"(a)\">to one another, <r v=\"John.13.35\"></r>; </s> <s n=\"(b)\">to God, <r v=\"1John.2.5\"></r>.</s> </s> <s n=\"2.\">Of divine love; <s n=\"(a)\">God's love: to men, <r v=\"Rom.5.8\"></r>; to Christ, <r v=\"John.17.26\"></r>; </s> <s n=\"(b)\">Christ's love to men: <r v=\"Rom.8.35\"></r>. </s> </s> <s n=\"3.\">In pl., <b>love feasts</b>: <r v=\"Jude.1.12\"></r> (<i>DB</i>, iii, 157).</s> </s> <sy><i>SYN.</i>: <x><g>φιλία</g></x>. <g>ἀ.</g>, signifying properly (v.s. <x><g>ἀγαπάω</g></x>) love which chooses its object, is taken over from LXX, where its connotation is more general, into NT, and there used exclusively to express that spiritual bond of love between God and man and between man and man, in Christ, which is characteristic of Christianity. It is thus distinct from <x><g>φιλία</g></x>, <i>friendship</i> (<r v=\"Jas.4.4\"></r> only), <x><g>στοργή</g></x>, <i>natural affection</i> (in NT only in compounds, v.s. <x><g>ἄστοργος</g></x>) and <x><g>ἔρως</g></x>, <i>sexual love</i>, which is not used in NT, its place being taken by <x><g>ἐπιθυμία</g></x>. (Cf. <x><g>ἀγαπάω</g></x>; and v. Abbott, <i>Essays</i>, 70f.; <i>DB</i>, vol. i., 555; Cremer, 13, 593; MM, <i>VGT</i>, s.v.).</sy>","ar":"<f>† <o>ἀγάπη</o>، <g>-ης, ἡ</g> </f> <s><b>محبة</b>، <b>مودّة، حسن نية</b>، <b>تقدير</b>. وفي العهد الجديد، كما في <x><g>ἀγαπάω</g></x>، <g>-ῶ</g>، <s n=\"1.\">عن محبة البشر: <s n=\"(a)\">بعضهم لبعض، <r v=\"John.13.35\"></r>؛ </s> <s n=\"(b)\">لله، <r v=\"1John.2.5\"></r>.</s> </s> <s n=\"2.\">عن المحبة الإلهية؛ <s n=\"(a)\">محبة الله: للبشر، <r v=\"Rom.5.8\"></r>؛ للمسيح، <r v=\"John.17.26\"></r>؛ </s> <s n=\"(b)\">محبة المسيح للبشر: <r v=\"Rom.8.35\"></r>. </s> </s> <s n=\"3.\">في الجمع: <b>ولائم المحبة (الأغابي)</b>: <r v=\"Jude.1.12\"></r>.</s> </s>"},"G260":{"l":"ἅμα","o":10,"en":"<f><o>ἅμα </o></f> adv., <s><b>at once</b> (Lat. <l>simul</l>): <r v=\"Acts.24.26\"></r> <r v=\"Acts.27.40\"></r>, <r v=\"Rom.3.12\"></r> (<i>one and all</i> = <h n=\"H3162\">יַחַד</h>, <r v=\"Ps.14.3\"></r>), <r v=\"Col.4.3\"></r>, <r v=\"1Tim.5.13\"></r>, <r v=\"Phlm.1.22\"></r>; seq. <g>σύν</g>, <r v=\"1Thess.4.17\"></r> <r v=\"1Thess.5.10\"></r>; as prep. c. dat., <b>together with</b>: <r v=\"Matt.13.29\"></r> (v. MM, <i>VGT</i>, s.v.); also, c. adv., <g>ἅ. πρωΐ</g> (cl., <g>ἅ. ἕω</g>, etc.), <b>early in the morning</b>: <r v=\"Matt.20.1\"></r>.†</s>","ar":"<f><o>ἅμα </o></f> ظرف، <s><b>معًا، في الوقت نفسه</b> (اللاتينية <l>simul</l>): <r v=\"Acts.24.26\"></r> <r v=\"Acts.27.40\"></r>، <r v=\"Rom.3.12\"></r> (<i>جميعًا</i> = <h n=\"H3162\">יַחַד</h>، <r v=\"Ps.14.3\"></r>)، <r v=\"Col.4.3\"></r>، <r v=\"1Tim.5.13\"></r>، <r v=\"Phlm.1.22\"></r>؛ يليه <g>σύν</g>، <r v=\"1Thess.4.17\"></r> <r v=\"1Thess.5.10\"></r>؛ حرف جر مع القابل: <b>مع، جنبًا إلى جنب مع</b>: <r v=\"Matt.13.29\"></r>؛ وأيضًا مع ظرف، <g>ἅ. πρωΐ</g>: <b>باكرًا جدًّا</b>: <r v=\"Matt.20.1\"></r>.†</s>"},"G27":{"l":"ἀγαπητός","o":61,"en":"<f><o>ἀγαπητός</o>, <g>-ή, -όν</g> </f> <et> <e t=\"derivation\">(&lt; <x><g>ἀγαπάω</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3039\">יָתִיד</h>, <h n=\"H3039\">יָדִיד</h>;]</e> </et> <s><b>beloved</b> (v. M, <i>Pr.</i>, 221); <s n=\"(a)\">by God: of Christ, <r v=\"Matt.3.17\"></r>; of men, <r v=\"Rom.1.7\"></r>; </s> <s n=\"(b)\">by Christians, of one another: <r v=\"1Cor.4.14\"></r>; freq. as form of address, <r v=\"1Cor.10.14\"></r>; opp. to <x><g>ἐχθρός</g></x>, <r v=\"Rom.11.28\"></r> (v. AR, <i>Eph.</i>, 229; Cremer, 17; MM, <i>VGT</i>, s.v.).</s> </s>","ar":"<f><o>ἀγαπητός</o>، <g>-ή, -όν</g> </f> <s><b>محبوب</b>؛ <s n=\"(a)\">من الله: عن المسيح، <r v=\"Matt.3.17\"></r>؛ عن البشر، <r v=\"Rom.1.7\"></r>؛ </s> <s n=\"(b)\">من المسيحيين، بعضهم لبعض: <r v=\"1Cor.4.14\"></r>؛ وكثيرًا صيغةً للخطاب، <r v=\"1Cor.10.14\"></r>؛ عكس <x><g>ἐχθρός</g></x>، <r v=\"Rom.11.28\"></r>.</s> </s>"},"G2722":{"l":"κατέχω","o":17,"en":"<f><o>κατ-έχω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H270\">אחז</h>, <h n=\"H2388\">חזק</h> hi., etc.;]</e> </et> <s n=\"1.\">perfective of <g>ἔχω</g> (M, <i>Pr.</i>, 116; M, <i>Th.</i>, 155), <s n=\"(a)\"><b>to possess</b>, <b>hold fast</b>: <r v=\"Luke.8.15\"></r>, <r v=\"John.5.4\"></r>, <r v=\"Rom.1.18\"></r> (Lft., <i>Notes</i>, 251), <r v=\"1Cor.7.30\"></r> <r v=\"1Cor.11.2\"></r>, <r v=\"2Cor.6.10\"></r>, <r v=\"1Thess.5.21\"></r>, <r v=\"Heb.3.6\"></r>, <r v=\"Heb.3.14\"></r> <r v=\"Heb.10.23\"></r>;</s> <s n=\"(b)\"><b>to lay hold of</b>, <b>get possession of</b>: <r v=\"Luke.14.9\"></r>.</s> </s> <s n=\"2.\"><b>to hold back</b>, <b>detain</b>, <b>restrain</b> (M, <i>Th.</i>, 156 f.): c. acc. seq. <g>τοῦ μή</g> c. inf., <r v=\"Luke.4.42\"></r>; seq. <g>πρός</g>, c. acc., <r v=\"Phlm.1.13\"></r>; absol., <g>τὸ κατέχον</g> (<g>ὁ κ.</g>), <r v=\"2Thess.2.6\"></r>, <r v=\"2Thess.2.7\"></r>.</s> <s n=\"3.\">Intrans., as nautical term, <b>to put in</b>, <b>make for</b> (LS, s.v.): <r v=\"Acts.27.40\"></r>.†</s>","ar":"<f><o>κατ-έχω</o>،</f> <s n=\"1.\">صيغة إتمامية من <g>ἔχω</g>، <s n=\"(a)\"><b>امتلك</b>، <b>تمسّك بـ</b>: <r v=\"Luke.8.15\"></r>، <r v=\"John.5.4\"></r>، <r v=\"Rom.1.18\"></r>، <r v=\"1Cor.7.30\"></r>، <r v=\"1Cor.11.2\"></r>، <r v=\"2Cor.6.10\"></r>، <r v=\"1Thess.5.21\"></r>، <r v=\"Heb.3.6\"></r>، <r v=\"Heb.3.14\"></r>، <r v=\"Heb.10.23\"></r>؛</s> <s n=\"(b)\"><b>قبض على</b>، <b>استولى على</b>: <r v=\"Luke.14.9\"></r>.</s> </s> <s n=\"2.\"><b>أمسك</b>، <b>عاق، احتجز</b>، <b>منع، ضبط</b>: مع المنصوب يليه <g>τοῦ μή</g> مع المصدر: <r v=\"Luke.4.42\"></r>؛ يليه <g>πρός</g> مع المنصوب: <r v=\"Phlm.1.13\"></r>؛ مطلقًا، <g>τὸ κατέχον</g> (<g>ὁ κ.</g>): <r v=\"2Thess.2.6\"></r>، <r v=\"2Thess.2.7\"></r>.</s> <s n=\"3.\">لازم، مصطلحًا بحريًّا: <b>أقلع نحو</b>، <b>اتجه إلى</b>: <r v=\"Acts.27.40\"></r>.†</s>"},"G2842":{"l":"κοινωνία","o":19,"en":"<f><o>κοινωνία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κοινωνός</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Lev.6.2\"></r> (<r v=\"Lev.5.21\"></r>) (<h n=\"H3027\">יָד</h> <h n=\"H8667\">תְּשׂוּמֶת</h>), <r v=\"Wis.8.18\"></r>, <r v=\"3Macc.4.6\"></r>*;]</e> </et> <s n=\"1.\"><b>fellowship</b>, <b>communion</b>: <r v=\"Acts.2.42\"></r>, <r v=\"2Cor.6.14\"></r>, <r v=\"Phil.1.5\"></r>; <g>τ. υἱοῦ</g>, <r v=\"1Cor.1.9\"></r>; <g>τ. αἵματος, σώματος Χρ.</g>, <r v=\"1Cor.10.16\"></r>; <g>παθημάτων αὐτσῦ</g>, <r v=\"Phil.3.10\"></r>; <g>τ. πνεύματος</g>, <r v=\"2Cor.13.13\"></r>, <r v=\"Phil.2.1\"></r>; <g>δεξιὰς κοινωνίας</g>, <r v=\"Gal.2.9\"></r>; <g>τ. πίστεώς σου</g>, <r v=\"Phlm.1.6\"></r>; seq. <g>μετὰ</g>: <g>τ. πατρός</g>, <r v=\"1John.1.3\"></r>, <r v=\"1John.1.6\"></r>; <g>ἡμῶν, ἀλλήλων</g>, <r v=\"1John.1.3\"></r>, <r v=\"1John.1.7\"></r>.</s> <s n=\"2.\"><b>contribution</b> (as outcome of fellowship): <r v=\"Rom.15.26\"></r>, <r v=\"2Cor.8.4\"></r> <r v=\"2Cor.9.13\"></r>, <r v=\"Heb.13.6\"></r> (cf. Art. <i>Communion</i>, <i>DB</i>, i, 460 ff.; MM, <i>Exp.</i>, xv).†</s>","ar":"<f><o>κοινωνία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\"><b>شركة</b>، <b>مشاركة، تواصل</b>: <r v=\"Acts.2.42\"></r>، <r v=\"2Cor.6.14\"></r>، <r v=\"Phil.1.5\"></r>؛ <g>τ. υἱοῦ</g> (شركة ابنه)، <r v=\"1Cor.1.9\"></r>؛ <g>τ. αἵματος, σώματος Χρ.</g> (شركة دم المسيح وجسده)، <r v=\"1Cor.10.16\"></r>؛ <g>παθημάτων αὐτσῦ</g> (شركة آلامه)، <r v=\"Phil.3.10\"></r>؛ <g>τ. πνεύματος</g> (شركة الروح)، <r v=\"2Cor.13.13\"></r>، <r v=\"Phil.2.1\"></r>؛ <g>δεξιὰς κοινωνίας</g> (يمين الشركة)، <r v=\"Gal.2.9\"></r>؛ <g>τ. πίστεώς σου</g> (شركة إيمانك)، <r v=\"Phlm.1.6\"></r>؛ يليه <g>μετὰ</g>: <g>τ. πατρός</g> (مع الآب)، <r v=\"1John.1.3\"></r>، <r v=\"1John.1.6\"></r>؛ <g>ἡμῶν, ἀλλήλων</g> (معنا، بعضنا مع بعض)، <r v=\"1John.1.3\"></r>، <r v=\"1John.1.7\"></r>.</s> <s n=\"2.\"><b>عطاء، إسهام، توزيع</b> (بوصفه ثمرة الشركة): <r v=\"Rom.15.26\"></r>، <r v=\"2Cor.8.4\"></r> <r v=\"2Cor.9.13\"></r>، <r v=\"Heb.13.6\"></r>.†</s>"},"G2844":{"l":"κοινωνός","o":10,"en":"<f><o>κοινωνός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>κοινός</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.28.24\"></r>, <r v=\"Isa.1.23\"></r> (<h n=\"H2270\">חָבֵר</h>), <r v=\"Mal.2.14\"></r> (<h n=\"H2278\">חֲבֶרֶת</h>), <r v=\"Ezra.8.13\"></r>, al.;]</e> </et> <s n=\"1.\">as adj., = <g>κοινός</g>.</s> <s n=\"2.\">As subst., <g>ὁ, ἡ κ.</g>, <s n=\"(a)\"><b>a partner</b>, <b>associate</b>, <b>companion</b>: <r v=\"2Cor.8.23\"></r>, <r v=\"Phlm.1.17\"></r>; c. dat. pers., <r v=\"Luke.5.10\"></r>; c. gen. pers., <r v=\"Heb.10.33\"></r>; id. seq. <g>ἐν</g>, <r v=\"Matt.23.30\"></r>;</s> <s n=\"(b)\"><b>a partaker</b>, <b>sharer</b>: c. gen. rei, <r v=\"1Cor.10.18\"></r>, <r v=\"1Cor.10.20\"></r>, <r v=\"2Cor.1.7\"></r>, <r v=\"1Pet.5.1\"></r>, <r v=\"2Pet.1.4\"></r> (v. Deiss., <i>BS</i>, 368 n<i>2</i>).†</s> </s>","ar":"<f><o>κοινωνός</o>، <g>-ή, -όν</g></f> <s n=\"1.\">صفةً، = <g>κοινός</g>.</s> <s n=\"2.\">اسمًا، <g>ὁ, ἡ κ.</g>، <s n=\"(a)\"><b>شريك</b>، <b>رفيق</b>، <b>صاحب</b>: <r v=\"2Cor.8.23\"></r>، <r v=\"Phlm.1.17\"></r>؛ مع قابل الشخص، <r v=\"Luke.5.10\"></r>؛ مع المضاف إليه للشخص، <r v=\"Heb.10.33\"></r>؛ والتعبير نفسه يليه <g>ἐν</g>، <r v=\"Matt.23.30\"></r>؛</s> <s n=\"(b)\"><b>شريك في</b>، <b>مُشارِك</b>: مع المضاف إليه للشيء، <r v=\"1Cor.10.18\"></r>، <r v=\"1Cor.10.20\"></r>، <r v=\"2Cor.1.7\"></r>، <r v=\"1Pet.5.1\"></r>، <r v=\"2Pet.1.4\"></r>.†</s> </s>"},"G2962":{"l":"κύριος","o":717,"en":"<f><o>κύριος</o>, <g>-α, -ον</g> (also <g>-ος, -ον</g>),</f> <et> <e t=\"septuagint\">[in LXX (subst.) chiefly for <h n=\"H3069\">יהוה</h>, also for <h n=\"H113\">אָדוֹן</h>, <h n=\"H1167\">בַּעַל</h>, etc.;]</e> </et> <s><b>having power</b> (<g>κῦρος</g>) or <b>authority</b>; as subst., <g>ὁ κ.</g>, <b>lord</b>, <b>master</b>; <s n=\"1.\">in general: c. gen. rei, <r v=\"Matt.9.38\"></r> <r v=\"Matt.20.8\"></r>, <r v=\"Mark.12.9\"></r> <r v=\"Mark.13.35\"></r>, <r v=\"Luke.19.33\"></r>; <g>τ. σαββάτου</g>, <r v=\"Matt.12.8\"></r>, <r v=\"Mark.2.28\"></r>, <r v=\"Luke.6.5\"></r>; c. gen. pers., <g>δούλου</g>, etc., <r v=\"Matt.10.24\"></r>, <r v=\"Luke.14.21\"></r>, <r v=\"Acts.16.16\"></r>, al.; absol., opp. to <g>οἱ δοῦλοι</g>, <r v=\"Eph.6.5\"></r>, <r v=\"Eph.6.9\"></r>, al.; of the Emperor (Deiss., <i>LAE</i>, 161), <r v=\"Acts.25.26\"></r>; <g>θεοὶ πολλοὶ καὶ κ. πολλοί</g>, <r v=\"1Cor.8.5\"></r>; of a husband, <r v=\"1Pet.3.6\"></r>; in voc., as a title of respect to masters, teachers, magistrates, etc., <r v=\"Matt.13.27\"></r> <r v=\"Matt.16.22\"></r> <r v=\"Matt.27.63\"></r>, <r v=\"Mark.7.28\"></r>, <r v=\"Luke.5.12\"></r>, <r v=\"John.4.11\"></r>, <r v=\"Acts.9.5\"></r>, al.</s> <s n=\"2.\">As a divine title (freq. in <g>π.</g>; Deiss., <i>LAE</i>, 353 ff.); in NT, <s n=\"(a)\">of God: <g>ὁ κ.</g>, <r v=\"Matt.5.33\"></r>, <r v=\"Mark.5.19\"></r>, <r v=\"Luke.1.6\"></r>, <r v=\"Acts.7.33\"></r>, <r v=\"Heb.8.2\"></r>, <r v=\"Jas.4.15\"></r>, al.; anarth. (Bl., § 46, 6), <r v=\"Matt.21.9\"></r>, <r v=\"Mark.13.20\"></r>, <r v=\"Luke.1.17\"></r>, <r v=\"Heb.7.21\"></r>, <r v=\"1Pet.1.25\"></r>, al.; <g>κ. τ. οὐρανοῦ καὶ τ. γῆς</g>, <r v=\"Matt.11.25\"></r>; <g>τ. κυριευόντων</g>, <r v=\"1Tim.6.15\"></r>; <g>κ. ὁ θεός</g>, <r v=\"Matt.4.7\"></r>, <r v=\"Matt.4.10\"></r> al.; id. seq. <g>ὁ παντοκράτωρ</g>, <r v=\"Rev.4.8\"></r>; <g>κ. σαβαώθ</g>, <r v=\"Rom.9.29\"></r>; (<g>ὁ</g>) <g>ἄγγελος κυρίου</g>, <r v=\"Matt.1.20\"></r> <r v=\"Matt.2.13\"></r>, <r v=\"Luke.1.11\"></r>, al.; <g>πνεῦμα κυρίου</g>, <r v=\"Luke.4.18\"></r>, <r v=\"Acts.8.39\"></r>;</s> <s n=\"(b)\">of the Christ: <r v=\"Matt.21.3\"></r>, <r v=\"Mark.11.3\"></r>, <r v=\"Luke.1.43\"></r> <r v=\"Luke.20.44\"></r>, al.; of Jesus after his resurrection (Dalman, <i>Words</i>, 330), <r v=\"Acts.10.36\"></r>, <r v=\"Rom.14.8\"></r>, <r v=\"1Cor.7.22\"></r>, <r v=\"Eph.4.5\"></r>, al.; <g>ὁ κ. μου</g>, <r v=\"John.20.28\"></r>; <g>ὁ κ. Ἰησοῦς</g>, <r v=\"Acts.1.21\"></r>, <r v=\"1Cor.11.23\"></r>, al.; id. seq. <g>Χριστός</g>, <r v=\"Eph.1.2\"></r>, al.; <g>ὁ κ. ἡμῶν</g>, <r v=\"1Tim.1.14\"></r>, <r v=\"Heb.7.14\"></r>, al.; id. seq. <g>Ἰησοῦς</g>, <r v=\"1Thess.3.11\"></r>, <r v=\"Heb.13.20\"></r>, al.; <g>Χριστός</g>, <r v=\"Rom.16.18\"></r>; <g>Ἰ Χ.</g>, <r v=\"1Cor.1.2\"></r>, <r v=\"1Thess.1.3\"></r>, al.; <g>Ἰ. Χ.</g> (<g>Χ. Ἰ</g>) <g>ὁ κ.</g> (<g>ἡμῶν</g>), <r v=\"Rom.1.4\"></r>, <r v=\"Col.2.6\"></r>, <r v=\"Eph.3.11\"></r>, al.; <g>ὁ κ. καὶ ὁ σωτὴρ</g>, <r v=\"2Pet.3.2\"></r>; id. seq. <g>Ἰ. Χ.</g>, <r v=\"2Pet.3.18\"></r>; anarth., <r v=\"1Cor.7.22\"></r>, <r v=\"1Cor.7.25\"></r>, <r v=\"Jas.5.4\"></r>, al.; <g>κ. κυρίων</g>, <r v=\"Rev.19.16\"></r>; c. prep., <g>ἀπὸ</g> (<g>κατὰ</g>, <g>πρὸς</g>, <g>σὺν</g>, etc.) <g>κ.</g>, <r v=\"Col.3.24\"></r>, al.</s> </s> </s> <sy><i>SYN:</i> v.s. <g>δεσπότης</g>.</sy>","ar":"<f><o>κύριος</o>، <g>-α, -ον</g> (وأيضًا <g>-ος, -ον</g>)،</f> <s><b>ذو سلطان</b> (<g>κῦρος</g>) أو <b>ذو سيادة</b>؛ اسمًا، <g>ὁ κ.</g>، <b>رب</b>، <b>سيد</b>؛ <s n=\"1.\">بوجه عام: مع المضاف إليه للشيء، <r v=\"Matt.9.38\"></r> <r v=\"Matt.20.8\"></r>، <r v=\"Mark.12.9\"></r> <r v=\"Mark.13.35\"></r>، <r v=\"Luke.19.33\"></r>؛ <g>τ. σαββάτου</g>، <r v=\"Matt.12.8\"></r>، <r v=\"Mark.2.28\"></r>، <r v=\"Luke.6.5\"></r>؛ مع المضاف إليه للشخص، <g>δούλου</g>، إلخ، <r v=\"Matt.10.24\"></r>، <r v=\"Luke.14.21\"></r>، <r v=\"Acts.16.16\"></r>، وفي مواضع أخرى؛ مطلقًا، عكس <g>οἱ δοῦλοι</g>، <r v=\"Eph.6.5\"></r>، <r v=\"Eph.6.9\"></r>، وفي مواضع أخرى؛ عن الإمبراطور، <r v=\"Acts.25.26\"></r>؛ <g>θεοὶ πολλοὶ καὶ κ. πολλοί</g>، <r v=\"1Cor.8.5\"></r>؛ عن الزوج، <r v=\"1Pet.3.6\"></r>؛ في النداء، لقبَ احترام للسادة والمعلمين والحكام ونحوهم، <r v=\"Matt.13.27\"></r> <r v=\"Matt.16.22\"></r> <r v=\"Matt.27.63\"></r>، <r v=\"Mark.7.28\"></r>، <r v=\"Luke.5.12\"></r>، <r v=\"John.4.11\"></r>، <r v=\"Acts.9.5\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\">لقبًا إلهيًّا؛ في العهد الجديد، <s n=\"(a)\">عن الله: <g>ὁ κ.</g>، <r v=\"Matt.5.33\"></r>، <r v=\"Mark.5.19\"></r>، <r v=\"Luke.1.6\"></r>، <r v=\"Acts.7.33\"></r>، <r v=\"Heb.8.2\"></r>، <r v=\"Jas.4.15\"></r>، وفي مواضع أخرى؛ بدون أداة التعريف، <r v=\"Matt.21.9\"></r>، <r v=\"Mark.13.20\"></r>، <r v=\"Luke.1.17\"></r>، <r v=\"Heb.7.21\"></r>، <r v=\"1Pet.1.25\"></r>، وفي مواضع أخرى؛ <g>κ. τ. οὐρανοῦ καὶ τ. γῆς</g>، <r v=\"Matt.11.25\"></r>؛ <g>τ. κυριευόντων</g>، <r v=\"1Tim.6.15\"></r>؛ <g>κ. ὁ θεός</g>، <r v=\"Matt.4.7\"></r>، <r v=\"Matt.4.10\"></r> وفي مواضع أخرى؛ والتعبير نفسه يليه <g>ὁ παντοκράτωρ</g>، <r v=\"Rev.4.8\"></r>؛ <g>κ. σαβαώθ</g>، <r v=\"Rom.9.29\"></r>؛ (<g>ὁ</g>) <g>ἄγγελος κυρίου</g>، <r v=\"Matt.1.20\"></r> <r v=\"Matt.2.13\"></r>، <r v=\"Luke.1.11\"></r>، وفي مواضع أخرى؛ <g>πνεῦμα κυρίου</g>، <r v=\"Luke.4.18\"></r>، <r v=\"Acts.8.39\"></r>؛</s> <s n=\"(b)\">عن المسيح: <r v=\"Matt.21.3\"></r>، <r v=\"Mark.11.3\"></r>، <r v=\"Luke.1.43\"></r> <r v=\"Luke.20.44\"></r>، وفي مواضع أخرى؛ عن يسوع بعد قيامته، <r v=\"Acts.10.36\"></r>، <r v=\"Rom.14.8\"></r>، <r v=\"1Cor.7.22\"></r>، <r v=\"Eph.4.5\"></r>، وفي مواضع أخرى؛ <g>ὁ κ. μου</g>، <r v=\"John.20.28\"></r>؛ <g>ὁ κ. Ἰησοῦς</g>، <r v=\"Acts.1.21\"></r>، <r v=\"1Cor.11.23\"></r>، وفي مواضع أخرى؛ والتعبير نفسه يليه <g>Χριστός</g>، <r v=\"Eph.1.2\"></r>، وفي مواضع أخرى؛ <g>ὁ κ. ἡμῶν</g>، <r v=\"1Tim.1.14\"></r>، <r v=\"Heb.7.14\"></r>، وفي مواضع أخرى؛ والتعبير نفسه يليه <g>Ἰησοῦς</g>، <r v=\"1Thess.3.11\"></r>، <r v=\"Heb.13.20\"></r>، وفي مواضع أخرى؛ <g>Χριστός</g>، <r v=\"Rom.16.18\"></r>؛ <g>Ἰ Χ.</g>، <r v=\"1Cor.1.2\"></r>، <r v=\"1Thess.1.3\"></r>، وفي مواضع أخرى؛ <g>Ἰ. Χ.</g> (<g>Χ. Ἰ</g>) <g>ὁ κ.</g> (<g>ἡμῶν</g>)، <r v=\"Rom.1.4\"></r>، <r v=\"Col.2.6\"></r>، <r v=\"Eph.3.11\"></r>، وفي مواضع أخرى؛ <g>ὁ κ. καὶ ὁ σωτὴρ</g>، <r v=\"2Pet.3.2\"></r>؛ والتعبير نفسه يليه <g>Ἰ. Χ.</g>، <r v=\"2Pet.3.18\"></r>؛ بدون أداة التعريف، <r v=\"1Cor.7.22\"></r>، <r v=\"1Cor.7.25\"></r>، <r v=\"Jas.5.4\"></r>، وفي مواضع أخرى؛ <g>κ. κυρίων</g>، <r v=\"Rev.19.16\"></r>؛ مع حرف جر، <g>ἀπὸ</g> (<g>κατὰ</g>، <g>πρὸς</g>، <g>σὺν</g>، إلخ) <g>κ.</g>، <r v=\"Col.3.24\"></r>، وفي مواضع أخرى.</s> </s> </s>"},"G3004":{"l":"λέγω","o":2335,"en":"<f><o>λέγω</o>,</f> <et> <e t=\"septuagint\">[in LXX very freq., chiefly for <h n=\"H559\">אמר</h>; <g>λέγει</g> for <h n=\"H5002\">נְאֻם</h>, <r v=\"Gen.22.16\"></r>, al.;]</e> </et> <s> <s n=\"1.\">in Hom., <b>to pick out</b>, <b>gather</b>, <b>reckon</b>, <b>recount</b>.</s> <s n=\"2.\">In Hdt. and Att., <b>to say</b>, <b>speak</b>, <b>affirm</b>, <b>declare</b>: absol., <r v=\"Acts.13.15\"></r> <r v=\"Acts.24.10\"></r>; seq. orat. dir., <r v=\"Matt.9.34\"></r>, <r v=\"Mark.3.11\"></r>, <r v=\"John.1.29\"></r>, al.; seq. <g>ὅτι</g> recit., <r v=\"Mark.3.21\"></r>, <r v=\"Luke.1.24\"></r>, <r v=\"John.6.14\"></r>, al.; acc. et. inf., <r v=\"Luke.11.18\"></r>, <r v=\"John.12.29\"></r>, al.; after another verb of speaking, <g>προσφωνεῖν κ. λέγειν</g>, <r v=\"Matt.11.17\"></r>, al.; <g>ἀπεκρίθη</g> (<g>ἐλάλησεν</g>) <g>λέγων</g> (<g>καὶ λέγει</g>; Dalman, <i>Words</i>, 24 ff.), <r v=\"Matt.25.9\"></r>, <r v=\"Mark.3.33\"></r>, <r v=\"Mark.7.28\"></r>, <r v=\"Luke.24.6\"></r>, <r v=\"Luke.24.7\"></r>, al.; of unspoken thought, <g>λ. ἐν ἑαυτῷ</g>, <r v=\"Matt.3.9\"></r>, <r v=\"Luke.3.8\"></r>, al.; of writing, <r v=\"2Cor.8.8\"></r>, <r v=\"Phil.4.11\"></r>, al.; <g>λέγει ἡ γραφή</g>, <r v=\"Rom.4.3\"></r>, <r v=\"Jas.2.23\"></r>, al.; c. acc. rei, <r v=\"Luke.8.8\"></r> <r v=\"Luke.9.33\"></r>, <r v=\"John.5.34\"></r>, al.; <g>σὺ λέγεις</g> (a non-committal phrase; Swete, <i>Mk.</i>, 359, 369 f.), <r v=\"Matt.27.11\"></r>, <r v=\"Mark.15.2\"></r>, <r v=\"Luke.23.3\"></r>, <r v=\"John.18.37\"></r>; c. dat. pers., seq. orat. dir., <r v=\"Matt.8.20\"></r>, <r v=\"Mark.2.17\"></r>, al. mult.; id. seq. <g>ὅτι</g>, <r v=\"Matt.3.9\"></r>, al.; c. prep., <g>πρός</g>, <g>μετά</g>, <g>περί</g>, etc., <r v=\"Mark.4.41\"></r>, <r v=\"John.11.56\"></r>, <r v=\"Heb.9.5\"></r>, al.; <b>to mean</b> (cl.), <r v=\"Mark.14.71\"></r>, <r v=\"John.6.71\"></r>, <r v=\"1Cor.10.29\"></r>, al.; <b>to call</b>, <b>name</b>, <r v=\"Mark.10.18\"></r>; pass., <r v=\"Matt.9.9\"></r>, <r v=\"Mark.15.7\"></r>, al (cf. <g>ἀντι-</g>, <g>δια-</g> (<g>-μαι</g>), <g>προ-</g>, <g>συλ-λέγω</g>).</s> </s> <sy><i>SYN.</i>: <g>λαλέω</g>, which refers to the utterance, as <g>λέγω</g> to the meaning of what is said, its correspondence with thought (Tr., <i>Syn.</i>, Ixxvi; Thayer, s.v. <g>λαλέω</g>).</sy>","ar":"<f><o>λέγω</o>،</f> <s> <s n=\"1.\">أصلاً، <b>يلتقط</b>، <b>يجمع</b>، <b>يعدّ</b>، <b>يسرد</b>.</s> <s n=\"2.\"><b>يقول</b>، <b>يتكلم</b>، <b>يؤكد</b>، <b>يُعلن</b>: مطلقًا، <r v=\"Acts.13.15\"></r> <r v=\"Acts.24.10\"></r>؛ يليه كلام مباشر، <r v=\"Matt.9.34\"></r>، <r v=\"Mark.3.11\"></r>، <r v=\"John.1.29\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g> لنقل الكلام، <r v=\"Mark.3.21\"></r>، <r v=\"Luke.1.24\"></r>، <r v=\"John.6.14\"></r>، وفي مواضع أخرى؛ مع المنصوب والمصدر، <r v=\"Luke.11.18\"></r>، <r v=\"John.12.29\"></r>، وفي مواضع أخرى؛ بعد فعل آخر من أفعال الكلام، <g>προσφωνεῖν κ. λέγειν</g>، <r v=\"Matt.11.17\"></r>، وفي مواضع أخرى؛ <g>ἀπεκρίθη</g> (<g>ἐλάλησεν</g>) <g>λέγων</g> (<g>καὶ λέγει</g>)، <r v=\"Matt.25.9\"></r>، <r v=\"Mark.3.33\"></r>، <r v=\"Mark.7.28\"></r>، <r v=\"Luke.24.6\"></r>، <r v=\"Luke.24.7\"></r>، وفي مواضع أخرى؛ عن الفكر غير المنطوق، <g>λ. ἐν ἑαυτῷ</g>، <r v=\"Matt.3.9\"></r>، <r v=\"Luke.3.8\"></r>، وفي مواضع أخرى؛ عن الكتابة، <r v=\"2Cor.8.8\"></r>، <r v=\"Phil.4.11\"></r>، وفي مواضع أخرى؛ <g>λέγει ἡ γραφή</g>، <r v=\"Rom.4.3\"></r>، <r v=\"Jas.2.23\"></r>، وفي مواضع أخرى؛ مع منصوب الشيء، <r v=\"Luke.8.8\"></r> <r v=\"Luke.9.33\"></r>، <r v=\"John.5.34\"></r>، وفي مواضع أخرى؛ <g>σὺ λέγεις</g> (عبارة لا تُلزِم القائل بموقف)، <r v=\"Matt.27.11\"></r>، <r v=\"Mark.15.2\"></r>، <r v=\"Luke.23.3\"></r>، <r v=\"John.18.37\"></r>؛ مع قابل الشخص، يليه كلام مباشر، <r v=\"Matt.8.20\"></r>، <r v=\"Mark.2.17\"></r>، وفي مواضع أخرى كثيرة؛ والتعبير نفسه يليه <g>ὅτι</g>، <r v=\"Matt.3.9\"></r>، وفي مواضع أخرى؛ مع حرف جر، <g>πρός</g>، <g>μετά</g>، <g>περί</g>، إلخ، <r v=\"Mark.4.41\"></r>، <r v=\"John.11.56\"></r>، <r v=\"Heb.9.5\"></r>، وفي مواضع أخرى؛ <b>يعني</b>، <r v=\"Mark.14.71\"></r>، <r v=\"John.6.71\"></r>، <r v=\"1Cor.10.29\"></r>، وفي مواضع أخرى؛ <b>يدعو</b>، <b>يُسمّي</b>، <r v=\"Mark.10.18\"></r>؛ المبني للمجهول، <r v=\"Matt.9.9\"></r>، <r v=\"Mark.15.7\"></r>، وفي مواضع أخرى (قارن <g>ἀντι-</g>، <g>δια-</g> (<g>-μαι</g>)، <g>προ-</g>، <g>συλ-λέγω</g>).</s> </s>"},"G3065":{"l":"Λουκᾶς","o":3,"en":"<f><o>Λουκᾶς</o>, <g>-ᾶ, ὁ</g></f> <et> <e t=\"derivation\">(prob. an abbreviation of <g>Λουκανός</g>; v. Lft., <i>Col.</i>, 240; <i>ICC</i>, <i>Lk.</i>, xviii; Bl., § 29; acc. to Ramsay, <i>Exp.</i>, Dec., 1912, pp. 502 ff., a by-form of <g>Λούκιος</g>, from Lat. <l>Lucius</l>),</e> </et> <s><b>Luke</b>: Lk, <i>tit.</i>, <r v=\"Col.4.14\"></r>, <r v=\"2Tim.4.11\"></r>, <r v=\"Phlm.1.24\"></r>.†</s>","ar":"<f><o>Λουκᾶς</o>، <g>-ᾶ, ὁ</g></f> <s><b>لوقا</b>: لوقا، <i>العنوان</i>، <r v=\"Col.4.14\"></r>، <r v=\"2Tim.4.11\"></r>، <r v=\"Phlm.1.24\"></r>.†</s>"},"G3122":{"l":"μάλιστα","o":12,"en":"<f><o>μάλιστα</o>, v.s. <g>μάλα</g>.</f>","ar":"<f><o>μάλιστα</o>، انظر تحت مدخل <g>μάλα</g>.</f>"},"G3123":{"l":"μάλα","o":81,"en":"<f><o>μάλα</o>,</f> adv., <et> <e t=\"septuagint\">[in LXX for <h n=\"H61\">אֲבָל</h>, <r v=\"1Kgs.1.43\"></r>, <r v=\"Dan.10.21\"></r>, al.; compar. for <h>מ</h>, <r v=\"Num.13.32\"></r> (<r v=\"Num.13.31\"></r>), al.; <g>μᾶλλον ἠ</g> (<h>מ</h>), <r v=\"Gen.19.9\"></r>, al.; superlat., <r v=\"2Macc.8.7\"></r>, <r v=\"4Macc.4.22\"></r> <r v=\"4Macc.12.9\"></r> <r v=\"4Macc.15.4\"></r>;]</e> </et> <s n=\"I.\">Pos., <b>very</b>, <b>very much</b>, <b>exceedingly</b> (cl.; LXX ut supr.; in NT its place is taken by <g>λίαν</g>, <g>σφόδρα</g>, etc.).</s> <s n=\"II.\">Compar., <g>μᾶλλον</g>. <s n=\"1.\">Of increase, <b>more</b>; with qualifying words: <g>πολλῷ</g>, <r v=\"Mark.10.48\"></r>, <r v=\"Luke.18.39\"></r>, <r v=\"Rom.5.15\"></r>, <r v=\"Rom.5.17\"></r>, <r v=\"Phil.2.12\"></r>, al.; <g>πόσῳ</g>, <r v=\"Luke.12.24\"></r>, <r v=\"Rom.11.12\"></r>, al.; <g>τοσούτῳ . . . ὅσῳ</g>, <r v=\"Heb.10.25\"></r>.</s> <s n=\"2.\">Of comparison, <b>the more</b>: <r v=\"Luke.5.15\"></r>, <r v=\"John.5.18\"></r>, <r v=\"Acts.5.14\"></r>, <r v=\"1Thess.4.1\"></r>, <r v=\"1Thess.4.10\"></r>, <r v=\"2Pet.1.10\"></r>; <g>ἔτι μ. καὶ μ.</g>, <r v=\"Phil.1.9\"></r>; c. compar., <r v=\"Mark.7.36\"></r>, <r v=\"2Cor.7.13\"></r>; <g>πολλῴ μ. κρεῖσσον</g>, <r v=\"Phil.1.23\"></r>; <g>μ. διαφέρειν</g>, c. gen., <r v=\"Matt.6.26\"></r>; <g>μ. ἤ</g>, <r v=\"Matt.18.13\"></r>; c. gen., <r v=\"1Cor.14.18\"></r>; as periphr. for compar., <r v=\"Acts.20.35\"></r>, <r v=\"1Cor.9.15\"></r>, <r v=\"Gal.4.27\"></r>; <g>μ. δέ</g> (EV, <i>yea rather</i>), <r v=\"Rom.8.34\"></r>.</s> <s n=\"3.\">Of preference, <b>rather</b>, <b>the rather</b>, <b>sooner</b>: with qualifying words, <g>πολλῷ</g>, <r v=\"Matt.6.30\"></r>, al.; <g>πολύ</g>, <r v=\"Heb.12.25\"></r>; <g>πόσῳ</g>, <r v=\"Matt.7.11\"></r>, al.; in a question, <g>οὐ μ.</g>, <r v=\"1Cor.9.12\"></r>; after a neg., <r v=\"Matt.10.6\"></r>, al.; <g>θέλω</g> (<g>εὐδοκῶ</g>) <g>μ.</g>, <r v=\"1Cor.14.5\"></r>, <r v=\"2Cor.5.8\"></r>; <g>ζηλῶ</g>, <r v=\"1Cor.14.1\"></r>; c. subst., <g>τ. σκότος ἢ τ. φῶς</g>, <r v=\"John.3.19\"></r>; <g>μ. δέ</g>, <r v=\"Gal.4.9\"></r>.</s> </s> <s n=\"III.\">Superl., <f><o>μάλιστα</o></f>, <b>most</b>, <b>most of all</b>, <b>above all</b>: <r v=\"Acts.20.38\"></r> <r v=\"Acts.25.26\"></r>, <r v=\"Gal.6.10\"></r>, <r v=\"Phil.4.22\"></r>, <r v=\"1Tim.4.10\"></r> <r v=\"1Tim.5.8\"></r>, <r v=\"1Tim.5.17\"></r>, <r v=\"2Tim.4.13\"></r>, <r v=\"Titus.1.10\"></r>, <r v=\"Phlm.1.16\"></r>, <r v=\"2Pet.2.10\"></r>; <g>μ. γνώστης</g>, <r v=\"Acts.26.3\"></r>.</s>","ar":"<f><o>μάλα</o>،</f> ظرف، <s n=\"I.\">في صيغته الأصلية: <b>جدًّا</b>، <b>كثيرًا</b>، <b>للغاية</b> (وفي العهد الجديد يحل محله <g>λίαν</g>، <g>σφόδρα</g> إلخ).</s> <s n=\"II.\">صيغة التفضيل: <g>μᾶλλον</g>. <s n=\"1.\">للزيادة: <b>أكثر</b>؛ مع ألفاظ مقيِّدة: <g>πολλῷ</g>: <r v=\"Mark.10.48\"></r>، <r v=\"Luke.18.39\"></r>، <r v=\"Rom.5.15\"></r>، <r v=\"Rom.5.17\"></r>، <r v=\"Phil.2.12\"></r>، وفي مواضع أخرى؛ <g>πόσῳ</g>: <r v=\"Luke.12.24\"></r>، <r v=\"Rom.11.12\"></r>، وفي مواضع أخرى؛ <g>τοσούτῳ . . . ὅσῳ</g>: <r v=\"Heb.10.25\"></r>.</s> <s n=\"2.\">للمقارنة: <b>بالأكثر</b>: <r v=\"Luke.5.15\"></r>، <r v=\"John.5.18\"></r>، <r v=\"Acts.5.14\"></r>، <r v=\"1Thess.4.1\"></r>، <r v=\"1Thess.4.10\"></r>، <r v=\"2Pet.1.10\"></r>؛ <g>ἔτι μ. καὶ μ.</g>: <r v=\"Phil.1.9\"></r>؛ مع صيغة التفضيل: <r v=\"Mark.7.36\"></r>، <r v=\"2Cor.7.13\"></r>؛ <g>πολλῴ μ. κρεῖσσον</g>: <r v=\"Phil.1.23\"></r>؛ <g>μ. διαφέρειν</g> مع المضاف إليه: <r v=\"Matt.6.26\"></r>؛ <g>μ. ἤ</g>: <r v=\"Matt.18.13\"></r>؛ مع المضاف إليه: <r v=\"1Cor.14.18\"></r>؛ أسلوبًا بديلاً عن صيغة التفضيل: <r v=\"Acts.20.35\"></r>، <r v=\"1Cor.9.15\"></r>، <r v=\"Gal.4.27\"></r>؛ <g>μ. δέ</g> (<i>بل بالحري</i>): <r v=\"Rom.8.34\"></r>.</s> <s n=\"3.\">للتفضيل: <b>بالحري</b>، <b>بالأولى</b>، <b>عوضًا عن ذلك</b>: مع ألفاظ مقيِّدة: <g>πολλῷ</g>: <r v=\"Matt.6.30\"></r>، وفي مواضع أخرى؛ <g>πολύ</g>: <r v=\"Heb.12.25\"></r>؛ <g>πόσῳ</g>: <r v=\"Matt.7.11\"></r>، وفي مواضع أخرى؛ في السؤال: <g>οὐ μ.</g>: <r v=\"1Cor.9.12\"></r>؛ بعد النفي: <r v=\"Matt.10.6\"></r>، وفي مواضع أخرى؛ <g>θέλω</g> (<g>εὐδοκῶ</g>) <g>μ.</g>: <r v=\"1Cor.14.5\"></r>، <r v=\"2Cor.5.8\"></r>؛ <g>ζηλῶ</g>: <r v=\"1Cor.14.1\"></r>؛ مع اسم: <g>τ. σκότος ἢ τ. φῶς</g>: <r v=\"John.3.19\"></r>؛ <g>μ. δέ</g>: <r v=\"Gal.4.9\"></r>.</s> </s> <s n=\"III.\">صيغة التفضيل العليا: <f><o>μάλιστα</o></f>: <b>أكثر شيء</b>، <b>أكثر من الكل</b>، <b>ولا سيما</b>: <r v=\"Acts.20.38\"></r>، <r v=\"Acts.25.26\"></r>، <r v=\"Gal.6.10\"></r>، <r v=\"Phil.4.22\"></r>، <r v=\"1Tim.4.10\"></r>، <r v=\"1Tim.5.8\"></r>، <r v=\"1Tim.5.17\"></r>، <r v=\"2Tim.4.13\"></r>، <r v=\"Titus.1.10\"></r>، <r v=\"Phlm.1.16\"></r>، <r v=\"2Pet.2.10\"></r>؛ <g>μ. γνώστης</g>: <r v=\"Acts.26.3\"></r>.</s>"},"G3138":{"l":"Μάρκος","o":8,"en":"<f><o>Μάρκος</o>, <g>-ου, ὁ</g>,</f> <s><b>Mark</b>: Mk., <i>tit.</i>, <r v=\"Acts.12.12\"></r>, <r v=\"Acts.12.25\"></r> <r v=\"Acts.15.37\"></r>, <r v=\"Acts.15.39\"></r>, <r v=\"Col.4.10\"></r>, <r v=\"2Tim.4.11\"></r>, <r v=\"Phlm.1.24\"></r>, <r v=\"1Pet.5.13\"></r> (v. Swete, <i>Mk.</i>, <i>Intr.</i>, xiii ff.; <i>DB</i>, iii, 245 ff).†</s>","ar":"<f><o>Μάρκος</o>، <g>-ου, ὁ</g>،</f> <s><b>مرقس</b>: عنوان إنجيل مرقس، <r v=\"Acts.12.12\"></r>، <r v=\"Acts.12.25\"></r> <r v=\"Acts.15.37\"></r>، <r v=\"Acts.15.39\"></r>، <r v=\"Col.4.10\"></r>، <r v=\"2Tim.4.11\"></r>، <r v=\"Phlm.1.24\"></r>، <r v=\"1Pet.5.13\"></r>.†</s>"},"G318":{"l":"ἀνάγκη","o":17,"en":"<f><o>ἀνάγκη</o>, <g>-ης, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4689\">מָצוֹק</h>, <h n=\"H6862\">צַר</h>;]</e> </et> <s n=\"1.\"><b>necessity</b>: <g>ἔχειν ἀ-</g>, c. inf., <b>to be compelled</b>, <r v=\"Luke.14.18\"></r> <r v=\"Luke.23.17\"></r> (Rec., R, mg.), <r v=\"1Cor.7.37\"></r>, <r v=\"Jude.1.3\"></r>, <r v=\"Heb.7.27\"></r>; <g>ἐξ ἀ., κατ</g>' <g>ἀ.</g>, <b>of necessity</b>, <r v=\"2Cor.9.7\"></r>, <r v=\"Heb.7.12\"></r>, <r v=\"Phlm.1.14\"></r>; <g>ἀ. μοι ἐπίκειται</g>, <i>n. is laid on me</i>, <r v=\"1Cor.9.16\"></r>; c. inf. (= <g>ἀναγκαῖον ἐστι</g>), <r v=\"Matt.18.7\"></r>, <r v=\"Rom.13.5\"></r>, <r v=\"Heb.9.16\"></r>, <r v=\"Heb.9.23\"></r> </s> <s n=\"2.\"><b>force</b>, <b>violence</b>, hence <b>pain</b>, <b>distress</b> (Diod., al.; LXX; v. M, <i>Th.</i>, 41; MM, <i>VGT</i>, s.v.; cf. <g>θλίψις</g>): <r v=\"Luke.21.23\"></r>, <r v=\"1Cor.7.26\"></r>, <r v=\"1Thess.3.7\"></r>; pl. (v. Bl., § 32, 6; Swete, <i>Mk.</i>, 153), <g>ἐν ἀ.</g>, <r v=\"2Cor.6.4\"></r> <r v=\"2Cor.12.10\"></r>.†</s>","ar":"<f><o>ἀνάγκη</o>، <g>-ης, ἡ </g></f> <s n=\"1.\"><b>ضرورة، اضطرار</b>: <g>ἔχειν ἀ-</g> مع المصدر: <b>اضطُرّ</b>: <r v=\"Luke.14.18\"></r>، <r v=\"Luke.23.17\"></r>، <r v=\"1Cor.7.37\"></r>، <r v=\"Jude.1.3\"></r>، <r v=\"Heb.7.27\"></r>؛ <g>ἐξ ἀ., κατ</g>' <g>ἀ.</g>: <b>اضطرارًا، بالضرورة</b>: <r v=\"2Cor.9.7\"></r>، <r v=\"Heb.7.12\"></r>، <r v=\"Phlm.1.14\"></r>؛ <g>ἀ. μοι ἐπίκειται</g>: <i>الضرورة موضوعة عليّ</i>: <r v=\"1Cor.9.16\"></r>؛ مع المصدر (= <g>ἀναγκαῖον ἐστι</g>): <r v=\"Matt.18.7\"></r>، <r v=\"Rom.13.5\"></r>، <r v=\"Heb.9.16\"></r>، <r v=\"Heb.9.23\"></r> </s> <s n=\"2.\"><b>قسر</b>، <b>عنف</b>، ومن هنا <b>ألم</b>، <b>ضيق، شدة</b> (قارن <g>θλίψις</g>): <r v=\"Luke.21.23\"></r>، <r v=\"1Cor.7.26\"></r>، <r v=\"1Thess.3.7\"></r>؛ في الجمع، <g>ἐν ἀ.</g>: <r v=\"2Cor.6.4\"></r>، <r v=\"2Cor.12.10\"></r>.†</s>"},"G3361":{"l":"μή","o":1042,"en":"<f><o>μή</o>,</f> subjective negative particle, <s>used where the negation depends on a condition or hypothesis, expressed or understood, as distinct from <g>οὐ</g>, which denies absolutely. <g>μή</g> is used where one <i>thinks</i> a thing is not, as distinct from an absolute negation. As a general rule, <g>οὐ</g> negatives the indic., <g>μή</g> the other moods, incl, ptcp. [In LXX for <h n=\"H369\">אֵין</h>, <h n=\"H369\">אַיִן</h>, <h n=\"H408\">אַל</h>.] <s n=\"I.\">As a neg. adv., <b>not</b>; <s n=\"1.\">with ref. to thought or opinion: <r v=\"John.3.18\"></r>, <r v=\"Titus.1.11\"></r>, <r v=\"2Pet.1.9\"></r>.</s> <s n=\"2.\">In delib. questions, c. subjc. (M, <i>Pr.</i>, 185): <r v=\"Mark.12.14\"></r>, <r v=\"Rom.3.8\"></r>.</s> <s n=\"3.\">In conditional and final sentences, after <g>εἰ</g>, <g>ἐάν</g>, <g>ἄν</g>, <g>ἵνα</g>, <g>ὅπως</g>: <r v=\"Matt.10.14\"></r>, <r v=\"Mark.6.11\"></r> <r v=\"Mark.12.19\"></r>, <r v=\"Luke.9.5\"></r>, <r v=\"John.6.50\"></r>, <r v=\"Rom.11.25\"></r>, al.</s> <s n=\"4.\">C. inf. (v. M, <i>Pr.</i>, 234 f., 239, 255), <s n=\"(a)\">after verbs of saying, etc.: <r v=\"Matt.2.12\"></r> <r v=\"Matt.5.34\"></r>, <r v=\"Mark.12.18\"></r>, <r v=\"Acts.15.38\"></r>, <r v=\"Rom.2.21\"></r>, al.;</s> <s n=\"(b)\">c. artic. inf.: after a prep., <r v=\"Matt.13.5\"></r>, <r v=\"Mark.4.5\"></r>, <r v=\"Acts.7.19\"></r>, <r v=\"1Cor.10.6\"></r>, al.; without a prep., <r v=\"Rom.14.13\"></r>, <r v=\"2Cor.2.1\"></r>, <r v=\"2Cor.1.13\"></r>, <r v=\"1Thess.4.6\"></r>;</s> <s n=\"(c)\">in sentences expressing consequence, after <g>ὥστε</g>: <r v=\"Matt.8.28\"></r>, <r v=\"Mark.3.20\"></r>, <r v=\"1Cor.1.7\"></r>, <r v=\"2Cor.3.7\"></r>, al.</s> </s> <s n=\"5.\">C. ptcp. (v. M, <i>Pr.</i>, 231 f., 239), in hypothetical references to persons of a certain character or description: <r v=\"Matt.10.28\"></r> <r v=\"Matt.12.30\"></r>, <r v=\"Luke.6.49\"></r>, <r v=\"John.3.18\"></r>, <r v=\"Rom.4.5\"></r>, <r v=\"1Cor.7.38\"></r>, <r v=\"1John.3.10\"></r>, al.; where the person or thing being definite, the denial is a matter of opinion: <r v=\"John.6.64\"></r>, <r v=\"1Cor.1.28\"></r> <r v=\"1Cor.4.7\"></r>, <r v=\"1Cor.4.18\"></r>, <r v=\"2Cor.5.21\"></r>, al.; where the ptcp. has a concessive, causal or conditional force, <b>if</b>, <b>though</b>, <b>because not</b>: <r v=\"Matt.18.25\"></r>, <r v=\"Luke.2.45\"></r>, <r v=\"John.7.49\"></r>, <r v=\"Acts.9.26\"></r>, <r v=\"Rom.2.14\"></r> <r v=\"Rom.5.13\"></r>, <r v=\"2Cor.3.14\"></r>, <r v=\"Gal.6.9\"></r>, <r v=\"Jude.1.5\"></r>; where the ptcp. has a descriptive force (<i>being such as</i>), <b>not</b>: <r v=\"Acts.9.9\"></r>, <r v=\"Rom.1.28\"></r>, <r v=\"1Cor.10.33\"></r>, <r v=\"Gal.4.8\"></r>, <r v=\"Heb.12.27\"></r>, al.</s> <s n=\"6.\"><g>μή</g> prohibitive, in indep. sentences, <s n=\"(a)\">c. subjc. praes., 1 pers. pl.: <r v=\"Gal.5.26\"></r> <r v=\"Gal.6.9\"></r>, <r v=\"1Thess.5.6\"></r>, <r v=\"1John.3.18\"></r>;</s> <s n=\"(b)\">c. imperat. praes., usually where one is bidden to desist from what has already begun (cf. M, <i>Pr.</i>, 122 ff.): <r v=\"Matt.7.1\"></r>, <r v=\"Mark.5.36\"></r>, <r v=\"Luke.6.30\"></r>, <r v=\"John.2.16\"></r> <r v=\"John.5.45\"></r>, <r v=\"Acts.10.15\"></r>, <r v=\"Rom.11.18\"></r>, <r v=\"Jas.2.1\"></r>, <r v=\"Rev.5.5\"></r>, al.;</s> <s n=\"(c)\">forbidding that which is still future: c. imperat. aor., 3 pers., <r v=\"Matt.24.18\"></r>, <r v=\"Mark.13.15\"></r>, <r v=\"Luke.17.31\"></r>, al.; c. subjc. aor., 2 pers., <r v=\"Matt.3.9\"></r> <r v=\"Matt.10.26\"></r>, <r v=\"Mark.5.7\"></r>, <r v=\"Luke.6.29\"></r>, <r v=\"John.3.7\"></r>, <r v=\"Rom.10.6\"></r>, al.;</s> <s n=\"(d)\">c. optat., in wishes: <r v=\"2Tim.4.16\"></r><i>(LXX)</i>; <g>μὴ γένοιτο</g> (v. M, <i>Pr.</i>, 194; Bl., § 66, 1), <r v=\"Luke.20.16\"></r>, <r v=\"Rom.3.3\"></r>, al.; <g>μή τις</g>, <r v=\"Mark.13.5\"></r>, al.</s> </s> </s> <s n=\"II.\">As a conj., <s n=\"1.\">after verbs of fearing, caution, etc., <b>that</b>, <b>lest</b>, <b>perhaps</b> (M, <i>Pr.</i>, 192 f.): c. subjc. praes., <r v=\"Heb.12.15\"></r>; c. subjc. aor., <r v=\"Matt.24.4\"></r>, <r v=\"Mark.13.5\"></r>, <r v=\"Luke.21.8\"></r>, <r v=\"Acts.13.40\"></r>, <r v=\"Gal.5.15\"></r>, al.; <g>ὅρα μή</g> (v. M, <i>Pr.</i>, 124, 178), elliptically, <r v=\"Rev.19.10\"></r> <r v=\"Rev.22.9\"></r>; c. indic, fut. (M, <i>Pr.</i>, 124, 178), <r v=\"Col.2.8\"></r>.</s> <s n=\"2.\"><b>in order that not</b>: c. subjc. aor., <r v=\"Mark.13.36\"></r>, <r v=\"2Cor.8.20\"></r> <r v=\"2Cor.12.6\"></r>.</s> </s> <s n=\"III.\">Interrogative, in hesitant questions (M, <i>Pr.</i>, 170), or where a negative answer is expected: <r v=\"Matt.7.9\"></r>, <r v=\"Matt.7.10\"></r>, <r v=\"Mark.2.19\"></r>, <r v=\"John.3.4\"></r>, <r v=\"Rom.3.3\"></r> <r v=\"Rom.10.18\"></r>, <r v=\"Rom.10.19\"></r>, <r v=\"1Cor.1.13\"></r>, al.; <g>μή τις</g>, <r v=\"Luke.22.35\"></r>, al.; seq. <g>οὐ</g> (<r v=\"Rom.10.17\"></r>, al. in Pl.), expecting an affirm, ans.; <g>οὐ μή</g>, <r v=\"Luke.18.7\"></r>, <r v=\"John.18.11\"></r>.</s> <s n=\"IV.\"><g>οὐ μή</g> as emphatic negation (cf. M, <i>Pr.</i>, 188, 190 ff.; Bl., § 64, 5), <b>not at all</b>, <b>by no means</b>: c. indic, fut., <r v=\"Matt.16.22\"></r>, <r v=\"John.6.35\"></r>, <r v=\"Heb.10.17\"></r>, al.; c. subjc. aor., <r v=\"Matt.24.2\"></r>, <r v=\"Mark.13.2\"></r>, <r v=\"Luke.6.37\"></r>, <r v=\"John.13.8\"></r>, <r v=\"1Cor.8.13\"></r>, al.</s> </s>","ar":"<f><o>μή</o>،</f> أداة نفي ذاتية، <s>تُستعمل حيث يتوقف النفي على شرط أو افتراض، ظاهر أو مفهوم، تمييزًا لها عن <g>οὐ</g> التي تنفي نفيًا مطلقًا. وتُستعمل <g>μή</g> حيث <i>يظن</i> المرء أن الأمر ليس كذلك، تمييزًا لها عن النفي المطلق. وكقاعدة عامة تنفي <g>οὐ</g> الإخباري، وتنفي <g>μή</g> سائر الصيغ، ومنها اسم الفاعل. <s n=\"I.\">بوصفها ظرف نفي: <b>لا</b>؛ <s n=\"1.\">فيما يتعلق بالفكر أو الرأي: <r v=\"John.3.18\"></r>، <r v=\"Titus.1.11\"></r>، <r v=\"2Pet.1.9\"></r>.</s> <s n=\"2.\">في أسئلة التداول (ماذا نفعل؟)، مع صيغة الاحتمال: <r v=\"Mark.12.14\"></r>، <r v=\"Rom.3.8\"></r>.</s> <s n=\"3.\">في جمل الشرط وجمل الغاية، بعد <g>εἰ</g>، <g>ἐάν</g>، <g>ἄν</g>، <g>ἵνα</g>، <g>ὅπως</g>: <r v=\"Matt.10.14\"></r>، <r v=\"Mark.6.11\"></r> <r v=\"Mark.12.19\"></r>، <r v=\"Luke.9.5\"></r>، <r v=\"John.6.50\"></r>، <r v=\"Rom.11.25\"></r>، وفي مواضع أخرى.</s> <s n=\"4.\">مع المصدر، <s n=\"(a)\">بعد أفعال القول ونحوها: <r v=\"Matt.2.12\"></r> <r v=\"Matt.5.34\"></r>، <r v=\"Mark.12.18\"></r>، <r v=\"Acts.15.38\"></r>، <r v=\"Rom.2.21\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">مع المصدر المعرَّف بالأداة: بعد حرف جر، <r v=\"Matt.13.5\"></r>، <r v=\"Mark.4.5\"></r>، <r v=\"Acts.7.19\"></r>، <r v=\"1Cor.10.6\"></r>، وفي مواضع أخرى؛ وبدون حرف جر، <r v=\"Rom.14.13\"></r>، <r v=\"2Cor.2.1\"></r>، <r v=\"2Cor.1.13\"></r>، <r v=\"1Thess.4.6\"></r>؛</s> <s n=\"(c)\">في الجمل الدالة على النتيجة، بعد <g>ὥστε</g>: <r v=\"Matt.8.28\"></r>، <r v=\"Mark.3.20\"></r>، <r v=\"1Cor.1.7\"></r>، <r v=\"2Cor.3.7\"></r>، وفي مواضع أخرى.</s> </s> <s n=\"5.\">مع اسم الفاعل، في الإشارة الافتراضية إلى أشخاص من صفة أو نوع معيَّن: <r v=\"Matt.10.28\"></r> <r v=\"Matt.12.30\"></r>، <r v=\"Luke.6.49\"></r>، <r v=\"John.3.18\"></r>، <r v=\"Rom.4.5\"></r>، <r v=\"1Cor.7.38\"></r>، <r v=\"1John.3.10\"></r>، وفي مواضع أخرى؛ وحيث يكون الشخص أو الشيء محدَّدًا فيكون النفي مسألة رأي: <r v=\"John.6.64\"></r>، <r v=\"1Cor.1.28\"></r> <r v=\"1Cor.4.7\"></r>، <r v=\"1Cor.4.18\"></r>، <r v=\"2Cor.5.21\"></r>، وفي مواضع أخرى؛ وحيث يحمل اسم الفاعل معنى التنازل أو السببية أو الشرط: <b>إن لم</b>، <b>مع أنه لا</b>، <b>لأنه لا</b>: <r v=\"Matt.18.25\"></r>، <r v=\"Luke.2.45\"></r>، <r v=\"John.7.49\"></r>، <r v=\"Acts.9.26\"></r>، <r v=\"Rom.2.14\"></r> <r v=\"Rom.5.13\"></r>، <r v=\"2Cor.3.14\"></r>، <r v=\"Gal.6.9\"></r>، <r v=\"Jude.1.5\"></r>؛ وحيث يكون لاسم الفاعل معنى وصفي (<i>كونه على حال كذا</i>): <b>لا، غير</b>: <r v=\"Acts.9.9\"></r>، <r v=\"Rom.1.28\"></r>، <r v=\"1Cor.10.33\"></r>، <r v=\"Gal.4.8\"></r>، <r v=\"Heb.12.27\"></r>، وفي مواضع أخرى.</s> <s n=\"6.\"><g>μή</g> الناهية، في الجمل المستقلة، <s n=\"(a)\">مع صيغة الاحتمال المضارعة، للمتكلم الجمع: <r v=\"Gal.5.26\"></r> <r v=\"Gal.6.9\"></r>، <r v=\"1Thess.5.6\"></r>، <r v=\"1John.3.18\"></r>؛</s> <s n=\"(b)\">مع الأمر المضارع، غالبًا حيث يُطلب من المرء الكف عما قد بدأه فعلاً: <r v=\"Matt.7.1\"></r>، <r v=\"Mark.5.36\"></r>، <r v=\"Luke.6.30\"></r>، <r v=\"John.2.16\"></r> <r v=\"John.5.45\"></r>، <r v=\"Acts.10.15\"></r>، <r v=\"Rom.11.18\"></r>، <r v=\"Jas.2.1\"></r>، <r v=\"Rev.5.5\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">في النهي عما لم يقع بعد: مع الأمر في الماضي البسيط، للغائب، <r v=\"Matt.24.18\"></r>، <r v=\"Mark.13.15\"></r>، <r v=\"Luke.17.31\"></r>، وفي مواضع أخرى؛ ومع صيغة الاحتمال في الماضي البسيط، للمخاطب، <r v=\"Matt.3.9\"></r> <r v=\"Matt.10.26\"></r>، <r v=\"Mark.5.7\"></r>، <r v=\"Luke.6.29\"></r>، <r v=\"John.3.7\"></r>، <r v=\"Rom.10.6\"></r>، وفي مواضع أخرى؛</s> <s n=\"(d)\">مع صيغة التمني، في الأمنيات: <r v=\"2Tim.4.16\"></r><i>(السبعينية)</i>؛ <g>μὴ γένοιτο</g>، <r v=\"Luke.20.16\"></r>، <r v=\"Rom.3.3\"></r>، وفي مواضع أخرى؛ <g>μή τις</g>، <r v=\"Mark.13.5\"></r>، وفي مواضع أخرى.</s> </s> </s> <s n=\"II.\">بوصفها أداة ربط، <s n=\"1.\">بعد أفعال الخوف والحذر ونحوها: <b>أن</b>، <b>لئلا</b>، <b>لعل</b>: مع صيغة الاحتمال المضارعة، <r v=\"Heb.12.15\"></r>؛ مع صيغة الاحتمال في الماضي البسيط، <r v=\"Matt.24.4\"></r>، <r v=\"Mark.13.5\"></r>، <r v=\"Luke.21.8\"></r>، <r v=\"Acts.13.40\"></r>، <r v=\"Gal.5.15\"></r>، وفي مواضع أخرى؛ <g>ὅρα μή</g> على الحذف، <r v=\"Rev.19.10\"></r> <r v=\"Rev.22.9\"></r>؛ مع الإخباري المستقبل، <r v=\"Col.2.8\"></r>.</s> <s n=\"2.\"><b>لكي لا</b>: مع صيغة الاحتمال في الماضي البسيط، <r v=\"Mark.13.36\"></r>، <r v=\"2Cor.8.20\"></r> <r v=\"2Cor.12.6\"></r>.</s> </s> <s n=\"III.\">استفهامية، في الأسئلة المتردِّدة، أو حيث يُنتظر جواب بالنفي: <r v=\"Matt.7.9\"></r>، <r v=\"Matt.7.10\"></r>، <r v=\"Mark.2.19\"></r>، <r v=\"John.3.4\"></r>، <r v=\"Rom.3.3\"></r> <r v=\"Rom.10.18\"></r>، <r v=\"Rom.10.19\"></r>، <r v=\"1Cor.1.13\"></r>، وفي مواضع أخرى؛ <g>μή τις</g>، <r v=\"Luke.22.35\"></r>، وفي مواضع أخرى؛ ويليها <g>οὐ</g> (<r v=\"Rom.10.17\"></r>، وفي مواضع أخرى عند بولس) حيث يُنتظر جواب بالإثبات؛ <g>οὐ μή</g>، <r v=\"Luke.18.7\"></r>، <r v=\"John.18.11\"></r>.</s> <s n=\"IV.\"><g>οὐ μή</g> للنفي المؤكَّد: <b>لا البتة</b>، <b>بأي حال من الأحوال</b>: مع الإخباري المستقبل، <r v=\"Matt.16.22\"></r>، <r v=\"John.6.35\"></r>، <r v=\"Heb.10.17\"></r>، وفي مواضع أخرى؛ مع صيغة الاحتمال في الماضي البسيط، <r v=\"Matt.24.2\"></r>، <r v=\"Mark.13.2\"></r>، <r v=\"Luke.6.37\"></r>، <r v=\"John.13.8\"></r>، <r v=\"1Cor.8.13\"></r>، وفي مواضع أخرى.</s> </s>"},"G3417":{"l":"μνεία","o":7,"en":"<f><o>μνεία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>μιμνήσκω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H2142\">זכר</h>, its parts and derivatives;]</e> </et> <s><b>remembrance</b>, <b>mention</b> (= <g>μνήμη</g>): <r v=\"Phil.1.3\"></r>; <g>μ. ποιεῖσθαι</g>, c. gen. pers., <r v=\"Rom.1.9\"></r>, <r v=\"Eph.1.16\"></r>, <r v=\"1Thess.1.2\"></r>, <r v=\"Phlm.1.4\"></r> (cf. <r v=\"Ps.111.4\"></r>); <g>μ. ἔχειν</g>, c. gen. pers., <r v=\"1Thess.3.6\"></r>, <r v=\"2Tim.1.3\"></r> (on the v.l. in <r v=\"Rom.12.13\"></r>, v. <i>ICC</i>, in l.; Field, <i>Notes</i>, 163).†</s>","ar":"<f><o>μνεία</o>، <g>-ας, ἡ</g></f> <s><b>ذِكر، تذكُّر</b>، <b>إشارة إلى</b> (= <g>μνήμη</g>): <r v=\"Phil.1.3\"></r>؛ <g>μ. ποιεῖσθαι</g> (يذكر)، مع المضاف إليه للأشخاص، <r v=\"Rom.1.9\"></r>، <r v=\"Eph.1.16\"></r>، <r v=\"1Thess.1.2\"></r>، <r v=\"Phlm.1.4\"></r> (قارن <r v=\"Ps.111.4\"></r>)؛ <g>μ. ἔχειν</g> (يحفظ ذكرى)، مع المضاف إليه للأشخاص، <r v=\"1Thess.3.6\"></r>، <r v=\"2Tim.1.3\"></r> (وعن القراءة المختلفة في <r v=\"Rom.12.13\"></r>).†</s>"},"G3450":{"l":"ἐγώ","o":2572,"en":"<f><o>ἐγώ</o>, gen, etc., <g>ἐμοῦ, ἐμοί, ἐμέ</g> (enclitic <g>μου, μοι, με</g>), pl. <g>ἡμεῖς, -ῶν, -ῖν, -ᾶς</g>, </f> pers. pron. <s><b>I</b>. <s n=\"(a)\">The nom. is usually emphatic, when expressed as subjc, as in <r v=\"Matt.3.11\"></r>, <r v=\"Mark.1.8\"></r>, <r v=\"Luke.3.16\"></r>, al. But often there is no apparent emphasis, as <r v=\"Matt.10.16\"></r>, <r v=\"John.10.17\"></r>; <g>ἰδοὺ ἐ.</g> (= Heb. <h n=\"H2005\">הִנֵּנִי</h>, cf. <r v=\"1Kgs.3.8\"></r>), <r v=\"Acts.9.10\"></r>; <g>ἐ.</g> (like Heb. <h n=\"H589\">אֲנִי</h>), <b>I am</b>, <r v=\"John.1.23\"></r>, <r v=\"Acts.7.32\"></r>. </s> <s n=\"(b)\">The enclitic forms (v. supr.) are used with nouns, adjectives, verbs, adverbs, where there is no emphasis: <g>ἐν τ. πατρί μου</g>, <r v=\"John.14.20\"></r>; <g>μου τ. λόγους</g>, <r v=\"Matt.7.24\"></r>; <g>ὀπίσω μου</g>, <r v=\"Matt.3.11\"></r>; <g>ἰσχυρότερός μου</g>, <r v=\"Matt.3.11\"></r>; <g>λέγει μοι</g>, <r v=\"Rev.5.5\"></r>; also with the prep. <g>πρός</g>, as <r v=\"Mark.9.19\"></r>, al. The full forms (<g>ἐμοῦ</g>, etc.) are used with the other prepositions, as <g>δι' ἐμοῦ, ἐν ἐμοί, εἰς ἐμέ</g>, etc., also for emphasis, as <r v=\"Luke.10.16\"></r>, <r v=\"John.7.23\"></r>, <r v=\"Mark.14.7\"></r>, al. </s> <s n=\"(c)\">The gen. <g>μου</g> and <g>ἡμῶν</g> are often used for the poss. pronouns <g>ἐμός, ἡμέτερος: τ. λαόν μου</g>, <r v=\"Matt.2.6\"></r>; <g>μου τῂ ἀπιστιᾳ</g>, <r v=\"Mark.9.24\"></r>. </s> <s n=\"(d)\"><g>τί ἐμοὶ καὶ σοί</g> ( = Heb. <h n=\"H4100\">וָלָךְ מַה־לִי</h>, <r v=\"Judg.11.12\"></r>, al.), i.e. <b>what have we in common</b>: <r v=\"Matt.8.29\"></r>, <r v=\"Mark.1.24\"></r> <r v=\"Mark.5.7\"></r>, <r v=\"Luke.8.28\"></r>, <r v=\"John.2.4\"></r>; <g>τί γάρ μοι</g>, <r v=\"1Cor.5.2\"></r>. </s> <s n=\"(e)\">The interchange of <g>ἐγώ</g> and <g>ἡμεῖς</g>, common in <g>π.</g>, appears in Pauline Epp. (v. M, <i>Pr.</i>, 86f., M, <i>Th.</i>, 131f.).</s> <s n=\"(f)\"><g>κἀγώ</g> (= <g>καὶ ἐγώ</g>, <b>and I, even I, I also</b>: <r v=\"Matt.2.8\"></r>, <r v=\"Luke.2.48\"></r>, <r v=\"John.6.56\"></r>, <r v=\"Rom.3.7\"></r>, <r v=\"1Cor.7.40\"></r>, al.; <g>κἀγώ . . . καί</g>, <b>both . . . and</b>, <r v=\"John.7.28\"></r>.</s> </s>","ar":"<f><o>ἐγώ</o>، حالة الجر إلخ: <g>ἐμοῦ, ἐμοί, ἐμέ</g> (الملحقة: <g>μου, μοι, με</g>)، الجمع: <g>ἡμεῖς, -ῶν, -ῖν, -ᾶς</g>، </f> ضمير شخصي. <s><b>أنا</b>. <s n=\"(a)\">حالة الرفع تفيد التوكيد عادةً حين تُذكر فاعلاً، كما في <r v=\"Matt.3.11\"></r>، <r v=\"Mark.1.8\"></r>، <r v=\"Luke.3.16\"></r>، وفي مواضع أخرى. لكن كثيرًا ما لا يظهر توكيد، كما في <r v=\"Matt.10.16\"></r>، <r v=\"John.10.17\"></r>؛ <g>ἰδοὺ ἐ.</g> (هأنذا) (= بالعبرية <h n=\"H2005\">הִנֵּנִי</h>، قارن <r v=\"1Kgs.3.8\"></r>)، <r v=\"Acts.9.10\"></r>؛ <g>ἐ.</g> (مثل العبرية <h n=\"H589\">אֲנִי</h>): <b>أنا هو</b>، <r v=\"John.1.23\"></r>، <r v=\"Acts.7.32\"></r>. </s> <s n=\"(b)\">تُستعمل الصيغ الملحقة (انظر أعلاه) مع الأسماء والصفات والأفعال والظروف حيث لا توكيد: <g>ἐν τ. πατρί μου</g> (في أبي)، <r v=\"John.14.20\"></r>؛ <g>μου τ. λόγους</g> (أقوالي)، <r v=\"Matt.7.24\"></r>؛ <g>ὀπίσω μου</g> (بعدي)، <r v=\"Matt.3.11\"></r>؛ <g>ἰσχυρότερός μου</g> (أقوى مني)، <r v=\"Matt.3.11\"></r>؛ <g>λέγει μοι</g> (قال لي)، <r v=\"Rev.5.5\"></r>؛ وكذلك مع حرف الجر <g>πρός</g>، كما في <r v=\"Mark.9.19\"></r>، وفي مواضع أخرى. وتُستعمل الصيغ الكاملة (<g>ἐμοῦ</g> إلخ) مع سائر حروف الجر، مثل <g>δι' ἐμοῦ, ἐν ἐμοί, εἰς ἐμέ</g> إلخ، وكذلك للتوكيد، كما في <r v=\"Luke.10.16\"></r>، <r v=\"John.7.23\"></r>، <r v=\"Mark.14.7\"></r>، وفي مواضع أخرى. </s> <s n=\"(c)\">كثيرًا ما تُستعمل حالة الجر <g>μου</g> و<g>ἡμῶν</g> بدل ضميري الملكية <g>ἐμός, ἡμέτερος: τ. λαόν μου</g> (شعبي)، <r v=\"Matt.2.6\"></r>؛ <g>μου τῂ ἀπιστιᾳ</g> (عدم إيماني)، <r v=\"Mark.9.24\"></r>. </s> <s n=\"(d)\"><g>τί ἐμοὶ καὶ σοί</g> ( = بالعبرية <h n=\"H4100\">וָלָךְ מַה־לִי</h>، <r v=\"Judg.11.12\"></r>، وفي مواضع أخرى)، أي <b>ما لي ولك، ما الذي يجمعنا</b>: <r v=\"Matt.8.29\"></r>، <r v=\"Mark.1.24\"></r> <r v=\"Mark.5.7\"></r>، <r v=\"Luke.8.28\"></r>، <r v=\"John.2.4\"></r>؛ <g>τί γάρ μοι</g> (ماذا لي)، <r v=\"1Cor.5.2\"></r>. </s> <s n=\"(e)\">التبادل بين <g>ἐγώ</g> و<g>ἡμεῖς</g> يظهر في رسائل بولس.</s> <s n=\"(f)\"><g>κἀγώ</g> (= <g>καὶ ἐγώ</g>): <b>وأنا، حتى أنا، أنا أيضًا</b>: <r v=\"Matt.2.8\"></r>، <r v=\"Luke.2.48\"></r>، <r v=\"John.6.56\"></r>، <r v=\"Rom.3.7\"></r>، <r v=\"1Cor.7.40\"></r>، وفي مواضع أخرى؛ <g>κἀγώ . . . καί</g>: <b>كلٌّ من . . . و</b>، <r v=\"John.7.28\"></r>.</s> </s>"},"G3483":{"l":"ναί","o":33,"en":"<f><o>ναί</o>,</f> particle of affirmation, <s><b>yea</b>, <b>verily</b>, <b>even so</b>; in answer to a question: <r v=\"Matt.9.28\"></r> <r v=\"Matt.13.51\"></r> <r v=\"Matt.17.25\"></r> <r v=\"Matt.21.16\"></r>, <r v=\"John.11.27\"></r> <r v=\"John.21.15\"></r>, <r v=\"John.21.16\"></r>, <r v=\"Acts.5.8\"></r> <r v=\"Acts.22.27\"></r>, <r v=\"Rom.3.29\"></r>; seq. <g>λέγω ὑμῖν</g>, <r v=\"Matt.11.9\"></r>, <r v=\"Luke.7.26\"></r>; repeated for emphasis, <g>ναὶ ναί</g> (opp. to <g>οὒ</g> <g>οὔ</g>): <r v=\"Matt.5.37\"></r>; <g>ἤτω ὑμῶν τὸ ναὶ ναί</g>, <r v=\"Jas.5.12\"></r>; <g>ν. καὶ οὔ</g>, <r v=\"2Cor.1.18\"></r>, <r v=\"2Cor.1.19\"></r>; <g>ἵνα ᾖ . . . τὸ ναὶ ναί</g>, <r v=\"2Cor.1.17\"></r>; <g>τὸ ν.</g>, <r v=\"2Cor.1.20\"></r>; in assent to an assertion: <r v=\"Matt.15.27\"></r>, <r v=\"Mark.7.28\"></r>, <r v=\"Rev.14.13\"></r> <r v=\"Rev.16.7\"></r>; in confirmation of a previous assertion: <r v=\"Matt.11.26\"></r>, <r v=\"Luke.10.21\"></r> <r v=\"Luke.11.51\"></r> <r v=\"Luke.12.5\"></r>, <r v=\"Phil.4.3\"></r>, <r v=\"Phlm.1.20\"></r>; in solemn asseveration: <r v=\"Rev.1.7\"></r> <r v=\"Rev.22.20\"></r>.†</s>","ar":"<f><o>ναί</o>،</f> أداة إثبات، <s><b>نعم</b>، <b>حقًّا</b>، <b>هكذا</b>؛ جوابًا عن سؤال: <r v=\"Matt.9.28\"></r> <r v=\"Matt.13.51\"></r> <r v=\"Matt.17.25\"></r> <r v=\"Matt.21.16\"></r>، <r v=\"John.11.27\"></r> <r v=\"John.21.15\"></r>، <r v=\"John.21.16\"></r>، <r v=\"Acts.5.8\"></r> <r v=\"Acts.22.27\"></r>، <r v=\"Rom.3.29\"></r>؛ يليه <g>λέγω ὑμῖν</g>، <r v=\"Matt.11.9\"></r>، <r v=\"Luke.7.26\"></r>؛ مكررًا للتوكيد، <g>ναὶ ναί</g> (عكس <g>οὒ</g> <g>οὔ</g>): <r v=\"Matt.5.37\"></r>؛ <g>ἤτω ὑμῶν τὸ ναὶ ναί</g>، <r v=\"Jas.5.12\"></r>؛ <g>ν. καὶ οὔ</g>، <r v=\"2Cor.1.18\"></r>، <r v=\"2Cor.1.19\"></r>؛ <g>ἵνα ᾖ . . . τὸ ναὶ ναί</g>، <r v=\"2Cor.1.17\"></r>؛ <g>τὸ ν.</g>، <r v=\"2Cor.1.20\"></r>؛ موافقةً على قول: <r v=\"Matt.15.27\"></r>، <r v=\"Mark.7.28\"></r>، <r v=\"Rev.14.13\"></r> <r v=\"Rev.16.7\"></r>؛ تأكيدًا لقول سابق: <r v=\"Matt.11.26\"></r>، <r v=\"Luke.10.21\"></r> <r v=\"Luke.11.51\"></r> <r v=\"Luke.12.5\"></r>، <r v=\"Phil.4.3\"></r>، <r v=\"Phlm.1.20\"></r>؛ في التوكيد الرسمي (القسَم): <r v=\"Rev.1.7\"></r> <r v=\"Rev.22.20\"></r>.†</s>"},"G3570":{"l":"νυνί","o":20,"en":"<f><o>νυνί</o>, an Attic strengthened form of <g>νῦν</g></f> <et> <e t=\"derivation\">(in cl. always of time, and most often strictly of the pres.),</e> <e t=\"septuagint\">[in LXX : Jb<i>5</i>, Pss<i>2</i>, II, IV Mac<i>4</i>, Ep. Je.*;]</e> </et> <s><b>now</b>; <s n=\"1.\">of time: c. praes., <r v=\"Acts.24.13\"></r>, <r v=\"Rom.15.23\"></r>, <r v=\"Rom.15.25\"></r>, <r v=\"1Cor.13.13\"></r>, <r v=\"2Cor.8.11\"></r>, <r v=\"2Cor.8.22\"></r>, <r v=\"Phlm.1.9\"></r>, <r v=\"Phlm.1.11\"></r>; c. pf., <r v=\"Rom.3.21\"></r>; c. pret., <r v=\"Rom.6.22\"></r> <r v=\"Rom.11.30\"></r> (WH, mg.) <r v=\"Rom.7.6\"></r>, <r v=\"Eph.2.13\"></r>, <r v=\"Col.1.21\"></r> <r v=\"Col.3.8\"></r>; <g>ἡ ν. ἀπολογία</g>, <r v=\"Acts.22.1\"></r>.</s> <s n=\"2.\">Of logical sequence (not so in cl.): <r v=\"Rom.7.17\"></r>, <r v=\"1Cor.5.11\"></r> (<g>νῦν</g>, WH) <r v=\"1Cor.12.18\"></r> (<g>νῦν</g>, WH, txt.) <r v=\"1Cor.15.20\"></r>, <r v=\"Heb.8.6\"></r> (<g>νῦν</g>, WH, txt.), <r v=\"Heb.9.26\"></r> (cf. WM, 24, 579<i>n</i>).†</s> </s>","ar":"<f><o>νυνί</o>، صيغة أتيكية مقوّاة من <g>νῦν</g></f> <s><b>الآن</b>؛ <s n=\"1.\">عن الزمان: مع المضارع، <r v=\"Acts.24.13\"></r>، <r v=\"Rom.15.23\"></r>، <r v=\"Rom.15.25\"></r>، <r v=\"1Cor.13.13\"></r>، <r v=\"2Cor.8.11\"></r>، <r v=\"2Cor.8.22\"></r>، <r v=\"Phlm.1.9\"></r>، <r v=\"Phlm.1.11\"></r>؛ مع التام، <r v=\"Rom.3.21\"></r>؛ مع الماضي، <r v=\"Rom.6.22\"></r> <r v=\"Rom.11.30\"></r> <r v=\"Rom.7.6\"></r>، <r v=\"Eph.2.13\"></r>، <r v=\"Col.1.21\"></r> <r v=\"Col.3.8\"></r>؛ <g>ἡ ν. ἀπολογία</g>، <r v=\"Acts.22.1\"></r>.</s> <s n=\"2.\">عن التسلسل المنطقي: <r v=\"Rom.7.17\"></r>، <r v=\"1Cor.5.11\"></r> <r v=\"1Cor.12.18\"></r> <r v=\"1Cor.15.20\"></r>، <r v=\"Heb.8.6\"></r>، <r v=\"Heb.9.26\"></r>.†</s> </s>"},"G3578":{"l":"ξενία","o":2,"en":"<f>** <o>ξενία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ξένος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Sir.29.27\"></r> B<i>1</i>*;]</e> </et> <s><b>hospitality</b>, <b>entertainment</b>: <r v=\"Phlm.1.22\"></r> (cf. <i>ICC</i>, in l., but v. infr.). By meton., <b>a place of entertainment</b>, <b>a lodging-place</b>: <r v=\"Acts.28.23\"></r>, and so perh. <r v=\"Phlm.1.22\"></r> (Lft., in l., <i>Phl.</i>, p. 9; but v. supr., and cf. MM, xvii).†</s>","ar":"<f>** <o>ξενία</o>، <g>-ας, ἡ</g></f> <s><b>ضيافة</b>، <b>إكرام الضيف</b>: <r v=\"Phlm.1.22\"></r> (لكن انظر أدناه). وكنايةً: <b>مكان الضيافة</b>، <b>منزل، مقام</b>: <r v=\"Acts.28.23\"></r>، وربما كذلك في <r v=\"Phlm.1.22\"></r>.†</s>"},"G3624":{"l":"οἶκος","o":114,"en":"<f><o>οἶκος</o>, <g>-οῦ, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1004\">בַּיִת</h>, also for <h n=\"H1964\">הֵיכָל</h>, <h n=\"H168\">אֹהֶל</h>, etc.;]</e> </et> <s> <s n=\"1.\">prop., <b>a house</b>, <b>dwelling</b>: <r v=\"Acts.2.2\"></r> <r v=\"Acts.19.16\"></r>; c. gen. poss., <r v=\"Matt.9.6\"></r>, <r v=\"Matt.9.7\"></r>, <r v=\"Mark.2.11\"></r>, <r v=\"Luke.1.23\"></r>, al.; c. gen. attrib., <g>ἐμπορίου</g>, <r v=\"John.2.16\"></r>; <g>προσευχῆς</g>, <r v=\"Matt.21.13\"></r>, al.; of a sanctuary (Hdt., Eur.): <g>οἶ. τ. θεοῦ</g>, of the tabernacle, <r v=\"Matt.12.4\"></r>, al.; the temple, <r v=\"Matt.21.13\"></r>, al.; metaph. of a city: <r v=\"Matt.23.38\"></r>, <r v=\"Luke.13.35\"></r>; of the body, <r v=\"Matt.12.44\"></r>, <r v=\"Luke.11.24\"></r>; of Christians, <r v=\"1Pet.2.5\"></r>; <g>ἐν οἴ</g> (M, <i>Pr.</i>, 81 f.), <b>at home</b>, <r v=\"Mark.2.1\"></r>, <r v=\"1Cor.11.34\"></r> <r v=\"1Cor.14.35\"></r>; so <g>κατ’ οἶκον</g>, <r v=\"Acts.2.46\"></r> <r v=\"Acts.5.42\"></r>; <g>οἱ εἰς</g> (= <g>οἱ ἐν</g>; v.s. <g>εἰς</g>) <g>τ. οἶ.</g>, <r v=\"Luke.7.10\"></r> <r v=\"Luke.15.6\"></r>; <g>κατ’ οἴκους</g>, <b>from house to house</b>, <r v=\"Acts.8.3\"></r> <r v=\"Acts.20.20\"></r>; <g>εἰς</g> (<g>κατ’</g>) <g>οἶκον</g>, c. gen. (Bl., § 46, 9), <r v=\"Mark.8.3\"></r>, <r v=\"Luke.14.1\"></r>, <r v=\"Rom.16.5\"></r>, al.</s> <s n=\"2.\">By meton., <b>a house</b>, <b>household</b>, <b>family</b>: <r v=\"Luke.10.5\"></r>, <r v=\"Acts.7.10\"></r>, <r v=\"1Cor.1.16\"></r>, <r v=\"1Tim.3.4\"></r>, <r v=\"1Tim.3.5\"></r> al.; of the Church, <g>ὁ οἶ. τ. θεοῦ</g>, <r v=\"1Tim.3.15\"></r>, <r v=\"Heb.3.2\"></r>, <r v=\"1Pet.4.17\"></r>; of descendants, <g>οἶ Ἰσραήλ</g> (<g>Δαυείδ</g>, <g>Ἰακώβ</g>; Bl, § 47, 9), <r v=\"Matt.10.6\"></r>, <r v=\"Luke.1.27\"></r>, <r v=\"Luke.1.33\"></r>, al. (cf. <r v=\"Exod.6.14\"></r>, <r v=\"1Sam.2.30\"></r>, al.).</s> </s> <sy><i>SYN.</i>: v.s. <g>οἰκία</g>.</sy>","ar":"<f><o>οἶκος</o>، <g>-οῦ, ὁ</g>،</f> <s> <s n=\"1.\">بالمعنى الحرفي، <b>بيت</b>، <b>مسكن</b>: <r v=\"Acts.2.2\"></r> <r v=\"Acts.19.16\"></r>؛ مع المضاف إليه للملكية، <r v=\"Matt.9.6\"></r>، <r v=\"Matt.9.7\"></r>، <r v=\"Mark.2.11\"></r>، <r v=\"Luke.1.23\"></r>، وفي مواضع أخرى؛ مع المضاف إليه الوصفي، <g>ἐμπορίου</g>، <r v=\"John.2.16\"></r>؛ <g>προσευχῆς</g>، <r v=\"Matt.21.13\"></r>، وفي مواضع أخرى؛ عن المَقدِس: <g>οἶ. τ. θεοῦ</g>، عن خيمة الاجتماع، <r v=\"Matt.12.4\"></r>، وفي مواضع أخرى؛ الهيكل، <r v=\"Matt.21.13\"></r>، وفي مواضع أخرى؛ مجازيًا عن مدينة: <r v=\"Matt.23.38\"></r>، <r v=\"Luke.13.35\"></r>؛ عن الجسد، <r v=\"Matt.12.44\"></r>، <r v=\"Luke.11.24\"></r>؛ عن المسيحيين، <r v=\"1Pet.2.5\"></r>؛ <g>ἐν οἴ</g>، <b>في البيت</b>، <r v=\"Mark.2.1\"></r>، <r v=\"1Cor.11.34\"></r> <r v=\"1Cor.14.35\"></r>؛ وكذلك <g>κατ’ οἶκον</g>، <r v=\"Acts.2.46\"></r> <r v=\"Acts.5.42\"></r>؛ <g>οἱ εἰς</g> (= <g>οἱ ἐν</g>؛ انظر تحت مدخل <g>εἰς</g>) <g>τ. οἶ.</g>، <r v=\"Luke.7.10\"></r> <r v=\"Luke.15.6\"></r>؛ <g>κατ’ οἴκους</g>، <b>من بيت إلى بيت</b>، <r v=\"Acts.8.3\"></r> <r v=\"Acts.20.20\"></r>؛ <g>εἰς</g> (<g>κατ’</g>) <g>οἶκον</g>، مع المضاف إليه، <r v=\"Mark.8.3\"></r>، <r v=\"Luke.14.1\"></r>، <r v=\"Rom.16.5\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\">كنايةً، <b>بيت</b>، <b>أهل البيت</b>، <b>عائلة</b>: <r v=\"Luke.10.5\"></r>، <r v=\"Acts.7.10\"></r>، <r v=\"1Cor.1.16\"></r>، <r v=\"1Tim.3.4\"></r>، <r v=\"1Tim.3.5\"></r> وفي مواضع أخرى؛ عن الكنيسة، <g>ὁ οἶ. τ. θεοῦ</g>، <r v=\"1Tim.3.15\"></r>، <r v=\"Heb.3.2\"></r>، <r v=\"1Pet.4.17\"></r>؛ عن النسل، <g>οἶ Ἰσραήλ</g> (<g>Δαυείδ</g>، <g>Ἰακώβ</g>)، <r v=\"Matt.10.6\"></r>، <r v=\"Luke.1.27\"></r>، <r v=\"Luke.1.33\"></r>، وفي مواضع أخرى (قارن <r v=\"Exod.6.14\"></r>، <r v=\"1Sam.2.30\"></r>، وفي مواضع أخرى).</s> </s>"},"G3682":{"l":"Ὀνήσιμος","o":2,"en":"<f><o>Ὀνήσιμος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(i.e. <i>profitable</i>, &lt; <g>ὄνησις</g>, <i>profit</i>),</e> </et> <s><b>Onesimus</b>: <r v=\"Col.4.9\"></r>, <r v=\"Phlm.1.10\"></r> (a common name among slaves; v. MM, iii, xviii).†</s>","ar":"<f><o>Ὀνήσιμος</o>، <g>-ου, ὁ</g></f> <s><b>أُنسيمس</b>: <r v=\"Col.4.9\"></r>، <r v=\"Phlm.1.10\"></r> (اسم شائع بين العبيد).†</s>"},"G3685":{"l":"ὀνίνημι","o":1,"en":"<f>** <o>ὀνίνημι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Tob.3.8\"></r>, <r v=\"Sir.30.2\"></r>*;]</e> </et> <s><b>to profit</b>, <b>benefit</b>, <b>help</b>; mid., <b>to have profit</b>, <b>derive benefit</b>: optat. (M, <i>Pr.</i>, 195), c. gen., <r v=\"Phlm.1.20\"></r>.†</s>","ar":"<f>** <o>ὀνίνημι</o>،</f> <s><b>ينفع</b>، <b>يفيد</b>، <b>يُعين</b>؛ الصيغة الوسطى، <b>ينتفع</b>، <b>يستفيد</b>: صيغة التمني، مع المضاف إليه، <r v=\"Phlm.1.20\"></r>.†</s>"},"G373":{"l":"ἀναπαύω","o":12,"en":"<f><o>ἀνα-παύω</o>,</f> <et> <e t=\"septuagint\">[in LXX for fourteen different words, chiefly <h n=\"H5117\">נוּחַ</h>, also <h n=\"H7257\">רָבַץ</h>, <h n=\"H7599\">שָׁאַן</h>, etc.;],</e> </et> <s><b>to give intermission from labour</b>, <b>to give rest</b>, <b>refresh</b>: <r v=\"Matt.11.28\"></r>, <r v=\"1Cor.16.18\"></r>, <r v=\"Phlm.1.20\"></r>; pass., <r v=\"Phlm.1.7\"></r>, <r v=\"2Cor.7.13\"></r>. Mid., <b>to ta</b>, <b> rest, enjoy rest</b>: <r v=\"Matt.26.45\"></r>, <r v=\"Mark.6.31\"></r> <r v=\"Mark.14.41\"></r>, <r v=\"Luke.12.19\"></r>, <r v=\"Rev.6.11\"></r> <r v=\"Rev.14.13\"></r>; as in <i>Heb.</i> of <r v=\"Isa.11.2\"></r> (<h n=\"H5117,H5921\">נוּחַ עַל</h>), <g>τὸ πνεῦμα ἐφ</g>' <g>ὑμᾶς ἀ.</g>, <r v=\"1Pet.4.14\"></r>. (In <g>π.</g> this word is used as a technical agricultural term; v. MM, <i>VGT</i>, s.v.; and cf. <r v=\"Lev.26.34\"></r> f.; Cremer, 826.)†</s>","ar":"<f><o>ἀνα-παύω</o>،</f> <s><b>أعطى فترة راحة من التعب</b>، <b>أراح</b>، <b>أنعش</b>: <r v=\"Matt.11.28\"></r>، <r v=\"1Cor.16.18\"></r>، <r v=\"Phlm.1.20\"></r>؛ المبني للمجهول: <r v=\"Phlm.1.7\"></r>، <r v=\"2Cor.7.13\"></r>. الصيغة الوسطى: <b>استراح</b>، <b> نال الراحة، تمتع بالراحة</b>: <r v=\"Matt.26.45\"></r>، <r v=\"Mark.6.31\"></r>، <r v=\"Mark.14.41\"></r>، <r v=\"Luke.12.19\"></r>، <r v=\"Rev.6.11\"></r>، <r v=\"Rev.14.13\"></r>؛ وكما في العبرية في <r v=\"Isa.11.2\"></r> (<h n=\"H5117,H5921\">נוּחַ עַל</h>)، <g>τὸ πνεῦμα ἐφ</g>' <g>ὑμᾶς ἀ.</g>: <r v=\"1Pet.4.14\"></r>. (قارن <r v=\"Lev.26.34\"></r> وما يليه.)†</s>"},"G3739":{"l":"ὅς","o":1913,"en":"<f><o>ὅς</o>, <g>ἥ, ὅ</g>,</f> the postpositive article (<g>ἄρθρον ὑποτακτικόν</g>). <s n=\"I.\">As demonstr. pron. = <g>οὗτος</g>, <g>ὅδε</g>, <b>this</b>, <b>that</b>, also for <g>αὐτός</g>, chiefly in nom.: <g>ὅς δέ</g>, <b>but he</b> (cf. <g>ἦ δὲ ὅς</g>, freq. in Plat.), <r v=\"Mark.15.23\"></r>, <r v=\"John.5.11\"></r>; <g>ὃς μὲν . . . ὃς δέ</g>, <b>the one . . . the other</b>, <r v=\"Matt.21.35\"></r> <r v=\"Matt.22.5\"></r> <r v=\"Matt.25.15\"></r>, <r v=\"Luke.23.33\"></r>, <r v=\"Acts.27.14\"></r>, <r v=\"Rom.14.5\"></r>, <r v=\"1Cor.11.21\"></r>, <r v=\"2Cor.2.16\"></r>, <r v=\"Jude.1.22\"></r>; neut., <g>ὃ μὲν . . . ὃ δέ</g>, <b>the one . . . the other</b>, <b>some . . . some</b>, <r v=\"Matt.13.8\"></r>, <r v=\"Matt.13.23\"></r>, <r v=\"Rom.9.21\"></r>; <g>ὃς</g> (<g>ὃ</g>) <g>μὲν . . .</g> (<g>ἄλλος</g> (<g>ἄλλο</g>)) <g>. . . ἕτερος</g> (<g>-ο</g>), <r v=\"Mark.4.4\"></r>, <r v=\"Luke.8.5\"></r>, <r v=\"1Cor.12.8-1Cor.12.10\"></r>; <g>οὓς μέν</g>, absol., <r v=\"1Cor.12.28\"></r>; <g>ὃς μὲν . . . ὁ δέ</g>, <r v=\"Rom.14.2\"></r>.</s> <s n=\"II.\">As relat. pron., <b>who</b>, <b>which</b>, <b>what</b>, <b>that</b>; <s n=\"1.\">agreeing in gender with its antecedent, but differently governed as to case: <r v=\"Matt.2.9\"></r>, <r v=\"Luke.9.9\"></r>, <r v=\"Acts.20.18\"></r>, <r v=\"Rom.2.29\"></r>, al. mult.</s> <s n=\"2.\">In variation from the common construction; <s n=\"(a)\">in gender, agreeing with a noun in apposition to the antecedent: <r v=\"Mark.15.16\"></r>, <r v=\"Gal.3.16\"></r>, <r v=\"Eph.6.17\"></r>, al.; constr. ad sensum: <r v=\"John.6.9\"></r>, <r v=\"Col.2.19\"></r>, <r v=\"1Tim.3.16\"></r>, <r v=\"Rev.13.14\"></r>, al.;</s> <s n=\"(b)\">in number, constr. ad sensum: <r v=\"Acts.15.36\"></r>, <r v=\"2Pet.3.1\"></r>;</s> <s n=\"(c)\">in case, by attraction to the case of the antecedent (Bl., § 50, 2): <r v=\"John.4.18\"></r>, <r v=\"Acts.3.21\"></r>, <r v=\"Rom.15.18\"></r>, <r v=\"1Cor.6.19\"></r>, <r v=\"Eph.1.8\"></r>, al.</s> </s> <s n=\"3.\">The neut. <g>ὅ</g> with nouns of other gender and with phrases, <b>which thing</b>, <b>which term</b>: <r v=\"Mark.3.17\"></r> <r v=\"Mark.12.42\"></r>, <r v=\"John.1.39\"></r>, <r v=\"Col.3.14\"></r>, al.; with a sentence, <r v=\"Acts.2.32\"></r>, <r v=\"Gal.2.10\"></r>, <r v=\"1John.2.8\"></r>, al.</s> <s n=\"4.\">With ellipse of a demonstrative (<g>οὗτος</g> or <g>ἐκεῖνος</g>), before or after: before, <r v=\"Matt.20.23\"></r>, <r v=\"Luke.7.43\"></r>, <r v=\"Rom.10.14\"></r>, al.; after, <r v=\"Matt.10.38\"></r>, <r v=\"Mark.9.40\"></r>, <r v=\"John.19.22\"></r>, <r v=\"Rom.2.1\"></r> al.</s> <s n=\"5.\">Expressing purpose, end or cause: <r v=\"Matt.11.10\"></r> (<i>who = that he may</i>), <r v=\"Mark.1.2\"></r>, <r v=\"Heb.12.6\"></r> al.</s> <s n=\"6.\">C. prep. as periphrasis for conjc.: <g>ἀνθ’ ὧν</g> ( = <g>ἀντὶ τούτων ὧν</g>), <b>because</b>, <r v=\"Luke.1.20\"></r>, al.; <b>wherefore</b>, <r v=\"Luke.12.3\"></r>; <g>ἐφ’ ᾧ</g>, <b>since</b>, <b>for that</b>, <r v=\"Rom.5.12\"></r>; <g>ἀφ’ οὗ</g>, <b>since</b> (temporal), <r v=\"Luke.13.25\"></r>; <g>ἐξ οὗ</g>, <b>whence</b>, <r v=\"Phil.3.20\"></r>; etc.</s> <s n=\"7.\">With particles: <g>ὃς ἄν</g> (<g>ἐάν</g>), v.s. <g>ἄν</g>, <g>ἐάν</g>; <g>ὃς καί</g>, <r v=\"Mark.3.19\"></r>, <r v=\"John.21.20\"></r>, <r v=\"Rom.5.2\"></r>, al.; <g>ὃς καὶ αὐτός</g>, <r v=\"Matt.27.57\"></r>.</s> <s n=\"8.\">Gen., <g>οὗ</g>, absol., as adv. (v.s. <g>οὗ</g>).</s> </s>","ar":"<f><o>ὅς</o>، <g>ἥ, ὅ</g>،</f> أداة التعريف اللاحقة (<g>ἄρθρον ὑποτακτικόν</g>). <s n=\"I.\">بوصفه ضمير إشارة = <g>οὗτος</g>، <g>ὅδε</g>: <b>هذا</b>، <b>ذاك</b>، وأيضًا بدل <g>αὐτός</g>، غالبًا في حالة الرفع: <g>ὅς δέ</g>: <b>أما هو</b>، <r v=\"Mark.15.23\"></r>، <r v=\"John.5.11\"></r>؛ <g>ὃς μὲν . . . ὃς δέ</g>: <b>الواحد . . . والآخر</b>، <r v=\"Matt.21.35\"></r> <r v=\"Matt.22.5\"></r> <r v=\"Matt.25.15\"></r>، <r v=\"Luke.23.33\"></r>، <r v=\"Acts.27.14\"></r>، <r v=\"Rom.14.5\"></r>، <r v=\"1Cor.11.21\"></r>، <r v=\"2Cor.2.16\"></r>، <r v=\"Jude.1.22\"></r>؛ المحايد، <g>ὃ μὲν . . . ὃ δέ</g>: <b>الواحد . . . والآخر</b>، <b>بعضٌ . . . وبعضٌ</b>، <r v=\"Matt.13.8\"></r>، <r v=\"Matt.13.23\"></r>، <r v=\"Rom.9.21\"></r>؛ <g>ὃς</g> (<g>ὃ</g>) <g>μὲν . . .</g> (<g>ἄλλος</g> (<g>ἄλλο</g>)) <g>. . . ἕτερος</g> (<g>-ο</g>)، <r v=\"Mark.4.4\"></r>، <r v=\"Luke.8.5\"></r>، <r v=\"1Cor.12.8-1Cor.12.10\"></r>؛ <g>οὓς μέν</g>، مطلقًا، <r v=\"1Cor.12.28\"></r>؛ <g>ὃς μὲν . . . ὁ δέ</g>، <r v=\"Rom.14.2\"></r>.</s> <s n=\"II.\">بوصفه اسمًا موصولاً: <b>الذي</b>، <b>التي</b>، <b>ما</b>، <b>مَن</b>؛ <s n=\"1.\">مطابقًا لمرجعه في الجنس، ومختلفًا عنه في الحالة الإعرابية: <r v=\"Matt.2.9\"></r>، <r v=\"Luke.9.9\"></r>، <r v=\"Acts.20.18\"></r>، <r v=\"Rom.2.29\"></r>، وفي مواضع أخرى كثيرة.</s> <s n=\"2.\">خارجًا عن التركيب المعتاد؛ <s n=\"(a)\">في الجنس، مطابقًا لاسم في موضع البدل من المرجع: <r v=\"Mark.15.16\"></r>، <r v=\"Gal.3.16\"></r>، <r v=\"Eph.6.17\"></r>، وفي مواضع أخرى؛ ومراعاةً للمعنى: <r v=\"John.6.9\"></r>، <r v=\"Col.2.19\"></r>، <r v=\"1Tim.3.16\"></r>، <r v=\"Rev.13.14\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">في العدد، مراعاةً للمعنى: <r v=\"Acts.15.36\"></r>، <r v=\"2Pet.3.1\"></r>؛</s> <s n=\"(c)\">في الحالة الإعرابية، بالجذب إلى حالة المرجع: <r v=\"John.4.18\"></r>، <r v=\"Acts.3.21\"></r>، <r v=\"Rom.15.18\"></r>، <r v=\"1Cor.6.19\"></r>، <r v=\"Eph.1.8\"></r>، وفي مواضع أخرى.</s> </s> <s n=\"3.\">المحايد <g>ὅ</g> مع أسماء من جنس آخر ومع العبارات: <b>الأمر الذي</b>، <b>اللفظ الذي</b>: <r v=\"Mark.3.17\"></r> <r v=\"Mark.12.42\"></r>، <r v=\"John.1.39\"></r>، <r v=\"Col.3.14\"></r>، وفي مواضع أخرى؛ ومع جملة كاملة، <r v=\"Acts.2.32\"></r>، <r v=\"Gal.2.10\"></r>، <r v=\"1John.2.8\"></r>، وفي مواضع أخرى.</s> <s n=\"4.\">مع حذف اسم الإشارة (<g>οὗτος</g> أو <g>ἐκεῖνος</g>) قبله أو بعده: قبله، <r v=\"Matt.20.23\"></r>، <r v=\"Luke.7.43\"></r>، <r v=\"Rom.10.14\"></r>، وفي مواضع أخرى؛ بعده، <r v=\"Matt.10.38\"></r>، <r v=\"Mark.9.40\"></r>، <r v=\"John.19.22\"></r>، <r v=\"Rom.2.1\"></r>، وفي مواضع أخرى.</s> <s n=\"5.\">للدلالة على الغاية أو الهدف أو السبب: <r v=\"Matt.11.10\"></r> (<i>الذي = لكي</i>)، <r v=\"Mark.1.2\"></r>، <r v=\"Heb.12.6\"></r>، وفي مواضع أخرى.</s> <s n=\"6.\">مع حرف جر، تعبيرًا بديلاً عن أداة ربط: <g>ἀνθ’ ὧν</g> ( = <g>ἀντὶ τούτων ὧν</g>): <b>لأن</b>، <r v=\"Luke.1.20\"></r>، وفي مواضع أخرى؛ <b>لذلك</b>، <r v=\"Luke.12.3\"></r>؛ <g>ἐφ’ ᾧ</g>: <b>إذ</b>، <b>لأن</b>، <r v=\"Rom.5.12\"></r>؛ <g>ἀφ’ οὗ</g>: <b>منذ</b> (زمانيًا)، <r v=\"Luke.13.25\"></r>؛ <g>ἐξ οὗ</g>: <b>من حيث</b>، <r v=\"Phil.3.20\"></r>؛ إلخ.</s> <s n=\"7.\">مع الأدوات: <g>ὃς ἄν</g> (<g>ἐάν</g>)، انظر تحت مدخل <g>ἄν</g>، <g>ἐάν</g>؛ <g>ὃς καί</g>، <r v=\"Mark.3.19\"></r>، <r v=\"John.21.20\"></r>، <r v=\"Rom.5.2\"></r>، وفي مواضع أخرى؛ <g>ὃς καὶ αὐτός</g>، <r v=\"Matt.27.57\"></r>.</s> <s n=\"8.\">حالة الجر <g>οὗ</g>، مطلقًا، بوصفها ظرفًا (انظر تحت مدخل <g>οὗ</g>).</s> </s>"},"G375":{"l":"ἀναπέμπω","o":5,"en":"<f>* <o>ἀνα-πέμπω </o></f> <s n=\"1.\"><b>to send up</b>, <s n=\"(a)\">to a higher place (Æsch., Plat., al.); </s> <s n=\"(b)\">to a higher authority (Deiss., BS, 229; MM, <i>VGT</i>, s.v.; cf. also Field, <i>Notes</i>, 140): <r v=\"Luke.23.7\"></r>, <r v=\"Luke.23.15\"></r>, <r v=\"Acts.25.21\"></r>.</s> </s> <s n=\"2.\"><b>to send back</b> (Pind.): <r v=\"Luke.23.11\"></r>, <r v=\"Phlm.1.11\"></r>.†</s>","ar":"<f>* <o>ἀνα-πέμπω </o></f> <s n=\"1.\"><b>أرسل إلى فوق</b>، <s n=\"(a)\">إلى مكان أعلى؛ </s> <s n=\"(b)\">إلى سلطة أعلى: <r v=\"Luke.23.7\"></r>، <r v=\"Luke.23.15\"></r>، <r v=\"Acts.25.21\"></r>.</s> </s> <s n=\"2.\"><b>أعاد، ردّ</b>: <r v=\"Luke.23.11\"></r>، <r v=\"Phlm.1.11\"></r>.†</s>"},"G3762":{"l":"οὐδείς","o":234,"en":"<f><o>οὐδείς</o>, <g>-δεμία, -δέν</g> (also in WH, txt., the Hellenistic forms <g>-θείς, -θέν</g>, <r v=\"Luke.22.35\"></r> <r v=\"Luke.23.14\"></r>, <r v=\"Acts.15.9\"></r> <r v=\"Acts.19.27\"></r> <r v=\"Acts.19.26\"></r>, <r v=\"1Cor.13.2\"></r>, <r v=\"2Cor.11.8\"></r>; cf. Bl., § 6, 7; M, <i>Pr.</i>, 56<i>n</i>, Thackeray, <i>Gr.</i>, 58), related to <g>μηδείς</g> as <g>οὐ</g> to <g>μή</g>,</f> <s><b>no</b>, <b>no one</b>, <b>none</b>: with nouns, <r v=\"Luke.4.24\"></r>, <r v=\"John.10.41\"></r>, <r v=\"Rom.8.1\"></r>, al.; absol., <r v=\"Matt.6.24\"></r>, <r v=\"Mark.3.27\"></r>, <r v=\"Luke.1.61\"></r>, <r v=\"John.1.18\"></r>, <r v=\"Acts.18.10\"></r>, <r v=\"Rom.14.7\"></r>, al. mult.; c. gen. partit., <r v=\"Luke.4.26\"></r>, <r v=\"John.13.28\"></r>, al.; neut., <g>οὐδέν</g>, <r v=\"Matt.10.26\"></r>, al.; id. c. gen. partit., <r v=\"Luke.9.36\"></r>, <r v=\"Acts.18.17\"></r>, al.; <g>οὐδὲν εἰ μή</g>, <r v=\"Matt.5.13\"></r>, <r v=\"Mark.9.29\"></r>, al.; c. neg., strengthening the negation, <r v=\"Mark.15.4\"></r>, <r v=\"Mark.15.5\"></r>, <r v=\"Luke.4.2\"></r>, <r v=\"John.3.27\"></r>, al.; adverbially, <r v=\"Acts.25.10\"></r>, <r v=\"Gal.4.12\"></r>, al.</s>","ar":"<f><o>οὐδείς</o>، <g>-δεμία, -δέν</g> (وترد أيضًا الصيغتان اليونانيتان المتأخرتان <g>-θείς, -θέν</g>: <r v=\"Luke.22.35\"></r>، <r v=\"Luke.23.14\"></r>، <r v=\"Acts.15.9\"></r>، <r v=\"Acts.19.27\"></r>، <r v=\"Acts.19.26\"></r>، <r v=\"1Cor.13.2\"></r>، <r v=\"2Cor.11.8\"></r>)، وعلاقتها بـ<g>μηδείς</g> كعلاقة <g>οὐ</g> بـ<g>μή</g>،</f> <s><b>لا أحد</b>، <b>لا شيء</b>، <b>ولا واحد</b>: مع الأسماء: <r v=\"Luke.4.24\"></r>، <r v=\"John.10.41\"></r>، <r v=\"Rom.8.1\"></r>، وفي مواضع أخرى؛ مطلقًا: <r v=\"Matt.6.24\"></r>، <r v=\"Mark.3.27\"></r>، <r v=\"Luke.1.61\"></r>، <r v=\"John.1.18\"></r>، <r v=\"Acts.18.10\"></r>، <r v=\"Rom.14.7\"></r>، ومواضع أخرى كثيرة؛ مع المضاف إليه التبعيضي: <r v=\"Luke.4.26\"></r>، <r v=\"John.13.28\"></r>، وفي مواضع أخرى؛ المحايد <g>οὐδέν</g>: <r v=\"Matt.10.26\"></r>، وفي مواضع أخرى؛ ونفسه مع المضاف إليه التبعيضي: <r v=\"Luke.9.36\"></r>، <r v=\"Acts.18.17\"></r>، وفي مواضع أخرى؛ <g>οὐδὲν εἰ μή</g>: <r v=\"Matt.5.13\"></r>، <r v=\"Mark.9.29\"></r>، وفي مواضع أخرى؛ مع النفي، تقويةً له: <r v=\"Mark.15.4\"></r>، <r v=\"Mark.15.5\"></r>، <r v=\"Luke.4.2\"></r>، <r v=\"John.3.27\"></r>، وفي مواضع أخرى؛ ظرفيًا: <r v=\"Acts.25.10\"></r>، <r v=\"Gal.4.12\"></r>، وفي مواضع أخرى.</s>"},"G3765":{"l":"οὐκέτι","o":47,"en":"<f><o>οὐκέτι</o>,</f> neg. adv. of time, <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5750\">עוֹד</h> c. neg., <h n=\"H3808\">לֹא</h>, etc.;]</e> </et> <s><b>no longer</b>, <b>no more</b>: <r v=\"Matt.19.6\"></r>, <r v=\"Mark.10.8\"></r>, <r v=\"Luke.15.19\"></r>, <r v=\"John.4.42\"></r>, <r v=\"Rom.6.9\"></r>, <r v=\"Gal.3.25\"></r>, <r v=\"Eph.2.19\"></r>, <r v=\"Heb.10.18\"></r>, al.; c. neg. (to strengthen the negation), <r v=\"Matt.22.46\"></r>, <r v=\"Mark.5.3\"></r>, <r v=\"Acts.8.39\"></r>, al.</s>","ar":"<f><o>οὐκέτι</o>،</f> ظرف زمان منفي، <s><b>لم يَعُد</b>، <b>لا ... بعدُ</b>: <r v=\"Matt.19.6\"></r>، <r v=\"Mark.10.8\"></r>، <r v=\"Luke.15.19\"></r>، <r v=\"John.4.42\"></r>، <r v=\"Rom.6.9\"></r>، <r v=\"Gal.3.25\"></r>، <r v=\"Eph.2.19\"></r>، <r v=\"Heb.10.18\"></r>، وفي مواضع أخرى؛ مع النفي (لتقوية النفي)، <r v=\"Matt.22.46\"></r>، <r v=\"Mark.5.3\"></r>، <r v=\"Acts.8.39\"></r>، وفي مواضع أخرى.</s>"},"G3784":{"l":"ὀφείλω","o":35,"en":"<f><o>ὀφείλω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Deut.15.2\"></r>, <r v=\"Isa.24.2\"></r> (<h n=\"H5383\">נשׁה</h>, <h n=\"H5378\">נשׁא</h>), <r v=\"Ezek.18.7\"></r> (<h n=\"H2326\">חוב</h>), <r v=\"Wis.12.15\"></r>, <r v=\"Wis.12.20\"></r>, al.;]</e> </et> <s><b>to owe</b>, <b>be a debtor</b>: c. acc. rei, <r v=\"Matt.18.28\"></r>, <r v=\"Luke.7.41\"></r> <r v=\"Luke.16.7\"></r>, <r v=\"Phlm.1.18\"></r>; id. c. dat. pers., <r v=\"Matt.18.28\"></r>, <r v=\"Luke.16.5\"></r>. Pass., <b>to be owed</b>, <b>to be due</b>: <g>τ. ὀφειλόμενον</g>, <r v=\"Matt.18.30\"></r>, <r v=\"Matt.18.34\"></r>. Metaph.: absol. (= Rabbinic <h n=\"????\">חַיָּב</h>; v. McNeile, in l.), <r v=\"Matt.23.16\"></r>, <r v=\"Matt.23.18\"></r>; c. acc. rei et dat. pers., <r v=\"Rom.13.8\"></r>; c. inf., <b>to be bound</b> or <b>obliged</b> to do (of. Westc., <i>Epp. Jo.</i>, 50), <r v=\"Luke.17.10\"></r>, <r v=\"John.13.14\"></r> <r v=\"John.19.7\"></r>, <r v=\"Acts.17.29\"></r>, <r v=\"Rom.15.1\"></r>, <r v=\"Rom.15.27\"></r>, <r v=\"1Cor.5.10\"></r> <r v=\"1Cor.7.36\"></r> <r v=\"1Cor.9.10\"></r> <r v=\"1Cor.11.7\"></r>, <r v=\"1Cor.11.10\"></r>, <r v=\"2Cor.12.14\"></r>, <r v=\"Eph.5.28\"></r>, <r v=\"2Thess.1.3\"></r> <r v=\"2Thess.2.13\"></r>, <r v=\"Heb.2.17\"></r> <r v=\"Heb.5.3\"></r>, <r v=\"Heb.5.12\"></r>, <r v=\"1John.2.6\"></r> <r v=\"1John.3.16\"></r> <r v=\"1John.4.11\"></r>, <r v=\"3John.1.8\"></r>; <g>ὤφειλον συνίστασθαι</g>, <b>I ought to have been commended</b>, <r v=\"2Cor.12.11\"></r>. In peculiar Aram. sense of having wronged one (v.s. <g>ὀφείλημα</g>; but of. also Inscr. <g>ἁμαρτίαν ὀφείλω</g>, Deiss., <i>BS</i>, 225), c. dat. pers., <r v=\"Luke.11.4\"></r> (cf. <g>προσ-οφείλω</g>).†</s>","ar":"<f><o>ὀφείλω</o>،</f> <s><b>يَدين بـ (عليه دَين)</b>، <b>يكون مديونًا</b>: مع المنصوب للأشياء، <r v=\"Matt.18.28\"></r>، <r v=\"Luke.7.41\"></r> <r v=\"Luke.16.7\"></r>، <r v=\"Phlm.1.18\"></r>؛ والتعبير نفسه مع القابل للأشخاص، <r v=\"Matt.18.28\"></r>، <r v=\"Luke.16.5\"></r>. المبني للمجهول: <b>يكون مستحَقًّا</b>، <b>يكون واجب الأداء</b>: <g>τ. ὀφειλόμενον</g> (ما هو مستحق)، <r v=\"Matt.18.30\"></r>، <r v=\"Matt.18.34\"></r>. مجازيًا: مطلقًا (= الربّينية <h n=\"????\">חַיָּב</h>، أي «ملتزم، مُلزَم»)، <r v=\"Matt.23.16\"></r>، <r v=\"Matt.23.18\"></r>؛ مع المنصوب للأشياء والقابل للأشخاص، <r v=\"Rom.13.8\"></r>؛ مع المصدر: <b>يجب عليه</b> أو <b>يلتزم</b> بأن يفعل، <r v=\"Luke.17.10\"></r>، <r v=\"John.13.14\"></r> <r v=\"John.19.7\"></r>، <r v=\"Acts.17.29\"></r>، <r v=\"Rom.15.1\"></r>، <r v=\"Rom.15.27\"></r>، <r v=\"1Cor.5.10\"></r> <r v=\"1Cor.7.36\"></r> <r v=\"1Cor.9.10\"></r> <r v=\"1Cor.11.7\"></r>، <r v=\"1Cor.11.10\"></r>، <r v=\"2Cor.12.14\"></r>، <r v=\"Eph.5.28\"></r>، <r v=\"2Thess.1.3\"></r> <r v=\"2Thess.2.13\"></r>، <r v=\"Heb.2.17\"></r> <r v=\"Heb.5.3\"></r>، <r v=\"Heb.5.12\"></r>، <r v=\"1John.2.6\"></r> <r v=\"1John.3.16\"></r> <r v=\"1John.4.11\"></r>، <r v=\"3John.1.8\"></r>؛ <g>ὤφειλον συνίστασθαι</g>: <b>كان ينبغي أن أُمدَح</b>، <r v=\"2Cor.12.11\"></r>. وبالمعنى الآرامي الخاص: أن يكون المرء قد أساء إلى غيره (انظر تحت مدخل <g>ὀφείλημα</g>)، مع القابل للأشخاص، <r v=\"Luke.11.4\"></r> (قارن <g>προσ-οφείλω</g>).†</s>"},"G3842":{"l":"πάντοτε","o":41,"en":"<f>** <o>πάντοτε</o>,</f> adv. of time <et> <e t=\"derivation\">(&lt; <g>πᾶς</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.11.21\"></r> <r v=\"Wis.19.18\"></r>*;]</e> <e t=\"derivation\">in late writers (once in Arist.) for <g>διαπαντός</g>, <g>ἑκάστοτε</g>,</e> </et> <s><b>at all times</b>, <b>always</b>: <r v=\"Matt.26.11\"></r>, <r v=\"Mark.14.7\"></r>, <r v=\"Luke.15.31\"></r>, <r v=\"John.6.34\"></r>, <r v=\"Rom.1.10\"></r>, and freq. in Paul. Epp.</s>","ar":"<f>** <o>πάντοτε</o>،</f> ظرف زمان <s><b>في كل حين</b>، <b>دائمًا</b>: <r v=\"Matt.26.11\"></r>، <r v=\"Mark.14.7\"></r>، <r v=\"Luke.15.31\"></r>، <r v=\"John.6.34\"></r>، <r v=\"Rom.1.10\"></r>، وكثيرًا في رسائل بولس.</s>"},"G3870":{"l":"παρακαλέω","o":109,"en":"<f><o>παρα-καλέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5162\">נחם</h> ni., pi.;]</e> </et> <s> <s n=\"1.\"><b>to call to</b> one, <b>call for</b>, <b>summon</b>: <r v=\"Acts.28.20\"></r> (R, mg.; R, txt., <i>entreat</i>); hence (of the gods: Dem., Xen., al.), <b>to invoke</b>, <b>call on</b>, <b>beseech</b>, <b>entreat</b>: <g>τ. πατέρα μου</g>, <r v=\"Matt.26.53\"></r>; <g>τ. κύριον</g>, <r v=\"2Cor.12.8\"></r>; in late writers (Polyb., Diod., al.; rarely in LXX; in <g>π.</g>, v. Deiss., <i>LAE</i>, 176<i>14</i>), also of men: absol., <r v=\"Phlm.1.9\"></r>; c. acc., <r v=\"Matt.8.5\"></r>, <r v=\"Mark.1.40\"></r>, <r v=\"Acts.16.9\"></r>, al.; c. inf., <r v=\"Mark.5.17\"></r>, <r v=\"Luke.8.41\"></r>, <r v=\"Acts.8.31\"></r>, al.; seq. <g>ἵνα</g> (v. M, <i>Pr.</i>, 205, 208), <r v=\"Matt.14.36\"></r>, <r v=\"Mark.5.18\"></r>, <r v=\"Luke.8.31\"></r>, al.</s> <s n=\"2.\"><b>to admonish</b>, <b>exhort</b>: absol., <r v=\"Luke.3.18\"></r>, <r v=\"Rom.12.8\"></r>, <r v=\"2Tim.4.2\"></r>, al.; c. acc., <r v=\"Acts.15.32\"></r>, <r v=\"1Thess.2.11\"></r>, <r v=\"Heb.3.13\"></r>, al.; id. seq. inf., <r v=\"Acts.11.23\"></r>, <r v=\"Rom.12.1\"></r>, <r v=\"Phil.4.2\"></r>, <r v=\"1Thess.4.10\"></r>, al.; seq. <g>ἵνα</g> (v. M, <i>Pr.</i>, 205, 208), <r v=\"1Cor.1.10\"></r>, <r v=\"2Cor.8.6\"></r>, <r v=\"1Thess.4.1\"></r>, al.</s> <s n=\"3.\"><b>to cheer</b>, <b>encourage</b>, <b>comfort</b> (Plut., LXX: <r v=\"Job.4.3\"></r>, <r v=\"Isa.35.3\"></r>, <r v=\"Sir.43.24\"></r>, al.): c. acc., <r v=\"2Cor.1.6\"></r>, <r v=\"Eph.6.22\"></r>, <r v=\"Col.2.2\"></r>, al.; id. seq. <g>ἐν</g>, <r v=\"1Thess.4.18\"></r>; <g>διά</g>, <r v=\"2Cor.1.4\"></r>; pass., <r v=\"Matt.5.4\"></r>, <r v=\"Luke.16.25\"></r>, <r v=\"Acts.20.12\"></r>.</s> </s> <sy><i>SYN.</i>: <g>παραμυθέω</g> (cf. M, <i>Th.</i>, 25).</sy>","ar":"<f><o>παρα-καλέω</o>، <g>-ῶ</g>،</f> <s> <s n=\"1.\"><b>يدعو</b> إليه، <b>يستدعي</b>، <b>يطلب حضور</b>: <r v=\"Acts.28.20\"></r>؛ ومن ثم <b>يستغيث بـ</b>، <b>يدعو</b>، <b>يتوسل</b>، <b>يطلب</b>: <g>τ. πατέρα μου</g>، <r v=\"Matt.26.53\"></r>؛ <g>τ. κύριον</g>، <r v=\"2Cor.12.8\"></r>؛ وفي الكتابات المتأخرة يُقال أيضًا عن البشر: مطلقًا، <r v=\"Phlm.1.9\"></r>؛ مع المنصوب، <r v=\"Matt.8.5\"></r>، <r v=\"Mark.1.40\"></r>، <r v=\"Acts.16.9\"></r>، وفي مواضع أخرى؛ مع المصدر، <r v=\"Mark.5.17\"></r>، <r v=\"Luke.8.41\"></r>، <r v=\"Acts.8.31\"></r>، وفي مواضع أخرى؛ يليه <g>ἵνα</g>، <r v=\"Matt.14.36\"></r>، <r v=\"Mark.5.18\"></r>، <r v=\"Luke.8.31\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\"><b>يَعِظ</b>، <b>يحثّ</b>: مطلقًا، <r v=\"Luke.3.18\"></r>، <r v=\"Rom.12.8\"></r>، <r v=\"2Tim.4.2\"></r>، وفي مواضع أخرى؛ مع المنصوب، <r v=\"Acts.15.32\"></r>، <r v=\"1Thess.2.11\"></r>، <r v=\"Heb.3.13\"></r>، وفي مواضع أخرى؛ والتعبير نفسه يليه المصدر، <r v=\"Acts.11.23\"></r>، <r v=\"Rom.12.1\"></r>، <r v=\"Phil.4.2\"></r>، <r v=\"1Thess.4.10\"></r>، وفي مواضع أخرى؛ يليه <g>ἵνα</g>، <r v=\"1Cor.1.10\"></r>، <r v=\"2Cor.8.6\"></r>، <r v=\"1Thess.4.1\"></r>، وفي مواضع أخرى.</s> <s n=\"3.\"><b>يُشجِّع</b>، <b>يُشدِّد</b>، <b>يُعزّي</b> (السبعينية: <r v=\"Job.4.3\"></r>، <r v=\"Isa.35.3\"></r>، <r v=\"Sir.43.24\"></r>، وفي مواضع أخرى): مع المنصوب، <r v=\"2Cor.1.6\"></r>، <r v=\"Eph.6.22\"></r>، <r v=\"Col.2.2\"></r>، وفي مواضع أخرى؛ والتعبير نفسه يليه <g>ἐν</g>، <r v=\"1Thess.4.18\"></r>؛ <g>διά</g>، <r v=\"2Cor.1.4\"></r>؛ المبني للمجهول، <r v=\"Matt.5.4\"></r>، <r v=\"Luke.16.25\"></r>، <r v=\"Acts.20.12\"></r>.</s> </s>"},"G3874":{"l":"παράκλησις","o":29,"en":"<f><o>παρά-κλησις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>παρακαλέω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Job.21.2\"></r>, <r v=\"Ps.94.19\"></r>, <r v=\"Hos.13.14\"></r>, <r v=\"Nah.3.7\"></r>, <r v=\"Isa.57.18\"></r> <r v=\"Isa.66.11\"></r>, <r v=\"Jer.16.7\"></r> (<h n=\"H5162\">נחם</h>, its parts and derivatives), <r v=\"Jer.31.9\"></r> (<h n=\"H8469\">תַּחֲנוּן</h>), <r v=\"Isa.28.29\"></r> <r v=\"Isa.30.7\"></r>, <r v=\"1Macc.10.24\"></r> <r v=\"1Macc.12.9\"></r>, <r v=\"2Macc.7.24\"></r> <r v=\"2Macc.15.11\"></r>*;]</e> </et> <s n=\"1.\"><b>a calling to one's aid</b>, <b>summons</b> (Thus.), hence, <b>appeal</b>, <b>entreaty</b> (Strab., Plut., al., <r v=\"1Macc.10.24\"></r>; cf. Lft., <i>Notes</i>, 20): <r v=\"2Cor.8.4\"></r>.</s> <s n=\"2.\"><b>exhortation</b>, <b>encouragement</b>: <r v=\"Acts.15.31\"></r>, <r v=\"Rom.12.8\"></r>, <r v=\"1Cor.14.3\"></r>, <r v=\"2Cor.8.17\"></r>, <r v=\"Phil.2.1\"></r>, <r v=\"1Thess.2.3\"></r>, <r v=\"1Tim.4.13\"></r>, <r v=\"Heb.12.5\"></r>; <g>λόγος</g> (<g>τῆς</g>) <g>π.</g>, <r v=\"Acts.13.15\"></r>, <r v=\"Heb.13.22\"></r>; <g>υἱὸς π.</g>, <r v=\"Acts.4.36\"></r>.</s> <s n=\"3.\"><b>consolation</b>, <b>comfort</b> (Phalar., LXX): <r v=\"Luke.6.24\"></r>, <r v=\"Acts.9.31\"></r>, <r v=\"2Cor.1.4-2Cor.1.7\"></r> <r v=\"2Cor.7.4\"></r>, <r v=\"2Cor.7.7\"></r>, <r v=\"2Cor.7.13\"></r>, <r v=\"2Thess.2.16\"></r>, <r v=\"Phlm.1.7\"></r>; <g>τ. γραφῶν</g>, <r v=\"Rom.15.4\"></r>; <g>θεὸς τῆς π.</g>, <r v=\"Rom.15.5\"></r>, <r v=\"2Cor.1.3\"></r>; <g>π. τοῦ Ἰσραήλ</g> (v. Dalman, <i>Words</i>, 109 f.), <r v=\"Luke.2.25\"></r>.†</s>","ar":"<f><o>παρά-κλησις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\"><b>استدعاء أحد للعون</b>، <b>دعوة</b>، ومن هنا <b>التماس</b>، <b>توسّل</b> (قارن <r v=\"1Macc.10.24\"></r>): <r v=\"2Cor.8.4\"></r>.</s> <s n=\"2.\"><b>وعظ، حثّ</b>، <b>تشجيع</b>: <r v=\"Acts.15.31\"></r>، <r v=\"Rom.12.8\"></r>، <r v=\"1Cor.14.3\"></r>، <r v=\"2Cor.8.17\"></r>، <r v=\"Phil.2.1\"></r>، <r v=\"1Thess.2.3\"></r>، <r v=\"1Tim.4.13\"></r>، <r v=\"Heb.12.5\"></r>؛ <g>λόγος</g> (<g>τῆς</g>) <g>π.</g>: <r v=\"Acts.13.15\"></r>، <r v=\"Heb.13.22\"></r>؛ <g>υἱὸς π.</g>: <r v=\"Acts.4.36\"></r>.</s> <s n=\"3.\"><b>تعزية</b>، <b>عزاء</b>: <r v=\"Luke.6.24\"></r>، <r v=\"Acts.9.31\"></r>، <r v=\"2Cor.1.4-2Cor.1.7\"></r>، <r v=\"2Cor.7.4\"></r>، <r v=\"2Cor.7.7\"></r>، <r v=\"2Cor.7.13\"></r>، <r v=\"2Thess.2.16\"></r>، <r v=\"Phlm.1.7\"></r>؛ <g>τ. γραφῶν</g>: <r v=\"Rom.15.4\"></r>؛ <g>θεὸς τῆς π.</g>: <r v=\"Rom.15.5\"></r>، <r v=\"2Cor.1.3\"></r>؛ <g>π. τοῦ Ἰσραήλ</g>: <r v=\"Luke.2.25\"></r>.†</s>"},"G3954":{"l":"παρρησία","o":31,"en":"<f><o>παρρησία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πᾶς</g> + <g>ῥῆσις</g>, <i>speech</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Lev.26.13\"></r> (<g>μετὰ π.</g>, <h n=\"H6968\">קוֹמְמִיּוּת</h>), <r v=\"Prov.1.20\"></r> <r v=\"Prov.10.10\"></r>, <r v=\"Wis.5.1\"></r>, al.;]</e> </et> <s n=\"1.\"><b>freedom of speech</b>, <b>plainness</b>, <b>openness</b>, <b>freedom</b> in speaking (Eur., Plat., al.): <r v=\"Acts.4.13\"></r>, <r v=\"2Cor.3.12\"></r>; <g>παρρησίᾳ</g>, adverbially, <b>freely</b>, <b>openly</b>, <b>plainly</b>, <r v=\"Mark.8.32\"></r>, <r v=\"John.7.13\"></r>, <r v=\"John.7.26\"></r> <r v=\"John.10.24\"></r> <r v=\"John.11.14\"></r> <r v=\"John.16.29\"></r> <r v=\"John.18.20\"></r>; opp. to <g>ἐν παροιμίαις</g>, <r v=\"John.16.25\"></r>; <g>ἐν π.</g>, <r v=\"Eph.6.19\"></r>; <g>μετὰ π.</g>, <r v=\"Acts.2.29\"></r> <r v=\"Acts.4.29\"></r>, <r v=\"Acts.4.31\"></r> <r v=\"Acts.28.31\"></r>.</s> <s n=\"2.\">In LXX (<r v=\"1Macc.4.18\"></r>, <r v=\"Wis.5.1\"></r>, al.), FlJ, and NT, also (from the absence of fear which accompanies freedom of speech), <b>confidence</b>, <b>boldness</b>: <r v=\"2Cor.7.4\"></r>, <r v=\"Phil.1.20\"></r>, <r v=\"1Tim.3.13\"></r>; <g>ἔχειν π.</g>, <r v=\"Eph.3.12\"></r>, <r v=\"Phlm.1.8\"></r>, <r v=\"Heb.3.6\"></r> <r v=\"Heb.10.19\"></r>, <r v=\"Heb.10.35\"></r>, <r v=\"1John.2.28\"></r> <r v=\"1John.3.21\"></r> <r v=\"1John.4.17\"></r> <r v=\"1John.5.14\"></r>; <g>μετὰ π.</g>, <r v=\"Heb.4.16\"></r>; <g>ἐν π.</g>, <r v=\"Col.2.15\"></r>; id. (as <h n=\"????\">בפרהסיא</h> in Rabbinic lit.; v. Westc., <i>Jo.</i>, i, 262), <b>in public</b>, <r v=\"John.7.4\"></r> and (without <g>ἐν</g>) <r v=\"John.11.54\"></r>.†</s>","ar":"<f><o>παρρησία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\"><b>حرية الكلام</b>، <b>صراحة</b>، <b>وضوح</b>، <b>جهارة</b> في الكلام: <r v=\"Acts.4.13\"></r>، <r v=\"2Cor.3.12\"></r>؛ <g>παρρησίᾳ</g> ظرفيًا: <b>بحرية</b>، <b>علانيةً</b>، <b>جهارًا</b>: <r v=\"Mark.8.32\"></r>، <r v=\"John.7.13\"></r>، <r v=\"John.7.26\"></r>، <r v=\"John.10.24\"></r>، <r v=\"John.11.14\"></r>، <r v=\"John.16.29\"></r>، <r v=\"John.18.20\"></r>؛ عكس <g>ἐν παροιμίαις</g>: <r v=\"John.16.25\"></r>؛ <g>ἐν π.</g>: <r v=\"Eph.6.19\"></r>؛ <g>μετὰ π.</g>: <r v=\"Acts.2.29\"></r>، <r v=\"Acts.4.29\"></r>، <r v=\"Acts.4.31\"></r>، <r v=\"Acts.28.31\"></r>.</s> <s n=\"2.\">وفي السبعينية (<r v=\"1Macc.4.18\"></r>، <r v=\"Wis.5.1\"></r>، وفي مواضع أخرى) والعهد الجديد أيضًا (لغياب الخوف المصاحب لحرية الكلام): <b>ثقة</b>، <b>جرأة، مجاهرة</b>: <r v=\"2Cor.7.4\"></r>، <r v=\"Phil.1.20\"></r>، <r v=\"1Tim.3.13\"></r>؛ <g>ἔχειν π.</g>: <r v=\"Eph.3.12\"></r>، <r v=\"Phlm.1.8\"></r>، <r v=\"Heb.3.6\"></r>، <r v=\"Heb.10.19\"></r>، <r v=\"Heb.10.35\"></r>، <r v=\"1John.2.28\"></r>، <r v=\"1John.3.21\"></r>، <r v=\"1John.4.17\"></r>، <r v=\"1John.5.14\"></r>؛ <g>μετὰ π.</g>: <r v=\"Heb.4.16\"></r>؛ <g>ἐν π.</g>: <r v=\"Col.2.15\"></r>؛ ونفسه (مثل <h n=\"????\">בפרהסיא</h> في الأدب الربّاني): <b>علانيةً، أمام الناس</b>: <r v=\"John.7.4\"></r> و(بدون <g>ἐν</g>) <r v=\"John.11.54\"></r>.†</s>"},"G3956":{"l":"πᾶς","o":1361,"en":"<f><o>πᾶς</o>, <g>πᾶσα, πᾶν</g>, gen., <g>παντός, πάσης, παντός</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3605\">כֹּל</h>;]</e> </et> <s><b>all</b>, <b>every</b>. <s n=\"I.\">As adj., <s n=\"1.\">c. subst. anarth., <b>all</b>, <b>every</b>, <b>of every kind</b>: <r v=\"Matt.3.10\"></r> <r v=\"Matt.4.23\"></r>, <r v=\"Mark.9.49\"></r>, <r v=\"Luke.4.37\"></r>, <r v=\"John.2.10\"></r>, <r v=\"Acts.27.20\"></r>, <r v=\"Rom.7.8\"></r>, <r v=\"Rev.18.17\"></r>, al. mult.; pl., <b>all</b>, <r v=\"Acts.22.15\"></r>, <r v=\"Rom.5.12\"></r>, <r v=\"Heb.1.6\"></r>, al.; of the highest degree, <g>π. ἐξουσία</g> (<g>προθυμία</g>, <g>χαρά</g>), <r v=\"Matt.28.18\"></r>, <r v=\"Acts.17.11\"></r>, <r v=\"Phil.2.29\"></r>, al.; also <b>the whole</b> (though in this sense more freq. c. art.), <r v=\"Matt.2.3\"></r>, <r v=\"Acts.2.36\"></r>, <r v=\"Rom.11.26\"></r>.</s> <s n=\"2.\">C. art. (before the art., after the noun, or, denoting totality, between the art. and noun), <b>all</b>, <b>whole</b>: <r v=\"Matt.8.32\"></r> <r v=\"Matt.13.2\"></r>, <r v=\"Mark.5.33\"></r>, <r v=\"Luke.1.10\"></r>, <r v=\"Acts.7.14\"></r>, <r v=\"Rom.3.19\"></r>, <r v=\"Gal.5.14\"></r>, <r v=\"Eph.4.16\"></r>, al.; pl., <r v=\"Matt.2.4\"></r>, <r v=\"Mark.4.13\"></r>, <r v=\"Rom.1.5\"></r>, al.</s> </s> <s n=\"II.\">As pron., <s n=\"1.\">masc. and fem., <b>every one</b>: <r v=\"Mark.9.49\"></r>, <r v=\"Luke.16.16\"></r>, <r v=\"Heb.2.9\"></r>; seq. rel. pron., <r v=\"Matt.7.24\"></r>, <r v=\"Acts.2.21\"></r>, <r v=\"Gal.3.10\"></r>, al.; c. ptcp. (anarth.), <r v=\"Matt.13.19\"></r>, <r v=\"Luke.11.4\"></r>; c. ptcp. (c. art.), <r v=\"Matt.5.22\"></r>, <r v=\"Mark.7.8\"></r>, <r v=\"Luke.6.47\"></r>, <r v=\"John.3.8\"></r>, <r v=\"Rom.1.16\"></r>, al.; pl., <g>πάντες</g>, absol., <b>all</b>, <b>all men</b>, <r v=\"Matt.10.22\"></r>, <r v=\"Mark.13.13\"></r>, <r v=\"Luke.20.38\"></r>, <r v=\"John.1.7\"></r> <r v=\"John.3.26\"></r>, <r v=\"1Cor.8.1\"></r>, al.; <g>οἱ π.</g> (collectively, as a definite whole), <r v=\"Rom.11.32\"></r>, <r v=\"1Cor.1.17\"></r>, <r v=\"Eph.4.13\"></r>, al.; <g>π. οἱ</g> (<g>ὅσοι</g>), <r v=\"Matt.4.24\"></r>, <r v=\"Mark.1.32\"></r>, <r v=\"Luke.4.40\"></r>, al.</s> <s n=\"2.\">Neut., <s n=\"(a)\">sing., <g>πᾶν</g>, <b>everything</b>, <b>all</b>: <g>πᾶν τό</g>, c. ptcp., <r v=\"1Cor.10.25\"></r>, <r v=\"1Cor.10.27\"></r>, <r v=\"Eph.5.13\"></r>, <r v=\"1John.2.16\"></r> <r v=\"1John.5.4\"></r> (sc. <g>ὄν</g>); <g>πᾶν ὅ</g>, <r v=\"John.17.2\"></r>, <r v=\"Rom.14.23\"></r>; collectively, of persons (Westc., in l.), <r v=\"John.6.37\"></r>, <r v=\"John.6.39\"></r>; c. prep., in adverbial phrases, <g>διὰ παντός</g>, <b>always</b>, <r v=\"Matt.18.10\"></r>, al.; <g>ἐν παντί</g>, <b>in everything</b>, <b>in every way</b>, <r v=\"2Cor.4.8\"></r>, <r v=\"Phil.4.6\"></r>, al.;</s> <s n=\"(b)\">pl., <g>πάτνα</g>, <b>all things</b>: absol., <r v=\"John.1.3\"></r>, <r v=\"1Cor.2.10\"></r>, <r v=\"Heb.2.8\"></r>, al.; of certain specified things, <r v=\"Mark.4.34\"></r>, <r v=\"Luke.1.3\"></r>, <r v=\"Rom.8.28\"></r>, <r v=\"1Thess.5.21\"></r>, al.; acc., <g>πάντα</g>, adverbially, <b>wholly</b>, <b>in all things</b>, <b>in all respects</b>, <r v=\"Acts.20.35\"></r>, <r v=\"1Cor.9.25\"></r>, al.; c. art., <g>τὰ π.</g>, <b>all things</b> (a totality, as distinct from anarth. <g>πάντα</g>, all things severally; cf. Westc., <i>Eph.</i>, 186 f.), absol.: <r v=\"Rom.11.36\"></r>, <r v=\"1Cor.8.6\"></r>, <r v=\"Eph.3.9\"></r>, <r v=\"Heb.1.3\"></r>, al.; relatively, <r v=\"Mark.4.11\"></r>, <r v=\"Acts.17.25\"></r>, <r v=\"Rom.8.32\"></r>, al.; <g>πάντα τά</g>, c. ptcp., <r v=\"Matt.18.31\"></r>, al.; <g>πάντα ταῦτα</g> (<g>ταῦτα π.</g>), <r v=\"Matt.6.32\"></r>, <r v=\"Matt.6.33\"></r>, al.; <g>πάντα</g>, c. prep, in adverbial phrases, <g>πρὸ πάντων</g>, <b>above all things</b>, <r v=\"Jas.5.12\"></r>, <r v=\"1Pet.4.8\"></r>; <g>ἐν π.</g>, <b>in all things</b>, <b>in all ways</b>, <r v=\"1Tim.3.11\"></r>, <r v=\"1Pet.4.11\"></r>, al.; <g>κατὰ πάντα</g>, <b>in all respects</b>, <r v=\"Acts.17.22\"></r>, al.</s> </s> <s n=\"3.\">C. neg., <g>πᾶς οὐ</g> (<g>μή</g>) = <g>οὐδείς</g>, v.s. <g>οὐ</g> and <g>μή</g>, and cf. M, <i>Pr.</i>, 245 f.</s> </s> </s>","ar":"<f><o>πᾶς</o>، <g>πᾶσα, πᾶν</g>، المضاف إليه: <g>παντός, πάσης, παντός</g>،</f> <s><b>كل، جميع</b>. <s n=\"I.\">صفةً، <s n=\"1.\">مع اسم بدون أداة التعريف: <b>كل</b>، <b>جميع</b>، <b>من كل نوع</b>: <r v=\"Matt.3.10\"></r>، <r v=\"Matt.4.23\"></r>، <r v=\"Mark.9.49\"></r>، <r v=\"Luke.4.37\"></r>، <r v=\"John.2.10\"></r>، <r v=\"Acts.27.20\"></r>، <r v=\"Rom.7.8\"></r>، <r v=\"Rev.18.17\"></r>، ومواضع أخرى كثيرة؛ في الجمع: <b>جميع</b>: <r v=\"Acts.22.15\"></r>، <r v=\"Rom.5.12\"></r>، <r v=\"Heb.1.6\"></r>، وفي مواضع أخرى؛ للدلالة على أعلى درجة: <g>π. ἐξουσία</g> (<g>προθυμία</g>، <g>χαρά</g>): <r v=\"Matt.28.18\"></r>، <r v=\"Acts.17.11\"></r>، <r v=\"Phil.2.29\"></r>، وفي مواضع أخرى؛ وأيضًا <b>كل</b> الشيء أي <b>بأسره</b> (وإن كان هذا المعنى أكثر مع أداة التعريف): <r v=\"Matt.2.3\"></r>، <r v=\"Acts.2.36\"></r>، <r v=\"Rom.11.26\"></r>.</s> <s n=\"2.\">مع أداة التعريف (قبل الأداة، أو بعد الاسم، أو بين الأداة والاسم للدلالة على الكلية): <b>كل</b>، <b>كامل، بأسره</b>: <r v=\"Matt.8.32\"></r>، <r v=\"Matt.13.2\"></r>، <r v=\"Mark.5.33\"></r>، <r v=\"Luke.1.10\"></r>، <r v=\"Acts.7.14\"></r>، <r v=\"Rom.3.19\"></r>، <r v=\"Gal.5.14\"></r>، <r v=\"Eph.4.16\"></r>، وفي مواضع أخرى؛ في الجمع: <r v=\"Matt.2.4\"></r>، <r v=\"Mark.4.13\"></r>، <r v=\"Rom.1.5\"></r>، وفي مواضع أخرى.</s> </s> <s n=\"II.\">ضميرًا، <s n=\"1.\">في المذكر والمؤنث: <b>كل واحد</b>: <r v=\"Mark.9.49\"></r>، <r v=\"Luke.16.16\"></r>، <r v=\"Heb.2.9\"></r>؛ يليه ضمير موصول: <r v=\"Matt.7.24\"></r>، <r v=\"Acts.2.21\"></r>، <r v=\"Gal.3.10\"></r>، وفي مواضع أخرى؛ مع اسم الفاعل (بدون أداة التعريف): <r v=\"Matt.13.19\"></r>، <r v=\"Luke.11.4\"></r>؛ مع اسم الفاعل (مع أداة التعريف): <r v=\"Matt.5.22\"></r>، <r v=\"Mark.7.8\"></r>، <r v=\"Luke.6.47\"></r>، <r v=\"John.3.8\"></r>، <r v=\"Rom.1.16\"></r>، وفي مواضع أخرى؛ في الجمع، <g>πάντες</g>، مطلقًا: <b>الجميع</b>، <b>جميع الناس</b>: <r v=\"Matt.10.22\"></r>، <r v=\"Mark.13.13\"></r>، <r v=\"Luke.20.38\"></r>، <r v=\"John.1.7\"></r>، <r v=\"John.3.26\"></r>، <r v=\"1Cor.8.1\"></r>، وفي مواضع أخرى؛ <g>οἱ π.</g> (جماعيًا، بوصفهم كُلًّا محددًا): <r v=\"Rom.11.32\"></r>، <r v=\"1Cor.1.17\"></r>، <r v=\"Eph.4.13\"></r>، وفي مواضع أخرى؛ <g>π. οἱ</g> (<g>ὅσοι</g>): <r v=\"Matt.4.24\"></r>، <r v=\"Mark.1.32\"></r>، <r v=\"Luke.4.40\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\">في المحايد، <s n=\"(a)\">المفرد، <g>πᾶν</g>: <b>كل شيء</b>، <b>الكل</b>: <g>πᾶν τό</g> مع اسم الفاعل: <r v=\"1Cor.10.25\"></r>، <r v=\"1Cor.10.27\"></r>، <r v=\"Eph.5.13\"></r>، <r v=\"1John.2.16\"></r>، <r v=\"1John.5.4\"></r> (أي بتقدير <g>ὄν</g>)؛ <g>πᾶν ὅ</g>: <r v=\"John.17.2\"></r>، <r v=\"Rom.14.23\"></r>؛ جماعيًا عن الأشخاص: <r v=\"John.6.37\"></r>، <r v=\"John.6.39\"></r>؛ مع حرف جر في عبارات ظرفية: <g>διὰ παντός</g>: <b>دائمًا</b>: <r v=\"Matt.18.10\"></r>، وفي مواضع أخرى؛ <g>ἐν παντί</g>: <b>في كل شيء</b>، <b>بكل طريقة</b>: <r v=\"2Cor.4.8\"></r>، <r v=\"Phil.4.6\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">الجمع، <g>πάτνα</g>: <b>كل الأشياء</b>: مطلقًا: <r v=\"John.1.3\"></r>، <r v=\"1Cor.2.10\"></r>، <r v=\"Heb.2.8\"></r>، وفي مواضع أخرى؛ عن أشياء معيّنة: <r v=\"Mark.4.34\"></r>، <r v=\"Luke.1.3\"></r>، <r v=\"Rom.8.28\"></r>، <r v=\"1Thess.5.21\"></r>، وفي مواضع أخرى؛ في حالة النصب، <g>πάντα</g>، ظرفيًا: <b>تمامًا</b>، <b>في كل شيء</b>، <b>من كل وجه</b>: <r v=\"Acts.20.35\"></r>، <r v=\"1Cor.9.25\"></r>، وفي مواضع أخرى؛ مع أداة التعريف، <g>τὰ π.</g>: <b>كل الأشياء</b> (بوصفها كُلًّا واحدًا، تمييزًا عن <g>πάντα</g> بدون أداة التعريف أي كل الأشياء آحادًا)، مطلقًا: <r v=\"Rom.11.36\"></r>، <r v=\"1Cor.8.6\"></r>، <r v=\"Eph.3.9\"></r>، <r v=\"Heb.1.3\"></r>، وفي مواضع أخرى؛ نسبيًا: <r v=\"Mark.4.11\"></r>، <r v=\"Acts.17.25\"></r>، <r v=\"Rom.8.32\"></r>، وفي مواضع أخرى؛ <g>πάντα τά</g> مع اسم الفاعل: <r v=\"Matt.18.31\"></r>، وفي مواضع أخرى؛ <g>πάντα ταῦτα</g> (<g>ταῦτα π.</g>): <r v=\"Matt.6.32\"></r>، <r v=\"Matt.6.33\"></r>، وفي مواضع أخرى؛ <g>πάντα</g> مع حرف جر في عبارات ظرفية: <g>πρὸ πάντων</g>: <b>قبل كل شيء</b>: <r v=\"Jas.5.12\"></r>، <r v=\"1Pet.4.8\"></r>؛ <g>ἐν π.</g>: <b>في كل شيء</b>، <b>بكل الطرق</b>: <r v=\"1Tim.3.11\"></r>، <r v=\"1Pet.4.11\"></r>، وفي مواضع أخرى؛ <g>κατὰ πάντα</g>: <b>من كل وجه</b>: <r v=\"Acts.17.22\"></r>، وفي مواضع أخرى.</s> </s> <s n=\"3.\">مع النفي، <g>πᾶς οὐ</g> (<g>μή</g>) = <g>οὐδείς</g>؛ انظر تحت مدخل <g>οὐ</g> و<g>μή</g>.</s> </s> </s>"},"G3962":{"l":"πατήρ","o":413,"en":"<f><o>πατήρ</o>, <g>πατρός, -τρί, τέρα</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly and very freq. for <h n=\"H1\">אָב</h>;]</e> </et> <s><b>a father</b>; <s n=\"1.\">prop., <s n=\"(a)\">of the male parent: <r v=\"Matt.2.22\"></r>, <r v=\"Luke.1.17\"></r>, <r v=\"John.4.53\"></r>; anarth., <r v=\"Heb.12.7\"></r> (M, <i>Pr.</i>, 82 f.); pl., of both parents (cl.), <r v=\"Heb.11.23\"></r>; <g>οἱ π. τ. σαρκός</g>, <r v=\"Heb.12.9\"></r>;</s> <s n=\"(b)\">of a forefather or ancestor (in cl. usually in pl.; Hom., al.): <r v=\"Matt.3.9\"></r>, <r v=\"Luke.1.73\"></r>, <r v=\"John.8.39\"></r>, al.; pl., <r v=\"Matt.23.30\"></r>, <r v=\"Matt.23.32\"></r>, <r v=\"Luke.6.23\"></r>, <r v=\"Luke.6.26\"></r>, <r v=\"John.4.20\"></r>, <r v=\"1Cor.10.1\"></r>, al.</s> </s> <s n=\"2.\">Metaph., <s n=\"(a)\">of an author, originator, or archetype (= <g>αἴτιος</g>, <g>ἀρχηγός</g>, etc.; Pind., Plat., al.): <r v=\"John.8.41-John.8.44\"></r>, <r v=\"Rom.4.11\"></r>, <r v=\"Rom.4.12\"></r>, <r v=\"Rom.4.16\"></r>.</s> <s n=\"(b)\">as a title of respect or honour, used of seniors, teachers and others in a position of responsible authority (<r v=\"Judg.17.10\"></r>, <r v=\"2Sam.2.12\"></r>, <r v=\"Prov.1.8\"></r>, al.): <r v=\"Matt.23.9\"></r>, <r v=\"Acts.7.2\"></r> <r v=\"Acts.22.1\"></r>, <r v=\"1John.2.13\"></r>.</s> </s> <s n=\"3.\">Of God (as in cl. of Zeus) as Father; <s n=\"(a)\">of created things: <g>τ. φώτων</g>, <r v=\"Jas.1.17\"></r>;</s> <s n=\"(b)\">of all sentient beings: <r v=\"Eph.3.14\"></r>, <r v=\"Eph.3.15\"></r>, <r v=\"Heb.12.9\"></r>;</s> <s n=\"(c)\">of men, esp. those in covenant relation with Him (freq in OT and later Jewish lit.; v. Dalman, <i>Words</i>, 184 ff.): <r v=\"Matt.6.4\"></r>, <r v=\"Luke.6.36\"></r>, <r v=\"John.4.21\"></r>, <r v=\"Jas.3.9\"></r>, al.; <g>ὁ π. ὁ ἐν</g> (<g>τ.</g>) <g>οὐρανοῖς</g>, <r v=\"Matt.5.16\"></r>, <r v=\"Mark.11.25\"></r>; <g>ὁ π. ὁ οὐράνιος</g>, <r v=\"Matt.6.14\"></r> <r v=\"Matt.15.13\"></r>; esp. in the Epp., of Christians: <r v=\"Rom.8.15\"></r>, <r v=\"2Cor.6.18\"></r>, <r v=\"Gal.4.6\"></r>, <r v=\"Eph.2.18\"></r> <r v=\"Eph.4.6\"></r>, <r v=\"1John.2.1\"></r>; c. gen. qual., <g>τ. οἰκτιρμῶν</g>, <r v=\"2Cor.1.3\"></r>; <g>τ. δοξῆς</g>, <r v=\"Eph.1.17\"></r>;</s> <s n=\"(d)\">of Christ (Dalman, <i>Words</i>, 190 ff.); <s n=\"(α)\">by our Lord himself: <g>ὁ π.</g>, <r v=\"Matt.11.25-Matt.11.27\"></r>, <r v=\"Luke.10.21\"></r>, <r v=\"Luke.10.22\"></r>, <r v=\"John.5.20-John.5.23\"></r>, al.; <g>ὁ π. μου</g>, <r v=\"Matt.11.27\"></r>, al.; <g>ὁ ἐν τ. οὐρανοῖς</g>, <r v=\"Matt.7.11\"></r>, al.; <g>ὁ οὐράνιος</g>, <r v=\"Matt.15.13\"></r>; vocat., <r v=\"John.11.41\"></r> <r v=\"John.12.27\"></r>, <r v=\"John.12.28\"></r> <r v=\"John.17.1\"></r>, <r v=\"John.17.5\"></r>, <r v=\"John.17.11\"></r>, <r v=\"John.17.20\"></r>, <r v=\"John.17.25\"></r> (cf. Abbott, <i>JG</i>., 96 f.);</s> <s n=\"(β)\">by Apostles: <r v=\"John.1.14\"></r> (anarth.; v. M, <i>Pr.</i>, 82 f.), <r v=\"Rom.15.6\"></r>, <r v=\"2Cor.1.3\"></r> <r v=\"2Cor.11.31\"></r>, <r v=\"Eph.1.3\"></r>, <r v=\"Col.1.3\"></r>, <r v=\"Heb.1.5\"></r>, <r v=\"1Pet.1.3\"></r>, <r v=\"Rev.1.6\"></r> (cf. Westc., <i>Epp. Jo.</i>, 27-34).</s> </s> </s> </s>","ar":"<f><o>πατήρ</o>، <g>πατρός, -τρί, τέρα</g>،</f> <s><b>أب</b>؛ <s n=\"1.\">بالمعنى الحرفي، <s n=\"(a)\">عن الوالد الذكر: <r v=\"Matt.2.22\"></r>، <r v=\"Luke.1.17\"></r>، <r v=\"John.4.53\"></r>؛ بدون أداة التعريف: <r v=\"Heb.12.7\"></r>؛ في الجمع عن الوالدين كليهما: <r v=\"Heb.11.23\"></r>؛ <g>οἱ π. τ. σαρκός</g>: <r v=\"Heb.12.9\"></r>؛</s> <s n=\"(b)\">عن السلف أو الجد الأعلى: <r v=\"Matt.3.9\"></r>، <r v=\"Luke.1.73\"></r>، <r v=\"John.8.39\"></r>، وفي مواضع أخرى؛ في الجمع: <r v=\"Matt.23.30\"></r>، <r v=\"Matt.23.32\"></r>، <r v=\"Luke.6.23\"></r>، <r v=\"Luke.6.26\"></r>، <r v=\"John.4.20\"></r>، <r v=\"1Cor.10.1\"></r>، وفي مواضع أخرى.</s> </s> <s n=\"2.\">مجازيًا، <s n=\"(a)\">عن المُبدِع أو المُنشئ أو المثال الأول (= <g>αἴτιος</g>، <g>ἀρχηγός</g> إلخ): <r v=\"John.8.41-John.8.44\"></r>، <r v=\"Rom.4.11\"></r>، <r v=\"Rom.4.12\"></r>، <r v=\"Rom.4.16\"></r>.</s> <s n=\"(b)\">لقبًا للاحترام والإكرام، يُطلق على الشيوخ والمعلمين وغيرهم ممن هم في موضع سلطة ومسؤولية (<r v=\"Judg.17.10\"></r>، <r v=\"2Sam.2.12\"></r>، <r v=\"Prov.1.8\"></r>، وفي مواضع أخرى): <r v=\"Matt.23.9\"></r>، <r v=\"Acts.7.2\"></r>، <r v=\"Acts.22.1\"></r>، <r v=\"1John.2.13\"></r>.</s> </s> <s n=\"3.\">عن الله بوصفه الآب؛ <s n=\"(a)\">للمخلوقات: <g>τ. φώτων</g>: <r v=\"Jas.1.17\"></r>؛</s> <s n=\"(b)\">لكل الكائنات الحية العاقلة: <r v=\"Eph.3.14\"></r>، <r v=\"Eph.3.15\"></r>، <r v=\"Heb.12.9\"></r>؛</s> <s n=\"(c)\">للبشر، خاصةً الذين في علاقة عهد معه (كثيرًا في العهد القديم والأدب اليهودي اللاحق): <r v=\"Matt.6.4\"></r>، <r v=\"Luke.6.36\"></r>، <r v=\"John.4.21\"></r>، <r v=\"Jas.3.9\"></r>، وفي مواضع أخرى؛ <g>ὁ π. ὁ ἐν</g> (<g>τ.</g>) <g>οὐρανοῖς</g>: <r v=\"Matt.5.16\"></r>، <r v=\"Mark.11.25\"></r>؛ <g>ὁ π. ὁ οὐράνιος</g>: <r v=\"Matt.6.14\"></r>، <r v=\"Matt.15.13\"></r>؛ خاصةً في الرسائل، عن المسيحيين: <r v=\"Rom.8.15\"></r>، <r v=\"2Cor.6.18\"></r>، <r v=\"Gal.4.6\"></r>، <r v=\"Eph.2.18\"></r>، <r v=\"Eph.4.6\"></r>، <r v=\"1John.2.1\"></r>؛ مع المضاف إليه للنوع، <g>τ. οἰκτιρμῶν</g>: <r v=\"2Cor.1.3\"></r>؛ <g>τ. δοξῆς</g>: <r v=\"Eph.1.17\"></r>؛</s> <s n=\"(d)\">للمسيح؛ <s n=\"(α)\">على لسان الرب نفسه: <g>ὁ π.</g>: <r v=\"Matt.11.25-Matt.11.27\"></r>، <r v=\"Luke.10.21\"></r>، <r v=\"Luke.10.22\"></r>، <r v=\"John.5.20-John.5.23\"></r>، وفي مواضع أخرى؛ <g>ὁ π. μου</g>: <r v=\"Matt.11.27\"></r>، وفي مواضع أخرى؛ <g>ὁ ἐν τ. οὐρανοῖς</g>: <r v=\"Matt.7.11\"></r>، وفي مواضع أخرى؛ <g>ὁ οὐράνιος</g>: <r v=\"Matt.15.13\"></r>؛ في النداء: <r v=\"John.11.41\"></r>، <r v=\"John.12.27\"></r>، <r v=\"John.12.28\"></r>، <r v=\"John.17.1\"></r>، <r v=\"John.17.5\"></r>، <r v=\"John.17.11\"></r>، <r v=\"John.17.20\"></r>، <r v=\"John.17.25\"></r>؛</s> <s n=\"(β)\">على لسان الرسل: <r v=\"John.1.14\"></r> (بدون أداة التعريف)، <r v=\"Rom.15.6\"></r>، <r v=\"2Cor.1.3\"></r>، <r v=\"2Cor.11.31\"></r>، <r v=\"Eph.1.3\"></r>، <r v=\"Col.1.3\"></r>، <r v=\"Heb.1.5\"></r>، <r v=\"1Pet.1.3\"></r>، <r v=\"Rev.1.6\"></r>.</s> </s> </s> </s>"},"G3972":{"l":"Παῦλος","o":158,"en":"<f><o>Παῦλος</o>, <g>-ου, ὁ</g> (Lat. <l>Paulus</l>),</f> <s n=\"1.\"><b>Sergius Paulus</b>: <r v=\"Acts.13.7\"></r>.</s> <s n=\"2.\"><b>the Apostle Paul</b> (cf. <g>Σαῦλος</g>): <r v=\"Acts.13.9\"></r>, and freq. throughout Ac., <r v=\"Rom.1.1\"></r>, <r v=\"1Cor.1.1\"></r>, al., <r v=\"2Pet.3.15\"></r>.</s>","ar":"<f><o>Παῦλος</o>، <g>-ου, ὁ</g> (باللاتينية <l>Paulus</l>)،</f> <s n=\"1.\"><b>سرجيوس بولس</b>: <r v=\"Acts.13.7\"></r>.</s> <s n=\"2.\"><b>بولس الرسول</b> (قارن <g>Σαῦλος</g>): <r v=\"Acts.13.9\"></r>، وكثيرًا في سفر أعمال الرسل، <r v=\"Rom.1.1\"></r>، <r v=\"1Cor.1.1\"></r>، وفي مواضع أخرى، <r v=\"2Pet.3.15\"></r>.</s>"},"G3982":{"l":"πείθω","o":52,"en":"<f><o>πείθω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H982\">בּטח</h>, its parts and derivatives;]</e> </et> <s n=\"(i)\">Active; <s n=\"1.\">trans., <b>to apply persuasion</b> (\"conative\" in pres.; v. M, <i>Pr.</i>, 147), <b>to prevail upon</b> or <b>win over</b>, <b>persuade</b>: absol., <r v=\"Matt.28.14\"></r>, <r v=\"Acts.19.26\"></r>; seq. <g>περί</g>, c. gen. rei, <r v=\"Acts.19.8\"></r>; c. acc. pers., <r v=\"Acts.12.20\"></r> <r v=\"Acts.14.19\"></r> <r v=\"Acts.18.4\"></r>, <r v=\"2Cor.5.11\"></r>, <r v=\"Gal.1.10\"></r>; <g>τ. καρδίας ἡμῶν</g>, <r v=\"1John.3.19\"></r>; c. acc. seq. <g>περί</g>, <r v=\"Acts.28.23\"></r>; c. acc. et inf., <r v=\"Acts.13.43\"></r> <r v=\"Acts.26.28\"></r> (v. Field, <i>Notes</i>, 141 ff.); c. acc. seq. <g>ἵνα</g> (Plut.), <r v=\"Matt.27.20\"></r>.</s> <s n=\"2.\">Intrans., 2 pf. <g>πέποιθα</g> with pres. sense (v. M, <i>Pr.</i>, 147, 154; Bl., § 59, 2): <b>to trust</b>, <b>be confident</b>, <b>have confidence</b>: c. acc. et inf., <r v=\"Rom.2.19\"></r>; c. acc. ref. (v. Ellic., in l.) : <r v=\"Phil.1.6\"></r>, <r v=\"Phil.1.25\"></r>; c. dat., <r v=\"Phil.1.14\"></r>, <r v=\"Phlm.1.21\"></r>; <g>ἑαυτῷ</g>, c. inf., <r v=\"2Cor.10.7\"></r>; seq. <g>ἐν</g>, <r v=\"Phil.3.3\"></r>, <r v=\"Phil.3.4\"></r>; <g>ἐν κυρίῳ ὅτι</g>, <r v=\"Phil.2.24\"></r>; <g>ἐπί</g>, c. dat., <r v=\"Matt.27.43\"></r> (WH, mg.), <r v=\"Mark.10.24\"></r> (T, WH, R, mg., om.), <r v=\"Luke.11.22\"></r> <r v=\"Luke.18.9\"></r>, <r v=\"2Cor.1.9\"></r>, <r v=\"Heb.2.13\"></r>; <g>ἐπί</g>, c. acc., <r v=\"Matt.27.43\"></r> (c. dat., WH, mg.); id. seq. <g>ὅτι</g>, <r v=\"2Cor.2.3\"></r>, <r v=\"2Thess.3.4\"></r> (v. Lft., <i>Notes</i>, 127); <g>εἰς</g>, c. acc. pers. seq. <g>ὅτι</g>, <r v=\"Gal.5.10\"></r>.</s> </s> <s n=\"(ii)\">Pass. and mid.; <s n=\"1.\"><b>to be persuaded</b>, <b>believe</b> (v. M, <i>Pr.</i>, 158): absol., <r v=\"Luke.16.31\"></r>, <r v=\"Acts.17.4\"></r> <r v=\"Acts.21.14\"></r>, <r v=\"Heb.13.18\"></r>; c. dat., <r v=\"Acts.28.24\"></r>; c. acc. et inf., <r v=\"Acts.26.26\"></r>; so also pf., <g>πέπεισμαι</g>, <g>πεπεισμένος εἰμί</g>: c. acc. ref. seq. <g>περί</g>, <r v=\"Heb.6.9\"></r>; c. acc. et inf., <r v=\"Luke.20.6\"></r>; <g>ὅτι</g>, <r v=\"Rom.8.38\"></r>, <r v=\"2Tim.1.5\"></r>, <r v=\"2Tim.1.12\"></r>; id. c. <g>ἐν κυρίῳ</g>, <r v=\"Rom.14.14\"></r>; <g>περί</g>, c. gen. seq. <g>ὅτι</g>, <r v=\"Rom.15.14\"></r>.</s> <s n=\"2.\"><b>to listen to</b>, <b>obey</b>: c. dat. pers., <r v=\"Acts.5.36\"></r>, <r v=\"Acts.5.37\"></r>, <r v=\"Acts.5.40\"></r> <r v=\"Acts.23.21\"></r> <r v=\"Acts.27.11\"></r>, <r v=\"Rom.2.8\"></r>, <r v=\"Gal.5.7\"></r>, <r v=\"Heb.13.17\"></r>, <r v=\"Jas.3.3\"></r> (cf. <g>ἀνα-πείθω</g>).†</s> </s>","ar":"<f><o>πείθω</o>،</f> <s n=\"(i)\">المبني للمعلوم؛ <s n=\"1.\">متعدٍّ: <b>حاول الإقناع</b> (بمعنى المحاولة في المضارع)، <b>استمال</b> أو <b>كسب</b>، <b>أقنع</b>: مطلقًا: <r v=\"Matt.28.14\"></r>، <r v=\"Acts.19.26\"></r>؛ يليه <g>περί</g> مع المضاف إليه للشيء: <r v=\"Acts.19.8\"></r>؛ مع المنصوب للشخص: <r v=\"Acts.12.20\"></r>، <r v=\"Acts.14.19\"></r>، <r v=\"Acts.18.4\"></r>، <r v=\"2Cor.5.11\"></r>، <r v=\"Gal.1.10\"></r>؛ <g>τ. καρδίας ἡμῶν</g>: <r v=\"1John.3.19\"></r>؛ مع المنصوب يليه <g>περί</g>: <r v=\"Acts.28.23\"></r>؛ مع المنصوب والمصدر: <r v=\"Acts.13.43\"></r>، <r v=\"Acts.26.28\"></r>؛ مع المنصوب يليه <g>ἵνα</g>: <r v=\"Matt.27.20\"></r>.</s> <s n=\"2.\">لازم، التام الثاني <g>πέποιθα</g> بمعنى المضارع: <b>وثق</b>، <b>تيقّن</b>، <b>كان واثقًا</b>: مع المنصوب والمصدر: <r v=\"Rom.2.19\"></r>؛ مع المنصوب للإشارة: <r v=\"Phil.1.6\"></r>، <r v=\"Phil.1.25\"></r>؛ مع القابل: <r v=\"Phil.1.14\"></r>، <r v=\"Phlm.1.21\"></r>؛ <g>ἑαυτῷ</g> مع المصدر: <r v=\"2Cor.10.7\"></r>؛ يليه <g>ἐν</g>: <r v=\"Phil.3.3\"></r>، <r v=\"Phil.3.4\"></r>؛ <g>ἐν κυρίῳ ὅτι</g>: <r v=\"Phil.2.24\"></r>؛ <g>ἐπί</g> مع القابل: <r v=\"Matt.27.43\"></r>، <r v=\"Mark.10.24\"></r>، <r v=\"Luke.11.22\"></r>، <r v=\"Luke.18.9\"></r>، <r v=\"2Cor.1.9\"></r>، <r v=\"Heb.2.13\"></r>؛ <g>ἐπί</g> مع المنصوب: <r v=\"Matt.27.43\"></r>؛ ونفسه يليه <g>ὅτι</g>: <r v=\"2Cor.2.3\"></r>، <r v=\"2Thess.3.4\"></r>؛ <g>εἰς</g> مع المنصوب للشخص يليه <g>ὅτι</g>: <r v=\"Gal.5.10\"></r>.</s> </s> <s n=\"(ii)\">المبني للمجهول والصيغة الوسطى؛ <s n=\"1.\"><b>اقتنع</b>، <b>صدّق</b>: مطلقًا: <r v=\"Luke.16.31\"></r>، <r v=\"Acts.17.4\"></r>، <r v=\"Acts.21.14\"></r>، <r v=\"Heb.13.18\"></r>؛ مع القابل: <r v=\"Acts.28.24\"></r>؛ مع المنصوب والمصدر: <r v=\"Acts.26.26\"></r>؛ وكذلك في التام، <g>πέπεισμαι</g>، <g>πεπεισμένος εἰμί</g>: مع المنصوب للإشارة يليه <g>περί</g>: <r v=\"Heb.6.9\"></r>؛ مع المنصوب والمصدر: <r v=\"Luke.20.6\"></r>؛ <g>ὅτι</g>: <r v=\"Rom.8.38\"></r>، <r v=\"2Tim.1.5\"></r>، <r v=\"2Tim.1.12\"></r>؛ ونفسه مع <g>ἐν κυρίῳ</g>: <r v=\"Rom.14.14\"></r>؛ <g>περί</g> مع المضاف إليه يليه <g>ὅτι</g>: <r v=\"Rom.15.14\"></r>.</s> <s n=\"2.\"><b>أصغى إلى</b>، <b>أطاع</b>: مع القابل للشخص: <r v=\"Acts.5.36\"></r>، <r v=\"Acts.5.37\"></r>، <r v=\"Acts.5.40\"></r>، <r v=\"Acts.23.21\"></r>، <r v=\"Acts.27.11\"></r>، <r v=\"Rom.2.8\"></r>، <r v=\"Gal.5.7\"></r>، <r v=\"Heb.13.17\"></r>، <r v=\"Jas.3.3\"></r> (قارن <g>ἀνα-πείθω</g>).†</s> </s>"},"G40":{"l":"ἅγιος","o":233,"en":"<f><o>ἅγιος</o>, <g>-α, ον</g> </f> <et> <e t=\"derivation\">(&lt; <x><g>τό ἅγός</g></x>, <i>religious awe</i>; <x><g>ἅζω</g></x>, <i>to venerate</i>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6944\">קֹ֫דֶשׁ</h>;]</e> </et> <s>primarily, <b>dedicated to the gods</b>, <b>sacred</b> (Hdt.; rare in Att., never in Hom., Hes. and Trag., who use <g>ἁγνός</g>), hence, <b>holy</b>, characteristic of God, separated to God, worthy of veneration. <s n=\"1.\"> Its highest application is to God himself, in his purity, majesty, and glory: <r v=\"Luke.1.49\"></r>, <r v=\"John.17.11\"></r>, <r v=\"Rev.4.8\"></r>. Hence <s n=\"(a)\">of things and places which have a claim to reverence as sacred to God, e.g. the Temple: <r v=\"Matt.24.15\"></r>, <r v=\"Heb.9.1\"></r>; </s> <s n=\"(b)\">of persons employed by him, as angels: <r v=\"1Thess.3.13\"></r>; prophets, <r v=\"Luke.1.70\"></r>; apostles, <r v=\"Eph.3.5\"></r>. </s> </s> <s n=\"2.\">Applied to persons as separated to God's service: <s n=\"(a)\">of Christ, <r v=\"Mark.1.24\"></r>, <r v=\"John.6.69\"></r>, <r v=\"Acts.4.30\"></r>; </s> <s n=\"(b)\">of Christians, <r v=\"Acts.9.13\"></r>, <r v=\"Rom.1.7\"></r>, <r v=\"Heb.6.10\"></r>, <r v=\"Rev.5.8\"></r>. </s> </s> <s n=\"3.\">In the moral sense of sharing God's purity: <r v=\"Mark.6.20\"></r>, <r v=\"John.17.11\"></r>, <r v=\"Acts.3.14\"></r>, <r v=\"Rev.3.7\"></r>.</s> <s n=\"4.\">Of pure, clean sacrifices and offerings: <r v=\"1Cor.7.14\"></r>, <r v=\"Eph.1.4\"></r>. </s> </s> <sy><i>SYN.</i>: <x><g>ἁγνός</g></x>, <i>pure</i>, both in ceremonial and spiritual sense; <x><g>ἱερός</g></x> (<l>sacer</l>), <i>sacred</i>, that which is inviolable because of its (external) relation to God; <x><g>ὅσιος</g></x> (<l>sanctus</l> as opp. to <l>nefas</l>), that which is based on everlasting ordinances of right. (Cf. Tr., <i>Syn.</i>, §lxxxviii; <i>DB</i>, ii, 399 f.; Cremer, 34, 594-601; MM, <i>VGT</i>, s.v.)</sy>","ar":"<f><o>ἅγιος</o>، <g>-α, ον</g> </f> <s>أصلاً، <b>مكرَّس للآلهة</b>، <b>مقدَّس</b>، ومن ثم <b>قدوس</b>، <b>مقدس</b>: ما يتصف به الله، المفروز لله، المستحق للتوقير. <s n=\"1.\"> وأسمى استعمالاته عن الله نفسه، في طهارته وجلاله ومجده: <r v=\"Luke.1.49\"></r>، <r v=\"John.17.11\"></r>، <r v=\"Rev.4.8\"></r>. ومن ثم <s n=\"(a)\">عن الأشياء والأماكن التي تستحق التوقير لكونها مقدسة لله، مثل الهيكل: <r v=\"Matt.24.15\"></r>، <r v=\"Heb.9.1\"></r>؛ </s> <s n=\"(b)\">عن الأشخاص الذين يستخدمهم، كالملائكة: <r v=\"1Thess.3.13\"></r>؛ والأنبياء، <r v=\"Luke.1.70\"></r>؛ والرسل، <r v=\"Eph.3.5\"></r>. </s> </s> <s n=\"2.\">عن الأشخاص المفروزين لخدمة الله: <s n=\"(a)\">عن المسيح، <r v=\"Mark.1.24\"></r>، <r v=\"John.6.69\"></r>، <r v=\"Acts.4.30\"></r>؛ </s> <s n=\"(b)\">عن المسيحيين، <r v=\"Acts.9.13\"></r>، <r v=\"Rom.1.7\"></r>، <r v=\"Heb.6.10\"></r>، <r v=\"Rev.5.8\"></r>. </s> </s> <s n=\"3.\">بالمعنى الأدبي، أي الاشتراك في طهارة الله: <r v=\"Mark.6.20\"></r>، <r v=\"John.17.11\"></r>، <r v=\"Acts.3.14\"></r>، <r v=\"Rev.3.7\"></r>.</s> <s n=\"4.\">عن الذبائح والتقدمات الطاهرة النقية: <r v=\"1Cor.7.14\"></r>، <r v=\"Eph.1.4\"></r>. </s> </s>"},"G4102":{"l":"πίστις","o":243,"en":"<f><o>πίστις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πείθω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H530\">אֱמוּנָה</h>;]</e> </et> <s n=\"1.\">in active sense, <b>faith</b>, <b>belief</b>, <b>trust</b>, <b>confidence</b>, in NT always of religious faith in God or Christ or spiritual things: <r v=\"Matt.8.10\"></r>, <r v=\"Luke.5.20\"></r>, <r v=\"Acts.14.9\"></r>, <r v=\"Rom.1.8\"></r>, <r v=\"1Cor.2.5\"></r>, <r v=\"2Cor.1.24\"></r>, <r v=\"1Tim.1.5\"></r>, al.; c. gen. obj., <r v=\"Mark.11.22\"></r>, <r v=\"Acts.3.16\"></r>, <r v=\"Rom.3.22\"></r>, <r v=\"Gal.2.16\"></r>, <r v=\"Eph.3.12\"></r>, <r v=\"Jas.2.1\"></r>, al.; c. prep., <g>ἐν</g>, <r v=\"Rom.3.25\"></r>, <r v=\"Gal.3.26\"></r>, <r v=\"Eph.1.15\"></r>, <r v=\"Col.1.24\"></r>, <r v=\"1Tim.1.14\"></r> <r v=\"1Tim.3.13\"></r>, <r v=\"2Tim.1.13\"></r> <r v=\"2Tim.3.15\"></r>, <r v=\"2Pet.1.1\"></r>; <g>εἰς</g>, <r v=\"Acts.20.21\"></r> <r v=\"Acts.24.24\"></r> <r v=\"Acts.26.18\"></r>, <r v=\"Col.2.5\"></r>, <r v=\"1Pet.1.21\"></r>; <g>πρός</g>, <r v=\"1Thess.1.8\"></r>, <r v=\"Phlm.1.5\"></r>; <g>ἐπί</g>, c. acc., <r v=\"Heb.6.1\"></r>; <g>ἐν τῇ π. στήκειν</g> (<g>εἶναι</g>, <g>μένειν</g>), <r v=\"1Cor.16.13\"></r>, <r v=\"1Cor.13.5\"></r>, <r v=\"1Tim.2.15\"></r>; <g>ὑπακοὴ τῆς π.</g>, <r v=\"Rom.1.5\"></r> <r v=\"Rom.16.26\"></r>; <g>ὁ ἐκ π.</g>, <r v=\"Rom.3.26\"></r> <r v=\"Rom.4.16\"></r>, <r v=\"Gal.3.12\"></r>; <g>διὰ</g> (<g>τῆς</g>) <g>π.</g>, <r v=\"Rom.3.30\"></r>, <r v=\"Gal.2.16\"></r>, <r v=\"Phil.3.9\"></r>. By meton., objectively, that which is the object or content of belief, <b>the faith</b>: <r v=\"Acts.6.7\"></r> <r v=\"Acts.14.22\"></r>, <r v=\"Gal.1.23\"></r> <r v=\"Gal.3.23\"></r> <r v=\"Gal.6.10\"></r>, <r v=\"Phil.1.25\"></r>, <r v=\"Phil.1.27\"></r>, <r v=\"Jude.1.3\"></r>, <r v=\"Jude.1.20\"></r>, and perh. also <r v=\"Acts.13.8\"></r> <r v=\"Acts.16.5\"></r>, <r v=\"Rom.1.5\"></r> and <r v=\"Rom.16.26\"></r> (v. supr.), <r v=\"1Cor.16.13\"></r>, <r v=\"Col.1.23\"></r>, <r v=\"2Thess.3.2\"></r> (Lft., <i>Notes</i>, 125), <r v=\"1Tim.1.19\"></r> <r v=\"1Tim.3.9\"></r> <r v=\"1Tim.4.1\"></r>, <r v=\"1Tim.4.6\"></r> <r v=\"1Tim.5.8\"></r> <r v=\"1Tim.6.10\"></r>, <r v=\"1Tim.6.12\"></r>, <r v=\"2Tim.3.8\"></r> <r v=\"2Tim.4.7\"></r>, <r v=\"Titus.1.4\"></r>, <r v=\"Titus.1.13\"></r> <r v=\"Titus.3.15\"></r>, <r v=\"1Pet.5.9\"></r>.</s> <s n=\"2.\">In passive sense, <s n=\"(a)\"><b>fidelity</b>, <b>faithfulness</b>: <r v=\"Matt.23.23\"></r>, <r v=\"Gal.5.22\"></r>; <g>ἡ π. τοῦ θεοῦ</g>, <r v=\"Rom.3.3\"></r>;</s> <s n=\"(b)\">objectively, <b>plighted faith</b>, <b>a pledge</b> of fidelity: <r v=\"1Tim.5.12\"></r>. (On the various shades of meaning in which the word is used in NT, v. esp. <i>ICC</i> on <r v=\"Rom.1.17\"></r>, pp. 31 ff.; Lft., <i>Ga.</i>, 154 ff.; Stevens, <i>Th. NT</i>, 422, 515 ff.; <i>DB</i>, i, 830 ff.; Cremer, s.v.)</s> </s>","ar":"<f><o>πίστις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">بالمعنى الفاعلي: <b>إيمان</b>، <b>تصديق</b>، <b>ثقة</b>، <b>اتكال</b>، وهو في العهد الجديد دائمًا عن الإيمان الديني بالله أو بالمسيح أو بالأمور الروحية: <r v=\"Matt.8.10\"></r>، <r v=\"Luke.5.20\"></r>، <r v=\"Acts.14.9\"></r>، <r v=\"Rom.1.8\"></r>، <r v=\"1Cor.2.5\"></r>، <r v=\"2Cor.1.24\"></r>، <r v=\"1Tim.1.5\"></r>، وفي مواضع أخرى؛ مع المضاف إليه المفعول: <r v=\"Mark.11.22\"></r>، <r v=\"Acts.3.16\"></r>، <r v=\"Rom.3.22\"></r>، <r v=\"Gal.2.16\"></r>، <r v=\"Eph.3.12\"></r>، <r v=\"Jas.2.1\"></r>، وفي مواضع أخرى؛ مع حرف جر: <g>ἐν</g>: <r v=\"Rom.3.25\"></r>، <r v=\"Gal.3.26\"></r>، <r v=\"Eph.1.15\"></r>، <r v=\"Col.1.24\"></r>، <r v=\"1Tim.1.14\"></r>، <r v=\"1Tim.3.13\"></r>، <r v=\"2Tim.1.13\"></r>، <r v=\"2Tim.3.15\"></r>، <r v=\"2Pet.1.1\"></r>؛ <g>εἰς</g>: <r v=\"Acts.20.21\"></r>، <r v=\"Acts.24.24\"></r>، <r v=\"Acts.26.18\"></r>، <r v=\"Col.2.5\"></r>، <r v=\"1Pet.1.21\"></r>؛ <g>πρός</g>: <r v=\"1Thess.1.8\"></r>، <r v=\"Phlm.1.5\"></r>؛ <g>ἐπί</g> مع المنصوب: <r v=\"Heb.6.1\"></r>؛ <g>ἐν τῇ π. στήκειν</g> (<g>εἶναι</g>، <g>μένειν</g>): <r v=\"1Cor.16.13\"></r>، <r v=\"1Cor.13.5\"></r>، <r v=\"1Tim.2.15\"></r>؛ <g>ὑπακοὴ τῆς π.</g>: <r v=\"Rom.1.5\"></r>، <r v=\"Rom.16.26\"></r>؛ <g>ὁ ἐκ π.</g>: <r v=\"Rom.3.26\"></r>، <r v=\"Rom.4.16\"></r>، <r v=\"Gal.3.12\"></r>؛ <g>διὰ</g> (<g>τῆς</g>) <g>π.</g>: <r v=\"Rom.3.30\"></r>، <r v=\"Gal.2.16\"></r>، <r v=\"Phil.3.9\"></r>. وكنايةً، بالمعنى الموضوعي، ما هو موضوع الإيمان أو مضمونه: <b>الإيمان</b>: <r v=\"Acts.6.7\"></r>، <r v=\"Acts.14.22\"></r>، <r v=\"Gal.1.23\"></r>، <r v=\"Gal.3.23\"></r>، <r v=\"Gal.6.10\"></r>، <r v=\"Phil.1.25\"></r>، <r v=\"Phil.1.27\"></r>، <r v=\"Jude.1.3\"></r>، <r v=\"Jude.1.20\"></r>، وربما أيضًا <r v=\"Acts.13.8\"></r>، <r v=\"Acts.16.5\"></r>، <r v=\"Rom.1.5\"></r> و<r v=\"Rom.16.26\"></r> (انظر أعلاه)، <r v=\"1Cor.16.13\"></r>، <r v=\"Col.1.23\"></r>، <r v=\"2Thess.3.2\"></r>، <r v=\"1Tim.1.19\"></r>، <r v=\"1Tim.3.9\"></r>، <r v=\"1Tim.4.1\"></r>، <r v=\"1Tim.4.6\"></r>، <r v=\"1Tim.5.8\"></r>، <r v=\"1Tim.6.10\"></r>، <r v=\"1Tim.6.12\"></r>، <r v=\"2Tim.3.8\"></r>، <r v=\"2Tim.4.7\"></r>، <r v=\"Titus.1.4\"></r>، <r v=\"Titus.1.13\"></r>، <r v=\"Titus.3.15\"></r>، <r v=\"1Pet.5.9\"></r>.</s> <s n=\"2.\">بالمعنى المفعولي، <s n=\"(a)\"><b>أمانة</b>، <b>وفاء</b>: <r v=\"Matt.23.23\"></r>، <r v=\"Gal.5.22\"></r>؛ <g>ἡ π. τοῦ θεοῦ</g>: <r v=\"Rom.3.3\"></r>؛</s> <s n=\"(b)\">بالمعنى الموضوعي: <b>عهد مقطوع</b>، <b>تعهّد</b> بالأمانة: <r v=\"1Tim.5.12\"></r>. (وعن ظلال المعنى المختلفة التي تُستعمل بها الكلمة في العهد الجديد انظر خاصةً التعليق على <r v=\"Rom.1.17\"></r>.)</s> </s>"},"G4151":{"l":"πνεῦμα","o":379,"en":"<f><o>πνεῦμα</o>, <g>-τος, τό</g>,</f> <et> <e t=\"derivation\">(&lt; <g>πνέω</g>),</e> <e t=\"septuagint\">[in LXX chiefly and very freq. for <h n=\"H7307\">רוּחַ</h>;]</e> </et> <s n=\"1.\">of air in motion; <s n=\"(a)\"><b>wind</b>: <r v=\"John.3.8\"></r>; pl., <r v=\"Heb.1.7\"></r><i>(LXX)</i>;</s> <s n=\"(b)\"><b>breath</b>: <g>π. ζωῆς</g>, <r v=\"Rev.11.11\"></r>; <g>π. τοῦ στόματος</g>, fig., <r v=\"2Thess.2.8\"></r> (cf. <r v=\"Ps.32.6\"></r>).</s> </s> <s n=\"2.\">Of the vital principle, <b>the spirit</b> (Arist., Polyb., al.): <r v=\"Luke.8.55\"></r>, <r v=\"John.19.30\"></r>, <r v=\"Acts.7.59\"></r>, al.; opp. to <g>σάρξ</g>, <r v=\"Matt.26.41\"></r>, <r v=\"Mark.14.38\"></r>, <r v=\"1Cor.5.5\"></r>, al.; to <g>σῶμα</g>, <r v=\"Rom.8.10\"></r>, <r v=\"1Cor.6.17\"></r> <r v=\"1Cor.7.34\"></r>, <r v=\"1Pet.4.6\"></r>; to <g>ψυχή</g>, <r v=\"Phil.1.27\"></r>, <r v=\"Heb.4.12\"></r>; <g>τὸ π. καὶ ἡ ψ. καὶ τ. σῶμα</g>, <r v=\"1Thess.5.23\"></r> (M, <i>Th.</i>, in l.); dat., <g>τῷ π.</g>, <b>in spirit</b>, <r v=\"Mark.2.8\"></r> <r v=\"Mark.8.12\"></r>, <r v=\"John.11.33\"></r> <r v=\"John.13.21\"></r>, <r v=\"Acts.18.25\"></r>, <r v=\"Rom.12.11\"></r>, <r v=\"1Cor.7.34\"></r>, <r v=\"1Pet.3.18\"></r>, al.; of the human spirit of Christ, <r v=\"Rom.1.4\"></r>, <r v=\"1Tim.3.16\"></r>.</s> <s n=\"3.\"><b>spirit</b>, i.e. frame of mind, disposition, influence: <r v=\"Luke.1.17\"></r>, <r v=\"Rom.8.15\"></r>, <r v=\"1Cor.4.21\"></r>, <r v=\"Gal.6.1\"></r>, <r v=\"Eph.2.2\"></r>, <r v=\"2Tim.1.7\"></r>, <r v=\"1John.4.6\"></r>, al.</s> <s n=\"4.\">An incorporeal being, <b>a spirit</b>: <r v=\"Luke.24.37\"></r>, <r v=\"Luke.24.39\"></r>, <r v=\"Acts.23.8\"></r>; <g>π. ὁ θεός</g>, <b>God is spirit</b>, <r v=\"John.4.24\"></r>; <g>πατὴρ τῶν π.</g>, <r v=\"Heb.12.9\"></r>; of disembodied human beings, <r v=\"Heb.12.23\"></r>, <r v=\"1Pet.3.19\"></r> (<i>ICC</i>, in l.; <i>DB</i>, iii, 795); of angels. <r v=\"Heb.1.14\"></r>; of demons or evil spirits, <r v=\"Matt.8.16\"></r>, <r v=\"Mark.9.20\"></r>, <r v=\"Luke.9.39\"></r>, al.; <g>π. πύθωνα</g>, <r v=\"Acts.16.16\"></r>; <g>πνεύματα δαιμονίων</g>, <r v=\"Rev.16.14\"></r>; <g>π. δαιμονίου ἀκαθάρτου</g>, <r v=\"Luke.4.33\"></r>; <g>π. ἀσθενείας</g> (Bl., § 35, 5), <r v=\"Luke.13.11\"></r>; <g>π. ἀκάθαρτον</g>, <r v=\"Matt.10.1\"></r>, <r v=\"Mark.1.23\"></r>, <r v=\"Luke.4.36\"></r>, <r v=\"Acts.5.16\"></r>; <g>π. ἄλαλον</g> (<g>καὶ κωφόν</g>), <r v=\"Mark.9.17\"></r>, <r v=\"Mark.9.25\"></r>; <g>πονηρόν</g>, <r v=\"Luke.7.21\"></r>, <r v=\"Acts.19.12\"></r>, al.</s> <s n=\"5.\">Of the <b>Holy Spirit</b>, <g>π. ἅγιον</g>, <g>τὸ ἅ. π.</g>, <g>τὸ π. τὸ ἅ.</g>, <g>τὸ π.</g>, <g>π.</g> (the article as a rule being used when the Spirit is regarded as a Person or a Divine Power, and omitted when the reference is to an operation, influence or gift of the Spirit; v. WM, 151<i>5</i>; Bl., § 46, 7): anarth., <r v=\"Matt.1.18\"></r> <r v=\"Matt.3.11\"></r>, <r v=\"Matt.3.16\"></r> <r v=\"Matt.4.1\"></r>, <r v=\"Mark.1.8\"></r> (Swete, in l.), <r v=\"Mark.1.10\"></r>, <r v=\"Luke.1.15\"></r>, <r v=\"John.7.39\"></r>, <r v=\"Acts.19.2\"></r>, <r v=\"Rom.5.5\"></r>, <r v=\"1Cor.2.4\"></r>, al.; c. art., <r v=\"Matt.4.1\"></r> <r v=\"Matt.12.31\"></r>, <r v=\"Matt.12.32\"></r>, <r v=\"Mark.1.10\"></r> <r v=\"Mark.3.29\"></r>, <r v=\"Luke.2.26\"></r>, <r v=\"John.7.36\"></r> <r v=\"John.14.26\"></r>, <r v=\"Acts.4.31\"></r> <r v=\"Acts.5.3\"></r>, <r v=\"Rom.8.16\"></r>, al.; (<g>τὸ</g>) <g>π.</g> (<g>τοῦ</g>) <g>θεοῦ</g>, <r v=\"Matt.3.16\"></r>, <r v=\"Rom.8.9\"></r>, <r v=\"Eph.3.16\"></r>, <r v=\"1John.4.2\"></r>, al.; <g>τὸ π. τ. πατρός</g>, <r v=\"Matt.10.20\"></r>; <g>π. θεοῦ ζῶντος</g>, <r v=\"2Cor.3.3\"></r>; (<g>τὸ</g>) <g>π. τοῦ κυρίου</g>, <r v=\"Luke.4.18\"></r>, <r v=\"Acts.5.9\"></r> <r v=\"Acts.8.39\"></r>; <g>τὸ π. Ἰησοῦ</g>, <r v=\"Acts.16.7\"></r>; <g>Χριστοῦ</g>, <r v=\"Rom.8.9\"></r>; <g>Ἰησοῦ Χριστοῦ</g>, <r v=\"Phil.1.19\"></r>; <g>τὸ π. τ. ἀληθείας</g>, <r v=\"John.15.26\"></r> <r v=\"John.16.13\"></r>, <r v=\"1John.4.6\"></r>; <g>λείγει</g> (<g>μαρτυρεῖ</g>) <g>τὸ π.</g> (<g>τὸ ἅγιον</g>), <r v=\"Acts.21.11\"></r> <r v=\"Acts.28.25\"></r>, <r v=\"1Tim.4.1\"></r>, <r v=\"Heb.3.7\"></r> <r v=\"Heb.10.15\"></r>, <r v=\"Rev.14.13\"></r>; seq. <g>τ. ἐκκλησίαις</g>, <r v=\"Rev.2.7\"></r>, <r v=\"Rev.2.11\"></r>, <r v=\"Rev.2.17\"></r>, <r v=\"Rev.2.29\"></r>, <r v=\"Rev.3.6\"></r>, <r v=\"Rev.3.13\"></r>, <r v=\"Rev.3.22\"></r>; <g>ἐν τ. π.</g>, <r v=\"Luke.2.27\"></r>; <g>κατὰ πνεῦμα</g>, <r v=\"Rom.8.4\"></r>, <r v=\"Rom.8.5\"></r>; <g>ἐξ ὕδατος καὶ π.</g>, <r v=\"John.3.5\"></r>; <g>διὰ πνεύματος αἰωνίου</g>, <r v=\"Heb.9.14\"></r>; <g>ἐν ἁγιασμῷ πνεύματος</g>, <r v=\"2Thess.2.18\"></r>, <r v=\"1Pet.1.2\"></r>; <g>ἓν π.</g>, <r v=\"1Cor.12.13\"></r>, <r v=\"Eph.2.18\"></r> <r v=\"Eph.4.4\"></r>; <g>ὁ δὲ κύριος τὸ π. ἐστιν</g>, <r v=\"2Cor.3.17\"></r>; of that which is effected or governed by the Spirit, opp. to <g>γράμμα</g>, <r v=\"Rom.2.29\"></r> <r v=\"Rom.7.6\"></r>, <r v=\"2Cor.3.6\"></r>.</s> <sy><i>SYN.</i>: <g>νοῦς</g>, which in NT is contrasted with <g>π.</g> as \"the action of the understanding in man with that of the spiritual or ecstatic impulse\" (<i>DB</i>, iv, 612); <g>ψυχή</g>—the usual term in cl. psychology—in NT, \"expresses man as apart from God, a separate individual, <g>π.</g> expresses man as drawing his life from God\" (<i>DB</i>, 1-vol., 872).</sy>","ar":"<f><o>πνεῦμα</o>، <g>-τος, τό</g>،</f> <s n=\"1.\">عن الهواء المتحرك؛ <s n=\"(a)\"><b>ريح</b>: <r v=\"John.3.8\"></r>؛ جمع: <r v=\"Heb.1.7\"></r><i>(السبعينية)</i>؛</s> <s n=\"(b)\"><b>نَفَس، نسمة</b>: <g>π. ζωῆς</g>: <r v=\"Rev.11.11\"></r>؛ <g>π. τοῦ στόματος</g>، مجازيًا: <r v=\"2Thess.2.8\"></r> (قارن <r v=\"Ps.32.6\"></r>).</s> </s> <s n=\"2.\">عن مبدأ الحياة: <b>الروح</b>: <r v=\"Luke.8.55\"></r>، <r v=\"John.19.30\"></r>، <r v=\"Acts.7.59\"></r>، وفي مواضع أخرى؛ عكس <g>σάρξ</g>: <r v=\"Matt.26.41\"></r>، <r v=\"Mark.14.38\"></r>، <r v=\"1Cor.5.5\"></r>، وفي مواضع أخرى؛ وعكس <g>σῶμα</g>: <r v=\"Rom.8.10\"></r>، <r v=\"1Cor.6.17\"></r>، <r v=\"1Cor.7.34\"></r>، <r v=\"1Pet.4.6\"></r>؛ وعكس <g>ψυχή</g>: <r v=\"Phil.1.27\"></r>، <r v=\"Heb.4.12\"></r>؛ <g>τὸ π. καὶ ἡ ψ. καὶ τ. σῶμα</g>: <r v=\"1Thess.5.23\"></r>؛ في حالة القابل، <g>τῷ π.</g>: <b>بالروح</b>: <r v=\"Mark.2.8\"></r>، <r v=\"Mark.8.12\"></r>، <r v=\"John.11.33\"></r>، <r v=\"John.13.21\"></r>، <r v=\"Acts.18.25\"></r>، <r v=\"Rom.12.11\"></r>، <r v=\"1Cor.7.34\"></r>، <r v=\"1Pet.3.18\"></r>، وفي مواضع أخرى؛ عن روح المسيح الإنسانية: <r v=\"Rom.1.4\"></r>، <r v=\"1Tim.3.16\"></r>.</s> <s n=\"3.\"><b>روح</b>، أي حالة الذهن، المزاج، التأثير: <r v=\"Luke.1.17\"></r>، <r v=\"Rom.8.15\"></r>، <r v=\"1Cor.4.21\"></r>، <r v=\"Gal.6.1\"></r>، <r v=\"Eph.2.2\"></r>، <r v=\"2Tim.1.7\"></r>، <r v=\"1John.4.6\"></r>، وفي مواضع أخرى.</s> <s n=\"4.\">كائن غير مادي، <b>روح</b>: <r v=\"Luke.24.37\"></r>، <r v=\"Luke.24.39\"></r>، <r v=\"Acts.23.8\"></r>؛ <g>π. ὁ θεός</g>: <b>الله روح</b>: <r v=\"John.4.24\"></r>؛ <g>πατὴρ τῶν π.</g>: <r v=\"Heb.12.9\"></r>؛ عن أرواح البشر المفارقة للأجساد: <r v=\"Heb.12.23\"></r>، <r v=\"1Pet.3.19\"></r>؛ عن الملائكة: <r v=\"Heb.1.14\"></r>؛ عن الشياطين أو الأرواح الشريرة: <r v=\"Matt.8.16\"></r>، <r v=\"Mark.9.20\"></r>، <r v=\"Luke.9.39\"></r>، وفي مواضع أخرى؛ <g>π. πύθωνα</g>: <r v=\"Acts.16.16\"></r>؛ <g>πνεύματα δαιμονίων</g>: <r v=\"Rev.16.14\"></r>؛ <g>π. δαιμονίου ἀκαθάρτου</g>: <r v=\"Luke.4.33\"></r>؛ <g>π. ἀσθενείας</g>: <r v=\"Luke.13.11\"></r>؛ <g>π. ἀκάθαρτον</g>: <r v=\"Matt.10.1\"></r>، <r v=\"Mark.1.23\"></r>، <r v=\"Luke.4.36\"></r>، <r v=\"Acts.5.16\"></r>؛ <g>π. ἄλαλον</g> (<g>καὶ κωφόν</g>): <r v=\"Mark.9.17\"></r>، <r v=\"Mark.9.25\"></r>؛ <g>πονηρόν</g>: <r v=\"Luke.7.21\"></r>، <r v=\"Acts.19.12\"></r>، وفي مواضع أخرى.</s> <s n=\"5.\">عن <b>الروح القدس</b>: <g>π. ἅγιον</g>، <g>τὸ ἅ. π.</g>، <g>τὸ π. τὸ ἅ.</g>، <g>τὸ π.</g>، <g>π.</g> (تُستعمل أداة التعريف في الغالب حين يُنظر إلى الروح بوصفه أقنومًا أو قوة إلهية، وتُحذف حين يكون الكلام عن عمل الروح أو تأثيره أو موهبته): بدون أداة التعريف: <r v=\"Matt.1.18\"></r>، <r v=\"Matt.3.11\"></r>، <r v=\"Matt.3.16\"></r>، <r v=\"Matt.4.1\"></r>، <r v=\"Mark.1.8\"></r>، <r v=\"Mark.1.10\"></r>، <r v=\"Luke.1.15\"></r>، <r v=\"John.7.39\"></r>، <r v=\"Acts.19.2\"></r>، <r v=\"Rom.5.5\"></r>، <r v=\"1Cor.2.4\"></r>، وفي مواضع أخرى؛ مع أداة التعريف: <r v=\"Matt.4.1\"></r>، <r v=\"Matt.12.31\"></r>، <r v=\"Matt.12.32\"></r>، <r v=\"Mark.1.10\"></r>، <r v=\"Mark.3.29\"></r>، <r v=\"Luke.2.26\"></r>، <r v=\"John.7.36\"></r>، <r v=\"John.14.26\"></r>، <r v=\"Acts.4.31\"></r>، <r v=\"Acts.5.3\"></r>، <r v=\"Rom.8.16\"></r>، وفي مواضع أخرى؛ (<g>τὸ</g>) <g>π.</g> (<g>τοῦ</g>) <g>θεοῦ</g>: <r v=\"Matt.3.16\"></r>، <r v=\"Rom.8.9\"></r>، <r v=\"Eph.3.16\"></r>، <r v=\"1John.4.2\"></r>، وفي مواضع أخرى؛ <g>τὸ π. τ. πατρός</g>: <r v=\"Matt.10.20\"></r>؛ <g>π. θεοῦ ζῶντος</g>: <r v=\"2Cor.3.3\"></r>؛ (<g>τὸ</g>) <g>π. τοῦ κυρίου</g>: <r v=\"Luke.4.18\"></r>، <r v=\"Acts.5.9\"></r>، <r v=\"Acts.8.39\"></r>؛ <g>τὸ π. Ἰησοῦ</g>: <r v=\"Acts.16.7\"></r>؛ <g>Χριστοῦ</g>: <r v=\"Rom.8.9\"></r>؛ <g>Ἰησοῦ Χριστοῦ</g>: <r v=\"Phil.1.19\"></r>؛ <g>τὸ π. τ. ἀληθείας</g>: <r v=\"John.15.26\"></r>، <r v=\"John.16.13\"></r>، <r v=\"1John.4.6\"></r>؛ <g>λείγει</g> (<g>μαρτυρεῖ</g>) <g>τὸ π.</g> (<g>τὸ ἅγιον</g>): <r v=\"Acts.21.11\"></r>، <r v=\"Acts.28.25\"></r>، <r v=\"1Tim.4.1\"></r>، <r v=\"Heb.3.7\"></r>، <r v=\"Heb.10.15\"></r>، <r v=\"Rev.14.13\"></r>؛ يليه <g>τ. ἐκκλησίαις</g>: <r v=\"Rev.2.7\"></r>، <r v=\"Rev.2.11\"></r>، <r v=\"Rev.2.17\"></r>، <r v=\"Rev.2.29\"></r>، <r v=\"Rev.3.6\"></r>، <r v=\"Rev.3.13\"></r>، <r v=\"Rev.3.22\"></r>؛ <g>ἐν τ. π.</g>: <r v=\"Luke.2.27\"></r>؛ <g>κατὰ πνεῦμα</g>: <r v=\"Rom.8.4\"></r>، <r v=\"Rom.8.5\"></r>؛ <g>ἐξ ὕδατος καὶ π.</g>: <r v=\"John.3.5\"></r>؛ <g>διὰ πνεύματος αἰωνίου</g>: <r v=\"Heb.9.14\"></r>؛ <g>ἐν ἁγιασμῷ πνεύματος</g>: <r v=\"2Thess.2.18\"></r>، <r v=\"1Pet.1.2\"></r>؛ <g>ἓν π.</g>: <r v=\"1Cor.12.13\"></r>، <r v=\"Eph.2.18\"></r>، <r v=\"Eph.4.4\"></r>؛ <g>ὁ δὲ κύριος τὸ π. ἐστιν</g>: <r v=\"2Cor.3.17\"></r>؛ عمّا يُحدثه الروح أو يقوده، عكس <g>γράμμα</g>: <r v=\"Rom.2.29\"></r>، <r v=\"Rom.7.6\"></r>، <r v=\"2Cor.3.6\"></r>.</s>"},"G4160":{"l":"ποιέω","o":568,"en":"<f><o>ποιέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX for a great variety of words, but chiefly for <h n=\"H6213\">עשׂה</h>;]</e> </et> <s n=\"1.\"><b>to make</b>, <b>produce</b>, <b>create</b>, <b>cause</b>: c. acc. rei, <r v=\"Matt.17.4\"></r>, <r v=\"Mark.9.5\"></r>, <r v=\"John.9.11\"></r>, <r v=\"Acts.9.39\"></r>, <r v=\"Rom.9.20\"></r>, al.; of God as Creator (c. acc. pers. also), <r v=\"Matt.19.4\"></r>, <r v=\"Mark.10.6\"></r>, <r v=\"Luke.11.40\"></r>, <r v=\"Acts.4.24\"></r>, <r v=\"Heb.1.2\"></r>, al.; like Heb. <h n=\"H6213\">עשׂה</h>, absol. = <g>ἐργάζομαι</g>, <b>to work</b>, <r v=\"Matt.20.12\"></r> (cf. <r v=\"Ruth.2.19\"></r>; so AV, but v. infr.), <r v=\"Rev.13.5\"></r>, R, mg. (but v. infr.); <g>σκάνδαλα</g>, <r v=\"Rom.16.17\"></r>; <g>εἰρήνην</g>, <r v=\"Eph.2.15\"></r>, <r v=\"Jas.3.18\"></r>; <g>ἐπίστασιν</g>, <r v=\"Acts.24.12\"></r>; <g>συστροφήν</g>, <r v=\"Acts.23.12\"></r>; c. acc. rei et dat. pers., <r v=\"Luke.1.68\"></r>, <r v=\"Acts.15.3\"></r>; with nouns expressing action or its accomplishment, forming a periphr. for the cogn. verb: <g>ὁδόν π.</g> (cl. <g>ὁ ποιεῖσθαι</g>), <b>to go on</b>, <b>advance</b>, <r v=\"Mark.2.23\"></r>; <g>πόλεμον</g>, <r v=\"Rev.11.7\"></r>, al.; <g>ἐκδίκησιν</g>, <r v=\"Luke.18.7\"></r>, <r v=\"Luke.18.8\"></r>; <g>ἐνέδραν</g>, <r v=\"Acts.25.3\"></r>; <g>κρίσιν</g>, <r v=\"John.5.27\"></r>, <r v=\"Jude.1.15\"></r>; <g>ἔργα</g>, <r v=\"John.5.36\"></r>, al.; <g>σημεῖα</g> (<g>τέρατα καὶ σ.</g>), <r v=\"John.2.23\"></r> and freq., <r v=\"Acts.2.22\"></r>, al.; so also mid. <g>ποιεῖσθαι</g>: <g>μονήν</g>, <r v=\"John.14.23\"></r>; <g>πορείαν</g>, <r v=\"Luke.13.22\"></r>; <g>κοινωνίαν</g>, <r v=\"Rom.15.26\"></r>; of food, <b>to make ready</b>, <b>prepare</b>: <g>δεῖπνον</g>, <r v=\"Mark.6.21\"></r>, al.; <g>δοχήν</g>, <r v=\"Luke.5.29\"></r> <r v=\"Luke.14.13\"></r>; <g>γάμους</g>, <r v=\"Matt.22.2\"></r>; of time, <b>to spend</b> (cl.): <g>ὥραν</g>, <r v=\"Matt.20.12\"></r>, RV (but v. supr. and cf. McN, in l.); <g>μῆνας</g>, <r v=\"Rev.13.5\"></r>, R, txt. (cf. Swete, in l.; but v. supr.); <g>ἐνιαυτόν</g>, <r v=\"Jas.4.13\"></r>; c. acc. seq. <g>ἐκ</g>, <r v=\"John.2.15\"></r>, al.; c. acc. et acc. pred., <r v=\"Matt.3.3\"></r> <r v=\"Matt.12.16\"></r>, <r v=\"Mark.1.3\"></r> <r v=\"Mark.3.12\"></r>, <r v=\"John.5.11\"></r>, al.; c. adv., <g>καλῶς</g>, <r v=\"Mark.7.37\"></r>; <g>ἑορτὴν π.</g> (Dem., <r v=\"Exod.23.16\"></r>, al.), <r v=\"Acts.18.21\"></r>, Rec.; <g>πάσχα</g>, <r v=\"Matt.26.18\"></r>; <b>to make</b> or <b>offer</b> a sacrifice (Plat., Xen., al.; <r v=\"Job.42.8\"></r>, <r v=\"1Kgs.11.33\"></r>; so some understand <g>τοῦτο ποιεῖτε</g>, <r v=\"Luke.22.19\"></r>, but v. Abbott, <i>Essays</i>, 110 ff.); seq. <g>ἵνα</g> (WM, 422 f.; M, <i>Pr.</i>, 228), <r v=\"John.11.37\"></r>, <r v=\"Col.4.16\"></r>, <r v=\"Rev.3.9\"></r>.</s> <s n=\"2.\"><b>to do</b>, <b>perform</b>, <b>carry out</b>, <b>execute</b>: absol., c. adv., <g>καλῶς π.</g>, <r v=\"Matt.12.12\"></r>, <r v=\"1Cor.7.37\"></r>, <r v=\"1Cor.7.38\"></r>, <r v=\"Jas.2.19\"></r>; id. seq. ptcp. (cl.; v. M, <i>Pr.</i>, 228), <r v=\"Acts.10.33\"></r>, <r v=\"Phil.4.14\"></r>, <r v=\"2Pet.1.19\"></r>, <r v=\"3John.1.6\"></r>; <g>οὕτως</g>, <r v=\"Matt.24.46\"></r>, <r v=\"Luke.9.15\"></r>, al.; <g>ὡς</g> (<g>καθώς</g>), <r v=\"Matt.1.24\"></r> <r v=\"Matt.21.6\"></r>, al.; <g>ὁμοίως</g>, <r v=\"Luke.3.11\"></r>; <g>ὡσαύτως</g>, <r v=\"Matt.20.5\"></r>; c. ptcp., <g>ἀγνοῶν ἐποίησα</g>, <r v=\"1Tim.1.13\"></r>; c. acc. rei: <g>τί</g> interrog., <r v=\"Matt.12.3\"></r>, <r v=\"Mark.2.25\"></r>, <r v=\"Luke.6.2\"></r>, al.; <g>τοῦτο</g>, <r v=\"Matt.13.28\"></r>, <r v=\"Mark.5.32\"></r>, <r v=\"Luke.22.19\"></r> (WH om.; v. supr., ref. to Abbott, <i>Essays</i>), <r v=\"Rom.7.20\"></r>, al.; with nouns expressing command or regulation: <g>τ. νόμον</g> (not as in cl., to <i>make</i> a law), <r v=\"John.7.19\"></r>, <r v=\"Gal.5.3\"></r> (cf. in LXX, <r v=\"Josh.22.5\"></r>, <r v=\"1Chr.22.12\"></r>, al.); <g>τ. ἐντολάς</g>, <r v=\"Matt.5.19\"></r>; similarly with other nouns expressing conduct: <g>τ. δικαιοσύνην</g>, <r v=\"Matt.6.1\"></r>, al.; <g>τ. ἀλήθειαν</g>, <r v=\"John.3.21\"></r>, al., etc.; c. dupl. acc., <r v=\"Matt.27.22\"></r>, <r v=\"Mark.15.12\"></r>; c. acc. rei et dat. pers. (commod., incomm.; rare in cl.), <r v=\"Matt.7.12\"></r>, <r v=\"Mark.5.19\"></r>, <r v=\"Mark.5.20\"></r>, <r v=\"Luke.1.49\"></r>, <r v=\"John.9.26\"></r>, al.</s> <sy><i>SYN.</i>: <g>πράσσω</g>, q.v. The general distinction between the two words is that between particular action and its habitual performance (cf. Tr., <i>Syn.</i>, § xcvi; Westc. on <r v=\"John.3.21\"></r>; <i>ICC</i> on <r v=\"Rom.1.32\"></r>).</sy>","ar":"<f><o>ποιέω</o>، <g>-ῶ</g>،</f> <s n=\"1.\"><b>يصنع</b>، <b>يُنتج</b>، <b>يخلق</b>، <b>يُسبِّب</b>: مع منصوب الشيء، <r v=\"Matt.17.4\"></r>، <r v=\"Mark.9.5\"></r>، <r v=\"John.9.11\"></r>، <r v=\"Acts.9.39\"></r>، <r v=\"Rom.9.20\"></r>، وفي مواضع أخرى؛ عن الله بوصفه الخالق (ومع منصوب الشخص أيضًا)، <r v=\"Matt.19.4\"></r>، <r v=\"Mark.10.6\"></r>، <r v=\"Luke.11.40\"></r>، <r v=\"Acts.4.24\"></r>، <r v=\"Heb.1.2\"></r>، وفي مواضع أخرى؛ مثل العبرية <h n=\"H6213\">עשׂה</h>، مطلقًا = <g>ἐργάζομαι</g>، <b>يعمل</b>، <r v=\"Matt.20.12\"></r> (قارن <r v=\"Ruth.2.19\"></r>)، <r v=\"Rev.13.5\"></r>؛ <g>σκάνδαλα</g>، <r v=\"Rom.16.17\"></r>؛ <g>εἰρήνην</g>، <r v=\"Eph.2.15\"></r>، <r v=\"Jas.3.18\"></r>؛ <g>ἐπίστασιν</g>، <r v=\"Acts.24.12\"></r>؛ <g>συστροφήν</g>، <r v=\"Acts.23.12\"></r>؛ مع منصوب الشيء وقابل الشخص، <r v=\"Luke.1.68\"></r>، <r v=\"Acts.15.3\"></r>؛ مع أسماء تدل على فعلٍ أو إتمامه، فتؤلّف تعبيرًا بديلاً عن الفعل المجانس: <g>ὁδόν π.</g>، <b>يسير</b>، <b>يتقدم</b>، <r v=\"Mark.2.23\"></r>؛ <g>πόλεμον</g>، <r v=\"Rev.11.7\"></r>، وفي مواضع أخرى؛ <g>ἐκδίκησιν</g>، <r v=\"Luke.18.7\"></r>، <r v=\"Luke.18.8\"></r>؛ <g>ἐνέδραν</g>، <r v=\"Acts.25.3\"></r>؛ <g>κρίσιν</g>، <r v=\"John.5.27\"></r>، <r v=\"Jude.1.15\"></r>؛ <g>ἔργα</g>، <r v=\"John.5.36\"></r>، وفي مواضع أخرى؛ <g>σημεῖα</g> (<g>τέρατα καὶ σ.</g>)، <r v=\"John.2.23\"></r> وكثيرًا، <r v=\"Acts.2.22\"></r>، وفي مواضع أخرى؛ وكذلك في الصيغة الوسطى <g>ποιεῖσθαι</g>: <g>μονήν</g>، <r v=\"John.14.23\"></r>؛ <g>πορείαν</g>، <r v=\"Luke.13.22\"></r>؛ <g>κοινωνίαν</g>، <r v=\"Rom.15.26\"></r>؛ عن الطعام، <b>يُعِدّ</b>، <b>يُهيِّئ</b>: <g>δεῖπνον</g>، <r v=\"Mark.6.21\"></r>، وفي مواضع أخرى؛ <g>δοχήν</g>، <r v=\"Luke.5.29\"></r> <r v=\"Luke.14.13\"></r>؛ <g>γάμους</g>، <r v=\"Matt.22.2\"></r>؛ عن الزمن، <b>يقضي</b>: <g>ὥραν</g>، <r v=\"Matt.20.12\"></r>؛ <g>μῆνας</g>، <r v=\"Rev.13.5\"></r>؛ <g>ἐνιαυτόν</g>، <r v=\"Jas.4.13\"></r>؛ مع المنصوب يليه <g>ἐκ</g>، <r v=\"John.2.15\"></r>، وفي مواضع أخرى؛ مع منصوب ومنصوب خبري، <r v=\"Matt.3.3\"></r> <r v=\"Matt.12.16\"></r>، <r v=\"Mark.1.3\"></r> <r v=\"Mark.3.12\"></r>، <r v=\"John.5.11\"></r>، وفي مواضع أخرى؛ مع الظرف، <g>καλῶς</g>، <r v=\"Mark.7.37\"></r>؛ <g>ἑορτὴν π.</g> (<r v=\"Exod.23.16\"></r>، وفي مواضع أخرى)، <r v=\"Acts.18.21\"></r>؛ <g>πάσχα</g>، <r v=\"Matt.26.18\"></r>؛ <b>يصنع</b> أو <b>يقدّم</b> ذبيحة (<r v=\"Job.42.8\"></r>، <r v=\"1Kgs.11.33\"></r>؛ وهكذا يفهم بعضهم <g>τοῦτο ποιεῖτε</g>، <r v=\"Luke.22.19\"></r>)؛ يليه <g>ἵνα</g>، <r v=\"John.11.37\"></r>، <r v=\"Col.4.16\"></r>، <r v=\"Rev.3.9\"></r>.</s> <s n=\"2.\"><b>يفعل</b>، <b>يعمل</b>، <b>يُجري</b>، <b>يُنفِّذ</b>: مطلقًا، مع الظرف، <g>καλῶς π.</g>، <r v=\"Matt.12.12\"></r>، <r v=\"1Cor.7.37\"></r>، <r v=\"1Cor.7.38\"></r>، <r v=\"Jas.2.19\"></r>؛ والتعبير نفسه يليه اسم الفاعل، <r v=\"Acts.10.33\"></r>، <r v=\"Phil.4.14\"></r>، <r v=\"2Pet.1.19\"></r>، <r v=\"3John.1.6\"></r>؛ <g>οὕτως</g>، <r v=\"Matt.24.46\"></r>، <r v=\"Luke.9.15\"></r>، وفي مواضع أخرى؛ <g>ὡς</g> (<g>καθώς</g>)، <r v=\"Matt.1.24\"></r> <r v=\"Matt.21.6\"></r>، وفي مواضع أخرى؛ <g>ὁμοίως</g>، <r v=\"Luke.3.11\"></r>؛ <g>ὡσαύτως</g>، <r v=\"Matt.20.5\"></r>؛ مع اسم الفاعل، <g>ἀγνοῶν ἐποίησα</g>، <r v=\"1Tim.1.13\"></r>؛ مع منصوب الشيء: <g>τί</g> الاستفهامية، <r v=\"Matt.12.3\"></r>، <r v=\"Mark.2.25\"></r>، <r v=\"Luke.6.2\"></r>، وفي مواضع أخرى؛ <g>τοῦτο</g>، <r v=\"Matt.13.28\"></r>، <r v=\"Mark.5.32\"></r>، <r v=\"Luke.22.19\"></r>، <r v=\"Rom.7.20\"></r>، وفي مواضع أخرى؛ مع أسماء تدل على أمرٍ أو فريضة: <g>τ. νόμον</g> (لا بمعنى <i>سَنّ</i> الناموس)، <r v=\"John.7.19\"></r>، <r v=\"Gal.5.3\"></r> (قارن في السبعينية <r v=\"Josh.22.5\"></r>، <r v=\"1Chr.22.12\"></r>، وفي مواضع أخرى)؛ <g>τ. ἐντολάς</g>، <r v=\"Matt.5.19\"></r>؛ وكذلك مع أسماء أخرى تدل على السلوك: <g>τ. δικαιοσύνην</g>، <r v=\"Matt.6.1\"></r>، وفي مواضع أخرى؛ <g>τ. ἀλήθειαν</g>، <r v=\"John.3.21\"></r>، وفي مواضع أخرى، إلخ؛ مع منصوبين، <r v=\"Matt.27.22\"></r>، <r v=\"Mark.15.12\"></r>؛ مع منصوب الشيء وقابل الشخص (لنفعه أو لضرره)، <r v=\"Matt.7.12\"></r>، <r v=\"Mark.5.19\"></r>، <r v=\"Mark.5.20\"></r>، <r v=\"Luke.1.49\"></r>، <r v=\"John.9.26\"></r>، وفي مواضع أخرى.</s>"},"G4183":{"l":"πολύς","o":416,"en":"<f><o>πολύς</o>, <g>πολλή, πολύ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7227\">רַב</h> and cognate forms;]</e> </et> <s n=\"1.\">as adj., <b>much</b>, <b>many</b>, <b>great</b>, of number, space, degree, value, time, etc.: <g>ἀριθμός</g>, <r v=\"Acts.11.21\"></r>; <g>ὄχλος</g>, <r v=\"Mark.5.24\"></r>; <g>θερισμός</g>, <r v=\"Matt.9.37\"></r>; <g>χόρτος</g>, <r v=\"John.6.10\"></r>; <g>χρόνος</g>, <r v=\"Matt.25.19\"></r>; <g>γογγυσμός</g>, <r v=\"John.7.12\"></r>; <g>πόνος</g>, <r v=\"Col.4.13\"></r>; <g>δόξα</g>, <r v=\"Matt.24.30\"></r>; <g>σιγή</g>, <r v=\"Acts.21.40\"></r>; pl., <g>προφῆται</g>, <r v=\"Matt.13.17\"></r>; <g>ὄχλοι</g>, <r v=\"Matt.4.25\"></r>; <g>δαιμόνια</g>, <r v=\"Mark.1.34\"></r>; <g>δυνάμεις</g>, <r v=\"Matt.7.22\"></r>,</s> <s n=\"2.\">As subst., pl. masc., <g>πολλοί</g>, <b>many</b> (persons): <r v=\"Matt.7.22\"></r>, <r v=\"Mark.2.2\"></r>, al.; c. gen. partit., <r v=\"Matt.3.7\"></r>, <r v=\"Luke.1.16\"></r>, al.; seq. <g>ἐκ</g>, <r v=\"John.7.31\"></r>, <r v=\"Acts.17.12\"></r>; c. art., <g>οἱ π.</g>, <b>the many</b>, <r v=\"Matt.24.12\"></r>, <r v=\"Rom.12.5\"></r>, <r v=\"1Cor.10.17\"></r>, <r v=\"1Cor.10.33\"></r>, <r v=\"2Cor.2.17\"></r>; opp. to <g>ὁ εἶς</g> (Lft., <i>Notes</i>, 291), <r v=\"Rom.5.15\"></r>, <r v=\"Rom.5.19\"></r>; neut. pl., <g>πολλά</g>: <r v=\"Matt.13.3\"></r>, <r v=\"Mark.5.26\"></r>, al.; acc. with adverbial force, <r v=\"Mark.1.45\"></r>, <r v=\"Rom.16.6\"></r> (Deiss., <i>LAE</i>, 317), <r v=\"1Cor.16.12\"></r>, <r v=\"Jas.3.2\"></r>, al.; neut. sing., <g>πολύ</g>: <r v=\"Luke.12.48\"></r>; adverbially, <r v=\"Mark.12.27\"></r>, al.; <g>πολλοῦ</g> (gen. pret.), <r v=\"Matt.26.9\"></r>; c. compar. (Bl., § 44, 5), <g>π. σπουδαιότερον</g>, <r v=\"2Cor.8.22\"></r>; <g>πολλῷ πλείους</g>, <r v=\"John.4.41\"></r>.</s> <s>Compar., <f><o>πλείων</o>,</f> neut., <g>πλεῖον</g> and <g>πλέον</g> (v. WH, <i>App.</i>, 151), pl., <g>πλείονες</g>, <g>-ας</g>, <g>-α</g>, contr., <g>πλείους</g>, <g>-ω</g> (cf. Mayser, 69), <b>more</b>, <b>greater</b>; <s n=\"1.\">as adj.: <r v=\"John.15.2\"></r>, <r v=\"Acts.18.20\"></r>, <r v=\"Heb.3.3\"></r>; seq. <g>παρά</g>, <r v=\"Heb.11.4\"></r> (cf. Westc, in l. Was <g>ΠΛΙΟΝΑ</g> here a primitive error for <g>ΗΔΙΟΝΑ</g>?); pi., <r v=\"Acts.13.31\"></r>, al.; c. gen. compar., <r v=\"Matt.21.36\"></r>; c. num. (<g>ἤ</g> of comp. omitted), <r v=\"Acts.4.22\"></r> <r v=\"Acts.24.11\"></r>, al.</s> <s n=\"2.\">As subst., <g>οἱ π.</g>, <b>the greater number</b>: <r v=\"Acts.19.32\"></r> <r v=\"Acts.27.12\"></r>, <r v=\"1Cor.10.5\"></r> <r v=\"1Cor.15.6\"></r>; also (Bl., § 44, 3) <b>others</b>, <b>more</b>, <b>the more</b>: <r v=\"2Cor.2.6\"></r> <r v=\"2Cor.4.15\"></r>, <r v=\"Phil.1.14\"></r>; <g>πλείονα</g>, <r v=\"Luke.11.53\"></r>; <g>πλειον</g>, <g>πλέον</g>, <r v=\"Matt.20.10\"></r>, <r v=\"2Tim.3.9\"></r>; c. gen. comp., <r v=\"Mark.12.43\"></r> <r v=\"Mark.12.43\"></r>, <r v=\"Luke.21.3\"></r>; <g>π. Ἰωνᾶ ὧδε</g>, <r v=\"Matt.12.41\"></r>; adverbially, <r v=\"Acts.4.17\"></r> <r v=\"Acts.20.9\"></r> <r v=\"Acts.24.4\"></r>.</s> <s n=\"3.\">As adv., <g>πλεῖον</g>: seq. <g>ἤ</g>, <r v=\"Luke.9.13\"></r>; c. gen. comp., <r v=\"Matt.5.20\"></r>; <g>πλείω</g>: c. num., <r v=\"Matt.26.53\"></r>.</s></s> <s>Superl., <f><o>πλεῖστος</o>, <g>-η, -ον</g>,</f> <s n=\"(a)\">prop., <b>most</b>: <r v=\"Matt.11.20\"></r> <r v=\"Matt.21.8\"></r>; adverbially, <g>τὸ π.</g>, <r v=\"1Cor.14.27\"></r>;</s> <s n=\"(b)\">elative (M, <i>Pr.</i>, 79), <b>very great</b>: <g>ὄχλος π.</g>, <r v=\"Mark.4.1\"></r>.</s></s>","ar":"<f><o>πολύς</o>، <g>πολλή, πολύ</g>،</f> <s n=\"1.\">صفةً، <b>كثير</b>، <b>عديد</b>، <b>عظيم</b>، عن العدد والمساحة والدرجة والقيمة والزمن ونحوها: <g>ἀριθμός</g>، <r v=\"Acts.11.21\"></r>؛ <g>ὄχλος</g>، <r v=\"Mark.5.24\"></r>؛ <g>θερισμός</g>، <r v=\"Matt.9.37\"></r>؛ <g>χόρτος</g>، <r v=\"John.6.10\"></r>؛ <g>χρόνος</g>، <r v=\"Matt.25.19\"></r>؛ <g>γογγυσμός</g>، <r v=\"John.7.12\"></r>؛ <g>πόνος</g>، <r v=\"Col.4.13\"></r>؛ <g>δόξα</g>، <r v=\"Matt.24.30\"></r>؛ <g>σιγή</g>، <r v=\"Acts.21.40\"></r>؛ جمعًا، <g>προφῆται</g>، <r v=\"Matt.13.17\"></r>؛ <g>ὄχλοι</g>، <r v=\"Matt.4.25\"></r>؛ <g>δαιμόνια</g>، <r v=\"Mark.1.34\"></r>؛ <g>δυνάμεις</g>، <r v=\"Matt.7.22\"></r>،</s> <s n=\"2.\">اسمًا، جمع مذكر، <g>πολλοί</g>، <b>كثيرون</b> (من الناس): <r v=\"Matt.7.22\"></r>، <r v=\"Mark.2.2\"></r>، وفي مواضع أخرى؛ مع المضاف إليه التبعيضي، <r v=\"Matt.3.7\"></r>، <r v=\"Luke.1.16\"></r>، وفي مواضع أخرى؛ يليه <g>ἐκ</g>، <r v=\"John.7.31\"></r>، <r v=\"Acts.17.12\"></r>؛ مع أداة التعريف، <g>οἱ π.</g>، <b>الكثيرون</b>، <r v=\"Matt.24.12\"></r>، <r v=\"Rom.12.5\"></r>، <r v=\"1Cor.10.17\"></r>، <r v=\"1Cor.10.33\"></r>، <r v=\"2Cor.2.17\"></r>؛ عكس <g>ὁ εἶς</g>، <r v=\"Rom.5.15\"></r>، <r v=\"Rom.5.19\"></r>؛ جمع محايد، <g>πολλά</g>: <r v=\"Matt.13.3\"></r>، <r v=\"Mark.5.26\"></r>، وفي مواضع أخرى؛ منصوبًا بمعنى الظرف، <r v=\"Mark.1.45\"></r>، <r v=\"Rom.16.6\"></r>، <r v=\"1Cor.16.12\"></r>، <r v=\"Jas.3.2\"></r>، وفي مواضع أخرى؛ مفرد محايد، <g>πολύ</g>: <r v=\"Luke.12.48\"></r>؛ ظرفًا، <r v=\"Mark.12.27\"></r>، وفي مواضع أخرى؛ <g>πολλοῦ</g> (مضاف إليه الثمن)، <r v=\"Matt.26.9\"></r>؛ مع صيغة التفضيل، <g>π. σπουδαιότερον</g>، <r v=\"2Cor.8.22\"></r>؛ <g>πολλῷ πλείους</g>، <r v=\"John.4.41\"></r>.</s> <s>صيغة التفضيل، <f><o>πλείων</o>،</f> المحايد <g>πλεῖον</g> و<g>πλέον</g>، الجمع <g>πλείονες</g>، <g>-ας</g>، <g>-α</g>، والمُدغَم <g>πλείους</g>، <g>-ω</g>، <b>أكثر</b>، <b>أعظم</b>؛ <s n=\"1.\">صفةً: <r v=\"John.15.2\"></r>، <r v=\"Acts.18.20\"></r>، <r v=\"Heb.3.3\"></r>؛ يليه <g>παρά</g>، <r v=\"Heb.11.4\"></r>؛ جمعًا، <r v=\"Acts.13.31\"></r>، وفي مواضع أخرى؛ مع المضاف إليه للمفاضلة، <r v=\"Matt.21.36\"></r>؛ مع العدد (مع حذف <g>ἤ</g> المفاضلة)، <r v=\"Acts.4.22\"></r> <r v=\"Acts.24.11\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\">اسمًا، <g>οἱ π.</g>، <b>الأكثرون</b>: <r v=\"Acts.19.32\"></r> <r v=\"Acts.27.12\"></r>، <r v=\"1Cor.10.5\"></r> <r v=\"1Cor.15.6\"></r>؛ وأيضًا <b>آخرون</b>، <b>أكثر</b>، <b>الأكثر</b>: <r v=\"2Cor.2.6\"></r> <r v=\"2Cor.4.15\"></r>، <r v=\"Phil.1.14\"></r>؛ <g>πλείονα</g>، <r v=\"Luke.11.53\"></r>؛ <g>πλειον</g>، <g>πλέον</g>، <r v=\"Matt.20.10\"></r>، <r v=\"2Tim.3.9\"></r>؛ مع المضاف إليه للمفاضلة، <r v=\"Mark.12.43\"></r> <r v=\"Mark.12.43\"></r>، <r v=\"Luke.21.3\"></r>؛ <g>π. Ἰωνᾶ ὧδε</g>، <r v=\"Matt.12.41\"></r>؛ ظرفًا، <r v=\"Acts.4.17\"></r> <r v=\"Acts.20.9\"></r> <r v=\"Acts.24.4\"></r>.</s> <s n=\"3.\">ظرفًا، <g>πλεῖον</g>: يليه <g>ἤ</g>، <r v=\"Luke.9.13\"></r>؛ مع المضاف إليه للمفاضلة، <r v=\"Matt.5.20\"></r>؛ <g>πλείω</g>: مع العدد، <r v=\"Matt.26.53\"></r>.</s></s> <s>صيغة التفضيل العليا، <f><o>πλεῖστος</o>، <g>-η, -ον</g>،</f> <s n=\"(a)\">بالمعنى الحرفي، <b>الأكثر</b>: <r v=\"Matt.11.20\"></r> <r v=\"Matt.21.8\"></r>؛ ظرفًا، <g>τὸ π.</g>، <r v=\"1Cor.14.27\"></r>؛</s> <s n=\"(b)\">بمعنى المبالغة، <b>عظيم جدًّا</b>: <g>ὄχλος π.</g>، <r v=\"Mark.4.1\"></r>.</s></s>"},"G4214":{"l":"πόσος","o":27,"en":"<f><o>πόσος</o>, <g>-η, -ον</g>,</f> adj. of number, magnitude, degree, etc., <s><b>how much</b>, <b>how great</b>, <b>how many</b>: <r v=\"Matt.6.23\"></r>, <r v=\"2Cor.7.11\"></r>; of time, <r v=\"Mark.9.21\"></r>; neut., absol., <r v=\"Luke.16.5\"></r>, <r v=\"Luke.16.7\"></r>; dat., <g>πόσῳ</g>, adverbially, <b>how much</b>, <r v=\"Matt.12.12\"></r>; id. seq. <g>μᾶλλον</g>, <r v=\"Matt.7.11\"></r> <r v=\"Matt.10.25\"></r>, <r v=\"Luke.11.13\"></r> <r v=\"Luke.12.24\"></r>, <r v=\"Luke.12.28\"></r>, <r v=\"Rom.11.12\"></r>, <r v=\"Rom.11.24\"></r>, <r v=\"Phlm.1.16\"></r>, <r v=\"Heb.9.14\"></r>; <g>π. χείρονος τιμωρίας</g>, <r v=\"Heb.10.29\"></r>; pl., <r v=\"Matt.15.34\"></r> <r v=\"Matt.16.9\"></r>, <r v=\"Matt.16.10\"></r> <r v=\"Matt.27.13\"></r>, <r v=\"Mark.6.38\"></r> <r v=\"Mark.8.5\"></r>, <r v=\"Mark.8.19\"></r>, <r v=\"Mark.8.20\"></r> <r v=\"Mark.15.4\"></r>, <r v=\"Luke.15.17\"></r>, <r v=\"Acts.21.20\"></r>.†</s>","ar":"<f><o>πόσος</o>، <g>-η, -ον</g>،</f> صفة للعدد والمقدار والدرجة إلخ، <s><b>كم</b>، <b>ما أعظم</b>، <b>كم عددًا</b>: <r v=\"Matt.6.23\"></r>، <r v=\"2Cor.7.11\"></r>؛ عن الزمن، <r v=\"Mark.9.21\"></r>؛ المحايد، مطلقًا، <r v=\"Luke.16.5\"></r>، <r v=\"Luke.16.7\"></r>؛ حالة القابل <g>πόσῳ</g> ظرفًا: <b>بكم</b> (كم بالحري)، <r v=\"Matt.12.12\"></r>؛ والتعبير نفسه يليه <g>μᾶλλον</g> (كم بالحري)، <r v=\"Matt.7.11\"></r> <r v=\"Matt.10.25\"></r>، <r v=\"Luke.11.13\"></r> <r v=\"Luke.12.24\"></r>، <r v=\"Luke.12.28\"></r>، <r v=\"Rom.11.12\"></r>، <r v=\"Rom.11.24\"></r>، <r v=\"Phlm.1.16\"></r>، <r v=\"Heb.9.14\"></r>؛ <g>π. χείρονος τιμωρίας</g> (فكم عقابًا أشرّ)، <r v=\"Heb.10.29\"></r>؛ جمع، <r v=\"Matt.15.34\"></r> <r v=\"Matt.16.9\"></r>، <r v=\"Matt.16.10\"></r> <r v=\"Matt.27.13\"></r>، <r v=\"Mark.6.38\"></r> <r v=\"Mark.8.5\"></r>، <r v=\"Mark.8.19\"></r>، <r v=\"Mark.8.20\"></r> <r v=\"Mark.15.4\"></r>، <r v=\"Luke.15.17\"></r>، <r v=\"Acts.21.20\"></r>.†</s>"},"G4218":{"l":"ποτέ","o":29,"en":"<f><o>ποτέ</o>,</f> enclitic particle, <s n=\"1.\"><b>once</b>, <b>formerly</b>, <b>sometime</b>: of the past, <r v=\"John.9.13\"></r>, <r v=\"Rom.7.9\"></r> <r v=\"Rom.11.30\"></r>, <r v=\"Gal.1.13\"></r>, <r v=\"Gal.1.23\"></r> <r v=\"Gal.2.6\"></r> (Lft., in l.), <r v=\"Eph.2.2\"></r>, <r v=\"Eph.2.3\"></r>, <r v=\"Eph.2.11\"></r>, <r v=\"Eph.2.13\"></r> <r v=\"Eph.5.8\"></r>, <r v=\"Col.1.21\"></r> <r v=\"Col.3.7\"></r>, <r v=\"1Thess.2.5\"></r>, <r v=\"Titus.3.3\"></r>, <r v=\"Phlm.1.11\"></r>, <r v=\"1Pet.2.10\"></r> <r v=\"1Pet.3.5\"></r>, <r v=\"1Pet.3.20\"></r>; <g>ἤδη ποτέ</g>, <b>now at length</b>, <r v=\"Phil.4.10\"></r>; of the fut., <r v=\"Luke.22.32\"></r>; <g>εἴ πως ἤδη ποτέ</g>, <b>if sometime soon at length</b>, <r v=\"Rom.1.10\"></r>.</s> <s n=\"2.\"><b>ever</b>: after a neg., <r v=\"Eph.5.29\"></r>, <r v=\"2Pet.1.10\"></r>, <r v=\"2Pet.1.21\"></r>; in a question, <g>τίς π.</g>, <r v=\"1Cor.9.7\"></r>, <r v=\"Heb.1.5\"></r>, <r v=\"Heb.1.13\"></r>.†</s>","ar":"<f><o>ποτέ</o>،</f> أداة ملحقة، <s n=\"1.\"><b>مرةً</b>، <b>قبلاً</b>، <b>حينًا</b>: عن الماضي، <r v=\"John.9.13\"></r>، <r v=\"Rom.7.9\"></r> <r v=\"Rom.11.30\"></r>، <r v=\"Gal.1.13\"></r>، <r v=\"Gal.1.23\"></r> <r v=\"Gal.2.6\"></r>، <r v=\"Eph.2.2\"></r>، <r v=\"Eph.2.3\"></r>، <r v=\"Eph.2.11\"></r>، <r v=\"Eph.2.13\"></r> <r v=\"Eph.5.8\"></r>، <r v=\"Col.1.21\"></r> <r v=\"Col.3.7\"></r>، <r v=\"1Thess.2.5\"></r>، <r v=\"Titus.3.3\"></r>، <r v=\"Phlm.1.11\"></r>، <r v=\"1Pet.2.10\"></r> <r v=\"1Pet.3.5\"></r>، <r v=\"1Pet.3.20\"></r>؛ <g>ἤδη ποτέ</g>، <b>الآن أخيرًا</b>، <r v=\"Phil.4.10\"></r>؛ عن المستقبل، <r v=\"Luke.22.32\"></r>؛ <g>εἴ πως ἤδη ποτέ</g>، <b>لعلّه الآن أخيرًا</b>، <r v=\"Rom.1.10\"></r>.</s> <s n=\"2.\"><b>قطّ</b>، <b>أبدًا</b>: بعد النفي، <r v=\"Eph.5.29\"></r>، <r v=\"2Pet.1.10\"></r>، <r v=\"2Pet.1.21\"></r>؛ في السؤال، <g>τίς π.</g>، <r v=\"1Cor.9.7\"></r>، <r v=\"Heb.1.5\"></r>، <r v=\"Heb.1.13\"></r>.†</s>"},"G4246":{"l":"πρεσβύτης","o":3,"en":"<f><o>πρεσβύτης</o>, <g>-ου </g> prose form of <g>πρέσβυς</g>, q.v.,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2205\">זָקֵן</h>, <r v=\"Gen.25.8\"></r>, al.; also (= <g>πρεσβευτής</g>), <r v=\"2Chr.32.31\"></r> B<i>1</i> (<h n=\"H3887\">מֵלִיץ</h>), <r v=\"1Macc.14.22\"></r> S, al. (v. Thackeray, <i>Gr.</i>, 97);]</e> </et> <s n=\"1.\"><b>an old man</b>: <r v=\"Luke.1.18\"></r>, <r v=\"Titus.2.2\"></r>, <r v=\"Phlm.1.9\"></r> (R, txt., but v. infr.).</s> <s n=\"2.\">As in LXX, also = <g>πρεσβευτής</g>, <b>an ambassador</b>: <r v=\"Phlm.1.9\"></r> (R, mg., v. Lft. and <i>ICC</i>, in l.).†</s>","ar":"<f><o>πρεσβύτης</o>، <g>-ου </g>، الصيغة النثرية لـ<g>πρέσβυς</g> (انظره)،</f> <s n=\"1.\"><b>شيخ، رجل مسنّ</b>: <r v=\"Luke.1.18\"></r>، <r v=\"Titus.2.2\"></r>، <r v=\"Phlm.1.9\"></r> (لكن انظر أدناه).</s> <s n=\"2.\">كما في السبعينية، بمعنى <g>πρεσβευτής</g> أيضًا: <b>سفير</b>: <r v=\"Phlm.1.9\"></r>.†</s>"},"G4314":{"l":"πρός","o":700,"en":"<f><o>πρός</o>,</f> prep. c. gen., dat., acc. <s n=\"I.\">C. gen., of motion from a place, <b>from the side of</b>, hence metaph., <b>in the interests of</b>, <r v=\"Acts.27.34\"></r> (cf. Page, in l.).</s> <s n=\"II.\">C. dat., of local proximity, <b>hard by</b>, <b>near</b>, <b>at</b>: <r v=\"Mark.5.11\"></r>, <r v=\"Luke.19.37\"></r>, <r v=\"John.18.16\"></r> <r v=\"John.20.11\"></r>, <r v=\"John.20.12\"></r>, <r v=\"Rev.1.13\"></r>.</s> <s n=\"III.\">C. acc., of motion or direction towards a place or object, <b>to</b>, <b>towards</b>. <s n=\"1.\">Of place, <s n=\"(a)\">after verbs of motion or of speaking and other words with the idea of direction: <g>ἔρχομαι</g>, <g>ἀναβαίνω</g>, <g>πορεύομαι</g>, <g>λέγω</g>, <g>ἐπιστολή</g>, etc., <r v=\"Matt.3.14\"></r>, <r v=\"Mark.6.51\"></r>, <r v=\"Luke.11.5\"></r>, <r v=\"John.2.3\"></r>, <r v=\"Acts.9.2\"></r>, al. mult.; metaph., of mental direction, hostile or otherwise, <r v=\"Luke.23.12\"></r>, <r v=\"John.6.52\"></r>, <r v=\"2Cor.7.4\"></r>, <r v=\"Eph.6.12\"></r>, <r v=\"Col.3.13\"></r>, al.; of the issue or end, <r v=\"Luke.14.32\"></r>, <r v=\"John.11.4\"></r>, al.; of purpose, <r v=\"Matt.26.12\"></r>, <r v=\"Rom.3.26\"></r>, <r v=\"1Cor.6.5\"></r>, al.; <g>πρὸς τό</g>, c. inf., denoting purpose (cf. M, <i>Pr.</i>, 218, 220; Lft., <i>Notes</i>, 131), <r v=\"Matt.5.28\"></r>, <r v=\"Mark.13.22\"></r>, <r v=\"Eph.6.11\"></r>, <r v=\"1Thess.2.9\"></r>, al.;</s> <s n=\"(b)\">of close proximity, <b>at</b>, <g>by</g>, <b>with</b>: <r v=\"Matt.3.10\"></r>, <r v=\"Mark.11.4\"></r>, <r v=\"Luke.4.11\"></r>, <r v=\"Acts.3.2\"></r>, al.; after <g>εἶναι</g>, <r v=\"Matt.13.56\"></r>, <r v=\"Mark.6.3\"></r>, <r v=\"John.1.1\"></r>, al.</s> </s> <s n=\"2.\">Of time, <s n=\"(a)\"><b>towards</b> (Plat., Xen., LXX: <r v=\"Gen.8.11\"></r>, al.): <r v=\"Luke.24.29\"></r>;</s> <s n=\"(b)\"><b>for</b>: <g>πρὸς καιρόν</g>, <r v=\"Luke.8.13\"></r>, <r v=\"1Cor.7.5\"></r>; <g>πρὸς ὥραν</g>, <r v=\"John.5.35\"></r>, al.; <g>πρὸς ὀλίγον</g>, <r v=\"Jas.4.14\"></r>.</s> </s> <s n=\"3.\">Of relation <s n=\"(a)\"><b>toward</b>, <b>with</b>: <r v=\"Rom.5.1\"></r>, <r v=\"2Cor.1.12\"></r>, <r v=\"Col.4.5\"></r>, <r v=\"1Thess.4.12\"></r>, al.;</s> <s n=\"(b)\"><b>with regard to</b>: <r v=\"Matt.19.8\"></r>, <r v=\"Mark.12.12\"></r>, <r v=\"Rom.8.31\"></r>, al.;</s> <s n=\"(c)\"><b>pertaining to</b>, <b>to</b>: <r v=\"Matt.27.4\"></r>, <r v=\"John.21.22\"></r>, <r v=\"Rom.15.17\"></r>, <r v=\"Heb.2.17\"></r> <r v=\"Heb.5.1\"></r>;</s> <s n=\"(d)\"><b>according to</b>: <r v=\"Luke.12.47\"></r>, <r v=\"2Cor.5.10\"></r>, <r v=\"Gal.2.14\"></r>, <r v=\"Eph.3.4\"></r> <r v=\"Eph.4.14\"></r>;</s> <s n=\"(e)\"><b>in comparison with</b>: <r v=\"Rom.8.18\"></r>.</s> </s> </s> <s n=\"IV.\">In composition: <b>towards</b> (<g>προσέρχομαι</g>), <b>to</b> (<g>προσάγω</g>), <b>against</b> (<g>προσκόπτω</g>), <b>besides</b> (<g>προσδαπανάω</g>).</s>","ar":"<f><o>πρός</o>،</f> حرف جر مع المضاف إليه ومع القابل ومع المنصوب. <s n=\"I.\">مع المضاف إليه، للحركة من مكان: <b>من جهة</b>، ومن ثَمَّ مجازيًا: <b>لمصلحة، لأجل</b>، <r v=\"Acts.27.34\"></r>.</s> <s n=\"II.\">مع القابل، للقرب المكاني: <b>بجانب</b>، <b>قرب</b>، <b>عند</b>: <r v=\"Mark.5.11\"></r>، <r v=\"Luke.19.37\"></r>، <r v=\"John.18.16\"></r> <r v=\"John.20.11\"></r>، <r v=\"John.20.12\"></r>، <r v=\"Rev.1.13\"></r>.</s> <s n=\"III.\">مع المنصوب، للحركة أو الاتجاه نحو مكان أو شيء: <b>إلى</b>، <b>نحو</b>. <s n=\"1.\">للمكان، <s n=\"(a)\">بعد أفعال الحركة أو الكلام وألفاظ أخرى تتضمن معنى الاتجاه: <g>ἔρχομαι</g>، <g>ἀναβαίνω</g>، <g>πορεύομαι</g>، <g>λέγω</g>، <g>ἐπιστολή</g>، إلخ، <r v=\"Matt.3.14\"></r>، <r v=\"Mark.6.51\"></r>، <r v=\"Luke.11.5\"></r>، <r v=\"John.2.3\"></r>، <r v=\"Acts.9.2\"></r>، وفي مواضع أخرى كثيرة؛ مجازيًا، عن اتجاه الذهن، عدائيًا كان أو غير ذلك، <r v=\"Luke.23.12\"></r>، <r v=\"John.6.52\"></r>، <r v=\"2Cor.7.4\"></r>، <r v=\"Eph.6.12\"></r>، <r v=\"Col.3.13\"></r>، وفي مواضع أخرى؛ عن العاقبة أو النهاية، <r v=\"Luke.14.32\"></r>، <r v=\"John.11.4\"></r>، وفي مواضع أخرى؛ عن الغرض، <r v=\"Matt.26.12\"></r>، <r v=\"Rom.3.26\"></r>، <r v=\"1Cor.6.5\"></r>، وفي مواضع أخرى؛ <g>πρὸς τό</g> مع المصدر، للدلالة على الغرض (لكي)، <r v=\"Matt.5.28\"></r>، <r v=\"Mark.13.22\"></r>، <r v=\"Eph.6.11\"></r>، <r v=\"1Thess.2.9\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">للقرب الشديد: <b>عند</b>، <b>بجانب</b>، <b>مع</b>: <r v=\"Matt.3.10\"></r>، <r v=\"Mark.11.4\"></r>، <r v=\"Luke.4.11\"></r>، <r v=\"Acts.3.2\"></r>، وفي مواضع أخرى؛ بعد <g>εἶναι</g>، <r v=\"Matt.13.56\"></r>، <r v=\"Mark.6.3\"></r>، <r v=\"John.1.1\"></r>، وفي مواضع أخرى.</s> </s> <s n=\"2.\">للزمان، <s n=\"(a)\"><b>نحو</b> (السبعينية: <r v=\"Gen.8.11\"></r>، وفي مواضع أخرى): <r v=\"Luke.24.29\"></r>؛</s> <s n=\"(b)\"><b>إلى، لمدة</b>: <g>πρὸς καιρόν</g> (إلى حين)، <r v=\"Luke.8.13\"></r>، <r v=\"1Cor.7.5\"></r>؛ <g>πρὸς ὥραν</g> (ساعةً)، <r v=\"John.5.35\"></r>، وفي مواضع أخرى؛ <g>πρὸς ὀλίγον</g> (قليلاً)، <r v=\"Jas.4.14\"></r>.</s> </s> <s n=\"3.\">للعلاقة، <s n=\"(a)\"><b>نحو</b>، <b>مع</b>: <r v=\"Rom.5.1\"></r>، <r v=\"2Cor.1.12\"></r>، <r v=\"Col.4.5\"></r>، <r v=\"1Thess.4.12\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\"><b>من جهة، بالنسبة إلى</b>: <r v=\"Matt.19.8\"></r>، <r v=\"Mark.12.12\"></r>، <r v=\"Rom.8.31\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\"><b>فيما يخص</b>، <b>لـ</b>: <r v=\"Matt.27.4\"></r>، <r v=\"John.21.22\"></r>، <r v=\"Rom.15.17\"></r>، <r v=\"Heb.2.17\"></r> <r v=\"Heb.5.1\"></r>؛</s> <s n=\"(d)\"><b>بحسب</b>: <r v=\"Luke.12.47\"></r>، <r v=\"2Cor.5.10\"></r>، <r v=\"Gal.2.14\"></r>، <r v=\"Eph.3.4\"></r> <r v=\"Eph.4.14\"></r>؛</s> <s n=\"(e)\"><b>بالمقارنة مع، بالقياس إلى</b>: <r v=\"Rom.8.18\"></r>.</s> </s> </s> <s n=\"IV.\">في التركيب: <b>نحو</b> (<g>προσέρχομαι</g>)، <b>إلى</b> (<g>προσάγω</g>)، <b>ضد</b> (<g>προσκόπτω</g>)، <b>فضلاً عن، علاوة على</b> (<g>προσδαπανάω</g>).</s>"},"G433":{"l":"ἀνήκω","o":3,"en":"<f><o>ἀν-ήκω</o></f> <et> <e t=\"derivation\">(<x><g>ἀνά</g></x>, <x><g>ἥκω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Josh.23.14\"></r> (<h n=\"H935\">בּוֹא</h>), <r v=\"1Sam.27.8\"></r>, <r v=\"SirP.1.10\"></r>, I, II Mac<i>6</i>*;]</e> </et> <s>prop., <b>to have come up to</b>; in later writers, impers. <b>it is due</b>, <b>it is befitting</b>: in ethical sense (MM, <i>VGT</i>, s.v.), <r v=\"Eph.5.4\"></r>, <r v=\"Col.3.18\"></r>; <g>τὸ ἀνῆκον</g>, <r v=\"Phlm.1.8\"></r>.†</s>","ar":"<f><o>ἀν-ήκω</o></f> <s>أصلاً: <b>يكون قد بلغ إلى</b>؛ وعند المتأخرين، غير شخصي: <b>يليق</b>، <b>يجب، ينبغي</b>: بالمعنى الأخلاقي، <r v=\"Eph.5.4\"></r>، <r v=\"Col.3.18\"></r>؛ <g>τὸ ἀνῆκον</g> (ما يليق)، <r v=\"Phlm.1.8\"></r>.†</s>"},"G4335":{"l":"προσευχή","o":36,"en":"<f>† <o>προσ-ευχή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>προσεύχομαι</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8605\">תְּפִלָּה</h>;]</e> </et> <s n=\"1.\"><b>prayer</b> to God: <r v=\"Matt.17.21\"></r> (WH, R, txt., om.) <r v=\"Matt.21.22\"></r>, <r v=\"Mark.9.29\"></r>, <r v=\"Luke.22.45\"></r>, <r v=\"Acts.3.1\"></r> <r v=\"Acts.6.4\"></r> <r v=\"Acts.10.31\"></r>, <r v=\"Rom.12.12\"></r>, <r v=\"1Cor.7.5\"></r>, <r v=\"Col.4.2\"></r>; pl., <r v=\"Acts.2.42\"></r> <r v=\"Acts.10.4\"></r>, <r v=\"Rom.1.10\"></r>, <r v=\"Eph.1.16\"></r>, <r v=\"Col.4.12\"></r>, <r v=\"1Thess.1.2\"></r>, <r v=\"Phlm.1.4\"></r>, <r v=\"Phlm.1.22\"></r>, <r v=\"1Pet.3.7\"></r> <r v=\"1Pet.4.7\"></r>, <r v=\"Rev.5.8\"></r> <r v=\"Rev.8.3\"></r>, <r v=\"Rev.8.4\"></r>; <g>οἶκος προσευχῆς</g>, <r v=\"Matt.21.13\"></r>, <r v=\"Mark.11.17\"></r>, <r v=\"Luke.19.46\"></r> (LXX); <g>π. καὶ δέησις</g>, <r v=\"Eph.6.18\"></r>, <r v=\"Phil.4.6\"></r>; pl., <r v=\"1Tim.2.1\"></r> <r v=\"1Tim.5.5\"></r>; <g>ἡ π. τοῦ θεοῦ</g>, <b>prayer to God</b> (cf. <r v=\"Wis.16.28\"></r>), <r v=\"Luke.6.12\"></r>; <g>πρὸς τ. θεόν</g>, seq. <g>ὑπέρ</g>, <r v=\"Acts.12.5\"></r>; pl., <r v=\"Rom.15.30\"></r>; Hebraistically (Bl., § 38, 3), <g>προσευχῇ προσεύχεσθαι</g>, <r v=\"Jas.5.17\"></r> (EV, <i>prayed fervently</i>).</s> <s n=\"2.\"><b>a place of prayer</b>: of a synagogue (<r v=\"3Macc.7.20\"></r>, v.l.; v. Charles, <i>APOT</i>, i, 173; for other exx., v. Kennedy, <i>Sources</i>, 114); of a place in the open (FlJ, <i>Ant.</i>, xiv, 10, 23), <r v=\"Acts.16.13\"></r>, <r v=\"Acts.16.16\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>δέησις</g>.</sy>","ar":"<f>† <o>προσ-ευχή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\"><b>صلاة</b> إلى الله: <r v=\"Matt.17.21\"></r>، <r v=\"Matt.21.22\"></r>، <r v=\"Mark.9.29\"></r>، <r v=\"Luke.22.45\"></r>، <r v=\"Acts.3.1\"></r>، <r v=\"Acts.6.4\"></r>، <r v=\"Acts.10.31\"></r>، <r v=\"Rom.12.12\"></r>، <r v=\"1Cor.7.5\"></r>، <r v=\"Col.4.2\"></r>؛ في الجمع: <r v=\"Acts.2.42\"></r>، <r v=\"Acts.10.4\"></r>، <r v=\"Rom.1.10\"></r>، <r v=\"Eph.1.16\"></r>، <r v=\"Col.4.12\"></r>، <r v=\"1Thess.1.2\"></r>، <r v=\"Phlm.1.4\"></r>، <r v=\"Phlm.1.22\"></r>، <r v=\"1Pet.3.7\"></r>، <r v=\"1Pet.4.7\"></r>، <r v=\"Rev.5.8\"></r>، <r v=\"Rev.8.3\"></r>، <r v=\"Rev.8.4\"></r>؛ <g>οἶκος προσευχῆς</g>: <r v=\"Matt.21.13\"></r>، <r v=\"Mark.11.17\"></r>، <r v=\"Luke.19.46\"></r> (السبعينية)؛ <g>π. καὶ δέησις</g>: <r v=\"Eph.6.18\"></r>، <r v=\"Phil.4.6\"></r>؛ في الجمع: <r v=\"1Tim.2.1\"></r>، <r v=\"1Tim.5.5\"></r>؛ <g>ἡ π. τοῦ θεοῦ</g>: <b>الصلاة إلى الله</b> (قارن <r v=\"Wis.16.28\"></r>): <r v=\"Luke.6.12\"></r>؛ <g>πρὸς τ. θεόν</g> يليه <g>ὑπέρ</g>: <r v=\"Acts.12.5\"></r>؛ في الجمع: <r v=\"Rom.15.30\"></r>؛ على الطريقة العبرية، <g>προσευχῇ προσεύχεσθαι</g>: <r v=\"Jas.5.17\"></r> (<i>صلّى بلجاجة</i>).</s> <s n=\"2.\"><b>مكان صلاة</b>: عن المجمع (قارن <r v=\"3Macc.7.20\"></r>، بقراءة مختلفة)؛ عن مكان في الخلاء: <r v=\"Acts.16.13\"></r>، <r v=\"Acts.16.16\"></r>.†</s>"},"G4355":{"l":"προσλαμβάνω","o":12,"en":"<f><o>προσ-λαμβάνω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.18.16\"></r> (<h n=\"H4871\">משׁה</h> hi.), <r v=\"Ps.73.24\"></r> (<h n=\"H3947\">לקח</h>), etc.;]</e> </et> <s n=\"1.\"><b>to take in addition</b>.</s> <s n=\"2.\"><b>to take to oneself</b>, <b>take</b>, <b>receive</b>; in NT always mid., <g>-ομαι</g>; <s n=\"(a)\">of things: of food, c. acc., <r v=\"Acts.27.33\"></r>; c. gen. part., <r v=\"Acts.27.36\"></r>;</s> <s n=\"(b)\">of persons: c. acc., <r v=\"Matt.16.22\"></r>, <r v=\"Mark.8.32\"></r> (v. Swete, in l.), <r v=\"Acts.17.5\"></r> <r v=\"Acts.18.26\"></r> <r v=\"Acts.28.2\"></r>, <r v=\"Rom.14.1\"></r>, <r v=\"Rom.14.3\"></r> <r v=\"Rom.15.7\"></r>, <r v=\"Phlm.1.17\"></r>.†</s> </s>","ar":"<f><o>προσ-λαμβάνω</o>،</f> <s n=\"1.\"><b>أخذ زيادةً، أضاف</b>.</s> <s n=\"2.\"><b>أخذ إليه</b>، <b>أخذ</b>، <b>قَبِل</b>؛ وهو في العهد الجديد دائمًا بالصيغة الوسطى، <g>-ομαι</g>؛ <s n=\"(a)\">عن الأشياء: عن الطعام، مع المنصوب: <r v=\"Acts.27.33\"></r>؛ مع المضاف إليه التبعيضي: <r v=\"Acts.27.36\"></r>؛</s> <s n=\"(b)\">عن الأشخاص: مع المنصوب: <r v=\"Matt.16.22\"></r>، <r v=\"Mark.8.32\"></r>، <r v=\"Acts.17.5\"></r>، <r v=\"Acts.18.26\"></r>، <r v=\"Acts.28.2\"></r>، <r v=\"Rom.14.1\"></r>، <r v=\"Rom.14.3\"></r>، <r v=\"Rom.15.7\"></r>، <r v=\"Phlm.1.17\"></r>.†</s> </s>"},"G4359":{"l":"προσοφείλω","o":1,"en":"<f>* <o>προσ-οφείλω</o>,</f> <s><b>to owe besides</b>: <r v=\"Phlm.1.19\"></r> (v. Field, <i>Notes</i>, 225).†</s>","ar":"<f>* <o>προσ-οφείλω</o>،</f> <s><b>يدين بشيء فوق ذلك</b>، <b>يكون مديونًا أيضًا</b>: <r v=\"Phlm.1.19\"></r>.†</s>"},"G4561":{"l":"σάρξ","o":147,"en":"<f><o>σάρξ</o>, <g>σαρκός, ἡ</g> </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1320\">בָּשָׂר</h> ;]</e> </et> <s><b>flesh</b>; <s n=\"1.\">as in cl. generally, <s n=\"(a)\">prop., of the soft substance of the animal body: <r v=\"1Cor.15.39\"></r>, <r v=\"2Cor.12.7\"></r>, <r v=\"Gal.6.13\"></r>, al.; <g>σ. καὶ αἷμα</g>, <r v=\"1Cor.5.50\"></r>; <g>σ. καὶ ὀστέα</g>, <r v=\"Luke.24.39\"></r>; pl., of the flesh of many or parts of the flesh of one (cl.), <r v=\"Rev.17.16\"></r> <r v=\"Rev.19.18\"></r>; <g>φαγεῖν</g>, Re, ll. c. (cf. <g>κατεσθίειν</g>, <r v=\"2Kgs.9.36\"></r>, al., and <g>βιβρώσκειν</g>, freq. in l.); metaph., <r v=\"Jas.5.3\"></r>; mystically, <g>φ. (τρώγειν) τὴν σ. τοῦ υἱοῦ τ. ἀνθρώπου</g>, <r v=\"John.6.52-John.6.56\"></r>; </s> <s n=\"(b)\">Of the whole substance of the body, = <g>σῶμα</g>: <r v=\"Acts.2.26\"></r> <i>(LXX)</i>, <r v=\"Acts.2.31\"></r>, <r v=\"2Cor.12.7\"></r>, <r v=\"Gal.4.14\"></r>, <r v=\"Eph.5.29\"></r>; <g>μία σ.</g>, <r v=\"Mark.10.8\"></r>; <g>εἰς σ. μίαν</g> (<r v=\"Gen.2.24\"></r>), <r v=\"Matt.19.5\"></r>, <r v=\"Mark.10.8\"></r>, <r v=\"1Cor.6.16\"></r>, <r v=\"Eph.5.31\"></r>; hence, of the material as opp. to the immaterial part of man (cf. Lft., <i>Notes</i>, 88): opp. to <g>πνεῦμα</g>, <r v=\"1Cor.5.5\"></r>, <r v=\"2Cor.7.1\"></r>, <r v=\"Col.2.5\"></r>, <r v=\"1Pet.3.18\"></r>, <r v=\"1Pet.4.6\"></r>; to <g>ψύχη</g>, <r v=\"Acts.2.31\"></r>, Rec.; of the present life, <g>ἐν (τῇ) σ.</g>, <r v=\"Rom.7.5\"></r>, <r v=\"Gal.2.20\"></r>, <r v=\"Phil.1.22\"></r>, <r v=\"Phil.1.24\"></r> <r v=\"1Pet.4.2\"></r>; of Christ's life on earth, <g>αἱ ἡμέραι τ. σαρκὸς αὐτοῦ</g>, <r v=\"Heb.5.7\"></r>; of things pertaining to the body, <g>ἐν (τῇ) σ.</g>, <r v=\"Gal.6.12\"></r>, <r v=\"Gal.6.13\"></r>, <r v=\"Phil.3.3\"></r>, <r v=\"Phil.3.4\"></r>. </s> </s> <s n=\"2.\">As in Heb. idiom, <s n=\"(a)\">of a living creature: <g>πᾶσα σ.</g> (Heb. <h n=\"H3605,H1320\">כָּל־בָּשָׂר</h>; cf. Bl., § 47, 9), <r v=\"Matt.24.22\"></r>, <r v=\"Mark.13.20\"></r>, <r v=\"1Pet.1.24\"></r>; esp. of man and his mortality (<r v=\"LXX:Ps.55.5\"></r>, <r v=\"Sir.28.5\"></r>, al.), <r v=\"John.1.14\"></r>; <g>πᾶσα σ.</g> (v. supr.), <r v=\"Luke.3.6\"></r>, <r v=\"John.17.2\"></r>, <r v=\"Acts.2.17\"></r>, <g>ἐν σ.</g>, <r v=\"1John.4.2\"></r>, <r v=\"1Tim.3.16\"></r>; </s> <s n=\"(b)\">of natural origin and relationship (<r v=\"Gen.2.24\"></r>, <r v=\"Isa.58.7\"></r>, al.): <g>τέκνα τῆς σ.</g>, <r v=\"Rom.9.8\"></r>; <g>κατὰ σάρκα</g>, <r v=\"Rom.9.3\"></r>, <r v=\"Rom.9.5\"></r>, <r v=\"1Cor.10.18\"></r>, <r v=\"Gal.4.23\"></r>, <r v=\"Gal.4.29\"></r>; <g>ἡ σ. μου</g>, <r v=\"Rom.11.14\"></r> (cf. <r v=\"Judg.9.2\"></r>, <r v=\"2Sam.5.1\"></r>, al.). </s> </s> <s n=\"3.\">Of the physical nature as subject to sensation and desire (Plut.), <s n=\"(a)\">without any ethical disparagement: <r v=\"Rom.7.18\"></r> <r v=\"Rom.13.14\"></r>; opp. to <g>πνεῦμα</g>, <r v=\"Matt.26.41\"></r>, <r v=\"Mark.14.38\"></r>; <g>τ. θέλημα τῆς σ.</g>, <r v=\"John.1.13\"></r>; <g>ἡ ἐπιθυμία τῆς σ.</g>, <r v=\"1John.2.16\"></r>; pl., <r v=\"2Pet.2.18\"></r>; <g>παθεῖν σαρκί</g>, <r v=\"1Pet.4.1\"></r>; </s> <s n=\"(b)\">in ethical sense, esp. in Pauline Epp., of the flesh as the seat and vehicle of sinful desires: opp. to <g>νοῦς</g>, <r v=\"Rom.7.25\"></r>; to <g>πνεῦμα</g>, <r v=\"Rom.8.4-Rom.8.9\"></r>, <r v=\"Rom.8.12\"></r>, <r v=\"Rom.8.13\"></r>, <r v=\"Gal.5.16\"></r>, <r v=\"Gal.5.17\"></r>, <r v=\"Gal.5.19\"></r> <r v=\"Gal.6.8\"></r> (cf. <i>DB</i>, ii, 14f.; iv, 165f.; Cremer, 844 ff.). </s> </s> </s>","ar":"<f><o>σάρξ</o>، <g>σαρκός, ἡ</g> </f> <s><b>جسد، لحم</b>؛ <s n=\"1.\">بالمعنى العام، <s n=\"(a)\">أصلاً، عن المادة الليِّنة في جسم الكائن الحي (اللحم): <r v=\"1Cor.15.39\"></r>، <r v=\"2Cor.12.7\"></r>، <r v=\"Gal.6.13\"></r>، وفي مواضع أخرى؛ <g>σ. καὶ αἷμα</g> (لحم ودم)، <r v=\"1Cor.5.50\"></r>؛ <g>σ. καὶ ὀστέα</g> (لحم وعظام)، <r v=\"Luke.24.39\"></r>؛ جمع، عن لحوم كثيرين أو أجزاء لحم الواحد، <r v=\"Rev.17.16\"></r> <r v=\"Rev.19.18\"></r>؛ <g>φαγεῖν</g> (أكل اللحوم)، رؤيا، في الموضعين المذكورين (قارن <g>κατεσθίειν</g>، <r v=\"2Kgs.9.36\"></r>، وفي مواضع أخرى)؛ مجازيًا، <r v=\"Jas.5.3\"></r>؛ وبمعنى سرّي، <g>φ. (τρώγειν) τὴν σ. τοῦ υἱοῦ τ. ἀνθρώπου</g> (أكل جسد ابن الإنسان)، <r v=\"John.6.52-John.6.56\"></r>؛ </s> <s n=\"(b)\">عن مادة الجسم كله، = <g>σῶμα</g> (الجسد): <r v=\"Acts.2.26\"></r> <i>(السبعينية)</i>، <r v=\"Acts.2.31\"></r>، <r v=\"2Cor.12.7\"></r>، <r v=\"Gal.4.14\"></r>، <r v=\"Eph.5.29\"></r>؛ <g>μία σ.</g> (جسد واحد)، <r v=\"Mark.10.8\"></r>؛ <g>εἰς σ. μίαν</g> (<r v=\"Gen.2.24\"></r>)، <r v=\"Matt.19.5\"></r>، <r v=\"Mark.10.8\"></r>، <r v=\"1Cor.6.16\"></r>، <r v=\"Eph.5.31\"></r>؛ ومن ثَمَّ عن الجزء المادي من الإنسان مقابل الجزء غير المادي: عكس <g>πνεῦμα</g> (الروح)، <r v=\"1Cor.5.5\"></r>، <r v=\"2Cor.7.1\"></r>، <r v=\"Col.2.5\"></r>، <r v=\"1Pet.3.18\"></r>، <r v=\"1Pet.4.6\"></r>؛ وعكس <g>ψύχη</g> (النفس)، <r v=\"Acts.2.31\"></r>؛ عن الحياة الحاضرة، <g>ἐν (τῇ) σ.</g> (في الجسد)، <r v=\"Rom.7.5\"></r>، <r v=\"Gal.2.20\"></r>، <r v=\"Phil.1.22\"></r>، <r v=\"Phil.1.24\"></r> <r v=\"1Pet.4.2\"></r>؛ عن حياة المسيح على الأرض، <g>αἱ ἡμέραι τ. σαρκὸς αὐτοῦ</g> (أيام جسده)، <r v=\"Heb.5.7\"></r>؛ عن الأمور المتعلقة بالجسد، <g>ἐν (τῇ) σ.</g>، <r v=\"Gal.6.12\"></r>، <r v=\"Gal.6.13\"></r>، <r v=\"Phil.3.3\"></r>، <r v=\"Phil.3.4\"></r>. </s> </s> <s n=\"2.\">كما في الاستعمال العبري، <s n=\"(a)\">عن الكائن الحي: <g>πᾶσα σ.</g> (كل ذي جسد، كل بشر) (بالعبرية <h n=\"H3605,H1320\">כָּל־בָּשָׂר</h>)، <r v=\"Matt.24.22\"></r>، <r v=\"Mark.13.20\"></r>، <r v=\"1Pet.1.24\"></r>؛ خاصةً عن الإنسان وفنائه (<r v=\"LXX:Ps.55.5\"></r>، <r v=\"Sir.28.5\"></r>، وفي مواضع أخرى)، <r v=\"John.1.14\"></r>؛ <g>πᾶσα σ.</g> (انظر أعلاه)، <r v=\"Luke.3.6\"></r>، <r v=\"John.17.2\"></r>، <r v=\"Acts.2.17\"></r>، <g>ἐν σ.</g> (في الجسد)، <r v=\"1John.4.2\"></r>، <r v=\"1Tim.3.16\"></r>؛ </s> <s n=\"(b)\">عن الأصل الطبيعي وقرابة النسب (<r v=\"Gen.2.24\"></r>، <r v=\"Isa.58.7\"></r>، وفي مواضع أخرى): <g>τέκνα τῆς σ.</g> (أولاد الجسد)، <r v=\"Rom.9.8\"></r>؛ <g>κατὰ σάρκα</g> (حسب الجسد)، <r v=\"Rom.9.3\"></r>، <r v=\"Rom.9.5\"></r>، <r v=\"1Cor.10.18\"></r>، <r v=\"Gal.4.23\"></r>، <r v=\"Gal.4.29\"></r>؛ <g>ἡ σ. μου</g> (أنسبائي)، <r v=\"Rom.11.14\"></r> (قارن <r v=\"Judg.9.2\"></r>، <r v=\"2Sam.5.1\"></r>، وفي مواضع أخرى). </s> </s> <s n=\"3.\">عن الطبيعة الجسدية بوصفها خاضعة للإحساس والشهوة، <s n=\"(a)\">بلا أي انتقاص أخلاقي: <r v=\"Rom.7.18\"></r> <r v=\"Rom.13.14\"></r>؛ عكس <g>πνεῦμα</g> (الروح)، <r v=\"Matt.26.41\"></r>، <r v=\"Mark.14.38\"></r>؛ <g>τ. θέλημα τῆς σ.</g> (مشيئة جسد)، <r v=\"John.1.13\"></r>؛ <g>ἡ ἐπιθυμία τῆς σ.</g> (شهوة الجسد)، <r v=\"1John.2.16\"></r>؛ جمع، <r v=\"2Pet.2.18\"></r>؛ <g>παθεῖν σαρκί</g> (التألم في الجسد)، <r v=\"1Pet.4.1\"></r>؛ </s> <s n=\"(b)\">بالمعنى الأخلاقي، خاصةً في رسائل بولس، عن الجسد بوصفه موطن الشهوات الخاطئة وأداتها: عكس <g>νοῦς</g> (الذهن)، <r v=\"Rom.7.25\"></r>؛ وعكس <g>πνεῦμα</g> (الروح)، <r v=\"Rom.8.4-Rom.8.9\"></r>، <r v=\"Rom.8.12\"></r>، <r v=\"Rom.8.13\"></r>، <r v=\"Gal.5.16\"></r>، <r v=\"Gal.5.17\"></r>، <r v=\"Gal.5.19\"></r> <r v=\"Gal.6.8\"></r>. </s> </s> </s>"},"G4572":{"l":"σεαυτοῦ","o":43,"en":"<f><o>σεαυτοῦ</o>, <g>-ῆς, -οῦ</g></f> <et> <e t=\"derivation\">(in NT not contracted, <g>σαυτοῦ</g>, as in Att..), </e> </et> reflex. prop. of 2nd pers. sing., used only in gen., dat. and acc. <s>(<b>of, to</b>) <b>thyself</b>: <r v=\"Matt.4.6\"></r>, <r v=\"John.8.13\"></r>, <r v=\"1Tim.4.16\"></r>, al. (In Hellenistic, the pl. is <g>ἑαυτῶν</g> (q.v.), not <g>ὑμῶν αὐτῶν</g> as in Attic, v. Bl., § 13, 1.) †</s>","ar":"<f><o>σεαυτοῦ</o>، <g>-ῆς, -οῦ</g></f> ضمير انعكاسي للمخاطب المفرد، لا يُستعمل إلا في المضاف إليه والقابل والمنصوب. <s>(<b>عن، إلى</b>) <b>نفسك</b>: <r v=\"Matt.4.6\"></r>، <r v=\"John.8.13\"></r>، <r v=\"1Tim.4.16\"></r>، وفي مواضع أخرى. (وفي اليونانية المتأخرة يكون الجمع <g>ἑαυτῶν</g> (انظره)، لا <g>ὑμῶν αὐτῶν</g> كما في الأتيكية.) †</s>"},"G4675":{"l":"αὐτός","o":5100,"en":"<f><o>αὐτός</o>, <g>-ή, -ό</g>,</f> determinative pron., in late Gk. much more freq. than in cl. (WM, 178 f.; Jannaris, <i>HGG</i>, §1399). <s n=\"1.\">Emphatic (so always in nom. exc. when preceded by the art., v. infr., iii); <s n=\"(1)\"><b>self</b> (<l>ipse</l>), expressing opposition, distinction, exclusion, etc., <g>αὐ. ἐκχυθήσεται</g>, <r v=\"Luke.5.37\"></r>; <g>αὐ. ἐγινώσκεν</g>, <r v=\"John.2.25\"></r>; <g>αὐ. ὑμεῖς</g>, <r v=\"John.3.28\"></r>; <g>καὶ αὐ. ἐγώ</g>, <r v=\"Rom.15.14\"></r>; <g>αὐ. Ἰησοῦς</g>, <r v=\"John.2.24\"></r>; <g>αὐ. καὶ οἱ μετ’ αὐτοῦ</g>, <r v=\"Matt.2.25\"></r>; <g>ὑμεῖς αὐ.</g>, <r v=\"Mark.6.31\"></r>; esp. (as freq in cl.) <g>αὐ. ὁ</g>, <r v=\"Matt.3.4\"></r>, <r v=\"Mark.6.17\"></r>, <r v=\"John.16.27\"></r>, <r v=\"1Thess.3.11\"></r>, al.; in late Gk., sometimes weakened, <g>ἐν αὐτῇ τ. ὥρᾳ</g>, <b>in that hour</b>, <r v=\"Luke.10.21\"></r> (M, <i>Pr.</i>, 91; MM, s.v.);</s> <s n=\"(2)\">emphatic, <b>he</b>, <b>she</b>, <b>it</b> (M, <i>Pr.</i>, 86; Bl., § 48, 1, 2, 7), <r v=\"Matt.1.21\"></r> <r v=\"Matt.12.50\"></r>, <r v=\"Luke.6.35\"></r>, al.; pointing to some one as master (cl.), <r v=\"Matt.8.24\"></r>, <r v=\"Mark.4.38\"></r>, al.; <g>αὐ., καὶ αὐ.</g> = <g>οὗτος, ὁ δε</g> (Bl., § 48, 1), <r v=\"Matt.14.2\"></r>, <r v=\"Mark.14.15\"></r>, <r v=\"Mark.14.44\"></r>, <r v=\"Luke.1.22\"></r> <r v=\"Luke.2.28\"></r>, al.</s> </s> <s n=\"2.\">In oblique cases (cl.), for the simple pron. of 3rd pers., <b>he</b>, <b>she</b>, <b>it</b>, <r v=\"Matt.7.9\"></r>, <r v=\"Matt.10.12\"></r>, <r v=\"Matt.26.44\"></r>, al.; with ptcp. in gen. absol., <r v=\"Matt.9.18\"></r>, <r v=\"Mark.13.1\"></r>, al. (for irreg. constructions, V. Bl., § 74, 5); pleonastically after the relative (cf. Heb. <h n=\"H834\">אֲשֶׁר לֹו</h>; WM, 184 ff.; Bl., § 50, 4; MM, s.v.), <r v=\"Mark.7.25\"></r>, <r v=\"Rev.3.8\"></r>, <r v=\"Rev.7.2\"></r>, al.; in constr. ad sensum, without proper subject expressly indicated, <r v=\"Matt.4.23\"></r>, <r v=\"Acts.8.5\"></r>, <r v=\"2Cor.2.13\"></r>, al.; gen. <g>αὐτοῦ</g> = <g>ἐκείνου</g>, <r v=\"Rom.11.11\"></r>, <r v=\"1Thess.2.19\"></r>, <r v=\"Titus.3.5\"></r>, <r v=\"Heb.2.4\"></r>.</s> <s n=\"3.\"><g>ὁ</g>, <g>ἡ</g>, <g>τὸ αὐ.</g>, <b>the same</b>: <r v=\"Heb.1.12\"></r>, <r v=\"Heb.13.8\"></r>; <g>τὸ αὐ.</g>, <g>ποιεῖν</g>, <r v=\"Matt.5.46\"></r>, <r v=\"Matt.5.47\"></r>, al.; <g>φρονεῖν</g>, <r v=\"Rom.12.16\"></r> <r v=\"Rom.15.5\"></r>, <r v=\"Phil.2.2\"></r>, al.; <g>τὰ αὐ.</g>, <r v=\"Acts.15.27\"></r>, <r v=\"Rom.2.1\"></r>, al.; <g>κατὰ τὸ</g> (<g>τὰ</g>) <g>αὐ.</g> (MM, s.v.), <r v=\"Acts.14.1\"></r>, <r v=\"Luke.6.23\"></r>, al.; <g>ἐπὶ τὸ αὐ.</g>, <b>together</b> (MM, s.v.), <r v=\"Matt.22.34\"></r>, <r v=\"Acts.1.15\"></r>, al.; <g>ἓν κ. τὸ αὐ.</g>, <r v=\"1Cor.11.5\"></r>, <r v=\"1Cor.12.11\"></r>; c. dat. (cl.), <r v=\"1Cor.11.5\"></r>; with a noun, <g>λόγος</g>, <r v=\"Mark\"></r>; <g>μέτρος</g>, <r v=\"Phil.1.30\"></r>; <g>πνεῦμα</g>, <r v=\"1Cor.12.4\"></r>.</s>","ar":"<f><o>αὐτός</o>، <g>-ή, -ό</g>،</f> ضمير تحديدي، أكثر استعمالاً بكثير في اليونانية المتأخرة. <s n=\"1.\">للتوكيد (وهكذا دائمًا في حالة الرفع إلا إذا سبقته أداة التعريف، انظر أدناه، 3)؛ <s n=\"(1)\"><b>نفس</b>، <b>ذات</b> (<l>ipse</l>)، للدلالة على المقابلة أو التمييز أو الحصر ونحوها، <g>αὐ. ἐκχυθήσεται</g>، <r v=\"Luke.5.37\"></r>؛ <g>αὐ. ἐγινώσκεν</g>، <r v=\"John.2.25\"></r>؛ <g>αὐ. ὑμεῖς</g>، <r v=\"John.3.28\"></r>؛ <g>καὶ αὐ. ἐγώ</g>، <r v=\"Rom.15.14\"></r>؛ <g>αὐ. Ἰησοῦς</g>، <r v=\"John.2.24\"></r>؛ <g>αὐ. καὶ οἱ μετ’ αὐτοῦ</g>، <r v=\"Matt.2.25\"></r>؛ <g>ὑμεῖς αὐ.</g>، <r v=\"Mark.6.31\"></r>؛ خاصةً <g>αὐ. ὁ</g>، <r v=\"Matt.3.4\"></r>، <r v=\"Mark.6.17\"></r>، <r v=\"John.16.27\"></r>، <r v=\"1Thess.3.11\"></r>، وفي مواضع أخرى؛ وفي اليونانية المتأخرة يضعف معناه أحيانًا، <g>ἐν αὐτῇ τ. ὥρᾳ</g>، <b>في تلك الساعة</b>، <r v=\"Luke.10.21\"></r>؛</s> <s n=\"(2)\">للتوكيد، <b>هو</b>، <b>هي</b>، <b>هو (للمحايد)</b>، <r v=\"Matt.1.21\"></r> <r v=\"Matt.12.50\"></r>، <r v=\"Luke.6.35\"></r>، وفي مواضع أخرى؛ إشارةً إلى شخصٍ بوصفه السيد، <r v=\"Matt.8.24\"></r>، <r v=\"Mark.4.38\"></r>، وفي مواضع أخرى؛ <g>αὐ., καὶ αὐ.</g> = <g>οὗτος, ὁ δε</g>، <r v=\"Matt.14.2\"></r>، <r v=\"Mark.14.15\"></r>، <r v=\"Mark.14.44\"></r>، <r v=\"Luke.1.22\"></r> <r v=\"Luke.2.28\"></r>، وفي مواضع أخرى.</s> </s> <s n=\"2.\">في الحالات غير حالة الرفع، بدلاً من ضمير الغائب البسيط، <b>هو</b>، <b>هي</b>، <b>هو (للمحايد)</b>، <r v=\"Matt.7.9\"></r>، <r v=\"Matt.10.12\"></r>، <r v=\"Matt.26.44\"></r>، وفي مواضع أخرى؛ مع اسم الفاعل في المضاف إليه المطلق، <r v=\"Matt.9.18\"></r>، <r v=\"Mark.13.1\"></r>، وفي مواضع أخرى؛ زائدًا بعد اسم الموصول (قارن العبرية <h n=\"H834\">אֲשֶׁר לֹו</h>)، <r v=\"Mark.7.25\"></r>، <r v=\"Rev.3.8\"></r>، <r v=\"Rev.7.2\"></r>، وفي مواضع أخرى؛ في تركيب بحسب المعنى، دون ذكر صريح للفاعل، <r v=\"Matt.4.23\"></r>، <r v=\"Acts.8.5\"></r>، <r v=\"2Cor.2.13\"></r>، وفي مواضع أخرى؛ المضاف إليه <g>αὐτοῦ</g> = <g>ἐκείνου</g>، <r v=\"Rom.11.11\"></r>، <r v=\"1Thess.2.19\"></r>، <r v=\"Titus.3.5\"></r>، <r v=\"Heb.2.4\"></r>.</s> <s n=\"3.\"><g>ὁ</g>، <g>ἡ</g>، <g>τὸ αὐ.</g>، <b>نفسه</b>، <b>هو هو</b>: <r v=\"Heb.1.12\"></r>، <r v=\"Heb.13.8\"></r>؛ <g>τὸ αὐ.</g>، <g>ποιεῖν</g>، <r v=\"Matt.5.46\"></r>، <r v=\"Matt.5.47\"></r>، وفي مواضع أخرى؛ <g>φρονεῖν</g>، <r v=\"Rom.12.16\"></r> <r v=\"Rom.15.5\"></r>، <r v=\"Phil.2.2\"></r>، وفي مواضع أخرى؛ <g>τὰ αὐ.</g>، <r v=\"Acts.15.27\"></r>، <r v=\"Rom.2.1\"></r>، وفي مواضع أخرى؛ <g>κατὰ τὸ</g> (<g>τὰ</g>) <g>αὐ.</g>، <r v=\"Acts.14.1\"></r>، <r v=\"Luke.6.23\"></r>، وفي مواضع أخرى؛ <g>ἐπὶ τὸ αὐ.</g>، <b>معًا</b>، <r v=\"Matt.22.34\"></r>، <r v=\"Acts.1.15\"></r>، وفي مواضع أخرى؛ <g>ἓν κ. τὸ αὐ.</g>، <r v=\"1Cor.11.5\"></r>، <r v=\"1Cor.12.11\"></r>؛ مع القابل، <r v=\"1Cor.11.5\"></r>؛ مع اسم، <g>λόγος</g>، <r v=\"Mark\"></r>؛ <g>μέτρος</g>، <r v=\"Phil.1.30\"></r>؛ <g>πνεῦμα</g>، <r v=\"1Cor.12.4\"></r>.</s>"},"G4698":{"l":"σπλάγχνον","o":11,"en":"<f><o>σπλάγχνον</o>, <g>-ου, τό </g> mostly (in NT always) in pl., <g>σπλάγχνα, -ων, τά</g>, </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.12.10\"></r> (<h n=\"H7356\">רַחֲמׅים</h>, elsewhere rendered by <g>οἰκτιρμοί</g>, <r v=\"Ps.25.6\"></r> <r v=\"Ps.40.12\"></r> and by <g>ἔλεος</g>, <r v=\"Isa.47.6\"></r>), <r v=\"Prov.26.22\"></r> (<h n=\"H990\">בֶּטֶן</h>), <r v=\"Wis.10.5\"></r>, <r v=\"Sir.30.7\"></r>, <r v=\"2Macc.9.5\"></r>, <r v=\"2Macc.9.6\"></r>, al. ;] </e> </et> <s><b>the inward parts</b> (heart, liver, lungs, etc.; Lat. <l>viscera</l>): <r v=\"Acts.1.18\"></r>. Metaph., of the seat of the feelings and of the feelings themselves (in Gk. poets, of anger, anxiety, etc.), <b>the heart, affections</b> (the characteristic LXX and NT reference of the word to feelings of kindness, benevolence and pity, is found in <g>π.</g>; v. MM, xxiii; cf. Lft. on <r v=\"Phil.1.8\"></r>): <r v=\"2Cor.6.12\"></r> <r v=\"2Cor.7.15\"></r>, <r v=\"Phlm.1.7\"></r>, <r v=\"Phlm.1.12\"></r>, <r v=\"Phlm.1.20\"></r>, <r v=\"1John.3.17\"></r>; <g>σ. οἰκτιρμοῦ</g>, <r v=\"Col.3.12\"></r>; <g>σ. καὶ οἰκτιρμοὶ</g>, <r v=\"Phil.2.1\"></r>; <g>σ. ἐλέους θεοῦ</g>; <g>ἡμῶν</g>, <r v=\"Luke.1.78\"></r>; <g>σ. Χριστοῦ Ἰησοῦ</g>, <r v=\"Phil.1.8\"></r>.†</s>","ar":"<f><o>σπλάγχνον</o>، <g>-ου, τό </g>، وغالبًا (ودائمًا في العهد الجديد) في الجمع: <g>σπλάγχνα, -ων, τά</g>، </f> <s><b>الأحشاء</b> (القلب والكبد والرئتان ونحوها؛ باللاتينية <l>viscera</l>): <r v=\"Acts.1.18\"></r>. ومجازيًا عن مكان المشاعر والمشاعرِ نفسها: <b>القلب، الأحشاء، العواطف</b> (وإشارة الكلمة المميِّزة في السبعينية والعهد الجديد هي إلى مشاعر اللطف والإحسان والرأفة؛ قارن <r v=\"Phil.1.8\"></r>): <r v=\"2Cor.6.12\"></r>، <r v=\"2Cor.7.15\"></r>، <r v=\"Phlm.1.7\"></r>، <r v=\"Phlm.1.12\"></r>، <r v=\"Phlm.1.20\"></r>، <r v=\"1John.3.17\"></r>؛ <g>σ. οἰκτιρμοῦ</g>: <r v=\"Col.3.12\"></r>؛ <g>σ. καὶ οἰκτιρμοὶ</g>: <r v=\"Phil.2.1\"></r>؛ <g>σ. ἐλέους θεοῦ</g>؛ <g>ἡμῶν</g>: <r v=\"Luke.1.78\"></r>؛ <g>σ. Χριστοῦ Ἰησοῦ</g>: <r v=\"Phil.1.8\"></r>.†</s>"},"G4869":{"l":"συναιχμάλωτος","o":3,"en":"<f>*† <o>συν-αιχμάλωτος</o>, <g>-ου, ὁ </g></f> <s><b>a fellow prisoner</b> (prop., of a captive in war, v. Lft., <i>Col.</i>, 234): <r v=\"Rom.16.7\"></r>, <r v=\"Col.4.10\"></r>, <r v=\"Phlm.1.23\"></r>.†</s>","ar":"<f>*† <o>συν-αιχμάλωτος</o>، <g>-ου, ὁ </g></f> <s><b>رفيق في الأسر، شريك في السجن</b> (أصلاً عن أسير الحرب): <r v=\"Rom.16.7\"></r>، <r v=\"Col.4.10\"></r>، <r v=\"Phlm.1.23\"></r>.†</s>"},"G4904":{"l":"συνεργός","o":13,"en":"<f>** <o>συνεργός</o>, <g>-όν </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.8.7\"></r> <r v=\"2Macc.14.5\"></r> * ;]</e> </et> <s><b>a fellow-worker</b>: c. gen. pers., <r v=\"Rom.16.3\"></r>, <r v=\"Rom.16.9\"></r>, <r v=\"Rom.16.21\"></r>, <r v=\"Phil.2.25\"></r> <r v=\"Phil.4.3\"></r>, <r v=\"1Thess.3.2\"></r>, Rec., <r v=\"Phlm.1.1\"></r>, <r v=\"Phlm.1.24\"></r>; <g>θεοῦ</g> (cf. Lft., <i>Notes</i>, 41, 188), <r v=\"1Cor.3.9\"></r> (pl.), <r v=\"1Thess.3.2\"></r> [WH] R, mg. (R, txt., <g>διάκονον τοῦ θ.</g>; on the original reading, v. <i>ICC</i>, in l.); <g>τ. χαρᾶς ὑηῶν</g>, <r v=\"2Cor.1.24\"></r>; <g>τ. ἀληθείᾳ</g>, <r v=\"3John.1.8\"></r>; seq. <g>εἰς</g>, <r v=\"2Cor.8.23\"></r>, <r v=\"Col.4.11\"></r>.†</s>","ar":"<f>** <o>συνεργός</o>، <g>-όν </g></f> <s><b>عامل مع، شريك في العمل</b>: مع المضاف إليه للشخص، <r v=\"Rom.16.3\"></r>، <r v=\"Rom.16.9\"></r>، <r v=\"Rom.16.21\"></r>، <r v=\"Phil.2.25\"></r> <r v=\"Phil.4.3\"></r>، <r v=\"1Thess.3.2\"></r>، <r v=\"Phlm.1.1\"></r>، <r v=\"Phlm.1.24\"></r>؛ <g>θεοῦ</g>، <r v=\"1Cor.3.9\"></r> (جمعًا)، <r v=\"1Thess.3.2\"></r>؛ <g>τ. χαρᾶς ὑηῶν</g>، <r v=\"2Cor.1.24\"></r>؛ <g>τ. ἀληθείᾳ</g>، <r v=\"3John.1.8\"></r>؛ يليه <g>εἰς</g>، <r v=\"2Cor.8.23\"></r>، <r v=\"Col.4.11\"></r>.†</s>"},"G4961":{"l":"συνστρατιώτης","o":2,"en":"<f>* <o>συν-στρατιώτης</o> (Rec. <g>συσ-</g>), <g>-ου, ὁ</g> </f> <s><b>a fellow-soldier</b> (Plat., Xen., al.). Metaph., of fellowship in Christian service: <r v=\"Phil.2.25\"></r>, <r v=\"Phlm.1.2\"></r> .†</s>","ar":"<f>* <o>συν-στρατιώτης</o>، <g>-ου, ὁ</g> </f> <s><b>رفيق في الجندية، زميل جندي</b>. مجازيًا، عن الشركة في الخدمة المسيحية: <r v=\"Phil.2.25\"></r>، <r v=\"Phlm.1.2\"></r>.†</s>"},"G5029":{"l":"τάχα","o":2,"en":"<f>** <o>τάχα</o> </f> <et> <e t=\"derivation\">(&lt; <g>ταχύς</g>), </e> </et> adv., <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.13.6\"></r> <r v=\"Wis.14.19\"></r> * ;] </e> </et> <s n=\"(a)\">(chiefly poët.), <b>quickly, presently</b>; </s> <s n=\"(b)\"><b>perhaps</b>: <r v=\"Rom.5.7\"></r>, <r v=\"Phlm.1.15\"></r>.†</s>","ar":"<f>** <o>τάχα</o> </f> ظرف، <s n=\"(a)\"><b>سريعًا، حالاً</b>؛ </s> <s n=\"(b)\"><b>ربما، لعلّ</b>: <r v=\"Rom.5.7\"></r>، <r v=\"Phlm.1.15\"></r>.†</s>"},"G5043":{"l":"τέκνον","o":99,"en":"<f><o>τέκνον</o>, <g>-ου, τό</g> </f> <et> <e t=\"derivation\">(&lt; <g>τίκτω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1121\">בֵּן</h>, also for <h n=\"H3206\">יֶלֶד</h>, etc. ;]</e> </et> <s>that which is begotten, born (cf. Scottish <i>bairn</i>), <b>a child</b> of either sex: <r v=\"Mark.13.12\"></r>, <r v=\"Luke.1.7\"></r>, <r v=\"Acts.7.5\"></r>; pl., <r v=\"Matt.7.11\"></r>, <r v=\"Mark.7.27\"></r>, <r v=\"Luke.1.17\"></r>, <r v=\"Eph.6.1\"></r>, al.; <g>τέκνα ἐπαγγελίας</g>, <r v=\"Rom.9.8\"></r>; <g>τ. τῆς σαρκός</g>, <r v=\"Rom.9.8\"></r>; in a wider sense (as Heb. <h n=\"H1121\">בָּנִים</h>), of posterity, <r v=\"Matt.2.18\"></r>, <r v=\"Luke.3.8\"></r>, al.; specif., of a male child, <r v=\"Matt.21.28\"></r>, <r v=\"Acts.21.21\"></r>, a,l.; in voc. as a form of kindly address from an elder to a junior or from a teacher to a disciple, <r v=\"Matt.9.2\"></r> <r v=\"Matt.21.28\"></r>, <r v=\"Mark.2.5\"></r>, <r v=\"Luke.2.48\"></r>; <g>τ. μου</g> (= cl. <g>τ. μοι</g>; v. Bl., §37, 5), <r v=\"Gal.4.19\"></r> (<g>τεκνία</g>, WH, txt.), <r v=\"2Tim.2.1\"></r>. Metaph., <s n=\"(a)\">of disciples (apart from direct address, v. supr.): <r v=\"Phlm.1.10\"></r>, <r v=\"1Tim.1.2\"></r>, <r v=\"Titus.1.4\"></r>, <r v=\"3John.1.4\"></r>; </s> <s n=\"(b)\">with reference to the Fatherhood of God (v.s. <g>πατήρ, γεννάω</g>), <g>τέκνα τ. θεοῦ</g> (cf. <r v=\"Isa.30.1\"></r>, <r v=\"Wis.16.21\"></r>): <r v=\"Rom.8.16\"></r>, <r v=\"Eph.5.1\"></r>, <r v=\"Phil.2.15\"></r>; and esp. in Johannine bks. (cf. Westc, <i>Epp. Jo.</i>, 94, 120), <r v=\"John.1.12\"></r>, <r v=\"1John.3.1\"></r> al.; </s> <s n=\"(c)\">of those who imitate others and are therefore regarded as the spiritual offspring of their exemplars: <r v=\"Matt.3.9\"></r>, <r v=\"Luke.3.8\"></r>, <r v=\"John.8.39\"></r>, <r v=\"Rom.9.7\"></r>, <r v=\"1Pet.3.6\"></r>; <g>τ. διαβόλου</g>, <r v=\"1John.3.10\"></r>; </s> <s n=\"(d)\">as in Heb. (LXX, <r v=\"Joel.2.23\"></r>, <r v=\"Ps.149.2\"></r>, <r v=\"1Macc.1.38\"></r>), of the inhabitants of a city: <r v=\"Matt.23.37\"></r>, <r v=\"Luke.13.34\"></r> <r v=\"Luke.19.44\"></r>, <r v=\"Gal.4.25\"></r>; </s> <s n=\"(e)\">with an adjectival gen., freq. rendering a Heb. expression, adopted from LXX or formed on the analogy of its language, but sometimes with parallels in Gk. writers (v. Deiss., <i>BS</i>, 161ff.): <g>τέκνα φωτός</g>, <r v=\"Eph.5.8\"></r>; <g>τ. ὑπακοῆς</g>, <r v=\"1Pet.1.14\"></r>; <g>κατάρας</g>, <r v=\"2Pet.2.14\"></r>; <g>ὀργῆς</g>, <r v=\"Eph.2.3\"></r>. </s> </s> <sy><i>SYN.</i>: v.s. <g>παῖς</g>.</sy>","ar":"<f><o>τέκνον</o>، <g>-ου, τό</g> </f> <s>ما يُولَد ويُنجَب، <b>ولد</b>، <b>طفل</b> من أيٍّ من الجنسين: <r v=\"Mark.13.12\"></r>، <r v=\"Luke.1.7\"></r>، <r v=\"Acts.7.5\"></r>؛ جمعًا، <r v=\"Matt.7.11\"></r>، <r v=\"Mark.7.27\"></r>، <r v=\"Luke.1.17\"></r>، <r v=\"Eph.6.1\"></r>، وفي مواضع أخرى؛ <g>τέκνα ἐπαγγελίας</g>، <r v=\"Rom.9.8\"></r>؛ <g>τ. τῆς σαρκός</g>، <r v=\"Rom.9.8\"></r>؛ بمعنى أوسع (مثل العبرية <h n=\"H1121\">בָּנִים</h>)، عن الذرية، <r v=\"Matt.2.18\"></r>، <r v=\"Luke.3.8\"></r>، وفي مواضع أخرى؛ وتحديدًا، عن الولد الذكر، <r v=\"Matt.21.28\"></r>، <r v=\"Acts.21.21\"></r>، وفي مواضع أخرى؛ في النداء، خطابًا وديًّا من الأكبر إلى الأصغر أو من المعلم إلى التلميذ، <r v=\"Matt.9.2\"></r> <r v=\"Matt.21.28\"></r>، <r v=\"Mark.2.5\"></r>، <r v=\"Luke.2.48\"></r>؛ <g>τ. μου</g>، <r v=\"Gal.4.19\"></r>، <r v=\"2Tim.2.1\"></r>. مجازيًا، <s n=\"(a)\">عن التلاميذ (في غير الخطاب المباشر، انظر أعلاه): <r v=\"Phlm.1.10\"></r>، <r v=\"1Tim.1.2\"></r>، <r v=\"Titus.1.4\"></r>، <r v=\"3John.1.4\"></r>؛ </s> <s n=\"(b)\">إشارةً إلى أبوّة الله (انظر تحت مدخل <g>πατήρ, γεννάω</g>)، <g>τέκνα τ. θεοῦ</g> (قارن <r v=\"Isa.30.1\"></r>، <r v=\"Wis.16.21\"></r>): <r v=\"Rom.8.16\"></r>، <r v=\"Eph.5.1\"></r>، <r v=\"Phil.2.15\"></r>؛ وخاصةً في كتابات يوحنا، <r v=\"John.1.12\"></r>، <r v=\"1John.3.1\"></r> وفي مواضع أخرى؛ </s> <s n=\"(c)\">عن الذين يقتدون بغيرهم فيُعَدّون نسلاً روحيًّا لمن يقتدون بهم: <r v=\"Matt.3.9\"></r>، <r v=\"Luke.3.8\"></r>، <r v=\"John.8.39\"></r>، <r v=\"Rom.9.7\"></r>، <r v=\"1Pet.3.6\"></r>؛ <g>τ. διαβόλου</g>، <r v=\"1John.3.10\"></r>؛ </s> <s n=\"(d)\">كما في العبرية (السبعينية، <r v=\"Joel.2.23\"></r>، <r v=\"Ps.149.2\"></r>، <r v=\"1Macc.1.38\"></r>)، عن سكان مدينة: <r v=\"Matt.23.37\"></r>، <r v=\"Luke.13.34\"></r> <r v=\"Luke.19.44\"></r>، <r v=\"Gal.4.25\"></r>؛ </s> <s n=\"(e)\">مع مضاف إليه بمعنى الصفة، وكثيرًا ما يترجم تعبيرًا عبريًّا مأخوذًا من السبعينية أو مصوغًا على نمط لغتها: <g>τέκνα φωτός</g>، <r v=\"Eph.5.8\"></r>؛ <g>τ. ὑπακοῆς</g>، <r v=\"1Pet.1.14\"></r>؛ <g>κατάρας</g>، <r v=\"2Pet.2.14\"></r>؛ <g>ὀργῆς</g>، <r v=\"Eph.2.3\"></r>. </s> </s>"},"G5095":{"l":"Τιμόθεος","o":24,"en":"<f><o>Τιμόθεος</o>, <g>-ου, ὁ </g></f> <s><b>Timothy</b>: <r v=\"Acts.17.14\"></r>, <r v=\"Acts.17.15\"></r> <r v=\"Acts.18.5\"></r>, <r v=\"Rom.16.21\"></r>, al. </s>","ar":"<f><o>Τιμόθεος</o>، <g>-ου, ὁ </g></f> <s><b>تيموثاوس</b>: <r v=\"Acts.17.14\"></r>، <r v=\"Acts.17.15\"></r>، <r v=\"Acts.18.5\"></r>، <r v=\"Rom.16.21\"></r>، وفي مواضع أخرى. </s>"},"G5100":{"l":"τις","o":496,"en":"<f><o>τις</o>, neut., <g>τι</g>, gen., <g>τινός</g>, </f> enclitic indefinite pron., related to interrog. <g>τίς</g> as <g>πού, πως, ποτέ</g> to <g>ποῦ, πῶς, πότε</g>. <s> <s n=\"I.\">As subst., <s n=\"1.\"><b>one, a certain one</b>: <r v=\"Luke.9.49\"></r>, <r v=\"John.11.1\"></r>, <r v=\"Acts.5.25\"></r>, al.; pl., <g>τίνες</g>, <b>certain, some</b>: <r v=\"Luke.13.1\"></r>, <r v=\"Acts.15.1\"></r>, <r v=\"Rom.3.8\"></r>, al. </s> <s n=\"2.\"><b>someone, anyone, something, anything</b>: <r v=\"Matt.12.29\"></r>, <r v=\"Mark.9.30\"></r>, <r v=\"Luke.8.46\"></r>, <r v=\"John.2.25\"></r>, <r v=\"Acts.17.25\"></r>, <r v=\"Rom.5.7\"></r>, al.; = indef., <b>one</b> (French <i>on</i>), <r v=\"Mark.8.4\"></r>, <r v=\"John.2.25\"></r>, <r v=\"Rom.8.24\"></r>, al.; pl., <g>τινες</g>, <b>some</b>, <r v=\"Mark.14.4\"></r>, al. </s> </s> <s n=\"II.\">As adj., <s n=\"1.\"><b>a certain</b>: <r v=\"Matt.18.12\"></r>, <r v=\"Luke.1.5\"></r> <r v=\"Luke.8.27\"></r>, <r v=\"Acts.3.2\"></r>, al.; with proper names, <r v=\"Mark.15.21\"></r>, <r v=\"Luke.23.26\"></r>, al.; c. gen. partit., <r v=\"Luke.7.19\"></r>, al. </s> <s n=\"2.\"><b>some</b>: <r v=\"Mark.16.18\"></r>, <r v=\"John.5.14\"></r>, <r v=\"Acts.17.21\"></r> <r v=\"Acts.24.24\"></r>, <r v=\"Heb.11.40\"></r>, al. </s> </s> </s>","ar":"<f><o>τις</o>، المحايد <g>τι</g>، حالة الجر <g>τινός</g>، </f> ضمير نكرة ملحق، علاقته بالاستفهامي <g>τίς</g> كعلاقة <g>πού, πως, ποτέ</g> بـ <g>ποῦ, πῶς, πότε</g>. <s> <s n=\"I.\">اسمًا، <s n=\"1.\"><b>واحد، أحدٌ ما، شخص معيَّن</b>: <r v=\"Luke.9.49\"></r>، <r v=\"John.11.1\"></r>، <r v=\"Acts.5.25\"></r>، وفي مواضع أخرى؛ جمع، <g>τίνες</g>: <b>قومٌ، بعضٌ</b>: <r v=\"Luke.13.1\"></r>، <r v=\"Acts.15.1\"></r>، <r v=\"Rom.3.8\"></r>، وفي مواضع أخرى. </s> <s n=\"2.\"><b>أحدٌ، أيُّ أحد، شيءٌ، أيُّ شيء</b>: <r v=\"Matt.12.29\"></r>، <r v=\"Mark.9.30\"></r>، <r v=\"Luke.8.46\"></r>، <r v=\"John.2.25\"></r>، <r v=\"Acts.17.25\"></r>، <r v=\"Rom.5.7\"></r>، وفي مواضع أخرى؛ بمعنى النكرة العامة: <b>المرء</b>، <r v=\"Mark.8.4\"></r>، <r v=\"John.2.25\"></r>، <r v=\"Rom.8.24\"></r>، وفي مواضع أخرى؛ جمع، <g>τινες</g>: <b>بعضٌ، قومٌ</b>، <r v=\"Mark.14.4\"></r>، وفي مواضع أخرى. </s> </s> <s n=\"II.\">صفةً، <s n=\"1.\"><b>ما، معيَّن</b> (إنسانٌ ما): <r v=\"Matt.18.12\"></r>، <r v=\"Luke.1.5\"></r> <r v=\"Luke.8.27\"></r>، <r v=\"Acts.3.2\"></r>، وفي مواضع أخرى؛ مع أسماء العَلَم، <r v=\"Mark.15.21\"></r>، <r v=\"Luke.23.26\"></r>، وفي مواضع أخرى؛ مع المضاف إليه التبعيضي، <r v=\"Luke.7.19\"></r>، وفي مواضع أخرى. </s> <s n=\"2.\"><b>بعض، شيء من</b>: <r v=\"Mark.16.18\"></r>، <r v=\"John.5.14\"></r>، <r v=\"Acts.17.21\"></r> <r v=\"Acts.24.24\"></r>، <r v=\"Heb.11.40\"></r>، وفي مواضع أخرى. </s> </s> </s>"},"G5108":{"l":"τοιοῦτος","o":57,"en":"<f><o>τοιοῦτος</o>, <g>-αύτη, -οῦτο</g></f> <et> <e t=\"derivation\">(as usually in Att.. prose. Ep. and Ion. neut. <g>-οῦτον</g> in Al., <r v=\"Acts.21.25\"></r>, Rec. only), </e> </et> <s>correlat. of <g>οἷος, ὁποῖος, ὥς</g>, etc., </s> <s><b>such as this, of such a kind, such</b>: <r v=\"Matt.9.8\"></r> <r v=\"Matt.18.5\"></r>, <r v=\"Mark.4.33\"></r> <r v=\"Mark.6.2\"></r> <r v=\"Mark.7.13\"></r> <r v=\"Mark.9.37\"></r> (T, <g>τούτων</g>), <r v=\"John.9.16\"></r>, <r v=\"Acts.16.24\"></r>, <r v=\"1Cor.5.1\"></r> <r v=\"1Cor.11.16\"></r>, <r v=\"2Cor.3.4\"></r>, <r v=\"2Cor.3.12\"></r> <r v=\"2Cor.12.3\"></r>, <r v=\"Heb.7.26\"></r> <r v=\"Heb.8.1\"></r> <r v=\"Heb.12.3\"></r> <r v=\"Heb.13.16\"></r>, <r v=\"Jas.4.16\"></r>; <g>οἷος . . . τ.</g>, <r v=\"1Cor.15.48\"></r>, <r v=\"2Cor.10.11\"></r>; id. pleonast. (v. Bl., § 50, 4), <r v=\"Mark.13.19\"></r>; seq. <g>ὁποῖος</g>, <r v=\"Acts.26.29\"></r>; <g>ὥς</g>, <r v=\"Phlm.1.9\"></r>. As subst., anarth: pl., <r v=\"Luke.9.9\"></r>; c. art., <g>ὁ τ.</g>, <b>such a one</b> (Bl., § 47, 9; Ellic. on <r v=\"Gal.5.21\"></r>): <r v=\"Acts.22.22\"></r>, <r v=\"1Cor.5.5\"></r>, al.; pl., <r v=\"Matt.19.14\"></r>, <r v=\"Mark.10.14\"></r>, al.; neut. pl., <r v=\"Acts.19.25\"></r>, <r v=\"Rom.1.32\"></r>, al.</s>","ar":"<f><o>τοιοῦτος</o>، <g>-αύτη, -οῦτο</g></f> <s>مقابِلُ <g>οἷος, ὁποῖος, ὥς</g> إلخ، </s> <s><b>مثل هذا، من هذا النوع، كهذا</b>: <r v=\"Matt.9.8\"></r> <r v=\"Matt.18.5\"></r>، <r v=\"Mark.4.33\"></r> <r v=\"Mark.6.2\"></r> <r v=\"Mark.7.13\"></r> <r v=\"Mark.9.37\"></r>، <r v=\"John.9.16\"></r>، <r v=\"Acts.16.24\"></r>، <r v=\"1Cor.5.1\"></r> <r v=\"1Cor.11.16\"></r>، <r v=\"2Cor.3.4\"></r>، <r v=\"2Cor.3.12\"></r> <r v=\"2Cor.12.3\"></r>، <r v=\"Heb.7.26\"></r> <r v=\"Heb.8.1\"></r> <r v=\"Heb.12.3\"></r> <r v=\"Heb.13.16\"></r>، <r v=\"Jas.4.16\"></r>؛ <g>οἷος . . . τ.</g> (كما ... هكذا)، <r v=\"1Cor.15.48\"></r>، <r v=\"2Cor.10.11\"></r>؛ والتعبير نفسه على سبيل الحشو، <r v=\"Mark.13.19\"></r>؛ يليه <g>ὁποῖος</g>، <r v=\"Acts.26.29\"></r>؛ <g>ὥς</g>، <r v=\"Phlm.1.9\"></r>. اسمًا، بدون أداة التعريف: جمع، <r v=\"Luke.9.9\"></r>؛ ومع أداة التعريف، <g>ὁ τ.</g>: <b>مثل هذا (الشخص)</b>، (قارن <r v=\"Gal.5.21\"></r>): <r v=\"Acts.22.22\"></r>، <r v=\"1Cor.5.5\"></r>، وفي مواضع أخرى؛ جمع، <r v=\"Matt.19.14\"></r>، <r v=\"Mark.10.14\"></r>، وفي مواضع أخرى؛ المحايد الجمع، <r v=\"Acts.19.25\"></r>، <r v=\"Rom.1.32\"></r>، وفي مواضع أخرى.</s>"},"G5124":{"l":"οὗτος","o":1387,"en":"<f><o>οὗτος</o>, <g>αὕτη, τοῦτο</g>, gen., <g>τούτου, ταύτης, τούτου</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2088\">זֶה</h>, <h n=\"H2063\">זֹאת</h>;]</e> </et> demonstr. pron. (related to <g>ἐκεῖνος</g> as <l>hic</l> to <l>ille</l>), <s><b>this</b>; <s n=\"1.\">as subst., <b>this one</b>, <b>he</b>; <s n=\"(a)\">absol.: <r v=\"Matt.3.17\"></r>, <r v=\"Mark.9.7\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"Luke.7.45\"></r>, <r v=\"John.1.15\"></r>, <r v=\"Acts.2.15\"></r>, al.; expressing contempt (cl.), <r v=\"Matt.13.55\"></r>, <r v=\"Matt.13.56\"></r>, <r v=\"Mark.6.2\"></r>, <r v=\"Mark.6.3\"></r>, <r v=\"John.6.42\"></r>, al.; <g>εἰς τοῦτο</g>, <r v=\"Mark.1.38\"></r>, <r v=\"Rom.14.9\"></r>; <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>; V. Westc. on <r v=\"John.5.1\"></r>), <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>, al.;</s> <s n=\"(b)\">epanaleptic (referring to what precedes): <r v=\"Matt.5.19\"></r>, <r v=\"Mark.3.35\"></r>, <r v=\"Luke.9.48\"></r>, <r v=\"John.6.46\"></r>, <r v=\"Rom.7.10\"></r>, al.;</s> <s n=\"(c)\">proleptic (referring to what follows): seq. <g>ἵνα</g> (Bl., § 69, 6), <r v=\"Luke.1.43\"></r>, <r v=\"John.3.19\"></r> (and freq.) <r v=\"John.15.8\"></r>, <r v=\"Rom.14.9\"></r>, al.; seq. <g>ὅτι</g>, <r v=\"Luke.10.11\"></r>, <r v=\"John.9.30\"></r>, <r v=\"Acts.24.14\"></r>, <r v=\"Rom.2.3\"></r>, al.; <g>ὅπως</g>, <r v=\"Rom.9.17\"></r>; <g>ἐάν</g>, <r v=\"John.13.35\"></r>;</s> <s n=\"(d)\">special idioms: <g>τοῦτο μὲν . . . τ. δέ</g> (cl), <b>partly . . . partly</b>, <r v=\"Heb.10.33\"></r>; <g>καὶ τοῦτο</g> (<g>τοῦτον</g>, <g>ταῦτα</g>), <b>and that</b> (<b>him</b>) <b>too</b>, <r v=\"Rom.13.11\"></r>, <r v=\"1Cor.2.2\"></r>, <r v=\"Heb.11.12\"></r>; <g>τοῦτ’ ἐστιν</g>, <b>that is to say</b>, <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">As adj., c. subst.; <s n=\"(a)\">c. art. <s n=\"(α)\">before the art.: <r v=\"Matt.12.32\"></r>, <r v=\"Mark.9.29\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"John.4.15\"></r>, <r v=\"Rom.11.24\"></r>, <r v=\"Rev.19.9\"></r>, al.;</s> <s n=\"(β)\">after the noun: <r v=\"Matt.3.9\"></r>, <r v=\"Mark.12.16\"></r>, <r v=\"Luke.11.31\"></r>, <r v=\"John.4.13\"></r>, <r v=\"Acts.6.13\"></r>, <r v=\"Rom.15.28\"></r>, <r v=\"1Cor.1.20\"></r>, <r v=\"Rev.2.24\"></r>, al.;</s> </s> <s n=\"(b)\">c. subst. anarth. (with predicative force; Bl., § 49, 4): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>, <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>, <r v=\"2Cor.13.1\"></r>.</s> </s> </s>","ar":"<f><o>οὗτος</o>، <g>αὕτη, τοῦτο</g>، حالة الجر: <g>τούτου, ταύτης, τούτου</g>،</f> ضمير إشارة (علاقته بـ <g>ἐκεῖνος</g> كعلاقة <l>hic</l> بـ <l>ille</l>، أي «هذا» مقابل «ذاك»)، <s><b>هذا</b>؛ <s n=\"1.\">اسمًا: <b>هذا</b>، <b>هو</b>؛ <s n=\"(a)\">مطلقًا: <r v=\"Matt.3.17\"></r>، <r v=\"Mark.9.7\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"Luke.7.45\"></r>، <r v=\"John.1.15\"></r>، <r v=\"Acts.2.15\"></r>، وفي مواضع أخرى؛ للتعبير عن الاحتقار، <r v=\"Matt.13.55\"></r>، <r v=\"Matt.13.56\"></r>، <r v=\"Mark.6.2\"></r>، <r v=\"Mark.6.3\"></r>، <r v=\"John.6.42\"></r>، وفي مواضع أخرى؛ <g>εἰς τοῦτο</g> (لهذا)، <r v=\"Mark.1.38\"></r>، <r v=\"Rom.14.9\"></r>؛ <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>؛ انظر <r v=\"John.5.1\"></r>) (بعد هذا)، <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">إعاديًا (يشير إلى ما سبق): <r v=\"Matt.5.19\"></r>، <r v=\"Mark.3.35\"></r>، <r v=\"Luke.9.48\"></r>، <r v=\"John.6.46\"></r>، <r v=\"Rom.7.10\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">استباقيًا (يشير إلى ما يلي): يليه <g>ἵνα</g>، <r v=\"Luke.1.43\"></r>، <r v=\"John.3.19\"></r> (وكثيرًا) <r v=\"John.15.8\"></r>، <r v=\"Rom.14.9\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g>، <r v=\"Luke.10.11\"></r>، <r v=\"John.9.30\"></r>، <r v=\"Acts.24.14\"></r>، <r v=\"Rom.2.3\"></r>، وفي مواضع أخرى؛ <g>ὅπως</g>، <r v=\"Rom.9.17\"></r>؛ <g>ἐάν</g>، <r v=\"John.13.35\"></r>؛</s> <s n=\"(d)\">تعابير خاصة: <g>τοῦτο μὲν . . . τ. δέ</g>: <b>من جهة . . . ومن جهة أخرى</b>، <r v=\"Heb.10.33\"></r>؛ <g>καὶ τοῦτο</g> (<g>τοῦτον</g>، <g>ταῦτα</g>): <b>وذلك</b> (<b>وإياه</b>) <b>أيضًا</b>، <r v=\"Rom.13.11\"></r>، <r v=\"1Cor.2.2\"></r>، <r v=\"Heb.11.12\"></r>؛ <g>τοῦτ’ ἐστιν</g>: <b>أي، أعني</b>، <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">صفةً مع اسم؛ <s n=\"(a)\">مع أداة التعريف، <s n=\"(α)\">قبل الأداة: <r v=\"Matt.12.32\"></r>، <r v=\"Mark.9.29\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"John.4.15\"></r>، <r v=\"Rom.11.24\"></r>، <r v=\"Rev.19.9\"></r>، وفي مواضع أخرى؛</s> <s n=\"(β)\">بعد الاسم: <r v=\"Matt.3.9\"></r>، <r v=\"Mark.12.16\"></r>، <r v=\"Luke.11.31\"></r>، <r v=\"John.4.13\"></r>، <r v=\"Acts.6.13\"></r>، <r v=\"Rom.15.28\"></r>، <r v=\"1Cor.1.20\"></r>، <r v=\"Rev.2.24\"></r>، وفي مواضع أخرى؛</s> </s> <s n=\"(b)\">مع اسم بدون أداة التعريف (بمعنى الخبر): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>، <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>، <r v=\"2Cor.13.1\"></r>.</s> </s> </s>"},"G5218":{"l":"ὑπακοή","o":15,"en":"<f>† <o>ὑπακοή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὑπακούω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Sam.22.36\"></r> (<h n=\"H6038\">עֲנָוָה</h>); in Aq.: <r v=\"2Sam.23.23\"></r> * ;]</e> </et> <s><b>obedience</b> (opp. to <g>παρακοή</g>); </s> <s n=\"1.\">in general, absol., <g>εἰς ὑ.</g>, <r v=\"Rom.6.16\"></r>; c. gen. subjc., <r v=\"2Cor.7.15\"></r> <r v=\"2Cor.10.6\"></r>, <r v=\"Phlm.1.21\"></r>; c. gen. obj., <r v=\"Rom.1.5\"></r> (Lft, <i>Notes</i>, 246) <r v=\"Rom.16.26\"></r>, <r v=\"1Pet.1.22\"></r>; <g>τ. Χριστοῦ</g>, <r v=\"2Cor.10.5\"></r>. </s> <s n=\"2.\">Of obedience to God's commands: absol., <r v=\"1Pet.1.2\"></r>; opp. to <g>ἁμαρτία</g>, <r v=\"Rom.6.16\"></r>; <g>τέκνα ὑπακοῆς</g>, <r v=\"1Pet.1.14\"></r>; c. gen. subj., <r v=\"Rom.15.18\"></r> <r v=\"Rom.16.19\"></r>. </s> <s n=\"3.\">Of Christ's obedience: absol., <r v=\"Heb.5.8\"></r>; c. gen. subj., <r v=\"Rom.5.19\"></r>. </s> <s>(The word is not found except in LXX, NT and eccl.).†</s>","ar":"<f>† <o>ὑπακοή</o>، <g>-ῆς, ἡ</g></f> <s><b>طاعة</b> (عكس <g>παρακοή</g>)؛ </s> <s n=\"1.\">بوجه عام، مطلقًا، <g>εἰς ὑ.</g>، <r v=\"Rom.6.16\"></r>؛ مع المضاف إليه الفاعلي، <r v=\"2Cor.7.15\"></r> <r v=\"2Cor.10.6\"></r>، <r v=\"Phlm.1.21\"></r>؛ مع المضاف إليه المفعولي، <r v=\"Rom.1.5\"></r> <r v=\"Rom.16.26\"></r>، <r v=\"1Pet.1.22\"></r>؛ <g>τ. Χριστοῦ</g>، <r v=\"2Cor.10.5\"></r>. </s> <s n=\"2.\">عن الطاعة لوصايا الله: مطلقًا، <r v=\"1Pet.1.2\"></r>؛ عكس <g>ἁμαρτία</g>، <r v=\"Rom.6.16\"></r>؛ <g>τέκνα ὑπακοῆς</g>، <r v=\"1Pet.1.14\"></r>؛ مع المضاف إليه الفاعلي، <r v=\"Rom.15.18\"></r> <r v=\"Rom.16.19\"></r>. </s> <s n=\"3.\">عن طاعة المسيح: مطلقًا، <r v=\"Heb.5.8\"></r>؛ مع المضاف إليه الفاعلي، <r v=\"Rom.5.19\"></r>. </s> <s>(لا ترد الكلمة إلا في السبعينية والعهد الجديد والكتابات الكنسية).†</s>"},"G5228":{"l":"ὑπέρ","o":150,"en":"<f><o>ὑπέρ</o> (when following subst.—poët.—<g>ὕπερ</g>; so as adv., <r v=\"2Cor.11.23\"></r>), </f> prep. c. gen., acc. <s> <s n=\"I.\">C. gen., primarily of place (rest or motion), <b>over, above, across, beyond</b>, hence, metaph., <s n=\"1.\"><b>for, on behalf of</b>: of prayer, <r v=\"Matt.5.44\"></r>, <r v=\"Acts.8.24\"></r>, <r v=\"Rom.10.1\"></r>, <r v=\"Jas.5.16\"></r>, al.; of laying down life, <r v=\"John.10.11\"></r>, <r v=\"Rom.9.3\"></r>, al.; esp. of Christ giving his life for man's redemption, <r v=\"Mark.14.24\"></r>, <r v=\"John.10.15\"></r>, <r v=\"Acts.21.13\"></r>, <r v=\"Rom.5.6-Rom.5.8\"></r>, al.; opp. to <g>κατά</g>, <r v=\"Mark.9.40\"></r>, <r v=\"Luke.9.50\"></r>, <r v=\"Rom.8.31\"></r>. </s> <s n=\"2.\">Causal, <b>for, because of, for the sake of</b>: c. gen. pers., <r v=\"Acts.5.41\"></r>, <r v=\"Rom.1.5\"></r>, <r v=\"Phil.1.29\"></r>, <r v=\"2Cor.12.10\"></r>, al.; c. gen. rei, <r v=\"John.11.4\"></r>, <r v=\"Rom.15.8\"></r>, <r v=\"2Cor.1.6\"></r>, al. </s> <s n=\"3.\"> = <g>ἀντί</g> (v. M, <i>Pr.</i>, 105), <b>for, instead of, in the name of</b> : <r v=\"1Cor.15.29\"></r>, <r v=\"2Cor.5.15\"></r>, <r v=\"2Cor.5.21\"></r> <r v=\"Gal.3.13\"></r>, <r v=\"Col.1.7\"></r>, <r v=\"Phlm.1.13\"></r> (cf. Field, <i>Notes</i>, 225). </s> <s n=\"4.\">In more colourless sense, = <g>περί</g> (M, <i>Pr.</i>, l.c.), <b>for, concerning, with regard to</b>: <r v=\"Rom.9.27\"></r>, <r v=\"2Cor.1.6\"></r> <r v=\"2Cor.8.23\"></r> <r v=\"2Cor.12.8\"></r>, <r v=\"Phil.1.7\"></r>, <r v=\"2Thess.2.1\"></r>, al. </s> </s> <s n=\"II.\">C. acc., primarily of place, <b>over, beyond, across</b>, hence, metaph., of measure or degree in excess, <b>above, beyond, over, more than</b>: <r v=\"Matt.10.24\"></r>, <r v=\"Matt.10.37\"></r> <r v=\"Luke.6.40\"></r>, <r v=\"Acts.26.13\"></r>, <r v=\"1Cor.10.13\"></r>, <r v=\"2Cor.1.8\"></r>, <r v=\"Eph.1.22\"></r> <r v=\"Eph.3.20\"></r>, <r v=\"Phlm.1.16\"></r>, al.; after comparatives = <b>than</b> (<r v=\"Judg.11.25\"></r>, al.), <r v=\"Luke.16.8\"></r>, <r v=\"Heb.4.12\"></r>. </s> <s n=\"III.\">As adv. (v. supr. ad init.), <b>more</b>: <g>ὕπερ ἐγώ</g>, <b>I more</b>, <r v=\"2Cor.11.23\"></r>; in compounds, v.s. <g>ὑπεράνω, ὑπερλίαν, ὑπερπερισσῶς</g>. </s> <s n=\"IV.\">In composition: <b>over</b> (<g>ὑπεραίρω</g>), <b>beyond</b> (<g>ὑπερβάλλω</g>), <b>more</b> (<g>ὐπερνικάω</g>), <b>on behalf of</b> (<g>ὐπερεντυγχάνω</g>).</s> </s>","ar":"<f><o>ὑπέρ</o> (وعندما يأتي بعد الاسم — شعريًا — <g>ὕπερ</g>؛ وكذلك ظرفًا، <r v=\"2Cor.11.23\"></r>)، </f> حرف جر مع المضاف إليه والمنصوب <s> <s n=\"I.\">مع المضاف إليه، أصلاً عن المكان (سكونًا أو حركةً)، <b>فوق، عبر، وراء</b>، ومن ثم مجازيًا، <s n=\"1.\"><b>لأجل، نيابةً عن</b>: عن الصلاة، <r v=\"Matt.5.44\"></r>، <r v=\"Acts.8.24\"></r>، <r v=\"Rom.10.1\"></r>، <r v=\"Jas.5.16\"></r>، وفي مواضع أخرى؛ عن بذل النفس، <r v=\"John.10.11\"></r>، <r v=\"Rom.9.3\"></r>، وفي مواضع أخرى؛ خاصةً عن المسيح باذلاً نفسه لفداء الإنسان، <r v=\"Mark.14.24\"></r>، <r v=\"John.10.15\"></r>، <r v=\"Acts.21.13\"></r>، <r v=\"Rom.5.6-Rom.5.8\"></r>، وفي مواضع أخرى؛ عكس <g>κατά</g>، <r v=\"Mark.9.40\"></r>، <r v=\"Luke.9.50\"></r>، <r v=\"Rom.8.31\"></r>. </s> <s n=\"2.\">سببيًّا، <b>لأجل، بسبب، من أجل</b>: مع المضاف إليه للشخص، <r v=\"Acts.5.41\"></r>، <r v=\"Rom.1.5\"></r>، <r v=\"Phil.1.29\"></r>، <r v=\"2Cor.12.10\"></r>، وفي مواضع أخرى؛ مع المضاف إليه للشيء، <r v=\"John.11.4\"></r>، <r v=\"Rom.15.8\"></r>، <r v=\"2Cor.1.6\"></r>، وفي مواضع أخرى. </s> <s n=\"3.\"> = <g>ἀντί</g>، <b>عن، عوضًا عن، باسم</b>: <r v=\"1Cor.15.29\"></r>، <r v=\"2Cor.5.15\"></r>، <r v=\"2Cor.5.21\"></r> <r v=\"Gal.3.13\"></r>، <r v=\"Col.1.7\"></r>، <r v=\"Phlm.1.13\"></r>. </s> <s n=\"4.\">بمعنى أضعف، = <g>περί</g>، <b>عن، بخصوص، من جهة</b>: <r v=\"Rom.9.27\"></r>، <r v=\"2Cor.1.6\"></r> <r v=\"2Cor.8.23\"></r> <r v=\"2Cor.12.8\"></r>، <r v=\"Phil.1.7\"></r>، <r v=\"2Thess.2.1\"></r>، وفي مواضع أخرى. </s> </s> <s n=\"II.\">مع المنصوب، أصلاً عن المكان، <b>فوق، وراء، عبر</b>، ومن ثم مجازيًا، عن مقدار أو درجة زائدة، <b>فوق، أكثر من، يفوق</b>: <r v=\"Matt.10.24\"></r>، <r v=\"Matt.10.37\"></r> <r v=\"Luke.6.40\"></r>، <r v=\"Acts.26.13\"></r>، <r v=\"1Cor.10.13\"></r>، <r v=\"2Cor.1.8\"></r>، <r v=\"Eph.1.22\"></r> <r v=\"Eph.3.20\"></r>، <r v=\"Phlm.1.16\"></r>، وفي مواضع أخرى؛ بعد صيغة التفضيل = <b>من</b> (<r v=\"Judg.11.25\"></r>، وفي مواضع أخرى)، <r v=\"Luke.16.8\"></r>، <r v=\"Heb.4.12\"></r>. </s> <s n=\"III.\">ظرفًا (انظر أعلاه في البداية)، <b>أكثر</b>: <g>ὕπερ ἐγώ</g>، <b>أنا أكثر</b>، <r v=\"2Cor.11.23\"></r>؛ وفي المركبات، انظر تحت مدخل <g>ὑπεράνω, ὑπερλίαν, ὑπερπερισσῶς</g>. </s> <s n=\"IV.\">في التركيب: <b>فوق</b> (<g>ὑπεραίρω</g>)، <b>وراء</b> (<g>ὑπερβάλλω</g>)، <b>أكثر</b> (<g>ὐπερνικάω</g>)، <b>نيابةً عن</b> (<g>ὐπερεντυγχάνω</g>).</s> </s>"},"G5371":{"l":"φιλήμων","o":1,"en":"<f><o>φιλήμων</o>, <g>-ονος, ὁ </g></f> <s><b>Philemon</b>: <r v=\"Phlm.1.1\"></r>.†</s>","ar":"<f><o>φιλήμων</o>، <g>-ονος, ὁ </g></f> <s><b>فليمون</b>: <r v=\"Phlm.1.1\"></r>.†</s>"},"G5479":{"l":"χαρά","o":59,"en":"<f><o>χαρά</o>, <g>-ᾶς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>χαίρω</g></x>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H8057\">שִׂמְחָה</h>, <h n=\"H8342\">שָׂשׂוֹן</h>, etc. ;]</e> </et> <s><b>joy, delight</b>: <r v=\"Luke.1.14\"></r> <r v=\"Luke.15.7\"></r>, <r v=\"Luke.15.10\"></r>, <r v=\"John.15.11\"></r> <r v=\"John.16.22\"></r>, <r v=\"John.16.24\"></r> <r v=\"John.17.13\"></r>, <r v=\"Acts.8.8\"></r>, <r v=\"2Cor.1.24\"></r> <r v=\"2Cor.7.13\"></r> <r v=\"2Cor.8.2\"></r>, <r v=\"Gal.5.22\"></r>, <r v=\"Col.1.11\"></r>, <r v=\"Phil.2.2\"></r>, <r v=\"1John.1.4\"></r>, <r v=\"2John.1.12\"></r>; opp. to <g>κατήφεια</g>, <r v=\"Jas.4.9\"></r>; to <g>λύπη</g>, <r v=\"John.16.20\"></r>; <g>χ. τῆς πίστεως</g>, <r v=\"Phil.1.25\"></r>; <g>ἀγαλλιᾶσθαι</g> (<g>χαίρειν</g>, q.v.), <g>χαρᾷ</g>, <r v=\"John.3.29\"></r>, <r v=\"1Pet.1.8\"></r>; <g>χ. ἔχειν</g>, <r v=\"Phlm.1.7\"></r>; <g>πληροῦν</g> (<g>-οῦσθαι</g>) <g>χαρᾶς</g>, <r v=\"Acts.13.52\"></r>, <r v=\"Rom.15.13\"></r>, <r v=\"2Tim.1.4\"></r>; <g>ποιεῖν χ. μεγάλην</g>, <r v=\"Acts.15.3\"></r>; <g>ἀπὸ τῆς χ.</g>, <r v=\"Matt.13.44\"></r>, <r v=\"Luke.24.41\"></r>, <r v=\"Acts.12.14\"></r>; <g>ἐν χ.</g>, <r v=\"Rom.15.32\"></r>; <g>μετὰ χαρᾶς</g>, <r v=\"Matt.13.20\"></r> <r v=\"Matt.28.8\"></r>, <r v=\"Mark.4.16\"></r>, <r v=\"Luke.8.13\"></r> <r v=\"Luke.10.17\"></r> <r v=\"Luke.24.52\"></r>, <r v=\"Phil.1.4\"></r> <r v=\"Phil.2.29\"></r>, <r v=\"Heb.10.34\"></r> <r v=\"Heb.13.17\"></r>; id. seq.<g>πνεύματος ἁγίου</g>, <r v=\"1Thess.1.6\"></r>; <g>χ. ἐν π. ἁ</g>, <r v=\"Rom.14.17\"></r>; <g>χ. ἐπί</g>, <r v=\"2Cor.7.4\"></r>; <g>διά</g>, <r v=\"1Thess.3.9\"></r>; <g>ὅτι</g>, <r v=\"John.16.21\"></r>; <g>ἵνα</g>, <r v=\"3John.1.4\"></r> By meton., of the cause or occasion of joy: <r v=\"Luke.2.10\"></r>, <r v=\"2Cor.1.15\"></r>, WH, txt., R, mg., <r v=\"Phil.4.1\"></r>, <r v=\"1Thess.2.19-1Thess.2.20\"></r>, <r v=\"Heb.12.2\"></r>, <r v=\"Jas.1.2\"></r>; <g>ἡ χ. τ. κυρίου</g>, <r v=\"Matt.25.21\"></r>, <r v=\"Matt.25.23\"></r>.†</s>","ar":"<f><o>χαρά</o>، <g>-ᾶς, ἡ</g></f> <s><b>فرح، سرور، بهجة</b>: <r v=\"Luke.1.14\"></r> <r v=\"Luke.15.7\"></r>، <r v=\"Luke.15.10\"></r>، <r v=\"John.15.11\"></r> <r v=\"John.16.22\"></r>، <r v=\"John.16.24\"></r> <r v=\"John.17.13\"></r>، <r v=\"Acts.8.8\"></r>، <r v=\"2Cor.1.24\"></r> <r v=\"2Cor.7.13\"></r> <r v=\"2Cor.8.2\"></r>، <r v=\"Gal.5.22\"></r>، <r v=\"Col.1.11\"></r>، <r v=\"Phil.2.2\"></r>، <r v=\"1John.1.4\"></r>، <r v=\"2John.1.12\"></r>؛ عكس <g>κατήφεια</g> (الغم)، <r v=\"Jas.4.9\"></r>؛ وعكس <g>λύπη</g> (الحزن)، <r v=\"John.16.20\"></r>؛ <g>χ. τῆς πίστεως</g> (فرح الإيمان)، <r v=\"Phil.1.25\"></r>؛ <g>ἀγαλλιᾶσθαι</g> (<g>χαίρειν</g>، انظره)، <g>χαρᾷ</g> (يفرح فرحًا)، <r v=\"John.3.29\"></r>، <r v=\"1Pet.1.8\"></r>؛ <g>χ. ἔχειν</g> (لنا فرح)، <r v=\"Phlm.1.7\"></r>؛ <g>πληροῦν</g> (<g>-οῦσθαι</g>) <g>χαρᾶς</g> (يمتلئ فرحًا)، <r v=\"Acts.13.52\"></r>، <r v=\"Rom.15.13\"></r>، <r v=\"2Tim.1.4\"></r>؛ <g>ποιεῖν χ. μεγάλην</g> (يسبب فرحًا عظيمًا)، <r v=\"Acts.15.3\"></r>؛ <g>ἀπὸ τῆς χ.</g> (من الفرح)، <r v=\"Matt.13.44\"></r>، <r v=\"Luke.24.41\"></r>، <r v=\"Acts.12.14\"></r>؛ <g>ἐν χ.</g> (بفرح)، <r v=\"Rom.15.32\"></r>؛ <g>μετὰ χαρᾶς</g> (بفرح)، <r v=\"Matt.13.20\"></r> <r v=\"Matt.28.8\"></r>، <r v=\"Mark.4.16\"></r>، <r v=\"Luke.8.13\"></r> <r v=\"Luke.10.17\"></r> <r v=\"Luke.24.52\"></r>، <r v=\"Phil.1.4\"></r> <r v=\"Phil.2.29\"></r>، <r v=\"Heb.10.34\"></r> <r v=\"Heb.13.17\"></r>؛ والتعبير نفسه يليه <g>πνεύματος ἁγίου</g>، <r v=\"1Thess.1.6\"></r>؛ <g>χ. ἐν π. ἁ</g> (فرح في الروح القدس)، <r v=\"Rom.14.17\"></r>؛ <g>χ. ἐπί</g>، <r v=\"2Cor.7.4\"></r>؛ <g>διά</g>، <r v=\"1Thess.3.9\"></r>؛ <g>ὅτι</g>، <r v=\"John.16.21\"></r>؛ <g>ἵνα</g>، <r v=\"3John.1.4\"></r>. وكنايةً عن سبب الفرح أو مناسبته: <r v=\"Luke.2.10\"></r>، <r v=\"2Cor.1.15\"></r>، <r v=\"Phil.4.1\"></r>، <r v=\"1Thess.2.19-1Thess.2.20\"></r>، <r v=\"Heb.12.2\"></r>، <r v=\"Jas.1.2\"></r>؛ <g>ἡ χ. τ. κυρίου</g> (فرح سيدك)، <r v=\"Matt.25.21\"></r>، <r v=\"Matt.25.23\"></r>.†</s>"},"G5483":{"l":"χαρίζομαι","o":23,"en":"<f><o>χαρίζομαι</o></f> <et> <e t=\"derivation\">(&lt; <x><g>χάρις</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Esth.8.7\"></r> (<h n=\"H5414\">נתן</h>), <r v=\"Song.1.4\"></r> <h>א</h>, <r v=\"Sir.12.3\"></r>, II-IV Mac <i>9</i> * ;]</e> </et> <s n=\"1.\"><b>to show favour or kindness</b>: c. dat. pers., <r v=\"Gal.3.18\"></r>. </s> <s n=\"2.\"><b>to give freely, bestow</b>: c. acc et dat., <r v=\"Luke.7.21\"></r>, <r v=\"Acts.3.14\"></r> <r v=\"Acts.25.11\"></r>, <r v=\"Acts.25.16\"></r> <r v=\"Acts.27.24\"></r>, <r v=\"Rom.8.32\"></r>, <r v=\"1Cor.2.12\"></r>, <r v=\"Phil.1.29\"></r> <r v=\"Phil.2.9\"></r>, <r v=\"Phlm.1.22\"></r>. </s> <s n=\"3.\">In late Gk. (= Lat. <l>condonare</l>), <b>to grant forgiveness, forgive freely</b>: of debt, <r v=\"Luke.7.42-Luke.7.43\"></r> (EGT, in l.); of sin, <r v=\"2Cor.2.7\"></r>, <r v=\"2Cor.2.10\"></r> <r v=\"2Cor.12.13\"></r>, <r v=\"Eph.4.32\"></r>, <r v=\"Col.2.13\"></r> <r v=\"Col.3.13\"></r> (cf. <i>DB</i>, ii, 57<i>a</i>).†</s>","ar":"<f><o>χαρίζομαι</o></f> <s n=\"1.\"><b>يُظهر نعمة أو لطفًا، يُنعم على</b>: مع القابل للأشخاص، <r v=\"Gal.3.18\"></r>. </s> <s n=\"2.\"><b>يهب مجانًا، يمنح</b>: مع المنصوب والقابل، <r v=\"Luke.7.21\"></r>، <r v=\"Acts.3.14\"></r> <r v=\"Acts.25.11\"></r>، <r v=\"Acts.25.16\"></r> <r v=\"Acts.27.24\"></r>، <r v=\"Rom.8.32\"></r>، <r v=\"1Cor.2.12\"></r>، <r v=\"Phil.1.29\"></r> <r v=\"Phil.2.9\"></r>، <r v=\"Phlm.1.22\"></r>. </s> <s n=\"3.\">في اليونانية المتأخرة (= اللاتينية <l>condonare</l>): <b>يصفح، يسامح مجانًا</b>: عن الدَّين، <r v=\"Luke.7.42-Luke.7.43\"></r>؛ عن الخطية، <r v=\"2Cor.2.7\"></r>، <r v=\"2Cor.2.10\"></r> <r v=\"2Cor.12.13\"></r>، <r v=\"Eph.4.32\"></r>، <r v=\"Col.2.13\"></r> <r v=\"Col.3.13\"></r>.†</s>"},"G5485":{"l":"χάρις","o":155,"en":"<f><o>χάρις, -ιτος, ἡ <i>Abbott-Smith does not include the article here.</i></o>, acc., <g>χάριν</g> (<g>χάριτα</g> in <r v=\"Acts.24.27\"></r>, <r v=\"Jude.1.4\"></r>; v. WH, <i>App.</i>, 157), </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2580\">חֵן</h> ;]</e> </et> <s> <s n=\"1.\">objectively, that which causes favourable regard, <b>gracefulness, grace, loveliness</b> of form, <b>graciousness</b> of speech (cl.; <r v=\"Eccl.10.12\"></r>, <r v=\"Sir.21.16\"></r>, al.): <r v=\"Col.4.6\"></r>; <g>λόγοι τ. χάριτος</g> (gen. qual.), <r v=\"Luke.4.22\"></r>. </s> <s n=\"2.\">Subjectively, <s n=\"(a)\">on the part of the giver, <b>grace, graciousness, kindness, goodwill, favour</b>: <r v=\"Luke.2.52\"></r>, <r v=\"Acts.7.10\"></r>, al.; esp. in NT of the divine <b>favour, grace</b>, with emphasis on its freeness and universality: <r v=\"Luke.1.30\"></r>, <r v=\"Acts.14.26\"></r>, <r v=\"Rom.1.7\"></r>, <r v=\"1Cor.1.3\"></r>, al.; opp. to <g>ὀφείλημα</g>, <r v=\"Rom.4.4\"></r>, 16; to <g>ἔργα</g>, <r v=\"Rom.11.6\"></r>; </s> <s n=\"(b)\">on the part of the receiver, a sense of favour received, <b>thanks, gratitude</b>: <r v=\"Rom.6.17\"></r> <r v=\"Rom.7.25\"></r>, al.; <g>χ. ἔχειν</g>, <b>to be thankful</b>, <r v=\"Luke.17.9\"></r>, <r v=\"1Tim.1.12\"></r>, al. </s> </s> <s n=\"3.\">Objectively, of the effect of grace, <s n=\"(a)\">a state of <b>grace</b>: <r v=\"Rom.5.2\"></r>, <r v=\"2Tim.2.1\"></r>, <r v=\"1Pet.5.12\"></r>, <r v=\"2Pet.3.18\"></r>; </s> <s n=\"(b)\">a proof or gift of <b>grace</b> (cl., <b>a favour</b>): <r v=\"John.1.16\"></r>, <r v=\"Acts.6.8\"></r>, <r v=\"Rom.1.5\"></r>, <r v=\"1Cor.3.10\"></r>, <r v=\"2Cor.9.8\"></r>, <r v=\"Gal.2.9\"></r>, <r v=\"Eph.3.2\"></r>, <r v=\"1Pet.5.5\"></r>, <r v=\"1Pet.5.10\"></r> al. (For fuller treatment of the NT usage, v. AR, <i>Eph.</i>, 221 ff.; <i>DB</i>, ii, 254 ff.; <i>DCG</i>, i, 686 ff.; Cremer, s.v.). </s> </s> </s>","ar":"<f><o>χάρις, -ιτος, ἡ <i>Abbott-Smith does not include the article here.</i></o>، حالة النصب: <g>χάριν</g> (<g>χάριτα</g> في <r v=\"Acts.24.27\"></r>، <r v=\"Jude.1.4\"></r>)، </f> <s> <s n=\"1.\">بالمعنى الموضوعي، ما يجلب الاستحسان: <b>جمال، نعمة، حُسن</b> الهيئة، <b>لُطف</b> الكلام (قارن <r v=\"Eccl.10.12\"></r>، <r v=\"Sir.21.16\"></r>، وفي مواضع أخرى): <r v=\"Col.4.6\"></r>؛ <g>λόγοι τ. χάριτος</g> (المضاف إليه للنوع): <r v=\"Luke.4.22\"></r>. </s> <s n=\"2.\">بالمعنى الذاتي، <s n=\"(a)\">من جهة المُعطي: <b>نعمة، لُطف، إحسان، رضا، حظوة</b>: <r v=\"Luke.2.52\"></r>، <r v=\"Acts.7.10\"></r>، وفي مواضع أخرى؛ وخاصةً في العهد الجديد عن <b>رضا</b> الله و<b>نعمته</b>، مع التشديد على مجانيتها وشمولها: <r v=\"Luke.1.30\"></r>، <r v=\"Acts.14.26\"></r>، <r v=\"Rom.1.7\"></r>، <r v=\"1Cor.1.3\"></r>، وفي مواضع أخرى؛ عكس <g>ὀφείλημα</g>: <r v=\"Rom.4.4\"></r>، 16؛ وعكس <g>ἔργα</g>: <r v=\"Rom.11.6\"></r>؛ </s> <s n=\"(b)\">من جهة المُتلقي، الإحساس بالإحسان المقبول: <b>شكر، امتنان</b>: <r v=\"Rom.6.17\"></r>، <r v=\"Rom.7.25\"></r>، وفي مواضع أخرى؛ <g>χ. ἔχειν</g>: <b>شكر، كان ممتنًّا</b>: <r v=\"Luke.17.9\"></r>، <r v=\"1Tim.1.12\"></r>، وفي مواضع أخرى. </s> </s> <s n=\"3.\">بالمعنى الموضوعي، عن أثر النعمة، <s n=\"(a)\">حالة <b>النعمة</b>: <r v=\"Rom.5.2\"></r>، <r v=\"2Tim.2.1\"></r>، <r v=\"1Pet.5.12\"></r>، <r v=\"2Pet.3.18\"></r>؛ </s> <s n=\"(b)\">دليل <b>النعمة</b> أو عطيتها (<b>معروف، إحسان</b>): <r v=\"John.1.16\"></r>، <r v=\"Acts.6.8\"></r>، <r v=\"Rom.1.5\"></r>، <r v=\"1Cor.3.10\"></r>، <r v=\"2Cor.9.8\"></r>، <r v=\"Gal.2.9\"></r>، <r v=\"Eph.3.2\"></r>، <r v=\"1Pet.5.5\"></r>، <r v=\"1Pet.5.10\"></r>، وفي مواضع أخرى. </s> </s> </s>"},"G5495":{"l":"χείρ","o":177,"en":"<f><o>χείρ</o>, gen., <g>χειρος</g> (acc., <g>χεῖραν</g>, <r v=\"1Pet.5.6\"></r> T), <g>ἡ</g>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3027\">יָד</h> ;]</e> </et> <s><b>the hand</b>: <r v=\"Matt.3.12\"></r>, <r v=\"Mark.3.1\"></r>, <r v=\"Luke.6.6\"></r>, al. mult.; <g>ἡ χ.</g>, acting subject, <r v=\"Luke.22.21\"></r>; pl., <r v=\"Acts.17.25\"></r> <r v=\"Acts.20.34\"></r>, <r v=\"1John.1.1\"></r>; <g>τ. ἔργα τῶν χ.</g>, <r v=\"Acts.7.41\"></r>, <r v=\"Rev.9.20\"></r>; <g>ὁ ἀσπασμὸς τ. ἐμῇ χ.</g>, <r v=\"1Cor.16.21\"></r>, <r v=\"Col.4.18\"></r>, <r v=\"2Thess.3.17\"></r>; prepositional phrases, esp. those without art., similar to Heb. constructions (Bl., §32, 4; 40, 9; 46, 9), <g>ἐν χ.</g>; c gen. (Lft., in l.), <r v=\"Gal.3.19\"></r>; <g>σὺν χ. ἀγγέλου</g>, <r v=\"Acts.7.35\"></r>; <g>διὰ (τῶν) χειρῶν (διὰ χειρός)</g>, <r v=\"Mark.6.2\"></r>, <r v=\"Acts.5.12\"></r> <r v=\"Acts.7.25\"></r>, al.; <g>ἐπὶ χειρῶν</g>, <r v=\"Matt.4.6\"></r>, <r v=\"Luke.4.11\"></r>; ellipse of <g>χ.</g> (<g>ἡ δεξία, ἀριστερα</g>; Bl., § 44, 1), <r v=\"Matt.6.3\"></r>, al. By meton., for the power or activity of an individual, <r v=\"Matt.17.22\"></r>, <r v=\"Mark.9.31\"></r>, <r v=\"Luke.9.44\"></r>, <r v=\"John.10.39\"></r>, <r v=\"Acts.12.11\"></r>, al.; metaph., of the activity or power of God: <r v=\"Luke.1.66\"></r> <r v=\"Luke.23.46\"></r>, <r v=\"John.10.29\"></r>, <r v=\"Acts.11.21\"></r> <r v=\"Acts.13.11\"></r>, al. </s>","ar":"<f><o>χείρ</o>، المضاف إليه: <g>χειρος</g> (حالة النصب: <g>χεῖραν</g>، <r v=\"1Pet.5.6\"></r>)، <g>ἡ</g>، </f> <s><b>يد</b>: <r v=\"Matt.3.12\"></r>، <r v=\"Mark.3.1\"></r>، <r v=\"Luke.6.6\"></r>، ومواضع أخرى كثيرة؛ <g>ἡ χ.</g> فاعلاً: <r v=\"Luke.22.21\"></r>؛ في الجمع: <r v=\"Acts.17.25\"></r>، <r v=\"Acts.20.34\"></r>، <r v=\"1John.1.1\"></r>؛ <g>τ. ἔργα τῶν χ.</g>: <r v=\"Acts.7.41\"></r>، <r v=\"Rev.9.20\"></r>؛ <g>ὁ ἀσπασμὸς τ. ἐμῇ χ.</g>: <r v=\"1Cor.16.21\"></r>، <r v=\"Col.4.18\"></r>، <r v=\"2Thess.3.17\"></r>؛ عبارات بحروف الجر، خاصةً ما كان منها بدون أداة التعريف، شبيهة بتراكيب عبرية: <g>ἐν χ.</g>؛ مع المضاف إليه: <r v=\"Gal.3.19\"></r>؛ <g>σὺν χ. ἀγγέλου</g>: <r v=\"Acts.7.35\"></r>؛ <g>διὰ (τῶν) χειρῶν (διὰ χειρός)</g>: <r v=\"Mark.6.2\"></r>، <r v=\"Acts.5.12\"></r>، <r v=\"Acts.7.25\"></r>، وفي مواضع أخرى؛ <g>ἐπὶ χειρῶν</g>: <r v=\"Matt.4.6\"></r>، <r v=\"Luke.4.11\"></r>؛ حذف <g>χ.</g> (<g>ἡ δεξία, ἀριστερα</g>): <r v=\"Matt.6.3\"></r>، وفي مواضع أخرى. وكنايةً عن قدرة الشخص أو عمله: <r v=\"Matt.17.22\"></r>، <r v=\"Mark.9.31\"></r>، <r v=\"Luke.9.44\"></r>، <r v=\"John.10.39\"></r>، <r v=\"Acts.12.11\"></r>، وفي مواضع أخرى؛ ومجازيًا عن عمل الله أو قدرته: <r v=\"Luke.1.66\"></r>، <r v=\"Luke.23.46\"></r>، <r v=\"John.10.29\"></r>، <r v=\"Acts.11.21\"></r>، <r v=\"Acts.13.11\"></r>، وفي مواضع أخرى. </s>"},"G5547":{"l":"Χριστός","o":529,"en":"<f><o>χριστός (Χρ-)</o>, <g>-ή, -όν</g> </f> <et> <e t=\"derivation\">(&lt; <x><g>χρίω</g></x>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H4899\">מָשִׁיחַ</h> and cogn. forms ;]</e> </et> <s> <s n=\"1.\">as adj., <s n=\"(a)\">of things, <b>anointing, to be used as ointment</b> (Æsch., Eur., al.; <g>τ. ἔλαιον τὸ χ.</g>, <r v=\"Lev.21.10\"></r>); </s> <s n=\"(b)\">of persons, <b>anointed</b> (<g>ὁ ἰερεὺς ὁ χ.</g>, <r v=\"Lev.4.5\"></r>; <g>οἱ χ. ἰευρεῖς</g>, <r v=\"2Macc.1.10\"></r>): <g>ὁ χ. τοῦ κυρίου</g> or <g>Θεοῦ</g> (<r v=\"1Ki.2.10\"></r>, <r v=\"Ps.2.2\"></r>, al.), of the Messiah (Aram., <h n=\"????\">מְשִׁיחָא</h>; cf. Dalman, <i>Words</i>, 289 ff.), <r v=\"Luke.2.11\"></r>, <r v=\"Luke.2.26\"></r> <r v=\"John.1.41\"></r>, <r v=\"Acts.2.36\"></r> <r v=\"Acts.4.26\"></r>, al. </s> </s> <s n=\"2.\">As subst., <g>ὁ Χριστός</g>, <b>the Messiah, the Christ</b>: <r v=\"Matt.2.4\"></r>, <r v=\"Mark.8.29\"></r>, <r v=\"Luke.2.11\"></r>, <r v=\"John.1.20\"></r>, <r v=\"Acts.2.31\"></r>, <r v=\"Rom.7.4\"></r>, al.; <g>Ἰησοῦς Χ.</g>, <r v=\"Mark.1.1\"></r>, <r v=\"John.1.17\"></r>, <r v=\"Acts.2.38\"></r>, al.; <g>Χ. Ἰησοῦς</g>, <r v=\"Matt.1.18\"></r>, WH, mg. <r v=\"Acts.5.42\"></r>, <r v=\"Rom.6.3\"></r>, al.; <g>Χ. κύριος</g>, <r v=\"Luke.2.11\"></r>; <g>Ἰησοῦς Χ. ὁ κύριος</g>, <r v=\"Acts.15.26\"></r>, <r v=\"Rom.1.7\"></r>, al. </s> </s>","ar":"<f><o>χριστός (Χρ-)</o>، <g>-ή, -όν</g> </f> <s> <s n=\"1.\">صفةً، <s n=\"(a)\">عن الأشياء: <b>للمسح، يُستعمل دهنًا</b> (<g>τ. ἔλαιον τὸ χ.</g>: <r v=\"Lev.21.10\"></r>)؛ </s> <s n=\"(b)\">عن الأشخاص: <b>ممسوح، مسيح</b> (<g>ὁ ἰερεὺς ὁ χ.</g>: <r v=\"Lev.4.5\"></r>؛ <g>οἱ χ. ἰευρεῖς</g>: <r v=\"2Macc.1.10\"></r>): <g>ὁ χ. τοῦ κυρίου</g> أو <g>Θεοῦ</g> (<r v=\"1Ki.2.10\"></r>، <r v=\"Ps.2.2\"></r>، وفي مواضع أخرى)، عن المسيّا (الآرامية <h n=\"????\">מְשִׁיחָא</h>): <r v=\"Luke.2.11\"></r>، <r v=\"Luke.2.26\"></r>، <r v=\"John.1.41\"></r>، <r v=\"Acts.2.36\"></r>، <r v=\"Acts.4.26\"></r>، وفي مواضع أخرى. </s> </s> <s n=\"2.\">اسمًا، <g>ὁ Χριστός</g>: <b>المسيّا، المسيح</b>: <r v=\"Matt.2.4\"></r>، <r v=\"Mark.8.29\"></r>، <r v=\"Luke.2.11\"></r>، <r v=\"John.1.20\"></r>، <r v=\"Acts.2.31\"></r>، <r v=\"Rom.7.4\"></r>، وفي مواضع أخرى؛ <g>Ἰησοῦς Χ.</g>: <r v=\"Mark.1.1\"></r>، <r v=\"John.1.17\"></r>، <r v=\"Acts.2.38\"></r>، وفي مواضع أخرى؛ <g>Χ. Ἰησοῦς</g>: <r v=\"Matt.1.18\"></r>، <r v=\"Acts.5.42\"></r>، <r v=\"Rom.6.3\"></r>، وفي مواضع أخرى؛ <g>Χ. κύριος</g>: <r v=\"Luke.2.11\"></r>؛ <g>Ἰησοῦς Χ. ὁ κύριος</g>: <r v=\"Acts.15.26\"></r>، <r v=\"Rom.1.7\"></r>، وفي مواضع أخرى. </s> </s>"},"G5563":{"l":"χωρίζω","o":13,"en":"<f><o>χωρίζω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Chr.12.8\"></r>, al. (<h n=\"H914\">בּדל</h> ni., etc.), <r v=\"Wis.1.3\"></r>, <r v=\"2Macc.5.21\"></r>, al. ;] </e> </et> <s n=\"1.\"><b>to separate, divide, put asunder</b>: c. acc. rei, opp. to <g>συζεύγνυμι</g> <r v=\"Matt.19.6\"></r>, <r v=\"Mark.10.9\"></r>; c. acc. pers., seq. <g>ἀπό</g> (<r v=\"Wis.1.3\"></r>), <r v=\"Rom.8.35\"></r>, <r v=\"Rom.8.39\"></r>; pf. pass ptcp., <r v=\"Heb.7.26\"></r>. </s> <s n=\"2.\">In late writers, mid. and 1 aor pass., to separate oneself, depart: <r v=\"Phlm.1.15\"></r>; seq. <g>ἀπό</g> <r v=\"Acts.1.4\"></r>, <g>ἐκ</g>, <r v=\"Acts.18.1-Acts.18.2\"></r>; of divorce (polyb., al.), <r v=\"1Cor.7.10-1Cor.7.11\"></r>, <r v=\"1Cor.7.15\"></r> (cf. <g>ἀπο-</g>, <g>δια-χωρίζω</g>).†</s>","ar":"<f><o>χωρίζω </o></f> <s n=\"1.\"><b>يفرِّق، يفصل، يقسم</b>: مع المنصوب للأشياء، عكس <g>συζεύγνυμι</g> (يجمع)، <r v=\"Matt.19.6\"></r>، <r v=\"Mark.10.9\"></r>؛ مع المنصوب للأشخاص، يليه <g>ἀπό</g> (<r v=\"Wis.1.3\"></r>)، <r v=\"Rom.8.35\"></r>، <r v=\"Rom.8.39\"></r>؛ اسم الفاعل التام المبني للمجهول (منفصل)، <r v=\"Heb.7.26\"></r>. </s> <s n=\"2.\">الصيغة الوسطى والماضي البسيط الأول المبني للمجهول: <b>ينفصل، يفارق، يرحل</b>: <r v=\"Phlm.1.15\"></r>؛ يليه <g>ἀπό</g> <r v=\"Acts.1.4\"></r>، <g>ἐκ</g>، <r v=\"Acts.18.1-Acts.18.2\"></r>؛ عن الطلاق (الفراق بين الزوجين)، <r v=\"1Cor.7.10-1Cor.7.11\"></r>، <r v=\"1Cor.7.15\"></r> (قارن <g>ἀπο-</g>، <g>δια-χωρίζω</g>).†</s>"},"G5565":{"l":"χωρίς","o":41,"en":"<f><o>χωρίς </o></f> adv., <s n=\"1.\"><b>separately, apart</b>: <r v=\"John.20.7\"></r>. </s> <s n=\"2.\">As prep., c. gen., </s> <s n=\"(a)\"><b>separate from, apart from, without</b> (practically equiv. to <g>ἄνευ</g>; v. Field, <i>Notes</i>, 103): <r v=\"Matt.13.34\"></r>, <r v=\"Mark.4.34\"></r>, <r v=\"Luke.6.49\"></r>, <r v=\"John.1.3\"></r> <r v=\"John.15.5\"></r>, <r v=\"Rom.3.21\"></r>, <r v=\"Rom.3.28\"></r> <r v=\"Rom.4.6\"></r> <r v=\"Rom.7.8-Rom.7.9\"></r> <r v=\"Rom.10.14\"></r>, <r v=\"1Cor.4.8\"></r> <r v=\"1Cor.11.11\"></r>, <r v=\"2Cor.12.3\"></r>, <r v=\"Eph.2.12\"></r>, <r v=\"Phil.2.14\"></r>, <r v=\"1Tim.2.8\"></r> <r v=\"1Tim.5.21\"></r>, <r v=\"Phlm.1.14\"></r>, <r v=\"Heb.4.15\"></r> <r v=\"Heb.7.7\"></r>, <r v=\"Heb.7.20\"></r> <r v=\"Heb.9.7\"></r>, <r v=\"Heb.9.18\"></r> <r v=\"Heb.9.22\"></r>, <r v=\"Heb.9.28\"></r> <r v=\"Heb.10.28\"></r> <r v=\"Heb.11.6\"></r>, <r v=\"Heb.11.40\"></r> <r v=\"Heb.12.8\"></r>, <r v=\"Heb.12.14\"></r> (<g>οὗ χωρίς</g>; v. Bl., § 82, 3), <r v=\"Jas.2.18\"></r>, <r v=\"Jas.2.20\"></r>, <r v=\"Jas.2.26\"></r>; </s> <s n=\"(b)\"><b>besides</b>: <r v=\"Matt.14.21\"></r> <r v=\"Matt.15.38\"></r>, <r v=\"2Cor.11.28\"></r>.†</s>","ar":"<f><o>χωρίς </o></f> ظرف، <s n=\"1.\"><b>على حدة، منفردًا</b>: <r v=\"John.20.7\"></r>. </s> <s n=\"2.\">حرف جر مع المضاف إليه، </s> <s n=\"(a)\"><b>منفصلاً عن، بمعزل عن، بدون</b> (يكاد يساوي <g>ἄνευ</g>): <r v=\"Matt.13.34\"></r>، <r v=\"Mark.4.34\"></r>، <r v=\"Luke.6.49\"></r>، <r v=\"John.1.3\"></r> <r v=\"John.15.5\"></r>، <r v=\"Rom.3.21\"></r>، <r v=\"Rom.3.28\"></r> <r v=\"Rom.4.6\"></r> <r v=\"Rom.7.8-Rom.7.9\"></r> <r v=\"Rom.10.14\"></r>، <r v=\"1Cor.4.8\"></r> <r v=\"1Cor.11.11\"></r>، <r v=\"2Cor.12.3\"></r>، <r v=\"Eph.2.12\"></r>، <r v=\"Phil.2.14\"></r>، <r v=\"1Tim.2.8\"></r> <r v=\"1Tim.5.21\"></r>، <r v=\"Phlm.1.14\"></r>، <r v=\"Heb.4.15\"></r> <r v=\"Heb.7.7\"></r>، <r v=\"Heb.7.20\"></r> <r v=\"Heb.9.7\"></r>، <r v=\"Heb.9.18\"></r> <r v=\"Heb.9.22\"></r>، <r v=\"Heb.9.28\"></r> <r v=\"Heb.10.28\"></r> <r v=\"Heb.11.6\"></r>، <r v=\"Heb.11.40\"></r> <r v=\"Heb.12.8\"></r>، <r v=\"Heb.12.14\"></r> (<g>οὗ χωρίς</g>: الذي بدونه)، <r v=\"Jas.2.18\"></r>، <r v=\"Jas.2.20\"></r>، <r v=\"Jas.2.26\"></r>؛ </s> <s n=\"(b)\"><b>عدا، ما عدا، فضلاً عن</b>: <r v=\"Matt.14.21\"></r> <r v=\"Matt.15.38\"></r>، <r v=\"2Cor.11.28\"></r>.†</s>"},"G5610":{"l":"ὥρα","o":100,"en":"<f><o>ὥρα</o>, <g>-ας, ἡ</g>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6256\">עֵת</h> and in Da for <h n=\"H8159\">שָׁעָה</h> ;]</e> </et> <s> <s n=\"1.\">any <b>time</b> or <b>period</b> fixed by nature, esp. a <b>season</b> (Hom., Hdt., Plat., al.). </s> <s n=\"2.\">A part of the day, and esp. a twelfth part of day or night, <b>an hour</b>: <r v=\"Matt.24.36\"></r>, <r v=\"Mark.13.32\"></r>, <r v=\"Acts.10.3\"></r>, al.; accus. in ans. to \"when\"? (M, <i>Pr.</i>, 63, 215; Bl., § 34, 8), <r v=\"John.4.52\"></r>, <r v=\"Acts.10.3\"></r>, <r v=\"Acts.10.30\"></r> <r v=\"1Cor.15.30\"></r>, <r v=\"Rev.3.3\"></r>; acc. of duration, <r v=\"Matt.20.12\"></r> <r v=\"Matt.26.40\"></r>, <r v=\"Mark.14.37\"></r>; inexactly, <g>πρὸς ὥραν</g>, <b>for a season, for a time</b>, <r v=\"John.5.35\"></r>, <r v=\"2Cor.7.8\"></r>, <r v=\"Gal.2.5\"></r>; <g>πρὸς καιρὸν ὥρας</g>, <b>for a short season</b> (<i>ICC</i>, in l.), <r v=\"1Thess.2.17\"></r>. </s> <s n=\"3.\">A definite point of time, <b>time, hour</b>: <r v=\"Matt.26.45\"></r>; c. gen. rei, <r v=\"Luke.1.10\"></r> <r v=\"Luke.14.17\"></r>, <r v=\"Rev.3.10\"></r>, al.; c. gen. pers., <r v=\"Luke.22.53\"></r>, <r v=\"John.2.4\"></r> <r v=\"John.7.30\"></r>, al.; <g>ἡ ἄρτι ὥρα</g>, <r v=\"1Cor.4.11\"></r>; <g>ἐσχάτη ὥ.</g>, <r v=\"1John.2.18\"></r>; seq. <g>ὅτε</g>, <r v=\"John.4.21\"></r>, <r v=\"John.4.23\"></r> <r v=\"John.5.25\"></r> <r v=\"John.16.25\"></r>; <g>ἵνα</g>, <r v=\"John.12.23\"></r>, al.; c. acc. et inf., <r v=\"Rom.13.11\"></r> (cf. <i>DB</i>, ext., 475<i>b</i>, 476<i>b</i>). </s> </s>","ar":"<f><o>ὥρα</o>، <g>-ας, ἡ</g>، </f> <s> <s n=\"1.\">أيُّ <b>وقت</b> أو <b>فترة</b> تحددها الطبيعة، خاصةً <b>فصل</b> من فصول السنة. </s> <s n=\"2.\">جزء من النهار، وخاصةً جزء من اثني عشر جزءًا من النهار أو الليل، <b>ساعة</b>: <r v=\"Matt.24.36\"></r>، <r v=\"Mark.13.32\"></r>، <r v=\"Acts.10.3\"></r>، وفي مواضع أخرى؛ منصوبًا جوابًا عن «متى؟»، <r v=\"John.4.52\"></r>، <r v=\"Acts.10.3\"></r>، <r v=\"Acts.10.30\"></r> <r v=\"1Cor.15.30\"></r>، <r v=\"Rev.3.3\"></r>؛ منصوبًا للمدة، <r v=\"Matt.20.12\"></r> <r v=\"Matt.26.40\"></r>، <r v=\"Mark.14.37\"></r>؛ على وجه التقريب، <g>πρὸς ὥραν</g>، <b>إلى ساعة، إلى حين</b>، <r v=\"John.5.35\"></r>، <r v=\"2Cor.7.8\"></r>، <r v=\"Gal.2.5\"></r>؛ <g>πρὸς καιρὸν ὥρας</g>، <b>إلى زمان ساعة (لوقت قصير)</b>، <r v=\"1Thess.2.17\"></r>. </s> <s n=\"3.\">لحظة محددة من الزمن، <b>وقت، ساعة</b>: <r v=\"Matt.26.45\"></r>؛ مع المضاف إليه للشيء، <r v=\"Luke.1.10\"></r> <r v=\"Luke.14.17\"></r>، <r v=\"Rev.3.10\"></r>، وفي مواضع أخرى؛ مع المضاف إليه للشخص، <r v=\"Luke.22.53\"></r>، <r v=\"John.2.4\"></r> <r v=\"John.7.30\"></r>، وفي مواضع أخرى؛ <g>ἡ ἄρτι ὥρα</g>، <r v=\"1Cor.4.11\"></r>؛ <g>ἐσχάτη ὥ.</g>، <r v=\"1John.2.18\"></r>؛ يليه <g>ὅτε</g>، <r v=\"John.4.21\"></r>، <r v=\"John.4.23\"></r> <r v=\"John.5.25\"></r> <r v=\"John.16.25\"></r>؛ <g>ἵνα</g>، <r v=\"John.12.23\"></r>، وفي مواضع أخرى؛ مع المنصوب والمصدر، <r v=\"Rom.13.11\"></r>. </s> </s>"},"G5613":{"l":"ὡς","o":435,"en":"<f><o>ὡς</o>, adverbial form of the relative pron. <g>ὅς, ἥ, ὅ</g>. </f> <s> <s n=\"I.\">As relat. adv. of manner, <b>as, like as, just as, even as</b>; <s n=\"1.\">with a demonstrative, like <g>οὕτως</g>, expressed or understood: <g>οὕτως . . . ὡς</g>, <r v=\"Mark.4.26\"></r>, <r v=\"1Cor.3.15\"></r>, <r v=\"Eph.5.28\"></r>, <r v=\"Jas.2.12\"></r>, al.; <g>ὡς . . . οὕτως</g>, <r v=\"Acts.8.32\"></r>, <r v=\"1Cor.7.17\"></r>, al.; elliptically (sc. <g>οὕτως, οὕτω</g>), c. nom., <r v=\"Matt.6.29\"></r>, al.; c. acc., <r v=\"Matt.19.19\"></r>, <r v=\"Mark.12.31\"></r>, al.; c. prep., <r v=\"Matt.26.55\"></r>, <r v=\"Mark.14.48\"></r>, <r v=\"Luke.22.52\"></r>, <r v=\"John.7.10\"></r>, al.; c. verb., <r v=\"John.15.6\"></r>, <r v=\"2Cor.3.1\"></r>, <r v=\"Eph.2.3\"></r>, <r v=\"1Thess.5.6\"></r>, al.; c. ptcp. (the ptcp. however not having the special force wh. it has in cl.; v. Bl., §73, 5; 74, 6), <r v=\"Matt.7.29\"></r>, <r v=\"Mark.1.22\"></r>, <r v=\"Heb.13.17\"></r>, al.; freq implying opinion or belief, <r v=\"Rom.9.32\"></r>; so esp, c. gen. absol., <r v=\"1Cor.4.18\"></r>, <r v=\"2Cor.5.20\"></r>, <r v=\"1Pet.4.12\"></r>, <r v=\"2Pet.1.3\"></r>. </s> <s n=\"2.\">Before numerals, <b>about, nearly</b>: <r v=\"Mark.5.13\"></r>, <r v=\"John.1.40\"></r>, <r v=\"Acts.5.7\"></r>, al. </s> <s n=\"3.\">Before adjectives and adverbs, <b>how</b>: <r v=\"Rom.10.15\"></r> <r v=\"Rom.11.33\"></r>, <r v=\"1Thess.2.10\"></r>; c. superl., <g>ὡς τάχιστα</g>, <b>as quickly as possible</b>, <r v=\"Acts.17.15\"></r>. </s> </s> <s n=\"II.\">As conjunction; <s n=\"1.\">temporal, <s n=\"(a)\"><b>as, when, since</b>: <r v=\"Mark.9.21\"></r> <r v=\"Mark.14.72\"></r>, <r v=\"Luke.1.23\"></r>, <r v=\"John.2.9\"></r>, al.; </s> <s n=\"(b)\"><b>while, when, as long as</b>: <r v=\"Luke.12.58\"></r>, <r v=\"John.12.36\"></r>, <r v=\"Gal.6.10\"></r> (Field, <i>Notes</i>, 191); <g>ὡς ἄν</g> (M, <i>Pr.</i>, 167, and v.s. <g>ἄν</g>), <r v=\"Rom.15.24\"></r>, <r v=\"1Cor.11.34\"></r>, <r v=\"Phil.2.23\"></r>. </s> </s> <s n=\"2.\">Final, <b>in order that</b>; c. inf., <b>in order to</b> (M, <i>Pr.</i>, 204n), <r v=\"Luke.9.52\"></r>, <r v=\"Acts.20.24\"></r>, <r v=\"Heb.7.9\"></r>. </s> </s> </s>","ar":"<f><o>ὡς</o>، الصيغة الظرفية لاسم الموصول <g>ὅς, ἥ, ὅ</g>. </f> <s> <s n=\"I.\">ظرفَ موصولٍ للحال (الكيفية)، <b>كما، مثل، كما أن، على نحو ما</b>؛ <s n=\"1.\">مع اسم إشارة، مثل <g>οὕτως</g>، مذكور أو مقدَّر: <g>οὕτως . . . ὡς</g>، <r v=\"Mark.4.26\"></r>، <r v=\"1Cor.3.15\"></r>، <r v=\"Eph.5.28\"></r>، <r v=\"Jas.2.12\"></r>، وفي مواضع أخرى؛ <g>ὡς . . . οὕτως</g>، <r v=\"Acts.8.32\"></r>، <r v=\"1Cor.7.17\"></r>، وفي مواضع أخرى؛ بالحذف (والمقدَّر <g>οὕτως, οὕτω</g>)، مع حالة الرفع، <r v=\"Matt.6.29\"></r>، وفي مواضع أخرى؛ مع المنصوب، <r v=\"Matt.19.19\"></r>، <r v=\"Mark.12.31\"></r>، وفي مواضع أخرى؛ مع حرف جر، <r v=\"Matt.26.55\"></r>، <r v=\"Mark.14.48\"></r>، <r v=\"Luke.22.52\"></r>، <r v=\"John.7.10\"></r>، وفي مواضع أخرى؛ مع فعل، <r v=\"John.15.6\"></r>، <r v=\"2Cor.3.1\"></r>، <r v=\"Eph.2.3\"></r>، <r v=\"1Thess.5.6\"></r>، وفي مواضع أخرى؛ مع اسم الفاعل، <r v=\"Matt.7.29\"></r>، <r v=\"Mark.1.22\"></r>، <r v=\"Heb.13.17\"></r>، وفي مواضع أخرى؛ وكثيرًا ما يفيد الظن أو الاعتقاد، <r v=\"Rom.9.32\"></r>؛ وهكذا خاصةً مع المضاف إليه المطلق، <r v=\"1Cor.4.18\"></r>، <r v=\"2Cor.5.20\"></r>، <r v=\"1Pet.4.12\"></r>، <r v=\"2Pet.1.3\"></r>. </s> <s n=\"2.\">قبل الأعداد، <b>نحو، قرابة</b>: <r v=\"Mark.5.13\"></r>، <r v=\"John.1.40\"></r>، <r v=\"Acts.5.7\"></r>، وفي مواضع أخرى. </s> <s n=\"3.\">قبل الصفات والظروف، <b>ما أ...!، كم</b>: <r v=\"Rom.10.15\"></r> <r v=\"Rom.11.33\"></r>، <r v=\"1Thess.2.10\"></r>؛ مع صيغة التفضيل العليا، <g>ὡς τάχιστα</g>، <b>بأسرع ما يمكن</b>، <r v=\"Acts.17.15\"></r>. </s> </s> <s n=\"II.\">أداةَ ربط؛ <s n=\"1.\">زمانية، <s n=\"(a)\"><b>لمّا، حين، منذ</b>: <r v=\"Mark.9.21\"></r> <r v=\"Mark.14.72\"></r>، <r v=\"Luke.1.23\"></r>، <r v=\"John.2.9\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(b)\"><b>بينما، حين، ما دام</b>: <r v=\"Luke.12.58\"></r>، <r v=\"John.12.36\"></r>، <r v=\"Gal.6.10\"></r>؛ <g>ὡς ἄν</g> (انظر تحت مدخل <g>ἄν</g>)، <r v=\"Rom.15.24\"></r>، <r v=\"1Cor.11.34\"></r>، <r v=\"Phil.2.23\"></r>. </s> </s> <s n=\"2.\">غائية، <b>لكي</b>؛ مع المصدر، <b>لأجل أن</b>، <r v=\"Luke.9.52\"></r>، <r v=\"Acts.20.24\"></r>، <r v=\"Heb.7.9\"></r>. </s> </s> </s>"},"G568":{"l":"ἀπέχω","o":25,"en":"<f><o>ἀπ-έχω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7368\">רחק</h>;]</e> </et> <s n=\"1.\">trans., <s n=\"(a)\"><b>to hold back</b>, <b>keep off</b>;</s> <s n=\"(b)\"><b>to have in full</b>, <b>to have received</b> (on the \"punctiliar\" force of the compound, v. M, <i>Pr.</i>, 109, 247): c. acc., <r v=\"Matt.6.2\"></r>, <r v=\"Matt.6.5\"></r>, <r v=\"Matt.6.16\"></r>, <r v=\"Luke.6.24\"></r>, <r v=\"Phil.4.18\"></r>, <r v=\"Phlm.1.15\"></r> (for illustr. from <g>π.</g>, where it is used in receipts, v. Deiss., <i>BS</i>, 229; <i>LAE</i>, 110 f.; MM, s.v.); impers., <g>ἀπέχει</g> (Field, <i>Notes</i>, 39), <b>it is enough</b>: <r v=\"Mark.14.41\"></r>.</s> </s> <s n=\"2.\">Intrans., <b>to be away</b>, <b>distant</b>: absol., <r v=\"Luke.15.20\"></r>; seq. <g>ἀπό</g>, <r v=\"Matt.14.24\"></r> <r v=\"Matt.15.8\"></r>, <r v=\"Mark.7.6\"></r>, <r v=\"Luke.7.6\"></r> <r v=\"Luke.15.20\"></r> <r v=\"Luke.24.13\"></r>. Mid., <b>to abstain</b>: c. gen., <r v=\"Acts.15.29\"></r>, <r v=\"1Tim.4.3\"></r>, <r v=\"1Pet.2.11\"></r>; seq. <g>ἀπό</g>, <r v=\"Acts.15.20\"></r>, <r v=\"1Thess.4.3\"></r> <r v=\"1Thess.5.22\"></r>.†</s>","ar":"<f><o>ἀπ-έχω</o>،</f> <s n=\"1.\">متعدٍّ، <s n=\"(a)\"><b>أمسك عن</b>، <b>أبعد</b>؛</s> <s n=\"(b)\"><b>نال كاملاً</b>، <b>استوفى</b>: مع المنصوب: <r v=\"Matt.6.2\"></r>، <r v=\"Matt.6.5\"></r>، <r v=\"Matt.6.16\"></r>، <r v=\"Luke.6.24\"></r>، <r v=\"Phil.4.18\"></r>، <r v=\"Phlm.1.15\"></r>؛ غير شخصي، <g>ἀπέχει</g>: <b>يكفي</b>: <r v=\"Mark.14.41\"></r>.</s> </s> <s n=\"2.\">لازم: <b>كان بعيدًا</b>، <b>على مسافة</b>: مطلقًا: <r v=\"Luke.15.20\"></r>؛ يليه <g>ἀπό</g>: <r v=\"Matt.14.24\"></r>، <r v=\"Matt.15.8\"></r>، <r v=\"Mark.7.6\"></r>، <r v=\"Luke.7.6\"></r>، <r v=\"Luke.15.20\"></r>، <r v=\"Luke.24.13\"></r>. الصيغة الوسطى: <b>امتنع عن</b>: مع المضاف إليه: <r v=\"Acts.15.29\"></r>، <r v=\"1Tim.4.3\"></r>، <r v=\"1Pet.2.11\"></r>؛ يليه <g>ἀπό</g>: <r v=\"Acts.15.20\"></r>، <r v=\"1Thess.4.3\"></r>، <r v=\"1Thess.5.22\"></r>.†</s>"},"G661":{"l":"ἀποτίνω","o":1,"en":"<f><o>ἀπο-τίνω</o> (or <g>-τίω</g>),</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7999\">שׂלם</h> pi.;]</e> </et> <s><b>to pay off</b>, <b>repay</b>: <r v=\"Phlm.1.19\"></r> (MM, s.v.).†</s>","ar":"<f><o>ἀπο-τίνω</o> (أو <g>-τίω</g>)،</f> <s><b>وفّى</b>، <b>ردّ، عوّض</b>: <r v=\"Phlm.1.19\"></r>.†</s>"},"G682":{"l":"Ἀπφία","o":1,"en":"<f><o>Ἀπφία</o>, <g>-ας, ἡ</g>,</f> <s><b>Apphia</b>: <r v=\"Phlm.1.2\"></r> (MM, s.v.).†</s>","ar":"<f><o>Ἀπφία</o>، <g>-ας, ἡ</g>،</f> <s><b>أبفية</b>: <r v=\"Phlm.1.2\"></r>.†</s>"},"G708":{"l":"Ἀρίσταρχος","o":5,"en":"<f><o>Ἀρίσταρχος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄριστος</g></x>, <x><g>ἀρχός</g></x>; i.e. <i>best-ruling</i>),</e> </et> <s><b>Aristarchus</b>: <r v=\"Acts.19.29\"></r> <r v=\"Acts.20.4\"></r> <r v=\"Acts.27.2\"></r>, <r v=\"Col.4.10\"></r>, <r v=\"Phlm.1.24\"></r>.†</s>","ar":"<f><o>Ἀρίσταρχος</o>، <g>-ου, ὁ</g></f> <s><b>أرسترخس</b>: <r v=\"Acts.19.29\"></r> <r v=\"Acts.20.4\"></r> <r v=\"Acts.27.2\"></r>، <r v=\"Col.4.10\"></r>، <r v=\"Phlm.1.24\"></r>.†</s>"},"G751":{"l":"Ἄρχιππος","o":2,"en":"<f><o>Ἄρχιππος</o>, <g>-ου, ὁ</g>,</f> <s><b>Archippus</b>: <r v=\"Col.4.17\"></r>, <r v=\"Phlm.1.2\"></r>.†</s>","ar":"<f><o>Ἄρχιππος</o>، <g>-ου, ὁ</g>،</f> <s><b>أرخبُّس</b>: <r v=\"Col.4.17\"></r>، <r v=\"Phlm.1.2\"></r>.†</s>"},"G782":{"l":"ἀσπάζομαι","o":59,"en":"<f><o>ἀσπάζομαι</o> depon.,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.18.7\"></r>, <r v=\"Judg.18.15\"></r> (<h n=\"H7965\">לְשָׁלוֹם</h> <h n=\"H7592\">שָׁאַל</h>), <r v=\"Ezra.5.2\"></r>, <r v=\"1Macc.7.29\"></r>, al.;]</e> </et> <s><b>to welcome</b>, <b>greet, salute</b>: c. acc. pers., <r v=\"Matt.5.47\"></r>, <r v=\"Mark.9.15\"></r>, <r v=\"Acts.21.7\"></r>, al.; id. seq. <g>ἐν φιλήματι</g>, <r v=\"Rom.16.16\"></r>, <r v=\"1Cor.16.20\"></r>, <r v=\"2Cor.13.12\"></r>, <r v=\"1Thess.5.26\"></r>, <r v=\"1Pet.5.14\"></r>; <g>τ. ἐκκλησίαν</g> (Deiss., <i>BS</i>, 257), <r v=\"Acts.18.22\"></r>; as <i>term. tech.</i> for conveying greetings at the end of a letter (MM, s.v.), used by an amanuensis (Milligan, <i>NTD</i>, 23), <r v=\"Rom.16.22\"></r> (on the aoristic pres., here and elsewhere, v. M, <i>Pr.</i>, 119; Bl., § 56, 4); <g>κατήντησαν . . . ἀσπασάμενοι</g> (on this constr., v. Bl., § 58, 4; M, <i>Pr.</i>, 132, 238), <r v=\"Acts.25.13\"></r> (cf. <g>ἀπ-ασπάζομαι</g>).†</s>","ar":"<f><o>ἀσπάζομαι</o>، فعل لازم الصيغة الوسطى،</f> <s><b>رحّب</b>، <b>حيّا، سلّم على</b>: مع المنصوب للشخص: <r v=\"Matt.5.47\"></r>، <r v=\"Mark.9.15\"></r>، <r v=\"Acts.21.7\"></r>، وفي مواضع أخرى؛ ونفسه يليه <g>ἐν φιλήματι</g>: <r v=\"Rom.16.16\"></r>، <r v=\"1Cor.16.20\"></r>، <r v=\"2Cor.13.12\"></r>، <r v=\"1Thess.5.26\"></r>، <r v=\"1Pet.5.14\"></r>؛ <g>τ. ἐκκλησίαν</g>: <r v=\"Acts.18.22\"></r>؛ مصطلحًا لنقل التحيات في ختام الرسالة، يستعمله الكاتب (الناسخ): <r v=\"Rom.16.22\"></r>؛ <g>κατήντησαν . . . ἀσπασάμενοι</g>: <r v=\"Acts.25.13\"></r> (قارن <g>ἀπ-ασπάζομαι</g>).†</s>"},"G79":{"l":"ἀδελφή","o":26,"en":"<f><o>ἀδελφή</o>, <g>-ῆς, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <x><g>ἀδελφός</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H269\">אָחוֹת</h>;]</e> </et> <s><b>a sister</b>: <r v=\"Matt.19.29\"></r>, al.; metaph. (MM, <i>VGT</i>, s.v.), of a member of the Christian community: <r v=\"Rom.16.1\"></r>, <r v=\"1Cor.7.15\"></r> <r v=\"Jas.21.15\"></r>, al.</s>","ar":"<f><o>ἀδελφή</o>، <g>-ῆς, ἡ</g> </f> <s><b>أخت</b>: <r v=\"Matt.19.29\"></r>، وفي مواضع أخرى؛ مجازيًا، عن عضو في الجماعة المسيحية: <r v=\"Rom.16.1\"></r>، <r v=\"1Cor.7.15\"></r> <r v=\"Jas.21.15\"></r>، وفي مواضع أخرى.</s>"},"G80":{"l":"ἀδελφός","o":343,"en":"<f><o>ἀδελφός</o>, <g>-οῦ, ὁ</g> </f> <et> <e t=\"derivation\">(&lt; <g>ἀ-</g> copul., <x><g>δελφύς</g></x>, <i>womb</i>),</e> </et> <s>in cl., <b>a brother</b>, born of the same parent or parents. [In LXX (Hort, <i>Ja.</i>, 102 f.), for <h n=\"H251\">אָח</h>;] <s n=\"1.\">lit. of a brother (<r v=\"Gen.4.2\"></r>, al.). </s> <s n=\"2.\">Of a neighbour (<r v=\"Lev.19.17\"></r>). </s> <s n=\"3.\">Of a member of the same nation (<r v=\"Exod.2.14\"></r>, <r v=\"Deut.15.3\"></r>). In NT in each of these senses (1. <r v=\"Matt.1.2\"></r>, al.; 2. <r v=\"Matt.7.3\"></r>; 3. <r v=\"Rom.9.3\"></r>) and also, </s> <s n=\"4.\">of a fellow-Christian: <r v=\"1Cor.1.1\"></r>, <r v=\"Acts.9.30\"></r>. This usage finds illustration in <g>π.</g>, where <g>ἀ.</g> is used of members of a pagan religious community (M, <i>Th.</i>, I, 1:4; MM, <i>VGT</i>, s.v.). The <g>ἀδελφοὶ τ. Κυρίου</g> (<r v=\"Matt.12.46-Matt.12.49\"></r> <r v=\"Matt.13.55\"></r> <r v=\"Matt.28.10\"></r>, <r v=\"Mark.3.31-Mark.3.34\"></r>, <r v=\"Luke.8.19-Luke.8.21\"></r>, <r v=\"John.2.12\"></r> <r v=\"John.7.3\"></r>, <r v=\"John.7.5\"></r> <r v=\"John.7.10\"></r> <r v=\"John.20.17\"></r>, <r v=\"Acts.1.14\"></r>, <r v=\"1Cor.9.5\"></r>) may have been sons of Joseph and Mary (Mayor, <i>Ja.</i>, Intr. viff.; <i>DB</i>, i, 320 ff.) or of Joseph by a former marriage (Lft., <i>Gal.</i>, 252ff.; <i>DCG</i>, i, 232 ff.), but the view of Jerome, which makes <g>ἀ.</g> equivalent to <g>ἀνεψιός</g>, is inconsistent with Greek usage. (Cremer, 66.)</s> </s>","ar":"<f><o>ἀδελφός</o>، <g>-οῦ, ὁ</g> </f> <s><b>أخ</b>، المولود من الأب نفسه أو الأم نفسها أو كليهما. [في السبعينية ترجمةً لـ <h n=\"H251\">אָח</h>:] <s n=\"1.\">حرفيًا، عن الأخ (<r v=\"Gen.4.2\"></r>، وفي مواضع أخرى). </s> <s n=\"2.\">عن القريب (<r v=\"Lev.19.17\"></r>). </s> <s n=\"3.\">عن ابن الأمة نفسها (<r v=\"Exod.2.14\"></r>، <r v=\"Deut.15.3\"></r>). وفي العهد الجديد يرد بكل هذه المعاني (1. <r v=\"Matt.1.2\"></r>، وفي مواضع أخرى؛ 2. <r v=\"Matt.7.3\"></r>؛ 3. <r v=\"Rom.9.3\"></r>) وأيضًا، </s> <s n=\"4.\">عن الأخ في الإيمان المسيحي: <r v=\"1Cor.1.1\"></r>، <r v=\"Acts.9.30\"></r>. أما <g>ἀδελφοὶ τ. Κυρίου</g> (إخوة الرب) (<r v=\"Matt.12.46-Matt.12.49\"></r> <r v=\"Matt.13.55\"></r> <r v=\"Matt.28.10\"></r>، <r v=\"Mark.3.31-Mark.3.34\"></r>، <r v=\"Luke.8.19-Luke.8.21\"></r>، <r v=\"John.2.12\"></r> <r v=\"John.7.3\"></r>، <r v=\"John.7.5\"></r> <r v=\"John.7.10\"></r> <r v=\"John.20.17\"></r>، <r v=\"Acts.1.14\"></r>، <r v=\"1Cor.9.5\"></r>) فربما كانوا أبناء يوسف ومريم، أو أبناء يوسف من زواج سابق، أما رأي جيروم الذي يجعل <g>ἀ.</g> مساويًا لـ <g>ἀνεψιός</g> (ابن العم أو الخال) فلا يتفق مع الاستعمال اليوناني.</s> </s>"},"G846":{"l":"αὐτός","o":5100,"en":"<f><o>αὐτός</o>, <g>-ή, -ό</g>,</f> determinative pron., in late Gk. much more freq. than in cl. (WM, 178 f.; Jannaris, <i>HGG</i>, §1399). <s n=\"1.\">Emphatic (so always in nom. exc. when preceded by the art., v. infr., iii); <s n=\"(1)\"><b>self</b> (<l>ipse</l>), expressing opposition, distinction, exclusion, etc., <g>αὐ. ἐκχυθήσεται</g>, <r v=\"Luke.5.37\"></r>; <g>αὐ. ἐγινώσκεν</g>, <r v=\"John.2.25\"></r>; <g>αὐ. ὑμεῖς</g>, <r v=\"John.3.28\"></r>; <g>καὶ αὐ. ἐγώ</g>, <r v=\"Rom.15.14\"></r>; <g>αὐ. Ἰησοῦς</g>, <r v=\"John.2.24\"></r>; <g>αὐ. καὶ οἱ μετ’ αὐτοῦ</g>, <r v=\"Matt.2.25\"></r>; <g>ὑμεῖς αὐ.</g>, <r v=\"Mark.6.31\"></r>; esp. (as freq in cl.) <g>αὐ. ὁ</g>, <r v=\"Matt.3.4\"></r>, <r v=\"Mark.6.17\"></r>, <r v=\"John.16.27\"></r>, <r v=\"1Thess.3.11\"></r>, al.; in late Gk., sometimes weakened, <g>ἐν αὐτῇ τ. ὥρᾳ</g>, <b>in that hour</b>, <r v=\"Luke.10.21\"></r> (M, <i>Pr.</i>, 91; MM, s.v.);</s> <s n=\"(2)\">emphatic, <b>he</b>, <b>she</b>, <b>it</b> (M, <i>Pr.</i>, 86; Bl., § 48, 1, 2, 7), <r v=\"Matt.1.21\"></r> <r v=\"Matt.12.50\"></r>, <r v=\"Luke.6.35\"></r>, al.; pointing to some one as master (cl.), <r v=\"Matt.8.24\"></r>, <r v=\"Mark.4.38\"></r>, al.; <g>αὐ., καὶ αὐ.</g> = <g>οὗτος, ὁ δε</g> (Bl., § 48, 1), <r v=\"Matt.14.2\"></r>, <r v=\"Mark.14.15\"></r>, <r v=\"Mark.14.44\"></r>, <r v=\"Luke.1.22\"></r> <r v=\"Luke.2.28\"></r>, al.</s> </s> <s n=\"2.\">In oblique cases (cl.), for the simple pron. of 3rd pers., <b>he</b>, <b>she</b>, <b>it</b>, <r v=\"Matt.7.9\"></r>, <r v=\"Matt.10.12\"></r>, <r v=\"Matt.26.44\"></r>, al.; with ptcp. in gen. absol., <r v=\"Matt.9.18\"></r>, <r v=\"Mark.13.1\"></r>, al. (for irreg. constructions, V. Bl., § 74, 5); pleonastically after the relative (cf. Heb. <h n=\"H834\">אֲשֶׁר לֹו</h>; WM, 184 ff.; Bl., § 50, 4; MM, s.v.), <r v=\"Mark.7.25\"></r>, <r v=\"Rev.3.8\"></r>, <r v=\"Rev.7.2\"></r>, al.; in constr. ad sensum, without proper subject expressly indicated, <r v=\"Matt.4.23\"></r>, <r v=\"Acts.8.5\"></r>, <r v=\"2Cor.2.13\"></r>, al.; gen. <g>αὐτοῦ</g> = <g>ἐκείνου</g>, <r v=\"Rom.11.11\"></r>, <r v=\"1Thess.2.19\"></r>, <r v=\"Titus.3.5\"></r>, <r v=\"Heb.2.4\"></r>.</s> <s n=\"3.\"><g>ὁ</g>, <g>ἡ</g>, <g>τὸ αὐ.</g>, <b>the same</b>: <r v=\"Heb.1.12\"></r>, <r v=\"Heb.13.8\"></r>; <g>τὸ αὐ.</g>, <g>ποιεῖν</g>, <r v=\"Matt.5.46\"></r>, <r v=\"Matt.5.47\"></r>, al.; <g>φρονεῖν</g>, <r v=\"Rom.12.16\"></r> <r v=\"Rom.15.5\"></r>, <r v=\"Phil.2.2\"></r>, al.; <g>τὰ αὐ.</g>, <r v=\"Acts.15.27\"></r>, <r v=\"Rom.2.1\"></r>, al.; <g>κατὰ τὸ</g> (<g>τὰ</g>) <g>αὐ.</g> (MM, s.v.), <r v=\"Acts.14.1\"></r>, <r v=\"Luke.6.23\"></r>, al.; <g>ἐπὶ τὸ αὐ.</g>, <b>together</b> (MM, s.v.), <r v=\"Matt.22.34\"></r>, <r v=\"Acts.1.15\"></r>, al.; <g>ἓν κ. τὸ αὐ.</g>, <r v=\"1Cor.11.5\"></r>, <r v=\"1Cor.12.11\"></r>; c. dat. (cl.), <r v=\"1Cor.11.5\"></r>; with a noun, <g>λόγος</g>, <r v=\"Mark\"></r>; <g>μέτρος</g>, <r v=\"Phil.1.30\"></r>; <g>πνεῦμα</g>, <r v=\"1Cor.12.4\"></r>.</s>","ar":"<f><o>αὐτός</o>، <g>-ή, -ό</g>،</f> ضمير تحديدي، وهو في اليونانية المتأخرة أكثر استعمالاً بكثير. <s n=\"1.\">للتوكيد (وهو كذلك دائمًا في حالة الرفع إلا إذا سبقته أداة التعريف، انظر أدناه، 3)؛ <s n=\"(1)\"><b>نفس، ذات</b> (<l>ipse</l>)، للتعبير عن المقابلة أو التمييز أو الحصر ونحوها: <g>αὐ. ἐκχυθήσεται</g>: <r v=\"Luke.5.37\"></r>؛ <g>αὐ. ἐγινώσκεν</g>: <r v=\"John.2.25\"></r>؛ <g>αὐ. ὑμεῖς</g>: <r v=\"John.3.28\"></r>؛ <g>καὶ αὐ. ἐγώ</g>: <r v=\"Rom.15.14\"></r>؛ <g>αὐ. Ἰησοῦς</g>: <r v=\"John.2.24\"></r>؛ <g>αὐ. καὶ οἱ μετ’ αὐτοῦ</g>: <r v=\"Matt.2.25\"></r>؛ <g>ὑμεῖς αὐ.</g>: <r v=\"Mark.6.31\"></r>؛ خاصةً <g>αὐ. ὁ</g>: <r v=\"Matt.3.4\"></r>، <r v=\"Mark.6.17\"></r>، <r v=\"John.16.27\"></r>، <r v=\"1Thess.3.11\"></r>، وفي مواضع أخرى؛ وفي اليونانية المتأخرة يضعف معناه أحيانًا: <g>ἐν αὐτῇ τ. ὥρᾳ</g>: <b>في تلك الساعة</b>: <r v=\"Luke.10.21\"></r>؛</s> <s n=\"(2)\">للتوكيد: <b>هو</b>، <b>هي</b>، <b>هو (للمحايد)</b>: <r v=\"Matt.1.21\"></r>، <r v=\"Matt.12.50\"></r>، <r v=\"Luke.6.35\"></r>، وفي مواضع أخرى؛ للإشارة إلى شخص بوصفه سيدًا: <r v=\"Matt.8.24\"></r>، <r v=\"Mark.4.38\"></r>، وفي مواضع أخرى؛ <g>αὐ., καὶ αὐ.</g> = <g>οὗτος, ὁ δε</g>: <r v=\"Matt.14.2\"></r>، <r v=\"Mark.14.15\"></r>، <r v=\"Mark.14.44\"></r>، <r v=\"Luke.1.22\"></r>، <r v=\"Luke.2.28\"></r>، وفي مواضع أخرى.</s> </s> <s n=\"2.\">في الحالات غير الرفع، بدلاً من ضمير الغائب البسيط: <b>هو</b>، <b>هي</b>، <b>هو (للمحايد)</b>: <r v=\"Matt.7.9\"></r>، <r v=\"Matt.10.12\"></r>، <r v=\"Matt.26.44\"></r>، وفي مواضع أخرى؛ مع اسم الفاعل في تركيب المضاف إليه المطلق: <r v=\"Matt.9.18\"></r>، <r v=\"Mark.13.1\"></r>، وفي مواضع أخرى؛ للحشو بعد الاسم الموصول (قارن العبرية <h n=\"H834\">אֲשֶׁר לֹו</h>): <r v=\"Mark.7.25\"></r>، <r v=\"Rev.3.8\"></r>، <r v=\"Rev.7.2\"></r>، وفي مواضع أخرى؛ في التركيب بحسب المعنى، دون ذكر صريح للفاعل الحقيقي: <r v=\"Matt.4.23\"></r>، <r v=\"Acts.8.5\"></r>، <r v=\"2Cor.2.13\"></r>، وفي مواضع أخرى؛ المضاف إليه <g>αὐτοῦ</g> = <g>ἐκείνου</g>: <r v=\"Rom.11.11\"></r>، <r v=\"1Thess.2.19\"></r>، <r v=\"Titus.3.5\"></r>، <r v=\"Heb.2.4\"></r>.</s> <s n=\"3.\"><g>ὁ</g>، <g>ἡ</g>، <g>τὸ αὐ.</g>: <b>نفسه، ذاته</b>: <r v=\"Heb.1.12\"></r>، <r v=\"Heb.13.8\"></r>؛ <g>τὸ αὐ.</g>، <g>ποιεῖν</g>: <r v=\"Matt.5.46\"></r>، <r v=\"Matt.5.47\"></r>، وفي مواضع أخرى؛ <g>φρονεῖν</g>: <r v=\"Rom.12.16\"></r>، <r v=\"Rom.15.5\"></r>، <r v=\"Phil.2.2\"></r>، وفي مواضع أخرى؛ <g>τὰ αὐ.</g>: <r v=\"Acts.15.27\"></r>، <r v=\"Rom.2.1\"></r>، وفي مواضع أخرى؛ <g>κατὰ τὸ</g> (<g>τὰ</g>) <g>αὐ.</g>: <r v=\"Acts.14.1\"></r>، <r v=\"Luke.6.23\"></r>، وفي مواضع أخرى؛ <g>ἐπὶ τὸ αὐ.</g>: <b>معًا</b>: <r v=\"Matt.22.34\"></r>، <r v=\"Acts.1.15\"></r>، وفي مواضع أخرى؛ <g>ἓν κ. τὸ αὐ.</g>: <r v=\"1Cor.11.5\"></r>، <r v=\"1Cor.12.11\"></r>؛ مع القابل: <r v=\"1Cor.11.5\"></r>؛ مع اسم: <g>λόγος</g>: <r v=\"Mark\"></r>؛ <g>μέτρος</g>: <r v=\"Phil.1.30\"></r>؛ <g>πνεῦμα</g>: <r v=\"1Cor.12.4\"></r>.</s>"},"G890":{"l":"ἄχρηστος","o":1,"en":"<f><o>ἄ-χρηστος</o>, <g>-ον</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Hos.8.8\"></r> (<h n=\"H2656\">חֵפֶץ</h> <h n=\"H369\">אַיִן</h>), <r v=\"Wis.2.11\"></r>, <r v=\"Sir.16.1\"></r>, al.;]</e> </et> <s><b>useless</b>, <b>unserviceable</b>: opp. to <g>εὔχρηστος</g>, <r v=\"Phlm.1.11\"></r>.†</s>","ar":"<f><o>ἄ-χρηστος</o>، <g>-ον</g>،</f> <s><b>غير نافع</b>، <b>عديم الفائدة</b>: عكس <g>εὔχρηστος</g>: <r v=\"Phlm.1.11\"></r>.†</s>"},"G91":{"l":"ἀδικέω","o":28,"en":"<f><o>ἀδικέω</o>, <g>-ῶ</g> </f> <et> <e t=\"derivation\">(&lt; <x><g>ἄδικος</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H6231\">עשׁק</h>, <h n=\"H5753\">עוה</h>, etc.;]</e> </et> <s n=\"1.\">intrans., to be <g>ἄδικος</g>, <b>do wrong</b>, <b>act wickedly</b> or <b>criminally</b>: <r v=\"Acts.25.11\"></r>, <r v=\"1Cor.6.8\"></r>, <r v=\"2Cor.7.12\"></r>, <r v=\"Col.3.25\"></r>, <r v=\"Rev.22.11\"></r>; <b>to do hurt</b>, <r v=\"Rev.9.19\"></r>. </s> <s n=\"2.\">Trans. <s n=\"(a)\"><b>to do</b> some <b>wrong</b>: <g>ὃ ἠδίκησεν</g>, <r v=\"Col.3.25\"></r>; <b>to wrong</b> some one, <r v=\"Matt.20.13\"></r>, <r v=\"Acts.7.26\"></r>, <r v=\"Acts.7.27\"></r> <r v=\"Acts.25.10\"></r>, <r v=\"2Cor.7.2\"></r>, <r v=\"Gal.4.12\"></r>, <r v=\"Phlm.1.18\"></r>, <r v=\"2Pet.2.13\"></r>; pass., <r v=\"Acts.7.24\"></r>, <r v=\"2Cor.7.12\"></r>; mid., <r v=\"1Cor.6.7\"></r> (<b>suffer . . . to be wronged</b>; WM, §38, 3; but v. Bl., §54, 5; and cf. <x><g>ἀποστερέω</g></x>);</s> <s n=\"(b)\"><b>to injure, hurt</b>: <r v=\"Luke.10.19\"></r> <r v=\"Rev.2.11\"></r> <r v=\"Rev.6.6\"></r> <r v=\"Rev.7.2\"></r>, <r v=\"Rev.7.3\"></r> <r v=\"Rev.9.4\"></r>, <r v=\"Rev.9.10\"></r> <r v=\"Rev.11.5\"></r>.†</s> </s>","ar":"<f><o>ἀδικέω</o>، <g>-ῶ</g> </f> <s n=\"1.\">لازم، أن يكون <g>ἄδικος</g>، <b>يظلم</b>، <b>يفعل شرًّا</b> أو <b>يرتكب جُرمًا</b>: <r v=\"Acts.25.11\"></r>، <r v=\"1Cor.6.8\"></r>، <r v=\"2Cor.7.12\"></r>، <r v=\"Col.3.25\"></r>، <r v=\"Rev.22.11\"></r>؛ <b>يؤذي</b>، <r v=\"Rev.9.19\"></r>. </s> <s n=\"2.\">متعدٍّ <s n=\"(a)\"><b>يرتكب</b> <b>ظلمًا</b> ما: <g>ὃ ἠδίκησεν</g>، <r v=\"Col.3.25\"></r>؛ <b>يظلم</b> أحدًا، <r v=\"Matt.20.13\"></r>، <r v=\"Acts.7.26\"></r>، <r v=\"Acts.7.27\"></r> <r v=\"Acts.25.10\"></r>، <r v=\"2Cor.7.2\"></r>، <r v=\"Gal.4.12\"></r>، <r v=\"Phlm.1.18\"></r>، <r v=\"2Pet.2.13\"></r>؛ المبني للمجهول، <r v=\"Acts.7.24\"></r>، <r v=\"2Cor.7.12\"></r>؛ الصيغة الوسطى، <r v=\"1Cor.6.7\"></r> (<b>يحتمل ... أن يُظلَم</b>؛ وقارن <x><g>ἀποστερέω</g></x>)؛</s> <s n=\"(b)\"><b>يضرّ، يؤذي</b>: <r v=\"Luke.10.19\"></r> <r v=\"Rev.2.11\"></r> <r v=\"Rev.6.6\"></r> <r v=\"Rev.7.2\"></r>، <r v=\"Rev.7.3\"></r> <r v=\"Rev.9.4\"></r>، <r v=\"Rev.9.10\"></r> <r v=\"Rev.11.5\"></r>.†</s> </s>"}}};